insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-32-acto-administrativo', 'III.2 El acto administrativo: concepto, clases, elementos, eficacia, validez, motivación y notificación') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-32-acto-administrativo' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El acto administrativo: concepto, producción y contenido (art. 34 LPAC)"},{"n":"2","title":"Clases de actos: resoluciones y actos de trámite; actos que ponen fin a la vía administrativa (arts. 112.1 y 114 LPAC)"},{"n":"3","title":"Elementos del acto: competencia, contenido, motivación y forma (arts. 34-36 LPAC)"},{"n":"3.1","title":"La motivación (art. 35 LPAC)"},{"n":"3.2","title":"La forma (art. 36 LPAC)"},{"n":"4","title":"Eficacia: inderogabilidad singular, ejecutividad, efectos y retroactividad (arts. 37-39 LPAC)"},{"n":"4.1","title":"Ejecutoriedad y ejecución forzosa (arts. 98-100 LPAC)"},{"n":"5","title":"La notificación: plazo, contenido, notificación defectuosa, práctica en papel e infructuosa (arts. 40-44 LPAC)"},{"n":"6","title":"La publicación (arts. 45-46 LPAC)"},{"n":"7","title":"Validez: nulidad de pleno derecho y anulabilidad (arts. 47-48 LPAC)"},{"n":"8","title":"Límites a la invalidez: conversión, conservación y convalidación (arts. 49-52 LPAC)"}]'::jsonb, '["Art. 34.1 Ley 39/2015: «Los actos administrativos que dicten las Administraciones Públicas, bien de oficio o a instancia del interesado, se producirán por el órgano competente ajustándose a los requisitos y al procedimiento establecido.»","Art. 112.1 Ley 39/2015: «Contra las resoluciones y los actos de trámite, si estos últimos deciden directa o indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento, producen indefensión o perjuicio irreparable a derechos e intereses legítimos, podrán interponerse por los interesados los recursos de alzada y potestativo de reposición, que cabrá fundar en cualquiera de los motivos de nulidad o anulabilidad previstos en los artículos 47 y 48 de esta Ley.»","Art. 35.1 Ley 39/2015: «Serán motivados, con sucinta referencia de hechos y fundamentos de derecho: a) Los actos que limiten derechos subjetivos o intereses legítimos.»","Art. 35.1.i) Ley 39/2015: «Los actos que se dicten en el ejercicio de potestades discrecionales, así como los que deban serlo en virtud de disposición legal o reglamentaria expresa.»","Art. 36.1 Ley 39/2015: «Los actos administrativos se producirán por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada de expresión y constancia.»","Art. 39.1-2 Ley 39/2015: «Los actos de las Administraciones Públicas sujetos al Derecho Administrativo se presumirán válidos y producirán efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa. 2. La eficacia quedará demorada cuando así lo exija el contenido del acto o esté supeditada a su notificación, publicación o aprobación superior.»","Art. 39.3 Ley 39/2015: «Excepcionalmente, podrá otorgarse eficacia retroactiva a los actos cuando se dicten en sustitución de actos anulados, así como cuando produzcan efectos favorables al interesado, siempre que los supuestos de hecho necesarios existieran ya en la fecha a que se retrotraiga la eficacia del acto y ésta no lesione derechos o intereses legítimos de otras personas.»","Art. 100.1 Ley 39/2015: «La ejecución forzosa por las Administraciones Públicas se efectuará, respetando siempre el principio de proporcionalidad, por los siguientes medios: a) Apremio sobre el patrimonio. b) Ejecución subsidiaria. c) Multa coercitiva. d) Compulsión sobre las personas.»","Art. 40.2 Ley 39/2015: «Toda notificación deberá ser cursada dentro del plazo de diez días a partir de la fecha en que el acto haya sido dictado, y deberá contener el texto íntegro de la resolución, con indicación de si pone fin o no a la vía administrativa, la expresión de los recursos que procedan, en su caso, en vía administrativa y judicial, el órgano ante el que hubieran de presentarse y el plazo para interponerlos, sin perjuicio de que los interesados puedan ejercitar, en su caso, cualquier otro que estimen procedente.»","Art. 42.2 Ley 39/2015: «Cuando la notificación se practique en el domicilio del interesado, de no hallarse presente éste en el momento de entregarse la notificación, podrá hacerse cargo de la misma cualquier persona mayor de catorce años que se encuentre en el domicilio y haga constar su identidad.»","Art. 44 Ley 39/2015: «Cuando los interesados en un procedimiento sean desconocidos, se ignore el lugar de la notificación o bien, intentada ésta, no se hubiese podido practicar, la notificación se hará por medio de un anuncio publicado en el «Boletín Oficial del Estado».»","Art. 45.1 Ley 39/2015: «Los actos administrativos serán objeto de publicación cuando así lo establezcan las normas reguladoras de cada procedimiento o cuando lo aconsejen razones de interés público apreciadas por el órgano competente.»","Art. 47.1 Ley 39/2015: «Los actos de las Administraciones Públicas son nulos de pleno derecho en los casos siguientes: a) Los que lesionen los derechos y libertades susceptibles de amparo constitucional. b) Los dictados por órgano manifiestamente incompetente por razón de la materia o del territorio. c) Los que tengan un contenido imposible. d) Los que sean constitutivos de infracción penal o se dicten como consecuencia de ésta.»","Art. 48.1-2 Ley 39/2015: «Son anulables los actos de la Administración que incurran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder. 2. No obstante, el defecto de forma sólo determinará la anulabilidad cuando el acto carezca de los requisitos formales indispensables para alcanzar su fin o dé lugar a la indefensión de los interesados.»","Art. 51 Ley 39/2015: «El órgano que declare la nulidad o anule las actuaciones dispondrá siempre la conservación de aquellos actos y trámites cuyo contenido se hubiera mantenido igual de no haberse cometido la infracción.»","Art. 52.1 Ley 39/2015: «La Administración podrá convalidar los actos anulables, subsanando los vicios de que adolezcan.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El acto administrativo: concepto, producción y contenido","blocks":[{"text":"La Ley 39/2015 no define el acto administrativo, pero de su regulación se deduce que es una declaración de una Administración Pública, sujeta al Derecho Administrativo, que produce efectos jurídicos sobre los interesados. Los actos se dictan de oficio o a instancia del interesado y deben producirse por el órgano competente, ajustándose a los requisitos y al procedimiento establecido (art. 34.1 LPAC). Su contenido debe ajustarse al ordenamiento jurídico y ser determinado y adecuado a los fines del acto (art. 34.2 LPAC).","refs":[{"ref":"Art. 34.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Los actos administrativos que dicten las Administraciones Públicas, bien de oficio o a instancia del interesado, se producirán por el órgano competente ajustándose a los requisitos y al procedimiento establecido."},{"ref":"Art. 34.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El contenido de los actos se ajustará a lo dispuesto por el ordenamiento jurídico y será determinado y adecuado a los fines de aquéllos."}]}]},{"n":"2","title":"Clases de actos: resoluciones y actos de trámite; actos que ponen fin a la vía administrativa","blocks":[{"text":"La ley distingue entre resoluciones, que deciden el fondo del procedimiento, y actos de trámite, que lo impulsan o preparan. Contra las resoluciones caben recursos; contra los actos de trámite, solo cuando son «cualificados»: si deciden directa o indirectamente el fondo del asunto, impiden continuar el procedimiento o producen indefensión o perjuicio irreparable a derechos e intereses legítimos (art. 112.1 LPAC). En los demás casos, la oposición a los actos de trámite puede alegarse para que se tenga en cuenta en la resolución que ponga fin al procedimiento.","refs":[{"ref":"Art. 112.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Contra las resoluciones y los actos de trámite, si estos últimos deciden directa o indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento, producen indefensión o perjuicio irreparable a derechos e intereses legítimos, podrán interponerse por los interesados los recursos de alzada y potestativo de reposición"},{"ref":"Art. 112.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La oposición a los restantes actos de trámite podrá alegarse por los interesados para su consideración en la resolución que ponga fin al procedimiento."}]},{"text":"Otra clasificación clave es la de actos que ponen fin a la vía administrativa (recurribles en reposición o directamente ante la jurisdicción) y actos que no la agotan (recurribles en alzada). Ponen fin a la vía, entre otros, las resoluciones de los recursos de alzada, las de órganos sin superior jerárquico y las de responsabilidad patrimonial (art. 114.1 LPAC). En el ámbito estatal también la agotan los actos de los miembros y órganos del Gobierno, de los Ministros y Secretarios de Estado y los de los órganos directivos con nivel de Director general o superior en materia de personal (art. 114.2 LPAC).","refs":[{"ref":"Art. 114.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) Las resoluciones de los recursos de alzada. […] c) Las resoluciones de los órganos administrativos que carezcan de superior jerárquico, salvo que una Ley establezca lo contrario."},{"ref":"Art. 114.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"b) Los emanados de los Ministros y los Secretarios de Estado en el ejercicio de las competencias que tienen atribuidas los órganos de los que son titulares. c) Los emanados de los órganos directivos con nivel de Director general o superior, en relación con las competencias que tengan atribuidas en materia de personal."}]},{"text":"Por sus destinatarios, los actos pueden ser singulares o dirigirse a una pluralidad indeterminada de personas (caso en que deben publicarse, art. 45.1.a LPAC); por su forma de producirse, expresos o presuntos (silencio); y por sus efectos, favorables o desfavorables (de gravamen), distinción que importa para la retroactividad y la motivación.","refs":[{"ref":"Art. 45.1.a) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Cuando el acto tenga por destinatario a una pluralidad indeterminada de personas"}]}]},{"n":"3","title":"Elementos del acto y la motivación","blocks":[{"text":"Los elementos del acto son subjetivos (el órgano competente), objetivos (el contenido, determinado y adecuado al fin) y formales (procedimiento, motivación y forma) (art. 34 LPAC). La motivación consiste en exponer, con sucinta referencia, los hechos y fundamentos de derecho de la decisión. No todos los actos la exigen; deben motivarse los que enumera el artículo 35.1 LPAC: los que limiten derechos subjetivos o intereses legítimos; los que resuelvan revisiones de oficio, recursos y arbitrajes o declaren su inadmisión; y los que se separen del criterio seguido en actuaciones precedentes o del dictamen de órganos consultivos.","refs":[{"ref":"Art. 35.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Serán motivados, con sucinta referencia de hechos y fundamentos de derecho: a) Los actos que limiten derechos subjetivos o intereses legítimos. b) Los actos que resuelvan procedimientos de revisión de oficio de disposiciones o actos administrativos, recursos administrativos y procedimientos de arbitraje y los que declaren su inadmisión. c) Los actos que se separen del criterio seguido en actuaciones precedentes o del dictamen de órganos consultivos."}]},{"text":"También deben motivarse: los acuerdos de suspensión de actos y de medidas provisionales; los de tramitación de urgencia, ampliación de plazos y actuaciones complementarias; los que rechacen pruebas propuestas por los interesados; los que terminen el procedimiento por imposibilidad material sobrevenida o acuerden el desistimiento de la Administración en procedimientos de oficio; las propuestas de resolución sancionadoras y las resoluciones sancionadoras y de responsabilidad patrimonial; y los actos dictados en ejercicio de potestades discrecionales o cuando lo exija una norma (art. 35.1.d a i LPAC).","refs":[{"ref":"Art. 35.1.e) y f) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"e) Los acuerdos de aplicación de la tramitación de urgencia, de ampliación de plazos y de realización de actuaciones complementarias. f) Los actos que rechacen pruebas propuestas por los interesados."},{"ref":"Art. 35.1.h) e i) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"h) Las propuestas de resolución en los procedimientos de carácter sancionador, así como los actos que resuelvan procedimientos de carácter sancionador o de responsabilidad patrimonial. i) Los actos que se dicten en el ejercicio de potestades discrecionales, así como los que deban serlo en virtud de disposición legal o reglamentaria expresa."}]},{"text":"En los procedimientos selectivos y de concurrencia competitiva, la motivación del acto que les pone fin se rige por las bases de la convocatoria, pero los fundamentos de la resolución deben quedar acreditados en el procedimiento (art. 35.2 LPAC).","refs":[{"ref":"Art. 35.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La motivación de los actos que pongan fin a los procedimientos selectivos y de concurrencia competitiva se realizará de conformidad con lo que dispongan las normas que regulen sus convocatorias, debiendo, en todo caso, quedar acreditados en el procedimiento los fundamentos de la resolución que se adopte."}]}]},{"n":"4","title":"La forma","blocks":[{"text":"La regla general es la forma escrita y electrónica: los actos se producen por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma más adecuada de expresión y constancia (art. 36.1 LPAC). Si el órgano ejerce su competencia de forma verbal, la constancia escrita, cuando sea necesaria, la efectúa y firma el titular del órgano inferior o el funcionario que la recibe oralmente; si son resoluciones, el titular de la competencia autoriza una relación de las dictadas verbalmente (art. 36.2 LPAC). Cuando deba dictarse una serie de actos de la misma naturaleza (nombramientos, concesiones o licencias), pueden refundirse en un único acto que individualice los efectos para cada interesado (art. 36.3 LPAC).","refs":[{"ref":"Art. 36.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Los actos administrativos se producirán por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada de expresión y constancia."},{"ref":"Art. 36.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"la constancia escrita del acto, cuando sea necesaria, se efectuará y firmará por el titular del órgano inferior o funcionario que la reciba oralmente"},{"ref":"Art. 36.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Cuando deba dictarse una serie de actos administrativos de la misma naturaleza, tales como nombramientos, concesiones o licencias, podrán refundirse en un único acto, acordado por el órgano competente, que especificará las personas u otras circunstancias que individualicen los efectos del acto para cada interesado."}]}]},{"n":"5","title":"Eficacia: inderogabilidad singular, ejecutividad, efectos y retroactividad","blocks":[{"text":"Una resolución particular no puede vulnerar una disposición general, aunque proceda de un órgano de igual o superior jerarquía al que la dictó (inderogabilidad singular, art. 37.1 LPAC). Los actos sujetos al Derecho Administrativo son ejecutivos (art. 38 LPAC), se presumen válidos y producen efectos desde la fecha en que se dictan, salvo que en ellos se disponga otra cosa (art. 39.1 LPAC). La eficacia queda demorada cuando lo exija el contenido del acto o esté supeditada a su notificación, publicación o aprobación superior (art. 39.2 LPAC).","refs":[{"ref":"Art. 37.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las resoluciones administrativas de carácter particular no podrán vulnerar lo establecido en una disposición de carácter general, aunque aquéllas procedan de un órgano de igual o superior jerarquía al que dictó la disposición general."},{"ref":"Art. 39.1-2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Los actos de las Administraciones Públicas sujetos al Derecho Administrativo se presumirán válidos y producirán efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa. 2. La eficacia quedará demorada cuando así lo exija el contenido del acto o esté supeditada a su notificación, publicación o aprobación superior."}]},{"text":"La retroactividad es excepcional. Solo cabe cuando el acto se dicta en sustitución de otro anulado o produce efectos favorables al interesado, siempre que los supuestos de hecho ya existieran en la fecha a la que se retrotrae la eficacia y no se lesionen derechos o intereses legítimos de otras personas (art. 39.3 LPAC). Además, los actos dictados por un órgano en ejercicio de su competencia deben ser observados por los demás órganos, aunque no dependan jerárquicamente de él o pertenezcan a otra Administración (art. 39.4 LPAC).","refs":[{"ref":"Art. 39.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Excepcionalmente, podrá otorgarse eficacia retroactiva a los actos cuando se dicten en sustitución de actos anulados, así como cuando produzcan efectos favorables al interesado, siempre que los supuestos de hecho necesarios existieran ya en la fecha a que se retrotraiga la eficacia del acto y ésta no lesione derechos o intereses legítimos de otras personas."},{"ref":"Art. 39.4 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"deberán ser observadas por el resto de los órganos administrativos, aunque no dependan jerárquicamente entre sí o pertenezcan a otra Administración."}]}]},{"n":"6","title":"Ejecutoriedad y ejecución forzosa","blocks":[{"text":"Los actos son inmediatamente ejecutivos salvo que se suspenda su ejecución; que se trate de una resolución sancionadora contra la que quepa algún recurso administrativo, incluido el potestativo de reposición; que una disposición establezca lo contrario; o que se necesite aprobación o autorización superior (art. 98.1 LPAC). Si el obligado no cumple, la Administración puede ejecutar forzosamente el acto, previo apercibimiento, salvo que se suspenda la ejecución o la Constitución o la ley exijan intervención judicial (art. 99 LPAC).","refs":[{"ref":"Art. 98.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"serán inmediatamente ejecutivos, salvo que: a) Se produzca la suspensión de la ejecución del acto. b) Se trate de una resolución de un procedimiento de naturaleza sancionadora contra la que quepa algún recurso en vía administrativa, incluido el potestativo de reposición. c) Una disposición establezca lo contrario. d) Se necesite aprobación o autorización superior."},{"ref":"Art. 99 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"podrán proceder, previo apercibimiento, a la ejecución forzosa de los actos administrativos"}]},{"text":"Los medios de ejecución forzosa, aplicados con proporcionalidad, son el apremio sobre el patrimonio, la ejecución subsidiaria, la multa coercitiva y la compulsión sobre las personas; si caben varios, se elige el menos restrictivo de la libertad individual (art. 100 LPAC). Para entrar en un domicilio hace falta el consentimiento del titular o autorización judicial. La ejecución subsidiaria se usa con actos no personalísimos, a costa del obligado (art. 102 LPAC); la multa coercitiva requiere autorización legal y es compatible con las sanciones (art. 103 LPAC).","refs":[{"ref":"Art. 100.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La ejecución forzosa por las Administraciones Públicas se efectuará, respetando siempre el principio de proporcionalidad, por los siguientes medios: a) Apremio sobre el patrimonio. b) Ejecución subsidiaria. c) Multa coercitiva. d) Compulsión sobre las personas."},{"ref":"Art. 100.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Si fueran varios los medios de ejecución admisibles se elegirá el menos restrictivo de la libertad individual."},{"ref":"Art. 103.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La multa coercitiva es independiente de las sanciones que puedan imponerse con tal carácter y compatible con ellas."}]}]},{"n":"7","title":"La notificación: plazo, contenido y notificación defectuosa","blocks":[{"text":"El órgano que dicta el acto lo notifica a los interesados cuyos derechos e intereses resulten afectados (art. 40.1 LPAC). La notificación debe cursarse en diez días desde que se dicta el acto y contener el texto íntegro de la resolución, si pone fin o no a la vía administrativa, los recursos procedentes, el órgano ante el que presentarlos y el plazo para interponerlos (art. 40.2 LPAC).","refs":[{"ref":"Art. 40.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Toda notificación deberá ser cursada dentro del plazo de diez días a partir de la fecha en que el acto haya sido dictado, y deberá contener el texto íntegro de la resolución, con indicación de si pone fin o no a la vía administrativa, la expresión de los recursos que procedan, en su caso, en vía administrativa y judicial, el órgano ante el que hubieran de presentarse y el plazo para interponerlos"}]},{"text":"Si la notificación contiene el texto íntegro pero omite otro requisito (por ejemplo, los recursos), es defectuosa: surte efecto cuando el interesado realiza actuaciones que suponen conocer el contenido y alcance del acto o interpone cualquier recurso (art. 40.3 LPAC). A los solos efectos de cumplir el plazo máximo de resolución basta con que la notificación contenga el texto íntegro y el intento de notificación esté debidamente acreditado (art. 40.4 LPAC).","refs":[{"ref":"Art. 40.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las notificaciones que, conteniendo el texto íntegro del acto, omitiesen alguno de los demás requisitos previstos en el apartado anterior, surtirán efecto a partir de la fecha en que el interesado realice actuaciones que supongan el conocimiento del contenido y alcance de la resolución o acto objeto de la notificación, o interponga cualquier recurso que proceda."},{"ref":"Art. 40.4 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a los solos efectos de entender cumplida la obligación de notificar dentro del plazo máximo de duración de los procedimientos, será suficiente la notificación que contenga, cuando menos, el texto íntegro de la resolución, así como el intento de notificación debidamente acreditado."}]}]},{"n":"8","title":"Práctica de la notificación: electrónica, en papel e infructuosa","blocks":[{"text":"Las notificaciones se practican preferentemente por medios electrónicos y siempre que el interesado esté obligado a recibirlas así (art. 41.1 LPAC). La electrónica se entiende practicada al acceder a su contenido y, si es obligatoria o elegida, rechazada a los diez días naturales de su puesta a disposición sin acceso (art. 43.2 LPAC). Si el interesado rechaza la notificación, se deja constancia y se da por efectuado el trámite (art. 41.5 LPAC).","refs":[{"ref":"Art. 41.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las notificaciones se practicarán preferentemente por medios electrónicos y, en todo caso, cuando el interesado resulte obligado a recibirlas por esta vía."},{"ref":"Art. 43.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se entenderá rechazada cuando hayan transcurrido diez días naturales desde la puesta a disposición de la notificación sin que se acceda a su contenido."}]},{"text":"En la notificación en papel en el domicilio, si el interesado no está, puede recogerla cualquier persona mayor de catorce años que se encuentre allí y se identifique. Si nadie se hace cargo, se repite una sola vez, a hora distinta, dentro de los tres días siguientes: si el primer intento fue antes de las quince horas, el segundo será después, y viceversa, con al menos tres horas de diferencia (art. 42.2 LPAC). Si también fracasa, o los interesados son desconocidos o se ignora el lugar, la notificación se hace por anuncio en el «Boletín Oficial del Estado» (art. 44 LPAC).","refs":[{"ref":"Art. 42.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"podrá hacerse cargo de la misma cualquier persona mayor de catorce años que se encuentre en el domicilio y haga constar su identidad."},{"ref":"Art. 42.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"intento que se repetirá por una sola vez y en una hora distinta dentro de los tres días siguientes. En caso de que el primer intento de notificación se haya realizado antes de las quince horas, el segundo intento deberá realizarse después de las quince horas y viceversa, dejando en todo caso al menos un margen de diferencia de tres horas entre ambos intentos de notificación."},{"ref":"Art. 44 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Cuando los interesados en un procedimiento sean desconocidos, se ignore el lugar de la notificación o bien, intentada ésta, no se hubiese podido practicar, la notificación se hará por medio de un anuncio publicado en el «Boletín Oficial del Estado»."}]}]},{"n":"9","title":"La publicación","blocks":[{"text":"Los actos se publican cuando lo establezcan sus normas o lo aconsejen razones de interés público (art. 45.1 LPAC). La publicación sustituye a la notificación cuando el acto se dirige a una pluralidad indeterminada de personas y en los actos de procedimientos selectivos o de concurrencia competitiva; en estos, la convocatoria indica el medio de las publicaciones y carecen de validez las hechas en lugares distintos (art. 45.1.b LPAC). Se publica en el diario oficial correspondiente con los mismos elementos que la notificación (art. 45.2 y 45.3 LPAC). Si la publicación lesiona derechos o intereses legítimos, se publica solo una somera indicación del contenido y del lugar donde comparecer para conocerlo íntegro (art. 46 LPAC).","refs":[{"ref":"Art. 45.1.b) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"En este caso, la convocatoria del procedimiento deberá indicar el medio donde se efectuarán las sucesivas publicaciones, careciendo de validez las que se lleven a cabo en lugares distintos."},{"ref":"Art. 46 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se limitará a publicar en el Diario oficial que corresponda una somera indicación del contenido del acto y del lugar donde los interesados podrán comparecer, en el plazo que se establezca, para conocimiento del contenido íntegro del mencionado acto y constancia de tal conocimiento."}]}]},{"n":"10","title":"Validez: nulidad de pleno derecho y anulabilidad","blocks":[{"text":"Son nulos de pleno derecho los actos que lesionen derechos y libertades susceptibles de amparo constitucional; los dictados por órgano manifiestamente incompetente por razón de la materia o del territorio; los de contenido imposible; los constitutivos de infracción penal o dictados como consecuencia de ella; los dictados prescindiendo total y absolutamente del procedimiento o de las reglas esenciales de los órganos colegiados; los actos por los que se adquieren facultades o derechos careciendo de requisitos esenciales; y los que establezca una ley (art. 47.1 LPAC). La incompetencia jerárquica no figura en la lista: no es causa de nulidad.","refs":[{"ref":"Art. 47.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"b) Los dictados por órgano manifiestamente incompetente por razón de la materia o del territorio. c) Los que tengan un contenido imposible."},{"ref":"Art. 47.1.e) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Los dictados prescindiendo total y absolutamente del procedimiento legalmente establecido o de las normas que contienen las reglas esenciales para la formación de la voluntad de los órganos colegiados."}]},{"text":"Cualquier otra infracción del ordenamiento, incluida la desviación de poder, produce anulabilidad (art. 48.1 LPAC). El defecto de forma solo anula si el acto carece de los requisitos formales indispensables para su fin o causa indefensión (art. 48.2 LPAC), y la actuación fuera de plazo solo anula cuando lo imponga la naturaleza del término o plazo (art. 48.3 LPAC).","refs":[{"ref":"Art. 48.1-2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Son anulables los actos de la Administración que incurran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder. 2. No obstante, el defecto de forma sólo determinará la anulabilidad cuando el acto carezca de los requisitos formales indispensables para alcanzar su fin o dé lugar a la indefensión de los interesados."},{"ref":"Art. 48.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La realización de actuaciones administrativas fuera del tiempo establecido para ellas sólo implicará la anulabilidad del acto cuando así lo imponga la naturaleza del término o plazo."}]}]},{"n":"11","title":"Límites a la invalidez: conversión, conservación y convalidación","blocks":[{"text":"La invalidez de un acto no arrastra a los sucesivos independientes, ni la de una parte a las partes independientes, salvo que sin la parte viciada el acto no se hubiera dictado (art. 49 LPAC). Por la conversión, los actos nulos o anulables que contengan los elementos de otro distinto producen los efectos de este (art. 50 LPAC). Por la conservación, el órgano que declara la nulidad o anula conserva los actos y trámites cuyo contenido habría sido igual sin la infracción (art. 51 LPAC).","refs":[{"ref":"Art. 49.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La nulidad o anulabilidad de un acto no implicará la de los sucesivos en el procedimiento que sean independientes del primero."},{"ref":"Art. 50 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Los actos nulos o anulables que, sin embargo, contengan los elementos constitutivos de otro distinto producirán los efectos de éste."},{"ref":"Art. 51 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El órgano que declare la nulidad o anule las actuaciones dispondrá siempre la conservación de aquellos actos y trámites cuyo contenido se hubiera mantenido igual de no haberse cometido la infracción."}]},{"text":"La convalidación solo cabe para actos anulables, subsanando sus vicios, y produce efecto desde su fecha, salvo la retroactividad del artículo 39.3 (art. 52.1 y 52.2 LPAC). Si el vicio es una incompetencia no determinante de nulidad, convalida el órgano competente cuando sea superior jerárquico del que dictó el acto; si falta una autorización, se convalida otorgándola (art. 52.3 y 52.4 LPAC).","refs":[{"ref":"Art. 52.1-2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La Administración podrá convalidar los actos anulables, subsanando los vicios de que adolezcan. 2. El acto de convalidación producirá efecto desde su fecha, salvo lo dispuesto en el artículo 39.3 para la retroactividad de los actos administrativos."},{"ref":"Art. 52.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Si el vicio consistiera en incompetencia no determinante de nulidad, la convalidación podrá realizarse por el órgano competente cuando sea superior jerárquico del que dictó el acto viciado."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Notificación: se cursa en diez días desde que se dicta el acto (art. 40.2 LPAC).","refs":[{"ref":"Art. 40.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Toda notificación deberá ser cursada dentro del plazo de diez días a partir de la fecha en que el acto haya sido dictado"}]},{"text":"Segundo intento en papel: una sola vez, dentro de tres días, en la franja horaria contraria a las quince horas y con tres horas de margen (art. 42.2 LPAC).","refs":[{"ref":"Art. 42.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"dejando en todo caso al menos un margen de diferencia de tres horas entre ambos intentos de notificación."}]},{"text":"Notificación electrónica no abierta: rechazada a los diez días naturales (art. 43.2 LPAC).","refs":[{"ref":"Art. 43.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"diez días naturales desde la puesta a disposición de la notificación"}]},{"text":"Rechazar pruebas o separarse del criterio precedente exige motivación (art. 35.1 LPAC).","refs":[{"ref":"Art. 35.1.f) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Los actos que rechacen pruebas propuestas por los interesados."}]},{"text":"La resolución sancionadora recurrible en vía administrativa no es inmediatamente ejecutiva (art. 98.1.b LPAC).","refs":[{"ref":"Art. 98.1.b) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Se trate de una resolución de un procedimiento de naturaleza sancionadora contra la que quepa algún recurso en vía administrativa, incluido el potestativo de reposición."}]},{"text":"Cuatro medios de ejecución forzosa: apremio, ejecución subsidiaria, multa coercitiva y compulsión (art. 100.1 LPAC).","refs":[{"ref":"Art. 100.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) Apremio sobre el patrimonio. b) Ejecución subsidiaria. c) Multa coercitiva. d) Compulsión sobre las personas."}]},{"text":"Desviación de poder = anulabilidad; incompetencia manifiesta por materia o territorio = nulidad (arts. 47.1.b y 48.1 LPAC).","refs":[{"ref":"Art. 48.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"incluso la desviación de poder."}]},{"text":"Conversión (art. 50), conservación (art. 51) y convalidación solo de anulables (art. 52 LPAC).","refs":[{"ref":"Art. 52.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La Administración podrá convalidar los actos anulables"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', null, null, null, null
