insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Representación de los interesados y su acreditación (art. 5 LPAC)"},{"n":"2","title":"Obligación de resolver, plazos máximos y silencio administrativo (arts. 21 y 24 LPAC)"},{"n":"3","title":"Cómputo de plazos por días, meses y años; días inhábiles; registro electrónico (arts. 30-31 LPAC)"},{"n":"4","title":"Ampliación de plazos (art. 32 LPAC)"},{"n":"5","title":"Iniciación a solicitud del interesado: subsanación y mejora (art. 68 LPAC)"},{"n":"6","title":"Ordenación: cumplimiento de trámites y cuestiones incidentales (arts. 73-74 LPAC)"},{"n":"7","title":"Tramitación simplificada (art. 96 LPAC)"},{"n":"8","title":"Revisión de oficio, lesividad, revocación y rectificación de errores (arts. 106-111 LPAC)"},{"n":"9","title":"Recursos administrativos: principios, fin de la vía administrativa, alzada, reposición y revisión (arts. 112-126 LPAC)"},{"n":"10","title":"Plazo del recurso contencioso-administrativo (art. 46 LJCA)"}]'::jsonb, '["Art. 5.3 Ley 39/2015: «Para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir de acciones y renunciar a derechos en nombre de otra persona, deberá acreditarse la representación. Para los actos y gestiones de mero trámite se presumirá aquella representación.»","Art. 5.6 Ley 39/2015: «La falta o insuficiente acreditación de la representación no impedirá que se tenga por realizado el acto de que se trate, siempre que se aporte aquélla o se subsane el defecto dentro del plazo de diez días que deberá conceder al efecto el órgano administrativo, o de un plazo superior cuando las circunstancias del caso así lo requieran.»","Art. 21.3 Ley 39/2015: «Cuando las normas reguladoras de los procedimientos no fijen el plazo máximo, éste será de tres meses.»","Art. 30.2 Ley 39/2015: «Siempre que por Ley o en el Derecho de la Unión Europea no se exprese otro cómputo, cuando los plazos se señalen por días, se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos.»","Art. 30.4 Ley 39/2015: «El plazo concluirá el mismo día en que se produjo la notificación, publicación o silencio administrativo en el mes o el año de vencimiento. Si en el mes de vencimiento no hubiera día equivalente a aquel en que comienza el cómputo, se entenderá que el plazo expira el último día del mes.»","Art. 30.5 Ley 39/2015: «Cuando el último día del plazo sea inhábil, se entenderá prorrogado al primer día hábil siguiente.»","Art. 31.2.b) Ley 39/2015: «A los efectos del cómputo de plazo fijado en días hábiles, y en lo que se refiere al cumplimiento de plazos por los interesados, la presentación en un día inhábil se entenderá realizada en la primera hora del primer día hábil siguiente salvo que una norma permita expresamente la recepción en día inhábil.»","Art. 32.3 Ley 39/2015: «En ningún caso podrá ser objeto de ampliación un plazo ya vencido.»","Art. 68.1 Ley 39/2015: «se requerirá al interesado para que, en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos, con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición»","Art. 74 Ley 39/2015: «Las cuestiones incidentales que se susciten en el procedimiento, incluso las que se refieran a la nulidad de actuaciones, no suspenderán la tramitación del mismo, salvo la recusación.»","Art. 96.6 Ley 39/2015: «Salvo que reste menos para su tramitación ordinaria, los procedimientos administrativos tramitados de manera simplificada deberán ser resueltos en treinta días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento»","Art. 106.5 Ley 39/2015: «Cuando el procedimiento se hubiera iniciado de oficio, el transcurso del plazo de seis meses desde su inicio sin dictarse resolución producirá la caducidad del mismo. Si el procedimiento se hubiera iniciado a solicitud de interesado, se podrá entender la misma desestimada por silencio administrativo.»","Art. 109.2 Ley 39/2015: «Las Administraciones Públicas podrán, asimismo, rectificar en cualquier momento, de oficio o a instancia de los interesados, los errores materiales, de hecho o aritméticos existentes en sus actos.»","Art. 121.2 Ley 39/2015: «Si el recurso se hubiera interpuesto ante el órgano que dictó el acto impugnado, éste deberá remitirlo al competente en el plazo de diez días, con su informe y con una copia completa y ordenada del expediente.»","Art. 122.2 Ley 39/2015: «El plazo máximo para dictar y notificar la resolución será de tres meses.»","Art. 46.1 Ley 29/1998: «El plazo para interponer el recurso contencioso-administrativo será de dos meses contados desde el día siguiente al de la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso. Si no lo fuera, el plazo será de seis meses»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Representación de los interesados y su acreditación","blocks":[{"text":"Los interesados con capacidad de obrar pueden actuar por medio de representante, y las actuaciones se entienden con este salvo manifestación expresa en contra (art. 5.1 LPAC). Pueden representar las personas físicas con capacidad de obrar y las jurídicas cuando lo prevean sus Estatutos (art. 5.2). La representación debe acreditarse para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir de acciones y renunciar a derechos; para los actos y gestiones de mero trámite se presume (art. 5.3).","refs":[{"ref":"Art. 5.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Los interesados con capacidad de obrar podrán actuar por medio de representante, entendiéndose con éste las actuaciones administrativas, salvo manifestación expresa en contra del interesado."},{"ref":"Art. 5.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir de acciones y renunciar a derechos en nombre de otra persona, deberá acreditarse la representación. Para los actos y gestiones de mero trámite se presumirá aquella representación."}]},{"text":"Se acredita por cualquier medio válido en Derecho que deje constancia fidedigna; entre otros, el apoderamiento apud acta (presencial o electrónico) o la inscripción en el registro electrónico de apoderamientos (art. 5.4). La falta o insuficiencia de acreditación no impide tener por realizado el acto si se aporta o subsana en el plazo de diez días que debe conceder el órgano, o en uno superior si las circunstancias lo requieren (art. 5.6). Ejemplo: requerimiento notificado el miércoles 3 de junio de 2026; sin festivos, los diez días hábiles empiezan el jueves 4 y vencen el miércoles 17 de junio.","refs":[{"ref":"Art. 5.4 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se entenderá acreditada la representación realizada mediante apoderamiento apud acta efectuado por comparecencia personal o comparecencia electrónica en la correspondiente sede electrónica, o a través de la acreditación de su inscripción en el registro electrónico de apoderamientos"},{"ref":"Art. 5.6 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La falta o insuficiente acreditación de la representación no impedirá que se tenga por realizado el acto de que se trate, siempre que se aporte aquélla o se subsane el defecto dentro del plazo de diez días que deberá conceder al efecto el órgano administrativo, o de un plazo superior cuando las circunstancias del caso así lo requieran."}]}]},{"n":"2","title":"Obligación de resolver, plazos máximos y silencio administrativo","blocks":[{"text":"La Administración debe dictar resolución expresa y notificarla en todos los procedimientos (art. 21.1 LPAC). El plazo máximo lo fija la norma del procedimiento y no puede exceder de seis meses salvo ley o Derecho de la UE (art. 21.2); si la norma no lo fija, es de tres meses (art. 21.3). Se cuenta, en los procedimientos de oficio, desde el acuerdo de iniciación, y en los iniciados a solicitud, desde la entrada de la solicitud en el registro electrónico del órgano competente.","refs":[{"ref":"Art. 21.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La Administración está obligada a dictar resolución expresa y a notificarla en todos los procedimientos cualquiera que sea su forma de iniciación."},{"ref":"Art. 21.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Este plazo no podrá exceder de seis meses salvo que una norma con rango de Ley establezca uno mayor o así venga previsto en el Derecho de la Unión Europea."},{"ref":"Art. 21.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Cuando las normas reguladoras de los procedimientos no fijen el plazo máximo, éste será de tres meses."}]},{"text":"En los procedimientos a solicitud del interesado, si vence el plazo sin notificar resolución, el silencio es, por regla general, estimatorio, salvo que una ley o el Derecho de la UE o internacional dispongan lo contrario (art. 24.1). Es desestimatorio, entre otros, en el derecho de petición, en la transferencia de facultades sobre el dominio o servicio público, en actividades que puedan dañar el medio ambiente, en la responsabilidad patrimonial y en los procedimientos de impugnación de actos y revisión de oficio a solicitud. La estimación por silencio es un verdadero acto que pone fin al procedimiento; la desestimación solo permite interponer el recurso procedente (art. 24.2). Tras un silencio positivo, la resolución expresa tardía solo puede ser confirmatoria (art. 24.3.a).","refs":[{"ref":"Art. 24.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El sentido del silencio también será desestimatorio en los procedimientos de impugnación de actos y disposiciones y en los de revisión de oficio iniciados a solicitud de los interesados."},{"ref":"Art. 24.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La estimación por silencio administrativo tiene a todos los efectos la consideración de acto administrativo finalizador del procedimiento. La desestimación por silencio administrativo tiene los solos efectos de permitir a los interesados la interposición del recurso administrativo o contencioso-administrativo que resulte procedente."},{"ref":"Art. 24.3.a) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"En los casos de estimación por silencio administrativo, la resolución expresa posterior a la producción del acto sólo podrá dictarse de ser confirmatoria del mismo."}]}]},{"n":"3","title":"Cómputo de plazos: días, meses y años; días inhábiles; registro electrónico","blocks":[{"text":"Salvo que una ley o el Derecho de la UE digan otra cosa, los plazos por días son hábiles: se excluyen sábados, domingos y festivos (art. 30.2 LPAC). Se cuentan desde el día siguiente a la notificación, publicación o silencio (art. 30.3). Los plazos por meses o años se cuentan también desde el día siguiente, pero concluyen el mismo día (ordinal) en que se produjo la notificación en el mes o año de vencimiento; si no existe día equivalente, el plazo expira el último día del mes (art. 30.4). Así, notificación el martes 31 de marzo de 2026 con plazo de un mes: vence el jueves 30 de abril.","refs":[{"ref":"Art. 30.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Siempre que por Ley o en el Derecho de la Unión Europea no se exprese otro cómputo, cuando los plazos se señalen por días, se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos."},{"ref":"Art. 30.4 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El plazo concluirá el mismo día en que se produjo la notificación, publicación o silencio administrativo en el mes o el año de vencimiento. Si en el mes de vencimiento no hubiera día equivalente a aquel en que comienza el cómputo, se entenderá que el plazo expira el último día del mes."}]},{"text":"Si el último día es inhábil, se prorroga al primer día hábil siguiente (art. 30.5): notificación el jueves 14 de mayo de 2026 y plazo de un mes; el 14 de junio es domingo, por lo que vence el lunes 15 de junio. Si un día es hábil donde reside el interesado e inhábil en la sede del órgano, o a la inversa, se considera inhábil en todo caso (art. 30.6). La AGE y las CCAA fijan cada año su calendario de días inhábiles (art. 30.7).","refs":[{"ref":"Art. 30.5 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Cuando el último día del plazo sea inhábil, se entenderá prorrogado al primer día hábil siguiente."},{"ref":"Art. 30.6 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Cuando un día fuese hábil en el municipio o Comunidad Autónoma en que residiese el interesado, e inhábil en la sede del órgano administrativo, o a la inversa, se considerará inhábil en todo caso."}]},{"text":"El registro electrónico admite documentos todos los días del año, las veinticuatro horas. En plazos por días hábiles, lo presentado en día inhábil se entiende presentado en la primera hora del primer día hábil siguiente, salvo norma que permita la recepción en día inhábil (art. 31.2.b): un escrito presentado el sábado 14 de marzo de 2026 a las 18:00 se tiene por presentado a primera hora del lunes 16. Para el registro electrónico rige solo el calendario de su sede, sin aplicar el artículo 30.6 (art. 31.3).","refs":[{"ref":"Art. 31.2.a) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Permitirá la presentación de documentos todos los días del año durante las veinticuatro horas."},{"ref":"Art. 31.2.b) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"A los efectos del cómputo de plazo fijado en días hábiles, y en lo que se refiere al cumplimiento de plazos por los interesados, la presentación en un día inhábil se entenderá realizada en la primera hora del primer día hábil siguiente salvo que una norma permita expresamente la recepción en día inhábil."}]}]},{"n":"4","title":"Ampliación de plazos","blocks":[{"text":"Salvo precepto en contrario, la Administración puede ampliar los plazos, de oficio o a petición, sin exceder de la mitad de los mismos, si las circunstancias lo aconsejan y no se perjudican derechos de tercero; el acuerdo se notifica (art. 32.1 LPAC). La ampliación máxima se aplica siempre en procedimientos tramitados por misiones diplomáticas y oficinas consulares o con trámites en el extranjero o interesados residentes fuera de España (art. 32.2). La petición y la decisión deben producirse antes del vencimiento: nunca puede ampliarse un plazo ya vencido, y los acuerdos de ampliación o denegación no son recurribles (art. 32.3). Por incidencias técnicas o ciberincidentes también cabe ampliar plazos no vencidos (art. 32.4 y 32.5).","refs":[{"ref":"Art. 32.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"podrá conceder de oficio o a petición de los interesados, una ampliación de los plazos establecidos, que no exceda de la mitad de los mismos, si las circunstancias lo aconsejan y con ello no se perjudican derechos de tercero."},{"ref":"Art. 32.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"En ningún caso podrá ser objeto de ampliación un plazo ya vencido. Los acuerdos sobre ampliación de plazos o sobre su denegación no serán susceptibles de recurso"},{"ref":"Art. 32.4 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"la Administración podrá determinar una ampliación de los plazos no vencidos"}]}]},{"n":"5","title":"Iniciación a solicitud del interesado: subsanación y mejora","blocks":[{"text":"Si la solicitud no reúne los requisitos legales, se requiere al interesado para que en diez días subsane la falta o acompañe los documentos preceptivos, advirtiéndole de que, si no lo hace, se le tendrá por desistido, previa resolución dictada en los términos del artículo 21 (art. 68.1 LPAC). Este plazo puede ampliarse prudencialmente hasta cinco días cuando aportar los documentos presente dificultades especiales, pero no en procedimientos selectivos o de concurrencia competitiva (art. 68.2). En los procedimientos a solicitud, el órgano puede pedir la modificación o mejora voluntaria de la solicitud, levantando acta sucinta (art. 68.3). Si un obligado a relacionarse electrónicamente presenta en papel, se le requiere para subsanar electrónicamente, y la fecha de presentación será la de la subsanación (art. 68.4).","refs":[{"ref":"Art. 68.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se requerirá al interesado para que, en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos, con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición, previa resolución que deberá ser dictada en los términos previstos en el artículo 21."},{"ref":"Art. 68.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Siempre que no se trate de procedimientos selectivos o de concurrencia competitiva, este plazo podrá ser ampliado prudencialmente, hasta cinco días"},{"ref":"Art. 68.4 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se considerará como fecha de presentación de la solicitud aquella en la que haya sido realizada la subsanación."}]}]},{"n":"6","title":"Ordenación: cumplimiento de trámites y cuestiones incidentales","blocks":[{"text":"Los trámites a cargo de los interesados deben realizarse en diez días desde el siguiente a la notificación, salvo plazo distinto en la norma (art. 73.1 LPAC). Si un acto del interesado no reúne los requisitos, se le conceden diez días para cumplimentarlo (art. 73.2). Quien no cumpla puede ser declarado decaído en su derecho al trámite, aunque su actuación se admite si se produce antes o dentro del día en que se notifique la resolución que tenga por transcurrido el plazo (art. 73.3). Las cuestiones incidentales, incluso las de nulidad de actuaciones, no suspenden la tramitación, salvo la recusación (art. 74).","refs":[{"ref":"Art. 73.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Los trámites que deban ser cumplimentados por los interesados deberán realizarse en el plazo de diez días a partir del siguiente al de la notificación del correspondiente acto, salvo en el caso de que en la norma correspondiente se fije plazo distinto."},{"ref":"Art. 73.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se admitirá la actuación del interesado y producirá sus efectos legales, si se produjera antes o dentro del día que se notifique la resolución en la que se tenga por transcurrido el plazo."},{"ref":"Art. 74 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las cuestiones incidentales que se susciten en el procedimiento, incluso las que se refieran a la nulidad de actuaciones, no suspenderán la tramitación del mismo, salvo la recusación."}]}]},{"n":"7","title":"Tramitación simplificada","blocks":[{"text":"Puede acordarse, de oficio o a solicitud, por razones de interés público o falta de complejidad (art. 96.1 LPAC). Si se acuerda de oficio y algún interesado se opone expresamente, debe seguirse la tramitación ordinaria (art. 96.2), salvo en los sancionadores con elementos para calificar la infracción como leve, donde no cabe esa oposición (art. 96.5). La solicitud del interesado puede desestimarse en cinco días sin recurso (art. 96.3). Salvo que reste menos para la tramitación ordinaria, se resuelve en treinta días desde el siguiente a la notificación del acuerdo, con trámites tasados: alegaciones en cinco días y audiencia solo si la resolución va a ser desfavorable (art. 96.6). Si se exige un trámite no previsto, se tramita de forma ordinaria (art. 96.7).","refs":[{"ref":"Art. 96.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Si alguno de ellos manifestara su oposición expresa, la Administración deberá seguir la tramitación ordinaria."},{"ref":"Art. 96.5 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"existen elementos de juicio suficientes para calificar la infracción como leve, sin que quepa la oposición expresa por parte del interesado prevista en el apartado 2."},{"ref":"Art. 96.6 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Salvo que reste menos para su tramitación ordinaria, los procedimientos administrativos tramitados de manera simplificada deberán ser resueltos en treinta días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento"},{"ref":"Art. 96.6.c) y d) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"c) Alegaciones formuladas al inicio del procedimiento durante el plazo de cinco días. d) Trámite de audiencia, únicamente cuando la resolución vaya a ser desfavorable para el interesado."}]}]},{"n":"8","title":"Revisión de oficio, lesividad, revocación y rectificación de errores","blocks":[{"text":"La revisión de oficio de actos nulos procede en cualquier momento, de oficio o a solicitud, previo dictamen favorable del Consejo de Estado u órgano equivalente, sobre actos que pongan fin a la vía o no recurridos en plazo, por causas del artículo 47.1 (art. 106.1 LPAC); las disposiciones nulas solo se revisan de oficio (art. 106.2). Si el procedimiento se inició de oficio, el transcurso de seis meses sin resolución produce su caducidad; si fue a solicitud, puede entenderse desestimada (art. 106.5). Los actos favorables anulables no se anulan por la Administración: los declara lesivos y los impugna ante la jurisdicción contencioso-administrativa, en un máximo de cuatro años desde que se dictaron y con audiencia de los interesados; el procedimiento caduca a los seis meses (art. 107).","refs":[{"ref":"Art. 106.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"en cualquier momento, por iniciativa propia o a solicitud de interesado, y previo dictamen favorable del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma, si lo hubiere, declararán de oficio la nulidad de los actos administrativos que hayan puesto fin a la vía administrativa o que no hayan sido recurridos en plazo"},{"ref":"Art. 106.5 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Cuando el procedimiento se hubiera iniciado de oficio, el transcurso del plazo de seis meses desde su inicio sin dictarse resolución producirá la caducidad del mismo."},{"ref":"Art. 107.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La declaración de lesividad no podrá adoptarse una vez transcurridos cuatro años desde que se dictó el acto administrativo"}]},{"text":"Los actos de gravamen pueden revocarse mientras no haya prescrito, si no supone dispensa no permitida ni es contrario a la igualdad, al interés público o al ordenamiento (art. 109.1). Los errores materiales, de hecho o aritméticos pueden rectificarse en cualquier momento, de oficio o a instancia de los interesados (art. 109.2). En la AGE revisan: el Consejo de Ministros, sus actos y los de los Ministros; los Ministros, los de los Secretarios de Estado y órganos directivos no dependientes de una Secretaría de Estado; y los Secretarios de Estado, los de sus órganos directivos dependientes (art. 111).","refs":[{"ref":"Art. 109.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las Administraciones Públicas podrán, asimismo, rectificar en cualquier momento, de oficio o a instancia de los interesados, los errores materiales, de hecho o aritméticos existentes en sus actos."},{"ref":"Art. 111.b) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"1.º Los Ministros, respecto de los actos y disposiciones de los Secretarios de Estado y de los dictados por órganos directivos de su Departamento no dependientes de una Secretaría de Estado."}]}]},{"n":"9","title":"Recursos administrativos: principios, alzada, reposición y revisión","blocks":[{"text":"El error o la falta de calificación del recurso no impide tramitarlo si se deduce su verdadero carácter (art. 115.2 LPAC). Son causas de inadmisión, entre otras, la incompetencia cuando el órgano competente pertenece a otra Administración, la falta de legitimación y el plazo vencido (art. 116). La interposición no suspende la ejecución salvo disposición en contrario, pero puede suspenderse; y se entiende suspendida si en un mes desde la entrada de la solicitud no se resuelve sobre ella (art. 117). Al resolver, el órgano decide todas las cuestiones de forma y fondo, oyendo antes a los interesados sobre las no alegadas, sin poder agravar la situación inicial del recurrente (art. 119.3).","refs":[{"ref":"Art. 115.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El error o la ausencia de la calificación del recurso por parte del recurrente no será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter."},{"ref":"Art. 117.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La ejecución del acto impugnado se entenderá suspendida si transcurrido un mes desde que la solicitud de suspensión haya tenido entrada en el registro electrónico"},{"ref":"Art. 119.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El órgano que resuelva el recurso decidirá cuantas cuestiones, tanto de forma como de fondo, plantee el procedimiento, hayan sido o no alegadas por los interesados. En este último caso se les oirá previamente. No obstante, la resolución será congruente con las peticiones formuladas por el recurrente, sin que en ningún caso pueda agravarse su situación inicial."}]},{"text":"La alzada procede contra actos que no ponen fin a la vía administrativa, ante el superior jerárquico; los tribunales de selección se consideran dependientes del órgano al que estén adscritos o, en su defecto, del que nombró a su presidente (art. 121.1). Puede presentarse ante el órgano autor, que la remite al competente en diez días con informe y copia del expediente (art. 121.2). Plazo: un mes si el acto es expreso; si no, en cualquier momento desde que se produzcan los efectos del silencio. Se resuelve en tres meses (art. 122). La reposición es potestativa, contra actos que agotan la vía, ante el mismo órgano; plazo de un mes y resolución en un mes; mientras no se resuelva no cabe contencioso (arts. 123 y 124). El recurso extraordinario de revisión procede contra actos firmes por las causas tasadas del artículo 125.1: error de hecho (cuatro años) o documentos y sentencias (tres meses).","refs":[{"ref":"Art. 121.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se considerarán dependientes del órgano al que estén adscritos o, en su defecto, del que haya nombrado al presidente de los mismos."},{"ref":"Art. 121.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Si el recurso se hubiera interpuesto ante el órgano que dictó el acto impugnado, éste deberá remitirlo al competente en el plazo de diez días, con su informe y con una copia completa y ordenada del expediente."},{"ref":"Art. 122.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El plazo máximo para dictar y notificar la resolución será de tres meses."},{"ref":"Art. 124.1-2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El plazo para la interposición del recurso de reposición será de un mes, si el acto fuera expreso. […] 2. El plazo máximo para dictar y notificar la resolución del recurso será de un mes."},{"ref":"Art. 125.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"dentro del plazo de cuatro años siguientes a la fecha de la notificación de la resolución impugnada. En los demás casos, el plazo será de tres meses"}]}]},{"n":"10","title":"Plazo del recurso contencioso-administrativo","blocks":[{"text":"El plazo es de dos meses desde el día siguiente a la publicación de la disposición o a la notificación o publicación del acto que agote la vía administrativa, si es expreso; si no lo es, seis meses desde el día siguiente a aquel en que se produzca el acto presunto (art. 46.1 LJCA). Si se interpuso reposición, se cuenta desde el día siguiente a la notificación de su resolución expresa o a su desestimación presunta (art. 46.4 LJCA). Contra la vía de hecho, diez días tras el requerimiento o veinte sin él (art. 46.3), y el recurso de lesividad, dos meses desde la declaración (art. 46.5).","refs":[{"ref":"Art. 46.1 LJCA","law":"Ley 29/1998","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718","quote":"El plazo para interponer el recurso contencioso-administrativo será de dos meses contados desde el día siguiente al de la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso. Si no lo fuera, el plazo será de seis meses"},{"ref":"Art. 46.4 LJCA","law":"Ley 29/1998","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718","quote":"El plazo para interponer el recurso contencioso-administrativo se contará desde el día siguiente a aquel en que se notifique la resolución expresa del recurso potestativo de reposición o en que éste deba entenderse presuntamente desestimado."},{"ref":"Art. 46.5 LJCA","law":"Ley 29/1998","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718","quote":"El plazo para interponer recurso de lesividad será de dos meses a contar desde el día siguiente a la fecha de la declaración de lesividad."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Plazo máximo supletorio para resolver: tres meses (art. 21.3 LPAC).","refs":[{"ref":"Art. 21.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"éste será de tres meses."}]},{"text":"Subsanación de solicitud y de representación: diez días (arts. 5.6 y 68.1 LPAC).","refs":[{"ref":"Art. 68.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos"}]},{"text":"Plazo de meses sin día equivalente: vence el último día del mes (art. 30.4 LPAC).","refs":[{"ref":"Art. 30.4 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se entenderá que el plazo expira el último día del mes."}]},{"text":"Nunca se amplía un plazo vencido; la ampliación no supera la mitad (art. 32 LPAC).","refs":[{"ref":"Art. 32.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"En ningún caso podrá ser objeto de ampliación un plazo ya vencido."}]},{"text":"Tramitación simplificada: treinta días (art. 96.6 LPAC).","refs":[{"ref":"Art. 96.6 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"deberán ser resueltos en treinta días"}]},{"text":"Revisión de oficio iniciada de oficio: caduca a los seis meses (art. 106.5 LPAC).","refs":[{"ref":"Art. 106.5 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"producirá la caducidad del mismo."}]},{"text":"Alzada: un mes para recurrir y tres meses para resolver; reposición: un mes y un mes (arts. 122 y 124 LPAC).","refs":[{"ref":"Art. 122.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El plazo para la interposición del recurso de alzada será de un mes, si el acto fuera expreso."}]},{"text":"Contencioso: dos meses si el acto es expreso, seis si es presunto (art. 46.1 LJCA).","refs":[{"ref":"Art. 46.1 LJCA","law":"Ley 29/1998","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718","quote":"Si no lo fuera, el plazo será de seis meses"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', null, null, null, 'Otras normas citadas: Ley 29/1998 (https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718)'
  from public.topics t where t.slug = 'age-adm-33-procedimiento-revision'
