insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-34-contratos', 'III.4 Los contratos del sector público') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-34-contratos' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Concepto y clases de contratos: calificación y contratos típicos (arts. 12-18 LCSP)"},{"n":"1.1","title":"Contratos administrativos y privados (arts. 25-26 LCSP)"},{"n":"1.2","title":"Necesidad, duración y prórroga (arts. 28-29 LCSP)"},{"n":"2","title":"Preparación: expediente de contratación y contratos menores (arts. 116-118 LCSP)"},{"n":"3","title":"Adjudicación: procedimientos, criterios, clasificación de ofertas y formalización (arts. 131, 145, 150, 153, 156 y 159 LCSP)"},{"n":"4","title":"Efectos y cumplimiento: prerrogativas, penalidades y demora (arts. 190-196 LCSP)"},{"n":"5","title":"La revisión de precios y otras alteraciones contractuales: modificación (arts. 103 y 203-205 LCSP)"},{"n":"6","title":"Extinción: cumplimiento, recepción y resolución (arts. 209-213 LCSP)"},{"n":"7","title":"Régimen de invalidez (arts. 38-40 LCSP)"},{"n":"8","title":"Recurso especial en materia de contratación (arts. 44 y 50 LCSP)"}]'::jsonb, '["Art. 12.1 Ley 9/2017: «Los contratos de obras, concesión de obras, concesión de servicios, suministro y servicios que celebren las entidades pertenecientes al sector público se calificarán de acuerdo con las normas contenidas en la presente sección.»","Art. 15.1 Ley 9/2017: «El contrato de concesión de servicios es aquel en cuya virtud uno o varios poderes adjudicadores encomiendan a título oneroso a una o varias personas, naturales o jurídicas, la gestión de un servicio cuya prestación sea de su titularidad o competencia, y cuya contrapartida venga constituida bien por el derecho a explotar los servicios objeto del contrato o bien por dicho derecho acompañado del de percibir un precio.»","Art. 25.2 Ley 9/2017: «Los contratos administrativos se regirán, en cuanto a su preparación, adjudicación, efectos, modificación y extinción, por esta Ley y sus disposiciones de desarrollo; supletoriamente se aplicarán las restantes normas de derecho administrativo y, en su defecto, las normas de derecho privado.»","Art. 29.4 Ley 9/2017: «Los contratos de suministros y de servicios de prestación sucesiva tendrán un plazo máximo de duración de cinco años, incluyendo las posibles prórrogas que en aplicación del apartado segundo de este artículo acuerde el órgano de contratación»","Art. 116.1 Ley 9/2017: «La celebración de contratos por parte de las Administraciones Públicas requerirá la previa tramitación del correspondiente expediente, que se iniciará por el órgano de contratación motivando la necesidad del contrato en los términos previstos en el artículo 28 de esta Ley y que deberá ser publicado en el perfil de contratante.»","Art. 118.1 Ley 9/2017: «Se consideran contratos menores los contratos de valor estimado inferior a 40.000 euros, cuando se trate de contratos de obras, o a 15.000 euros, cuando se trate de contratos de suministro o de servicios»","Art. 131.2 Ley 9/2017: «La adjudicación se realizará, ordinariamente utilizando una pluralidad de criterios de adjudicación basados en el principio de mejor relación calidad-precio, y utilizando el procedimiento abierto o el procedimiento restringido»","Art. 156.1 Ley 9/2017: «En el procedimiento abierto todo empresario interesado podrá presentar una proposición, quedando excluida toda negociación de los términos del contrato con los licitadores.»","Art. 153.3 Ley 9/2017: «Si el contrato es susceptible de recurso especial en materia de contratación conforme al artículo 44, la formalización no podrá efectuarse antes de que transcurran quince días hábiles desde que se remita la notificación de la adjudicación a los licitadores y candidatos.»","Art. 190 Ley 9/2017: «Dentro de los límites y con sujeción a los requisitos y efectos señalados en la presente Ley, el órgano de contratación ostenta la prerrogativa de interpretar los contratos administrativos, resolver las dudas que ofrezca su cumplimiento, modificarlos por razones de interés público, declarar la responsabilidad imputable al contratista a raíz de la ejecución del contrato, suspender la ejecución del mismo, acordar su resolución y determinar los efectos de esta.»","Art. 193.3 Ley 9/2017: «Cuando el contratista, por causas imputables al mismo, hubiere incurrido en demora respecto al cumplimiento del plazo total, la Administración podrá optar, atendidas las circunstancias del caso, por la resolución del contrato o por la imposición de las penalidades diarias en la proporción de 0,60 euros por cada 1.000 euros del precio del contrato, IVA excluido.»","Art. 197 Ley 9/2017: «La ejecución del contrato se realizará a riesgo y ventura del contratista, sin perjuicio de lo establecido para el contrato de obras en el artículo 239.»","Art. 103.1 Ley 9/2017: «Los precios de los contratos del sector público solo podrán ser objeto de revisión periódica y predeterminada en los términos establecidos en este Capítulo.»","Art. 209 Ley 9/2017: «Los contratos se extinguirán por su cumplimiento o por resolución, acordada de acuerdo con lo regulado en esta Subsección 5.ª»","Art. 38 Ley 9/2017: «Los contratos celebrados por los poderes adjudicadores, incluidos los contratos subvencionados a que se refiere el artículo 23, serán inválidos: a) Cuando concurra en ellos alguna de las causas que los invalidan de conformidad con las disposiciones del derecho civil. b) Cuando lo sea alguno de sus actos preparatorios o del procedimiento de adjudicación, por concurrir en los mismos alguna de las causas de derecho administrativo a que se refieren los artículos siguientes. c) En aquellos casos en que la invalidez derive de la ilegalidad de su clausulado.»","Art. 50.1 Ley 9/2017: «El procedimiento de recurso se iniciará mediante escrito que deberá presentarse en el plazo de quince días hábiles.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Concepto y clases de contratos: calificación y contratos típicos","blocks":[{"text":"La Ley 9/2017, de Contratos del Sector Público (LCSP), distingue los contratos típicos, que califica ella misma, del resto de contratos del sector público. Son típicos cinco: obras, concesión de obras, concesión de servicios, suministro y servicios; los demás se califican según las normas de derecho administrativo o privado que les resulten aplicables (art. 12 LCSP). Esta calificación es el punto de partida, porque de ella depende el régimen jurídico de cada contrato y, como veremos, si es administrativo o privado.","refs":[{"ref":"Art. 12 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los contratos de obras, concesión de obras, concesión de servicios, suministro y servicios que celebren las entidades pertenecientes al sector público se calificarán de acuerdo con las normas contenidas en la presente sección."},{"ref":"Art. 12.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los restantes contratos del sector público se calificarán según las normas de derecho administrativo o de derecho privado que les sean de aplicación."}]},{"text":"El contrato de obras tiene por objeto la ejecución de una obra, sola o junto con la redacción del proyecto, y por «obra» se entiende el resultado de trabajos de construcción o ingeniería civil sobre un bien inmueble (art. 13 LCSP). El suministro consiste en adquirir, arrendar o tomar en arrendamiento financiero productos o bienes muebles (art. 16 LCSP). El contrato de servicios tiene por objeto prestaciones de hacer, distintas de una obra o un suministro, y nunca puede comprender servicios que impliquen ejercicio de la autoridad inherente a los poderes públicos (art. 17 LCSP).","refs":[{"ref":"Art. 13.1.a) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La ejecución de una obra, aislada o conjuntamente con la redacción del proyecto, o la realización de alguno de los trabajos enumerados en el Anexo I."},{"ref":"Art. 16.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Son contratos de suministro los que tienen por objeto la adquisición, el arrendamiento financiero, o el arrendamiento, con o sin opción de compra, de productos o bienes muebles."},{"ref":"Art. 17 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Son contratos de servicios aquellos cuyo objeto son prestaciones de hacer consistentes en el desarrollo de una actividad o dirigidas a la obtención de un resultado distinto de una obra o suministro, incluyendo aquellos en que el adjudicatario se obligue a ejecutar el servicio de forma sucesiva y por precio unitario. No podrán ser objeto de estos contratos los servicios que impliquen ejercicio de la autoridad inherente a los poderes públicos."}]},{"text":"En la concesión de servicios, uno o varios poderes adjudicadores encomiendan a título oneroso la gestión de un servicio de su titularidad o competencia, y la contrapartida es el derecho a explotarlo, solo o acompañado de un precio (art. 15.1 LCSP). La clave que la distingue del contrato de servicios es que ese derecho de explotación implica transferir al concesionario el riesgo operacional (art. 15.2 LCSP).","refs":[{"ref":"Art. 15.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"El contrato de concesión de servicios es aquel en cuya virtud uno o varios poderes adjudicadores encomiendan a título oneroso a una o varias personas, naturales o jurídicas, la gestión de un servicio cuya prestación sea de su titularidad o competencia, y cuya contrapartida venga constituida bien por el derecho a explotar los servicios objeto del contrato o bien por dicho derecho acompañado del de percibir un precio."},{"ref":"Art. 15.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"El derecho de explotación de los servicios implicará la transferencia al concesionario del riesgo operacional"}]}]},{"n":"1.1","title":"Contratos administrativos y contratos privados","blocks":[{"text":"Cuando los celebra una Administración Pública, los cinco contratos típicos son administrativos, con dos excepciones que la ley declara privadas: determinados servicios financieros, de creación artística y literaria y de espectáculos identificados por su código CPV, y los que tengan por objeto la suscripción a revistas, publicaciones periódicas y bases de datos (art. 25.1.a LCSP). También son administrativos los declarados así por una ley y los administrativos especiales, vinculados al giro o tráfico específico de la Administración o a una finalidad pública de su competencia (art. 25.1.b LCSP).","refs":[{"ref":"Art. 25.1.a) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los contratos de obra, concesión de obra, concesión de servicios, suministro y servicios. No obstante, tendrán carácter privado los siguientes contratos:"},{"ref":"Art. 25.1.a).2.º LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Aquellos cuyo objeto sea la suscripción a revistas, publicaciones periódicas y bases de datos."}]},{"text":"Los contratos administrativos se rigen por la LCSP en su preparación, adjudicación, efectos, modificación y extinción; supletoriamente, por el resto del derecho administrativo y, en su defecto, por el derecho privado (art. 25.2 LCSP). Son privados, entre otros, los que celebran poderes adjudicadores que no son Administraciones Públicas y las entidades que ni siquiera son poder adjudicador (art. 26.1 LCSP). En los privados de una Administración, la preparación y adjudicación siguen la LCSP, pero los efectos, la modificación y la extinción se rigen por el derecho privado (art. 26.2 LCSP).","refs":[{"ref":"Art. 25.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los contratos administrativos se regirán, en cuanto a su preparación, adjudicación, efectos, modificación y extinción, por esta Ley y sus disposiciones de desarrollo; supletoriamente se aplicarán las restantes normas de derecho administrativo y, en su defecto, las normas de derecho privado."},{"ref":"Art. 26.1.b)-c) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"b) Los celebrados por entidades del sector público que siendo poder adjudicador no reúnan la condición de Administraciones Públicas. c) Los celebrados por entidades del sector público que no reúnan la condición de poder adjudicador."},{"ref":"Art. 26.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"En lo que respecta a su efectos, modificación y extinción, estos contratos se regirán por el derecho privado."}]}]},{"n":"1.2","title":"Necesidad, duración y prórroga","blocks":[{"text":"El sector público solo puede celebrar los contratos necesarios para cumplir sus fines institucionales, y la necesidad y la idoneidad del objeto deben quedar documentadas antes de iniciar la adjudicación (art. 28.1 LCSP). La duración se fija atendiendo a la naturaleza de las prestaciones, a su financiación y a la necesidad de someterlas periódicamente a concurrencia (art. 29.1 LCSP).","refs":[{"ref":"Art. 28.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Las entidades del sector público no podrán celebrar otros contratos que aquellos que sean necesarios para el cumplimiento y realización de sus fines institucionales."},{"ref":"Art. 29.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La duración de los contratos del sector público deberá establecerse teniendo en cuenta la naturaleza de las prestaciones, las características de su financiación y la necesidad de someter periódicamente a concurrencia la realización de las mismas"}]},{"text":"El contrato puede prever prórrogas, que acuerda el órgano de contratación y que son obligatorias para el empresario si el preaviso se produce al menos con dos meses de antelación al final del contrato, salvo que el pliego fije uno mayor; nunca cabe la prórroga tácita (art. 29.2 LCSP). Por eso, si se comunica la prórroga tres meses antes y el pliego no dice otra cosa, el contratista queda obligado. Los contratos de suministros y de servicios de prestación sucesiva duran como máximo cinco años, prórrogas incluidas (art. 29.4 LCSP), y los contratos menores no pueden superar un año ni prorrogarse (art. 29.8 LCSP).","refs":[{"ref":"Art. 29.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La prórroga se acordará por el órgano de contratación y será obligatoria para el empresario, siempre que su preaviso se produzca al menos con dos meses de antelación a la finalización del plazo de duración del contrato, salvo que en el pliego que rija el contrato se establezca uno mayor."},{"ref":"Art. 29.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"En ningún caso podrá producirse la prórroga por el consentimiento tácito de las partes."},{"ref":"Art. 29.4 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los contratos de suministros y de servicios de prestación sucesiva tendrán un plazo máximo de duración de cinco años, incluyendo las posibles prórrogas que en aplicación del apartado segundo de este artículo acuerde el órgano de contratación"},{"ref":"Art. 29.8 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los contratos menores definidos en el apartado primero del artículo 118 no podrán tener una duración superior a un año ni ser objeto de prórroga."}]}]},{"n":"2","title":"Preparación: expediente de contratación y contratos menores","blocks":[{"text":"Toda Administración necesita tramitar previamente un expediente, que inicia el órgano de contratación motivando la necesidad del contrato y que se publica en el perfil de contratante (art. 116.1 LCSP). Al expediente se incorporan los pliegos de cláusulas administrativas particulares y de prescripciones técnicas, el certificado de existencia de crédito y, en su caso, la fiscalización previa de la intervención (art. 116.3 LCSP). En él se justifican, entre otros extremos, la elección del procedimiento, los criterios de solvencia y adjudicación, el valor estimado y, en los servicios, la insuficiencia de medios (art. 116.4 LCSP).","refs":[{"ref":"Art. 116.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La celebración de contratos por parte de las Administraciones Públicas requerirá la previa tramitación del correspondiente expediente, que se iniciará por el órgano de contratación motivando la necesidad del contrato en los términos previstos en el artículo 28 de esta Ley y que deberá ser publicado en el perfil de contratante."},{"ref":"Art. 116.3 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Al expediente se incorporarán el pliego de cláusulas administrativas particulares y el de prescripciones técnicas que hayan de regir el contrato."},{"ref":"Art. 116.4.a) y f) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"a) La elección del procedimiento de licitación. […] f) En los contratos de servicios, el informe de insuficiencia de medios."}]},{"text":"Completado el expediente, el órgano de contratación lo aprueba por resolución motivada, que abre el procedimiento de adjudicación y, en general, aprueba también el gasto (art. 117.1 LCSP). Son contratos menores los de valor estimado inferior a 40.000 euros en obras y a 15.000 euros en suministros o servicios (art. 118.1 LCSP): un servicio de traducción de 14.000 euros es, por tanto, menor. Su expediente exige un informe que motive la necesidad y que no se fracciona el objeto para eludir los umbrales, la aprobación del gasto y la factura (art. 118.2 y 3 LCSP). Estos umbrales son los del texto consolidado vigente; conviene comprobarlos en el BOE, porque la ley ha sido modificada en varias ocasiones.","refs":[{"ref":"Art. 117.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Completado el expediente de contratación, se dictará resolución motivada por el órgano de contratación aprobando el mismo y disponiendo la apertura del procedimiento de adjudicación. Dicha resolución implicará también la aprobación del gasto"},{"ref":"Art. 118.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Se consideran contratos menores los contratos de valor estimado inferior a 40.000 euros, cuando se trate de contratos de obras, o a 15.000 euros, cuando se trate de contratos de suministro o de servicios"},{"ref":"Art. 118.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"En los contratos menores la tramitación del expediente exigirá la emisión de un informe del órgano de contratación justificando de manera motivada la necesidad del contrato y que no se está alterando su objeto con el fin de evitar la aplicación de los umbrales descritos en el apartado anterior."}]}]},{"n":"3","title":"Adjudicación: procedimientos y criterios","blocks":[{"text":"Lo ordinario es adjudicar con una pluralidad de criterios basados en la mejor relación calidad-precio y por el procedimiento abierto o el restringido (art. 131.2 LCSP). Los demás procedimientos (negociado sin publicidad, diálogo competitivo, licitación con negociación, asociación para la innovación) solo caben en los supuestos tasados, y los contratos menores pueden adjudicarse directamente a cualquier empresario con capacidad de obrar y habilitación profesional (art. 131.3 LCSP). La mejor relación calidad-precio se mide con criterios económicos y cualitativos (art. 145.2 LCSP), que deben estar vinculados al objeto del contrato y formularse de manera objetiva (art. 145.5 LCSP).","refs":[{"ref":"Art. 131.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La adjudicación se realizará, ordinariamente utilizando una pluralidad de criterios de adjudicación basados en el principio de mejor relación calidad-precio, y utilizando el procedimiento abierto o el procedimiento restringido"},{"ref":"Art. 131.3 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los contratos menores podrán adjudicarse directamente a cualquier empresario con capacidad de obrar y que cuente con la habilitación profesional necesaria para realizar la prestación"},{"ref":"Art. 145.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La mejor relación calidad-precio se evaluará con arreglo a criterios económicos y cualitativos."},{"ref":"Art. 145.5.a)-b) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"a) En todo caso estarán vinculados al objeto del contrato, en el sentido expresado en el apartado siguiente de este artículo. b) Deberán ser formulados de manera objetiva"}]},{"text":"En el procedimiento abierto cualquier empresario interesado puede presentar proposición y no cabe negociar los términos del contrato (art. 156.1 LCSP). El abierto simplificado exige dos condiciones: un valor estimado igual o inferior a 2.000.000 de euros en obras (en suministros y servicios, inferior a los umbrales de regulación armonizada) y que los criterios sometidos a juicio de valor no existan o no superen el veinticinco por ciento del total, o el cuarenta y cinco por ciento en prestaciones intelectuales (art. 159.1 LCSP). Su anuncio solo se publica en el perfil de contratante y no se exige garantía provisional (art. 159.2 y 159.4.b LCSP). Las cuantías y umbrales se actualizan periódicamente, por lo que deben contrastarse con el texto vigente.","refs":[{"ref":"Art. 156.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"En el procedimiento abierto todo empresario interesado podrá presentar una proposición, quedando excluida toda negociación de los términos del contrato con los licitadores."},{"ref":"Art. 159.1.a) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Que su valor estimado sea igual o inferior a 2.000.000 de euros en el caso de contratos de obras"},{"ref":"Art. 159.1.b) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Que entre los criterios de adjudicación previstos en el pliego no haya ninguno evaluable mediante juicio de valor o, de haberlos, su ponderación no supere el veinticinco por ciento del total, salvo en el caso de que el contrato tenga por objeto prestaciones de carácter intelectual, como los servicios de ingeniería y arquitectura, en que su ponderación no podrá superar el cuarenta y cinco por ciento del total."},{"ref":"Art. 159.4.b) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"No procederá la constitución de garantía provisional por parte de los licitadores."}]}]},{"n":"3.1","title":"Clasificación de las ofertas, adjudicación y formalización","blocks":[{"text":"La mesa de contratación (o, en su defecto, el órgano de contratación) clasifica las proposiciones por orden decreciente y eleva la propuesta (art. 150.1 LCSP). Aceptada la propuesta, se requiere al licitador con la mejor oferta para que presente la documentación justificativa en diez días hábiles desde el siguiente al requerimiento (art. 150.2 LCSP), y el órgano de contratación adjudica dentro de los cinco días hábiles siguientes a recibirla (art. 150.3 LCSP).","refs":[{"ref":"Art. 150.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La mesa de contratación o, en su defecto, el órgano de contratación clasificará, por orden decreciente, las proposiciones presentadas"},{"ref":"Art. 150.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"requerirán al licitador que haya presentado la mejor oferta, de conformidad con lo dispuesto en el artículo 145 para que, dentro del plazo de diez días hábiles, a contar desde el siguiente a aquel en que hubiera recibido el requerimiento, presente la documentación justificativa"},{"ref":"Art. 150.3 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"El órgano de contratación adjudicará el contrato dentro de los cinco días hábiles siguientes a la recepción de la documentación."}]},{"text":"El contrato se formaliza en documento administrativo, que es título suficiente para acceder a cualquier registro público; el contratista puede pedir escritura pública a su costa (art. 153.1 LCSP). Si cabe recurso especial, la formalización no puede hacerse antes de quince días hábiles desde que se remite la notificación de la adjudicación (art. 153.3 LCSP); en los demás casos, debe hacerse no más tarde de los quince días hábiles siguientes a esa notificación. Si el adjudicatario no formaliza por causa suya, se le exige como penalidad el 3 por ciento del presupuesto base de licitación, IVA excluido, y se adjudica al siguiente licitador (art. 153.4 LCSP).","refs":[{"ref":"Art. 153.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los contratos que celebren las Administraciones Públicas deberán formalizarse en documento administrativo que se ajuste con exactitud a las condiciones de la licitación, constituyendo dicho documento título suficiente para acceder a cualquier registro público."},{"ref":"Art. 153.3 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Si el contrato es susceptible de recurso especial en materia de contratación conforme al artículo 44, la formalización no podrá efectuarse antes de que transcurran quince días hábiles desde que se remita la notificación de la adjudicación a los licitadores y candidatos."},{"ref":"Art. 153.4 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Cuando por causas imputables al adjudicatario no se hubiese formalizado el contrato dentro del plazo indicado se le exigirá el importe del 3 por ciento del presupuesto base de licitación, IVA excluido, en concepto de penalidad"}]}]},{"n":"4","title":"Efectos y cumplimiento: prerrogativas, penalidades y demora","blocks":[{"text":"En los contratos administrativos el órgano de contratación tiene prerrogativas: interpretarlos, resolver las dudas sobre su cumplimiento, modificarlos por razones de interés público, declarar la responsabilidad del contratista, suspender la ejecución, acordar la resolución y determinar sus efectos (art. 190 LCSP). Para ejercerlas debe oír al contratista (art. 191.1 LCSP), y se necesita dictamen del Consejo de Estado, entre otros casos, para interpretar, anular o resolver cuando el contratista se opone (art. 191.3.a LCSP). La ejecución se hace a riesgo y ventura del contratista (art. 197 LCSP).","refs":[{"ref":"Art. 190 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"el órgano de contratación ostenta la prerrogativa de interpretar los contratos administrativos, resolver las dudas que ofrezca su cumplimiento, modificarlos por razones de interés público, declarar la responsabilidad imputable al contratista a raíz de la ejecución del contrato, suspender la ejecución del mismo, acordar su resolución y determinar los efectos de esta."},{"ref":"Art. 191.3.a) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La interpretación, nulidad y resolución de los contratos, cuando se formule oposición por parte del contratista."},{"ref":"Art. 197 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La ejecución del contrato se realizará a riesgo y ventura del contratista"}]},{"text":"Para el cumplimiento defectuoso los pliegos pueden prever penalidades proporcionales, sin que cada una supere el 10 por ciento del precio ni el total el 50 por cien (art. 192.1 LCSP). En la demora, el contratista incurre en mora sin intimación previa, y si se retrasa en el plazo total por causa suya la Administración elige entre resolver o imponer penalidades diarias de 0,60 euros por cada 1.000 euros del precio, IVA excluido, salvo otras justificadas en el pliego (art. 193.2 y 3 LCSP). Cada vez que esas penalidades alcanzan un múltiplo del 5 por 100 del precio, puede resolver o seguir con nuevas penalidades (art. 193.4 LCSP). Las penalidades se descuentan de los pagos o de la garantía (art. 194.2 LCSP).","refs":[{"ref":"Art. 192.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"las cuantías de cada una de ellas no podrán ser superiores al 10 por ciento del precio del contrato, IVA excluido, ni el total de las mismas superar el 50 por cien del precio del contrato."},{"ref":"Art. 193.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La constitución en mora del contratista no precisará intimación previa por parte de la Administración."},{"ref":"Art. 193.3 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Cuando el contratista, por causas imputables al mismo, hubiere incurrido en demora respecto al cumplimiento del plazo total, la Administración podrá optar, atendidas las circunstancias del caso, por la resolución del contrato o por la imposición de las penalidades diarias en la proporción de 0,60 euros por cada 1.000 euros del precio del contrato, IVA excluido."},{"ref":"Art. 193.4 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Cada vez que las penalidades por demora alcancen un múltiplo del 5 por 100 del precio del contrato, IVA excluido, el órgano de contratación estará facultado para proceder a la resolución del mismo o acordar la continuidad de su ejecución con imposición de nuevas penalidades."}]}]},{"n":"5","title":"La revisión de precios y otras alteraciones contractuales: la modificación","blocks":[{"text":"Los precios solo pueden revisarse de forma periódica y predeterminada (art. 103.1 LCSP), y solo en obras, suministros de fabricación de armamento y equipamiento, suministro de energía y contratos cuyo periodo de recuperación de la inversión sea de cinco años o más; nunca son revisables las amortizaciones, los costes financieros, los gastos generales ni el beneficio industrial (art. 103.2 LCSP). Salvo en el suministro de energía, la revisión exige haber ejecutado al menos el 20 por ciento del importe y que haya pasado un año desde la formalización (art. 103.5 LCSP).","refs":[{"ref":"Art. 103.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los precios de los contratos del sector público solo podrán ser objeto de revisión periódica y predeterminada en los términos establecidos en este Capítulo."},{"ref":"Art. 103.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"No se considerarán revisables en ningún caso los costes asociados a las amortizaciones, los costes financieros, los gastos generales o de estructura ni el beneficio industrial."},{"ref":"Art. 103.5 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Salvo en los contratos de suministro de energía, cuando proceda, la revisión periódica y predeterminada de precios en los contratos del sector público tendrá lugar en los términos establecidos en este capítulo, cuando el contrato se hubiese ejecutado, al menos, en el 20 por ciento de su importe y hubiese transcurrido un año desde su formalización."}]},{"text":"La modificación solo cabe por razones de interés público y durante la vigencia del contrato en dos supuestos: si está prevista en el pliego (art. 204) o, excepcionalmente, si no está prevista pero se cumplen las condiciones del art. 205; fuera de ellos hay que resolver y licitar de nuevo (art. 203.2 LCSP). La modificación prevista puede llegar al veinte por ciento del precio inicial (art. 204.1 LCSP). Entre las no previstas, añadir obras, suministros o servicios adicionales exige que el cambio de contratista no sea posible y que la alteración no exceda del 50 por ciento del precio inicial, IVA excluido (art. 205.2.a LCSP).","refs":[{"ref":"Art. 203.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los contratos administrativos celebrados por los órganos de contratación solo podrán modificarse durante su vigencia cuando se dé alguno de los siguientes supuestos: a) Cuando así se haya previsto en el pliego de cláusulas administrativas particulares, en los términos y condiciones establecidos en el artículo 204; b) Excepcionalmente, cuando sea necesario realizar una modificación que no esté prevista en el pliego de cláusulas administrativas particulares, siempre y cuando se cumplan las condiciones que establece el artículo 205."},{"ref":"Art. 204.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los contratos de las Administraciones Públicas podrán modificarse durante su vigencia hasta un máximo del veinte por ciento del precio inicial cuando en los pliegos de cláusulas administrativas particulares se hubiere advertido expresamente de esta posibilidad"},{"ref":"Art. 205.2.a).2.º LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Que la modificación del contrato implique una alteración en su cuantía que no exceda, aislada o conjuntamente con otras modificaciones acordadas conforme a este artículo, del 50 por ciento de su precio inicial, IVA excluido."}]}]},{"n":"6","title":"Extinción: cumplimiento, recepción y resolución","blocks":[{"text":"Los contratos se extinguen por cumplimiento o por resolución (art. 209 LCSP). Hay cumplimiento cuando el contratista ha realizado toda la prestación a satisfacción de la Administración, que debe constatarlo con un acto formal y positivo de recepción o conformidad dentro del mes siguiente a la entrega, o en el plazo del pliego (art. 210.1 y 2 LCSP). Desde la recepción corre un plazo de garantía; si transcurre sin objeciones, se extingue la responsabilidad del contratista (art. 210.3 LCSP).","refs":[{"ref":"Art. 209 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los contratos se extinguirán por su cumplimiento o por resolución"},{"ref":"Art. 210.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"En todo caso, su constatación exigirá por parte de la Administración un acto formal y positivo de recepción o conformidad dentro del mes siguiente a la entrega o realización del objeto del contrato, o en el plazo que se determine en el pliego de cláusulas administrativas particulares por razón de sus características."},{"ref":"Art. 210.3 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"En los contratos se fijará un plazo de garantía a contar de la fecha de recepción o conformidad"}]},{"text":"Son causas de resolución, entre otras, la muerte o incapacidad del contratista individual, el concurso o la insolvencia, el mutuo acuerdo, la demora del contratista, la demora en el pago de la Administración más allá del plazo legal y el incumplimiento de la obligación principal (art. 211.1 LCSP). La acuerda el órgano de contratación, de oficio o a instancia del contratista (art. 212.1 LCSP). Si se resuelve por incumplimiento culpable del contratista, se le incauta la garantía y debe indemnizar los daños en lo que excedan de ella (art. 213.3 LCSP); si el incumplidor es la Administración, esta paga los daños y perjuicios (art. 213.2 LCSP).","refs":[{"ref":"Art. 211.1.c), d) y f) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"c) El mutuo acuerdo entre la Administración y el contratista. d) La demora en el cumplimiento de los plazos por parte del contratista."},{"ref":"Art. 211.1.f) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"El incumplimiento de la obligación principal del contrato."},{"ref":"Art. 212.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La resolución del contrato se acordará por el órgano de contratación, de oficio o a instancia del contratista"},{"ref":"Art. 213.3 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Cuando el contrato se resuelva por incumplimiento culpable del contratista le será incautada la garantía y deberá, además, indemnizar a la Administración los daños y perjuicios ocasionados en lo que excedan del importe de la garantía incautada."}]}]},{"n":"7","title":"Régimen de invalidez","blocks":[{"text":"Los contratos de los poderes adjudicadores son inválidos por causas de derecho civil, por vicios de derecho administrativo en sus actos preparatorios o de adjudicación, o por ilegalidad de su clausulado (art. 38 LCSP). Son nulos de pleno derecho por las causas del art. 47 de la Ley 39/2015 y, además, por las propias de la LCSP (art. 39 LCSP): por ejemplo, la falta de capacidad o solvencia del adjudicatario, la carencia o insuficiencia de crédito (salvo emergencia) o la falta de publicación del anuncio de licitación cuando sea preceptiva. Las demás infracciones son causas de anulabilidad, entre ellas incumplir los requisitos de modificación de los arts. 204 y 205 (art. 40 LCSP).","refs":[{"ref":"Art. 38 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"a) Cuando concurra en ellos alguna de las causas que los invalidan de conformidad con las disposiciones del derecho civil. b) Cuando lo sea alguno de sus actos preparatorios o del procedimiento de adjudicación, por concurrir en los mismos alguna de las causas de derecho administrativo a que se refieren los artículos siguientes. c) En aquellos casos en que la invalidez derive de la ilegalidad de su clausulado."},{"ref":"Art. 39.2.b) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La carencia o insuficiencia de crédito, de conformidad con lo establecido en la Ley 47/2003, de 26 de noviembre, General Presupuestaria, o en las normas presupuestarias de las restantes Administraciones Públicas sujetas a esta Ley, salvo los supuestos de emergencia."},{"ref":"Art. 40.a) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"El incumplimiento de las circunstancias y requisitos exigidos para la modificación de los contratos en los artículos 204 y 205."}]}]},{"n":"8","title":"Recurso especial en materia de contratación","blocks":[{"text":"El recurso especial cabe en contratos de obras de valor estimado superior a tres millones de euros, de suministro y servicios superior a cien mil euros y en concesiones de más de tres millones, entre otros (art. 44.1 LCSP). Son recurribles los anuncios y pliegos, ciertos actos de trámite cualificados, la adjudicación, las modificaciones que debieron licitarse, los encargos a medios propios irregulares y el rescate de concesiones (art. 44.2 LCSP). Es potestativo y gratuito, y contra esos actos no proceden los recursos administrativos ordinarios (art. 44.5 y 7 LCSP). Estas cuantías son las del texto consolidado y pueden actualizarse.","refs":[{"ref":"Art. 44.1.a) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Contratos de obras cuyo valor estimado sea superior a tres millones de euros, y de suministro y servicios, que tenga un valor estimado superior a cien mil euros."},{"ref":"Art. 44.5 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Contra las actuaciones mencionadas en el presente artículo como susceptibles de ser impugnadas mediante el recurso especial, no procederá la interposición de recursos administrativos ordinarios."},{"ref":"Art. 44.7 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La interposición del recurso especial en materia de contratación tendrá carácter potestativo y será gratuito para los recurrentes."}]},{"text":"Se inicia mediante escrito presentado en quince días hábiles, cuyo cómputo depende del acto: contra la adjudicación, desde el día siguiente a su notificación; contra el anuncio, desde el siguiente a su publicación en el perfil de contratante (art. 50.1 LCSP).","refs":[{"ref":"Art. 50.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"El procedimiento de recurso se iniciará mediante escrito que deberá presentarse en el plazo de quince días hábiles."},{"ref":"Art. 50.1.a) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Cuando se interponga contra el anuncio de licitación, el plazo comenzará a contarse a partir del día siguiente al de su publicación en el perfil de contratante."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Concesión de servicios = derecho de explotación que transfiere al concesionario el riesgo operacional.","refs":[{"ref":"Art. 15.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"El derecho de explotación de los servicios implicará la transferencia al concesionario del riesgo operacional"}]},{"text":"Suministros y servicios de prestación sucesiva: máximo cinco años con prórrogas; la prórroga obliga con dos meses de preaviso.","refs":[{"ref":"Art. 29.4 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"tendrán un plazo máximo de duración de cinco años, incluyendo las posibles prórrogas"}]},{"text":"Contrato menor: menos de 40.000 euros en obras y de 15.000 euros en suministros y servicios (cifras del texto consolidado).","refs":[{"ref":"Art. 118.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Se consideran contratos menores los contratos de valor estimado inferior a 40.000 euros, cuando se trate de contratos de obras, o a 15.000 euros, cuando se trate de contratos de suministro o de servicios"}]},{"text":"Formalización con recurso especial posible: no antes de quince días hábiles; si el adjudicatario no formaliza, penalidad del 3 por ciento del presupuesto base de licitación.","refs":[{"ref":"Art. 153.4 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"se le exigirá el importe del 3 por ciento del presupuesto base de licitación, IVA excluido, en concepto de penalidad"}]},{"text":"Demora: 0,60 euros por cada 1.000 euros diarios; cada múltiplo del 5 por 100, opción de resolver o seguir.","refs":[{"ref":"Art. 193.3 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"penalidades diarias en la proporción de 0,60 euros por cada 1.000 euros del precio del contrato, IVA excluido."}]},{"text":"Revisión de precios: 20 por ciento ejecutado y un año desde la formalización; el beneficio industrial nunca es revisable.","refs":[{"ref":"Art. 103.5 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"cuando el contrato se hubiese ejecutado, al menos, en el 20 por ciento de su importe y hubiese transcurrido un año desde su formalización."}]},{"text":"Modificación prevista: hasta el 20 por ciento; no prevista por prestaciones adicionales: hasta el 50 por ciento del precio inicial.","refs":[{"ref":"Art. 204.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"hasta un máximo del veinte por ciento del precio inicial"}]},{"text":"Recepción: acto formal y positivo dentro del mes siguiente a la entrega. Recurso especial: quince días hábiles.","refs":[{"ref":"Art. 50.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"deberá presentarse en el plazo de quince días hábiles."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902', null, null, null, null
