insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Procedimientos y formas de la actividad administrativa: limitación, arbitraje, servicio público y fomento"},{"n":"2","title":"La actividad de limitación o policía: principios de intervención (art. 4 Ley 40/2015; art. 84 Ley 7/1985)"},{"n":"2.1","title":"Declaración responsable y comunicación (art. 69 Ley 39/2015)"},{"n":"2.2","title":"Potestad sancionadora (arts. 25-31 Ley 40/2015) y ejecución forzosa (arts. 99-104 Ley 39/2015)"},{"n":"3","title":"La actividad arbitral: sustitución de recursos y terminación convencional (arts. 86 y 112.2 Ley 39/2015)"},{"n":"4","title":"La actividad de servicio público: concesión de servicios (arts. 15, 29.6 y 284-288 Ley 9/2017)"},{"n":"5","title":"Formas de gestión de los servicios públicos: gestión directa e indirecta; reserva de servicios (arts. 85-86 Ley 7/1985)"},{"n":"6","title":"La actividad de fomento: subvenciones, plan estratégico y procedimientos de concesión (arts. 2, 8 y 22 Ley 38/2003)"}]'::jsonb, '["Art. 4.1 Ley 40/2015: «Las Administraciones Públicas que, en el ejercicio de sus respectivas competencias, establezcan medidas que limiten el ejercicio de derechos individuales o colectivos o exijan el cumplimiento de requisitos para el desarrollo de una actividad, deberán aplicar el principio de proporcionalidad y elegir la medida menos restrictiva, motivar su necesidad para la protección del interés público así como justificar su adecuación para lograr los fines que se persiguen, sin que en ningún caso se produzcan diferencias de trato discriminatorias.»","Art. 84.1 Ley 7/1985: «Las Entidades locales podrán intervenir la actividad de los ciudadanos a través de los siguientes medios: a) Ordenanzas y bandos.»","Art. 69.1 Ley 39/2015: «se entenderá por declaración responsable el documento suscrito por un interesado en el que éste manifiesta, bajo su responsabilidad, que cumple con los requisitos establecidos en la normativa vigente para obtener el reconocimiento de un derecho o facultad o para su ejercicio, que dispone de la documentación que así lo acredita, que la pondrá a disposición de la Administración cuando le sea requerida, y que se compromete a mantener el cumplimiento de las anteriores obligaciones durante el período de tiempo inherente a dicho reconocimiento o ejercicio.»","Art. 69.3 Ley 39/2015: «Las declaraciones responsables y las comunicaciones permitirán, el reconocimiento o ejercicio de un derecho o bien el inicio de una actividad, desde el día de su presentación, sin perjuicio de las facultades de comprobación, control e inspección que tengan atribuidas las Administraciones Públicas.»","Art. 25.1 Ley 40/2015: «La potestad sancionadora de las Administraciones Públicas se ejercerá cuando haya sido expresamente reconocida por una norma con rango de Ley»","Art. 31.1 Ley 40/2015: «No podrán sancionarse los hechos que lo hayan sido penal o administrativamente, en los casos en que se aprecie identidad del sujeto, hecho y fundamento.»","Art. 100.1 Ley 39/2015: «La ejecución forzosa por las Administraciones Públicas se efectuará, respetando siempre el principio de proporcionalidad, por los siguientes medios: a) Apremio sobre el patrimonio. b) Ejecución subsidiaria. c) Multa coercitiva. d) Compulsión sobre las personas.»","Art. 86.1 Ley 39/2015: «Las Administraciones Públicas podrán celebrar acuerdos, pactos, convenios o contratos con personas tanto de Derecho público como privado, siempre que no sean contrarios al ordenamiento jurídico ni versen sobre materias no susceptibles de transacción y tengan por objeto satisfacer el interés público que tienen encomendado»","Art. 112.2 Ley 39/2015: «Las leyes podrán sustituir el recurso de alzada, en supuestos o ámbitos sectoriales determinados, y cuando la especificidad de la materia así lo justifique, por otros procedimientos de impugnación, reclamación, conciliación, mediación y arbitraje, ante órganos colegiados o Comisiones específicas no sometidas a instrucciones jerárquicas»","Art. 284.1 Ley 9/2017: «La Administración podrá gestionar indirectamente, mediante contrato de concesión de servicios, los servicios de su titularidad o competencia siempre que sean susceptibles de explotación económica por particulares. En ningún caso podrán prestarse mediante concesión de servicios los que impliquen ejercicio de la autoridad inherente a los poderes públicos.»","Art. 287.2 Ley 9/2017: «En el caso de que la concesión recaiga sobre un servicio público, la Administración conservará los poderes de policía necesarios para asegurar la buena marcha de los servicios de que se trate.»","Art. 85.1 Ley 7/1985: «Son servicios públicos locales los que prestan las entidades locales en el ámbito de sus competencias.»","Art. 86.2 Ley 7/1985: «Se declara la reserva en favor de las Entidades Locales de las siguientes actividades o servicios esenciales: abastecimiento domiciliario y depuración de aguas; recogida, tratamiento y aprovechamiento de residuos, y transporte público de viajeros, de conformidad con lo previsto en la legislación sectorial aplicable.»","Art. 2.1 Ley 38/2003: «Se entiende por subvención, a los efectos de esta ley, toda disposición dineraria realizada por cualesquiera de los sujetos contemplados en el artículo 3 de esta ley, a favor de personas públicas o privadas, y que cumpla los siguientes requisitos: a) Que la entrega se realice sin contraprestación directa de los beneficiarios.»","Art. 8.3 Ley 38/2003: «La gestión de las subvenciones a que se refiere esta ley se realizará de acuerdo con los siguientes principios: a) Publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación. b) Eficacia en el cumplimiento de los objetivos fijados por la Administración otorgante.»","Art. 22.1 Ley 38/2003: «El procedimiento ordinario de concesión de subvenciones se tramitará en régimen de concurrencia competitiva.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Procedimientos y formas de la actividad administrativa","blocks":[{"text":"La Administración sirve con objetividad los intereses generales con sometimiento pleno a la ley y al Derecho (art. 103.1 CE), y para ello actúa de formas muy distintas. El programa agrupa esa actividad en cuatro grandes formas, siguiendo la clasificación tradicional de la doctrina: la limitación o policía (la Administración condiciona o controla la actividad de los particulares), la actividad arbitral (decide o media en conflictos entre particulares), el servicio público (la Administración asume una actividad como propia y la presta directamente o a través de un concesionario) y el fomento (estimula actividades privadas de interés público, sobre todo con subvenciones). La clasificación es doctrinal; las leyes no la recogen como tal, pero sí regulan cada una de sus técnicas, que son las que estudiamos en este tema.","refs":[{"ref":"Art. 103.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho."}]}]},{"n":"2","title":"La actividad de limitación o policía: principios de intervención","blocks":[{"text":"Cuando una Administración limita derechos o exige requisitos para desarrollar una actividad, la Ley 40/2015 le impone tres deberes: aplicar el principio de proporcionalidad eligiendo la medida menos restrictiva, motivar su necesidad para proteger el interés público y justificar su adecuación a los fines, sin diferencias de trato discriminatorias (art. 4.1 LRJSP). A cambio, puede comprobar, verificar, investigar e inspeccionar los hechos y circunstancias necesarios para velar por el cumplimiento de los requisitos (art. 4.2 LRJSP).","refs":[{"ref":"Art. 4.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Las Administraciones Públicas que, en el ejercicio de sus respectivas competencias, establezcan medidas que limiten el ejercicio de derechos individuales o colectivos o exijan el cumplimiento de requisitos para el desarrollo de una actividad, deberán aplicar el principio de proporcionalidad y elegir la medida menos restrictiva, motivar su necesidad para la protección del interés público así como justificar su adecuación para lograr los fines que se persiguen, sin que en ningún caso se produzcan diferencias de trato discriminatorias."},{"ref":"Art. 4.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"podrán, en el ámbito de sus respectivas competencias y con los límites establecidos en la legislación de protección de datos de carácter personal, comprobar, verificar, investigar e inspeccionar los hechos, actos, elementos, actividades, estimaciones y demás circunstancias que fueran necesarias."}]},{"text":"En el ámbito local, la Ley 7/1985 (LBRL) enumera los medios de intervención: ordenanzas y bandos; licencia previa y otros controles preventivos; comunicación previa o declaración responsable; control posterior al inicio de la actividad; y órdenes individuales de mandato o prohibición (art. 84.1 LBRL). Esa intervención se rige por la igualdad de trato, la necesidad y la proporcionalidad (art. 84.2 LBRL), y como regla general las actividades no se someten a licencia, que solo se admite por razones tasadas como el orden público, la salud pública o el medio ambiente (art. 84 bis LBRL). Ojo: el art. 84.1.c LBRL todavía remite al art. 71 bis de la Ley 30/1992, hoy derogada; la regulación vigente de la declaración responsable está en el art. 69 de la Ley 39/2015.","refs":[{"ref":"Art. 84.1 LBRL","law":"Ley 7/1985","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Las Entidades locales podrán intervenir la actividad de los ciudadanos a través de los siguientes medios: a) Ordenanzas y bandos. b) Sometimiento a previa licencia y otros actos de control preventivo."},{"ref":"Art. 84.1.d)-e) LBRL","law":"Ley 7/1985","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"d) Sometimiento a control posterior al inicio de la actividad, a efectos de verificar el cumplimiento de la normativa reguladora de la misma. e) Órdenes individuales constitutivas de mandato para la ejecución de un acto o la prohibición del mismo."},{"ref":"Art. 84 bis.1 LBRL","law":"Ley 7/1985","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"con carácter general, el ejercicio de actividades no se someterá a la obtención de licencia u otro medio de control preventivo."}]}]},{"n":"2.1","title":"Declaración responsable y comunicación","blocks":[{"text":"La declaración responsable es el documento con el que el interesado manifiesta, bajo su responsabilidad, que cumple los requisitos exigidos, que tiene la documentación que lo acredita, que la pondrá a disposición de la Administración cuando se le pida y que mantendrá su cumplimiento (art. 69.1 LPAC). La comunicación es el documento con el que el interesado pone en conocimiento de la Administración sus datos identificativos u otros datos relevantes para iniciar una actividad o ejercer un derecho (art. 69.2 LPAC).","refs":[{"ref":"Art. 69.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se entenderá por declaración responsable el documento suscrito por un interesado en el que éste manifiesta, bajo su responsabilidad, que cumple con los requisitos establecidos en la normativa vigente para obtener el reconocimiento de un derecho o facultad o para su ejercicio, que dispone de la documentación que así lo acredita, que la pondrá a disposición de la Administración cuando le sea requerida, y que se compromete a mantener el cumplimiento de las anteriores obligaciones durante el período de tiempo inherente a dicho reconocimiento o ejercicio."},{"ref":"Art. 69.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se entenderá por comunicación aquel documento mediante el que los interesados ponen en conocimiento de la Administración Pública competente sus datos identificativos o cualquier otro dato relevante para el inicio de una actividad o el ejercicio de un derecho."}]},{"text":"Ambas permiten ejercer el derecho o iniciar la actividad desde el día de su presentación, sin perjuicio de las facultades de comprobación, control e inspección de la Administración (art. 69.3 LPAC). Si hay inexactitud, falsedad u omisión esencial en cualquier dato, o no se presentan, no se puede continuar con la actividad desde que se tenga constancia de ello, además de las responsabilidades que procedan (art. 69.4 LPAC). Para una misma actividad solo puede exigirse una de las dos, nunca ambas acumulativamente (art. 69.6 LPAC).","refs":[{"ref":"Art. 69.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las declaraciones responsables y las comunicaciones permitirán, el reconocimiento o ejercicio de un derecho o bien el inicio de una actividad, desde el día de su presentación, sin perjuicio de las facultades de comprobación, control e inspección que tengan atribuidas las Administraciones Públicas."},{"ref":"Art. 69.4 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"determinará la imposibilidad de continuar con el ejercicio del derecho o actividad afectada desde el momento en que se tenga constancia de tales hechos"},{"ref":"Art. 69.6 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Únicamente será exigible, bien una declaración responsable, bien una comunicación para iniciar una misma actividad u obtener el reconocimiento de un mismo derecho o facultad para su ejercicio, sin que sea posible la exigencia de ambas acumulativamente."}]}]},{"n":"2.2","title":"La potestad sancionadora","blocks":[{"text":"La potestad sancionadora es la herramienta más intensa de la limitación. Rige el principio de legalidad: solo se ejerce si una norma con rango de ley la reconoce expresamente (art. 25.1 LRJSP). Rigen también la irretroactividad, salvo de lo favorable al infractor (art. 26 LRJSP), y la tipicidad: solo son infracciones las previstas por una ley, que las clasifica en leves, graves y muy graves (art. 27.1 LRJSP). Solo se sanciona a quien sea responsable a título de dolo o culpa (art. 28.1 LRJSP), y ninguna sanción administrativa puede implicar privación de libertad (art. 29.1 LRJSP).","refs":[{"ref":"Art. 25.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"La potestad sancionadora de las Administraciones Públicas se ejercerá cuando haya sido expresamente reconocida por una norma con rango de Ley"},{"ref":"Art. 26.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Las disposiciones sancionadoras producirán efecto retroactivo en cuanto favorezcan al presunto infractor o al infractor"},{"ref":"Art. 27.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Las infracciones administrativas se clasificarán por la Ley en leves, graves y muy graves."},{"ref":"Art. 29.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Las sanciones administrativas, sean o no de naturaleza pecuniaria, en ningún caso podrán implicar, directa o subsidiariamente, privación de libertad."}]},{"text":"Si la ley no fija plazos de prescripción, las infracciones muy graves prescriben a los tres años, las graves a los dos y las leves a los seis meses; las sanciones por faltas muy graves, a los tres años, por graves a los dos y por leves al año (art. 30.1 LRJSP). Por el principio non bis in idem, no se pueden sancionar hechos ya sancionados penal o administrativamente cuando hay identidad de sujeto, hecho y fundamento (art. 31.1 LRJSP).","refs":[{"ref":"Art. 30.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Si éstas no fijan plazos de prescripción, las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses; las sanciones impuestas por faltas muy graves prescribirán a los tres años, las impuestas por faltas graves a los dos años y las impuestas por faltas leves al año."},{"ref":"Art. 31.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"No podrán sancionarse los hechos que lo hayan sido penal o administrativamente, en los casos en que se aprecie identidad del sujeto, hecho y fundamento."}]}]},{"n":"2.3","title":"La ejecución forzosa","blocks":[{"text":"Si el particular no cumple voluntariamente, la Administración puede ejecutar forzosamente sus actos, previo apercibimiento (art. 99 LPAC). Los medios son cuatro: apremio sobre el patrimonio, ejecución subsidiaria, multa coercitiva y compulsión sobre las personas, siempre respetando la proporcionalidad; si caben varios, se elige el menos restrictivo de la libertad individual (art. 100 LPAC). Para entrar en un domicilio hace falta el consentimiento del titular o autorización judicial (art. 100.3 LPAC).","refs":[{"ref":"Art. 99 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las Administraciones Públicas, a través de sus órganos competentes en cada caso, podrán proceder, previo apercibimiento, a la ejecución forzosa de los actos administrativos"},{"ref":"Art. 100.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La ejecución forzosa por las Administraciones Públicas se efectuará, respetando siempre el principio de proporcionalidad, por los siguientes medios: a) Apremio sobre el patrimonio. b) Ejecución subsidiaria. c) Multa coercitiva. d) Compulsión sobre las personas."},{"ref":"Art. 100.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Si fueran varios los medios de ejecución admisibles se elegirá el menos restrictivo de la libertad individual."}]},{"text":"La ejecución subsidiaria procede en actos no personalísimos, que puede realizar otra persona: la Administración los hace por sí o a través de quien determine, a costa del obligado (art. 102 LPAC). Es el caso del propietario que no retira unos escombros y la Administración encarga a una empresa retirarlos a su costa. La multa coercitiva exige autorización legal, se reitera por lapsos de tiempo y es compatible con las sanciones (art. 103 LPAC); la compulsión directa sobre las personas solo cabe cuando la ley lo autoriza expresamente y con respeto a su dignidad (art. 104.1 LPAC).","refs":[{"ref":"Art. 102.1-2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Habrá lugar a la ejecución subsidiaria cuando se trate de actos que por no ser personalísimos puedan ser realizados por sujeto distinto del obligado. 2\\. En este caso, las Administraciones Públicas realizarán el acto, por sí o a través de las personas que determinen, a costa del obligado."},{"ref":"Art. 103.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La multa coercitiva es independiente de las sanciones que puedan imponerse con tal carácter y compatible con ellas."}]}]},{"n":"3","title":"La actividad arbitral: sustitución de recursos y terminación convencional","blocks":[{"text":"La Ley 39/2015 abre la puerta a fórmulas arbitrales en dos lugares. Primero, las leyes pueden sustituir el recurso de alzada, en ámbitos sectoriales concretos y cuando la materia lo justifique, por procedimientos de impugnación, reclamación, conciliación, mediación y arbitraje ante órganos colegiados o comisiones específicas no sometidas a instrucciones jerárquicas (art. 112.2 LPAC). También el recurso de reposición puede sustituirse, respetando su carácter potestativo.","refs":[{"ref":"Art. 112.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las leyes podrán sustituir el recurso de alzada, en supuestos o ámbitos sectoriales determinados, y cuando la especificidad de la materia así lo justifique, por otros procedimientos de impugnación, reclamación, conciliación, mediación y arbitraje, ante órganos colegiados o Comisiones específicas no sometidas a instrucciones jerárquicas"},{"ref":"Art. 112.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"En las mismas condiciones, el recurso de reposición podrá ser sustituido por los procedimientos a que se refiere el párrafo anterior, respetando su carácter potestativo para el interesado."}]},{"text":"Segundo, la terminación convencional: la Administración puede celebrar acuerdos, pactos, convenios o contratos con personas públicas o privadas, siempre que no sean contrarios al ordenamiento ni versen sobre materias no susceptibles de transacción y persigan el interés público (art. 86.1 LPAC). Deben identificar a las partes, su ámbito y su vigencia (art. 86.2 LPAC), y los que versen sobre materias de competencia directa del Consejo de Ministros requieren en todo caso su aprobación expresa (art. 86.3 LPAC). Estos acuerdos no alteran las competencias de los órganos ni las responsabilidades de autoridades y funcionarios (art. 86.4 LPAC).","refs":[{"ref":"Art. 86.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las Administraciones Públicas podrán celebrar acuerdos, pactos, convenios o contratos con personas tanto de Derecho público como privado, siempre que no sean contrarios al ordenamiento jurídico ni versen sobre materias no susceptibles de transacción y tengan por objeto satisfacer el interés público que tienen encomendado"},{"ref":"Art. 86.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Requerirán en todo caso la aprobación expresa del Consejo de Ministros u órgano equivalente de las Comunidades Autónomas, los acuerdos que versen sobre materias de la competencia directa de dicho órgano."}]}]},{"n":"4","title":"La actividad de servicio público: la concesión de servicios","blocks":[{"text":"Cuando la Administración no presta el servicio con sus propios medios, puede gestionarlo indirectamente mediante el contrato de concesión de servicios (art. 15 LCSP), en el que el concesionario asume el riesgo operacional. Solo cabe para servicios susceptibles de explotación económica por particulares y nunca para los que impliquen ejercicio de la autoridad inherente a los poderes públicos (art. 284.1 LCSP). Si se trata de un servicio público, antes de contratar debe haberse establecido su régimen jurídico, que declare expresamente que la Administración asume la actividad como propia (art. 284.2 LCSP).","refs":[{"ref":"Art. 15.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"El derecho de explotación de los servicios implicará la transferencia al concesionario del riesgo operacional"},{"ref":"Art. 284.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La Administración podrá gestionar indirectamente, mediante contrato de concesión de servicios, los servicios de su titularidad o competencia siempre que sean susceptibles de explotación económica por particulares. En ningún caso podrán prestarse mediante concesión de servicios los que impliquen ejercicio de la autoridad inherente a los poderes públicos."},{"ref":"Art. 284.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"deberá haberse establecido su régimen jurídico, que declare expresamente que la actividad de que se trata queda asumida por la Administración respectiva como propia de la misma"}]},{"text":"Sobre un servicio público concedido, la Administración conserva los poderes de policía necesarios para asegurar su buena marcha (art. 287.2 LCSP). El concesionario debe prestar el servicio con la continuidad convenida y, si el contrato se extingue por cumplimiento, seguir prestándolo hasta que se formalice el nuevo; también debe cuidar del buen orden del servicio e indemnizar los daños a terceros, salvo los imputables a la Administración (art. 288 LCSP). La duración es limitada: si supera cinco años, no puede exceder, prórrogas incluidas, de cuarenta años si comprende obras y explotación, veinticinco si es un servicio no sanitario y diez si es sanitario (art. 29.6 LCSP).","refs":[{"ref":"Art. 287.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"En el caso de que la concesión recaiga sobre un servicio público, la Administración conservará los poderes de policía necesarios para asegurar la buena marcha de los servicios de que se trate."},{"ref":"Art. 288.a) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"En caso de extinción del contrato por cumplimiento del mismo, el contratista deberá seguir prestando el servicio hasta que se formalice el nuevo contrato."},{"ref":"Art. 29.6.b) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Veinticinco años en los contratos de concesión de servicios que comprendan la explotación de un servicio no relacionado con la prestación de servicios sanitarios."}]}]},{"n":"5","title":"Formas de gestión de los servicios públicos: gestión directa e indirecta","blocks":[{"text":"La LBRL define los servicios públicos locales como los que prestan las entidades locales en el ámbito de sus competencias, y exige gestionarlos de la forma más sostenible y eficiente (art. 85 LBRL). La gestión directa puede hacerse por la propia entidad local, por un organismo autónomo local, por una entidad pública empresarial local o por una sociedad mercantil local de capital público; las dos últimas solo si una memoria justificativa acredita que son más sostenibles y eficientes que las dos primeras (art. 85.2.A LBRL).","refs":[{"ref":"Art. 85.1 LBRL","law":"Ley 7/1985","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Son servicios públicos locales los que prestan las entidades locales en el ámbito de sus competencias."},{"ref":"Art. 85.2.A) LBRL","law":"Ley 7/1985","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"a) Gestión por la propia Entidad Local. b) Organismo autónomo local. c) Entidad pública empresarial local. d) Sociedad mercantil local, cuyo capital social sea de titularidad pública."}]},{"text":"La gestión indirecta se hace mediante las formas contractuales previstas en la legislación de contratos (art. 85.2.B LBRL). El texto consolidado de la LBRL aún remite al antiguo contrato de gestión de servicios públicos del Real Decreto Legislativo 3/2011, derogado; hoy esa función la cumple la concesión de servicios de la Ley 9/2017 (apartado 4). Además, la LBRL reserva a las entidades locales servicios esenciales como el abastecimiento domiciliario y depuración de aguas, la recogida, tratamiento y aprovechamiento de residuos y el transporte público de viajeros; para prestarlos en monopolio hace falta acuerdo del pleno y aprobación de la Comunidad Autónoma (art. 86.2 LBRL).","refs":[{"ref":"Art. 85.2.B) LBRL","law":"Ley 7/1985","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Gestión indirecta, mediante las distintas formas previstas para el contrato de gestión de servicios públicos en el texto refundido de la Ley de Contratos del Sector Público, aprobado por Real Decreto Legislativo 3/2011, de 14 de noviembre."},{"ref":"Art. 86.2 LBRL","law":"Ley 7/1985","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Se declara la reserva en favor de las Entidades Locales de las siguientes actividades o servicios esenciales: abastecimiento domiciliario y depuración de aguas; recogida, tratamiento y aprovechamiento de residuos, y transporte público de viajeros, de conformidad con lo previsto en la legislación sectorial aplicable."},{"ref":"Art. 86.2 LBRL","law":"Ley 7/1985","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"La efectiva ejecución de estas actividades en régimen de monopolio requiere, además del acuerdo de aprobación del pleno de la correspondiente Corporación local, la aprobación por el órgano competente de la Comunidad Autónoma."}]}]},{"n":"6","title":"La actividad de fomento: las subvenciones","blocks":[{"text":"La técnica principal del fomento es la subvención: toda disposición dineraria a favor de personas públicas o privadas que se entrega sin contraprestación directa de los beneficiarios, sujeta al cumplimiento de un objetivo, proyecto, actividad o comportamiento, y destinada a fomentar una actividad de utilidad pública o interés social (art. 2.1 Ley 38/2003, General de Subvenciones, LGS). No son subvenciones, por ejemplo, las prestaciones de la Seguridad Social ni los beneficios fiscales (art. 2.4 LGS).","refs":[{"ref":"Art. 2.1 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"Se entiende por subvención, a los efectos de esta ley, toda disposición dineraria realizada por cualesquiera de los sujetos contemplados en el artículo 3 de esta ley, a favor de personas públicas o privadas, y que cumpla los siguientes requisitos: a) Que la entrega se realice sin contraprestación directa de los beneficiarios."},{"ref":"Art. 2.1.c) LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"Que el proyecto, la acción, conducta o situación financiada tenga por objeto el fomento de una actividad de utilidad pública o interés social o de promoción de una finalidad pública."},{"ref":"Art. 2.4.g) LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"Los beneficios fiscales y beneficios en la cotización a la Seguridad Social."}]},{"text":"Antes de establecer subvenciones, el órgano que las propone debe concretar en un plan estratégico de subvenciones los objetivos y efectos, el plazo, los costes previsibles y sus fuentes de financiación (art. 8.1 LGS). La gestión se rige por la publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación, la eficacia y la eficiencia (art. 8.3 LGS).","refs":[{"ref":"Art. 8.1 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"deberán concretar en un plan estratégico de subvenciones los objetivos y efectos que se pretenden con su aplicación, el plazo necesario para su consecución, los costes previsibles y sus fuentes de financiación"},{"ref":"Art. 8.3 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"a) Publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación. b) Eficacia en el cumplimiento de los objetivos fijados por la Administración otorgante. c) Eficiencia en la asignación y utilización de los recursos públicos."}]},{"text":"El procedimiento ordinario de concesión es la concurrencia competitiva, que compara las solicitudes y establece una prelación según los criterios de las bases y la convocatoria (art. 22.1 LGS). Pueden concederse de forma directa tres tipos: las nominativas, cuya dotación y beneficiario figuran en los estados de gasto del presupuesto; las impuestas por una norma de rango legal; y, excepcionalmente, las justificadas por razones de interés público, social, económico o humanitario que dificulten su convocatoria pública (art. 22.2 LGS).","refs":[{"ref":"Art. 22.1 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"El procedimiento ordinario de concesión de subvenciones se tramitará en régimen de concurrencia competitiva."},{"ref":"Art. 22.2.a) LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"se entiende por subvención prevista nominativamente en los Presupuestos Generales del Estado aquella en que al menos su dotación presupuestaria y beneficiario aparezcan determinados en los estados de gasto del Presupuesto."},{"ref":"Art. 22.2.c) LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"Con carácter excepcional, aquellas otras subvenciones en que se acrediten razones de interés público, social, económico o humanitario, u otras debidamente justificadas que dificulten su convocatoria pública."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Limitar derechos exige proporcionalidad y elegir la medida menos restrictiva (art. 4.1 LRJSP).","refs":[{"ref":"Art. 4.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"deberán aplicar el principio de proporcionalidad y elegir la medida menos restrictiva"}]},{"text":"Declaración responsable o comunicación: actividad desde el día de su presentación; nunca ambas a la vez.","refs":[{"ref":"Art. 69.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"desde el día de su presentación, sin perjuicio de las facultades de comprobación, control e inspección que tengan atribuidas las Administraciones Públicas."}]},{"text":"Potestad sancionadora: solo si la reconoce una norma con rango de ley; infracciones leves prescriben a los seis meses si la ley no dice otra cosa.","refs":[{"ref":"Art. 30.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"las graves a los dos años y las leves a los seis meses"}]},{"text":"Ejecución subsidiaria: actos no personalísimos que la Administración realiza a costa del obligado.","refs":[{"ref":"Art. 102.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"las Administraciones Públicas realizarán el acto, por sí o a través de las personas que determinen, a costa del obligado."}]},{"text":"Acuerdos sobre materias de competencia directa del Consejo de Ministros: aprobación expresa de este.","refs":[{"ref":"Art. 86.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Requerirán en todo caso la aprobación expresa del Consejo de Ministros"}]},{"text":"Concesión de servicios: nunca para el ejercicio de autoridad; la Administración conserva poderes de policía; máximo veinticinco años en servicios no sanitarios.","refs":[{"ref":"Art. 287.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"la Administración conservará los poderes de policía necesarios para asegurar la buena marcha de los servicios de que se trate."}]},{"text":"Gestión directa local: propia entidad, organismo autónomo local, entidad pública empresarial local o sociedad mercantil local.","refs":[{"ref":"Art. 85.2.A).b) LBRL","law":"Ley 7/1985","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"Organismo autónomo local."}]},{"text":"Reserva local: aguas, residuos y transporte público de viajeros.","refs":[{"ref":"Art. 86.2 LBRL","law":"Ley 7/1985","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392","quote":"recogida, tratamiento y aprovechamiento de residuos"}]},{"text":"Subvención: sin contraprestación directa; procedimiento ordinario, concurrencia competitiva; nominativas, concesión directa.","refs":[{"ref":"Art. 22.2.a) LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"Las previstas nominativamente en los Presupuestos Generales del Estado"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', null, null, null, 'Otras normas citadas: Ley 40/2015 (https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566), Ley 7/1985 (https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392), Ley 9/2017 (https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902), Ley 38/2003 (https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977)'
  from public.topics t where t.slug = 'age-adm-35-actividad-administrativa'
