insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Concepto y fundamento constitucional de la responsabilidad patrimonial (arts. 106.2 y 121 CE)"},{"n":"2","title":"Clases: por funcionamiento de los servicios públicos, del Estado legislador y de la Administración de Justicia (art. 32 Ley 40/2015; arts. 292-293 LOPJ)"},{"n":"3","title":"Requisitos generales: lesión, daño efectivo, evaluable e individualizado, relación de causalidad y ausencia de fuerza mayor (arts. 32 y 34.1 Ley 40/2015)"},{"n":"4","title":"Responsabilidad concurrente de varias Administraciones y de Derecho privado (arts. 33 y 35 Ley 40/2015)"},{"n":"5","title":"Efectos: la indemnización, su cálculo y modo de pago (art. 34 Ley 40/2015)"},{"n":"6","title":"Responsabilidad de las autoridades y del personal: acción de regreso y responsabilidad penal (arts. 36-37 Ley 40/2015)"},{"n":"7","title":"Procedimiento: iniciación, prescripción, informes, dictamen, resolución y tramitación simplificada (arts. 65, 67, 81, 91, 92 y 96 Ley 39/2015)"},{"n":"8","title":"Revisión jurisdiccional: el orden contencioso-administrativo (art. 2.e Ley 29/1998)"}]'::jsonb, '["Art. 106.2 CE: «Los particulares, en los términos establecidos por la ley, tendrán derecho a ser indemnizados por toda lesión que sufran en cualquiera de sus bienes y derechos, salvo en los casos de fuerza mayor, siempre que la lesión sea consecuencia del funcionamiento de los servicios públicos.»","Art. 121 CE: «Los daños causados por error judicial, así como los que sean consecuencia del funcionamiento anormal de la Administración de Justicia, darán derecho a una indemnización a cargo del Estado, conforme a la ley.»","Art. 32.1 Ley 40/2015: «Los particulares tendrán derecho a ser indemnizados por las Administraciones Públicas correspondientes, de toda lesión que sufran en cualquiera de sus bienes y derechos, siempre que la lesión sea consecuencia del funcionamiento normal o anormal de los servicios públicos salvo en los casos de fuerza mayor o de daños que el particular tenga el deber jurídico de soportar de acuerdo con la Ley.»","Art. 32.2 Ley 40/2015: «En todo caso, el daño alegado habrá de ser efectivo, evaluable económicamente e individualizado con relación a una persona o grupo de personas.»","Art. 32.3 Ley 40/2015: «Asimismo, los particulares tendrán derecho a ser indemnizados por las Administraciones Públicas de toda lesión que sufran en sus bienes y derechos como consecuencia de la aplicación de actos legislativos de naturaleza no expropiatoria de derechos que no tengan el deber jurídico de soportar cuando así se establezca en los propios actos legislativos y en los términos que en ellos se especifiquen.»","Art. 34.1 Ley 40/2015: «Sólo serán indemnizables las lesiones producidas al particular provenientes de daños que éste no tenga el deber jurídico de soportar de acuerdo con la Ley.»","Art. 33.1 Ley 40/2015: «Cuando de la gestión dimanante de fórmulas conjuntas de actuación entre varias Administraciones públicas se derive responsabilidad en los términos previstos en la presente Ley, las Administraciones intervinientes responderán frente al particular, en todo caso, de forma solidaria.»","Art. 34.2 Ley 40/2015: «La indemnización se calculará con arreglo a los criterios de valoración establecidos en la legislación fiscal, de expropiación forzosa y demás normas aplicables, ponderándose, en su caso, las valoraciones predominantes en el mercado.»","Art. 34.4 Ley 40/2015: «La indemnización procedente podrá sustituirse por una compensación en especie o ser abonada mediante pagos periódicos, cuando resulte más adecuado para lograr la reparación debida y convenga al interés público, siempre que exista acuerdo con el interesado.»","Art. 36.1 Ley 40/2015: «Para hacer efectiva la responsabilidad patrimonial a que se refiere esta Ley, los particulares exigirán directamente a la Administración Pública correspondiente las indemnizaciones por los daños y perjuicios causados por las autoridades y personal a su servicio.»","Art. 36.2 Ley 40/2015: «La Administración correspondiente, cuando hubiere indemnizado a los lesionados, exigirá de oficio en vía administrativa de sus autoridades y demás personal a su servicio la responsabilidad en que hubieran incurrido por dolo, o culpa o negligencia graves, previa instrucción del correspondiente procedimiento.»","Art. 67.1 Ley 39/2015: «El derecho a reclamar prescribirá al año de producido el hecho o el acto que motive la indemnización o se manifieste su efecto lesivo. En caso de daños de carácter físico o psíquico a las personas, el plazo empezará a computarse desde la curación o la determinación del alcance de las secuelas.»","Art. 81.2 Ley 39/2015: «Cuando las indemnizaciones reclamadas sean de cuantía igual o superior a 50.000 euros o a la que se establezca en la correspondiente legislación autonómica, así como en aquellos casos que disponga la Ley Orgánica 3/1980, de 22 de abril, del Consejo de Estado, será preceptivo solicitar dictamen del Consejo de Estado o, en su caso, del órgano consultivo de la Comunidad Autónoma.»","Art. 91.3 Ley 39/2015: «Transcurridos seis meses desde que se inició el procedimiento sin que haya recaído y se notifique resolución expresa o, en su caso, se haya formalizado el acuerdo, podrá entenderse que la resolución es contraria a la indemnización del particular.»","Art. 92 Ley 39/2015: «En el ámbito de la Administración General del Estado, los procedimientos de responsabilidad patrimonial se resolverán por el Ministro respectivo o por el Consejo de Ministros en los casos del artículo 32.3 de la Ley de Régimen Jurídico del Sector Público o cuando una ley así lo disponga.»","Art. 2.e) Ley 29/1998: «La responsabilidad patrimonial de las Administraciones públicas, cualquiera que sea la naturaleza de la actividad o el tipo de relación de que derive, no pudiendo ser demandadas aquellas por este motivo ante los órdenes jurisdiccionales civil o social, aun cuando en la producción del daño concurran con particulares o cuenten con un seguro de responsabilidad.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Concepto y fundamento constitucional de la responsabilidad patrimonial","blocks":[{"text":"La responsabilidad patrimonial es la obligación de la Administración de reparar los daños que causa a los particulares con su actividad. Tiene base directa en la Constitución: los particulares, en los términos de la ley, tienen derecho a ser indemnizados por toda lesión en sus bienes y derechos que sea consecuencia del funcionamiento de los servicios públicos, salvo en los casos de fuerza mayor (art. 106.2 CE). Para la Justicia, la Constitución añade que los daños por error judicial o por funcionamiento anormal de la Administración de Justicia dan derecho a una indemnización a cargo del Estado (art. 121 CE). Es una garantía del particular frente al poder público y un complemento del control judicial de la Administración (art. 106.1 CE).","refs":[{"ref":"Art. 106.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los particulares, en los términos establecidos por la ley, tendrán derecho a ser indemnizados por toda lesión que sufran en cualquiera de sus bienes y derechos, salvo en los casos de fuerza mayor, siempre que la lesión sea consecuencia del funcionamiento de los servicios públicos."},{"ref":"Art. 121 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los daños causados por error judicial, así como los que sean consecuencia del funcionamiento anormal de la Administración de Justicia, darán derecho a una indemnización a cargo del Estado, conforme a la ley."},{"ref":"Art. 106.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los Tribunales controlan la potestad reglamentaria y la legalidad de la actuación administrativa, así como el sometimiento de ésta a los fines que la justifican."}]},{"text":"La regulación general está repartida entre dos leyes de 2015: la Ley 40/2015 (LRJSP) fija los principios sustantivos (arts. 32 a 37) y la Ley 39/2015 (LPAC) regula el procedimiento como especialidades del procedimiento común. La responsabilidad es objetiva: nace del funcionamiento normal o anormal de los servicios públicos, sin necesidad de culpa (art. 32.1 LRJSP). Pero la simple anulación de un acto o disposición, en vía administrativa o contenciosa, no presupone por sí misma derecho a indemnización (art. 32.1 LRJSP).","refs":[{"ref":"Art. 32.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los particulares tendrán derecho a ser indemnizados por las Administraciones Públicas correspondientes, de toda lesión que sufran en cualquiera de sus bienes y derechos, siempre que la lesión sea consecuencia del funcionamiento normal o anormal de los servicios públicos salvo en los casos de fuerza mayor o de daños que el particular tenga el deber jurídico de soportar de acuerdo con la Ley."},{"ref":"Art. 32.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"La anulación en vía administrativa o por el orden jurisdiccional contencioso administrativo de los actos o disposiciones administrativas no presupone, por sí misma, derecho a la indemnización."}]}]},{"n":"2","title":"Clases de responsabilidad","blocks":[{"text":"Además de la responsabilidad por funcionamiento de los servicios públicos, la ley regula la del Estado legislador. Cabe indemnización por actos legislativos no expropiatorios cuando así lo establezcan esos mismos actos (art. 32.3 LRJSP), y también cuando el daño derive de una ley declarada inconstitucional o de una norma contraria al Derecho de la Unión Europea. En el primer caso, el particular debe haber obtenido, en cualquier instancia, sentencia firme desestimatoria de un recurso contra la actuación que causó el daño, habiendo alegado la inconstitucionalidad después declarada (art. 32.4 LRJSP). En el caso del Derecho de la Unión se exigen además que la norma confiera derechos, que el incumplimiento esté suficientemente caracterizado y que haya causalidad directa (art. 32.5 LRJSP).","refs":[{"ref":"Art. 32.3 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"los particulares tendrán derecho a ser indemnizados por las Administraciones Públicas de toda lesión que sufran en sus bienes y derechos como consecuencia de la aplicación de actos legislativos de naturaleza no expropiatoria de derechos que no tengan el deber jurídico de soportar cuando así se establezca en los propios actos legislativos y en los términos que en ellos se especifiquen."},{"ref":"Art. 32.4 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Si la lesión es consecuencia de la aplicación de una norma con rango de ley declarada inconstitucional, procederá su indemnización cuando el particular haya obtenido, en cualquier instancia, sentencia firme desestimatoria de un recurso contra la actuación administrativa que ocasionó el daño, siempre que se hubiera alegado la inconstitucionalidad posteriormente declarada."},{"ref":"Art. 32.5 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"a) La norma ha de tener por objeto conferir derechos a los particulares. b) El incumplimiento ha de estar suficientemente caracterizado."}]},{"text":"La responsabilidad por el funcionamiento de la Administración de Justicia se rige por la Ley Orgánica del Poder Judicial (art. 32.7 LRJSP). Los daños por error judicial o por funcionamiento anormal dan a los perjudicados derecho a indemnización a cargo del Estado, salvo fuerza mayor, y la mera revocación o anulación de resoluciones judiciales no basta (art. 292 LOPJ). La reclamación por error exige una decisión judicial previa que lo reconozca; si no resulta de un recurso de revisión, la acción debe instarse inexcusablemente en tres meses desde que pudo ejercitarse, ante la Sala del Tribunal Supremo del mismo orden (art. 293.1 LOPJ). La petición indemnizatoria se dirige al Ministerio de Justicia y prescribe al año (art. 293.2 LOPJ).","refs":[{"ref":"Art. 32.7 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"La responsabilidad patrimonial del Estado por el funcionamiento de la Administración de Justicia se regirá por la Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial."},{"ref":"Art. 292.3 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La mera revocación o anulación de las resoluciones judiciales no presupone por sí sola derecho a indemnización."},{"ref":"Art. 293.1.a) LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La acción judicial para el reconocimiento del error deberá instarse inexcusablemente en el plazo de tres meses, a partir del día en que pudo ejercitarse."},{"ref":"Art. 293.2 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"el interesado dirigirá su petición indemnizatoria directamente al Ministerio de Justicia"}]}]},{"n":"3","title":"Requisitos generales","blocks":[{"text":"Para que haya responsabilidad deben concurrir varios requisitos. Primero, una lesión: un daño que el particular no tenga el deber jurídico de soportar de acuerdo con la ley (art. 34.1 LRJSP). Segundo, el daño debe ser efectivo, evaluable económicamente e individualizado con relación a una persona o grupo de personas (art. 32.2 LRJSP). Tercero, una relación de causalidad entre el funcionamiento del servicio público y la lesión, sobre la que deben pronunciarse el dictamen y la resolución (arts. 81.2 y 91.2 LPAC). Y cuarto, que no haya fuerza mayor, que excluye la responsabilidad (art. 32.1 LRJSP).","refs":[{"ref":"Art. 34.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Sólo serán indemnizables las lesiones producidas al particular provenientes de daños que éste no tenga el deber jurídico de soportar de acuerdo con la Ley."},{"ref":"Art. 32.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"En todo caso, el daño alegado habrá de ser efectivo, evaluable económicamente e individualizado con relación a una persona o grupo de personas."},{"ref":"Art. 91.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"será necesario que la resolución se pronuncie sobre la existencia o no de la relación de causalidad entre el funcionamiento del servicio público y la lesión producida"}]},{"text":"La ley excluye también los llamados riesgos del desarrollo: no son indemnizables los daños derivados de hechos o circunstancias que no se hubieran podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes cuando se produjeron, sin perjuicio de las prestaciones asistenciales que establezcan las leyes (art. 34.1 LRJSP).","refs":[{"ref":"Art. 34.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"No serán indemnizables los daños que se deriven de hechos o circunstancias que no se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes en el momento de producción de aquéllos"}]}]},{"n":"4","title":"Responsabilidad concurrente y de Derecho privado","blocks":[{"text":"Si el daño deriva de fórmulas conjuntas de actuación entre varias Administraciones, todas responden frente al particular, en todo caso, de forma solidaria, aunque el instrumento regulador puede repartir la responsabilidad entre ellas (art. 33.1 LRJSP). En otros casos de concurrencia, la responsabilidad se fija para cada una según competencia, interés público tutelado e intensidad de la intervención, y es solidaria si no puede determinarse (art. 33.2 LRJSP). En las actuaciones conjuntas, tramita y resuelve la Administración que fijen los estatutos o reglas de la organización colegiada y, en su defecto, la de mayor participación en la financiación del servicio, que consulta a las demás para que aleguen en quince días (art. 33.3 y 4 LRJSP).","refs":[{"ref":"Art. 33.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Cuando de la gestión dimanante de fórmulas conjuntas de actuación entre varias Administraciones públicas se derive responsabilidad en los términos previstos en la presente Ley, las Administraciones intervinientes responderán frente al particular, en todo caso, de forma solidaria."},{"ref":"Art. 33.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"la responsabilidad se fijará para cada Administración atendiendo a los criterios de competencia, interés público tutelado e intensidad de la intervención. La responsabilidad será solidaria cuando no sea posible dicha determinación."},{"ref":"Art. 33.3 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"será la fijada en los Estatutos o reglas de la organización colegiada. En su defecto, la competencia vendrá atribuida a la Administración Pública con mayor participación en la financiación del servicio."}]},{"text":"Aunque la Administración actúe en relaciones de Derecho privado, directamente o mediante una entidad privada, su responsabilidad se exige conforme a los arts. 32 y siguientes LRJSP, incluso si concurre con sujetos privados o se reclama a la aseguradora (art. 35 LRJSP). Se evita así que la Administración escape del régimen público de responsabilidad.","refs":[{"ref":"Art. 35 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Cuando las Administraciones Públicas actúen, directamente o a través de una entidad de derecho privado, en relaciones de esta naturaleza, su responsabilidad se exigirá de conformidad con lo previsto en los artículos 32 y siguientes"}]}]},{"n":"5","title":"Efectos: la indemnización","blocks":[{"text":"La indemnización se calcula con los criterios de valoración de la legislación fiscal, de expropiación forzosa y demás normas aplicables, ponderando las valoraciones de mercado; en muerte o lesiones corporales pueden usarse como referencia los baremos de seguros obligatorios y Seguridad Social (art. 34.2 LRJSP). La cuantía se refiere al día en que la lesión efectivamente se produjo, y se actualiza a la fecha en que termina el procedimiento con el Índice de Garantía de la Competitividad del INE, más los intereses de demora que procedan (art. 34.3 LRJSP).","refs":[{"ref":"Art. 34.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"La indemnización se calculará con arreglo a los criterios de valoración establecidos en la legislación fiscal, de expropiación forzosa y demás normas aplicables, ponderándose, en su caso, las valoraciones predominantes en el mercado."},{"ref":"Art. 34.3 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"La cuantía de la indemnización se calculará con referencia al día en que la lesión efectivamente se produjo, sin perjuicio de su actualización a la fecha en que se ponga fin al procedimiento de responsabilidad con arreglo al Índice de Garantía de la Competitividad"}]},{"text":"La indemnización puede sustituirse por una compensación en especie o pagarse mediante pagos periódicos, cuando sea más adecuado para reparar y convenga al interés público, siempre que el interesado esté de acuerdo (art. 34.4 LRJSP). En la responsabilidad del legislador por ley inconstitucional o contraria al Derecho de la Unión, se indemnizan los daños producidos en los cinco años anteriores a la publicación de la sentencia, salvo que esta disponga otra cosa (art. 34.1 LRJSP).","refs":[{"ref":"Art. 34.4 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"La indemnización procedente podrá sustituirse por una compensación en especie o ser abonada mediante pagos periódicos, cuando resulte más adecuado para lograr la reparación debida y convenga al interés público, siempre que exista acuerdo con el interesado."},{"ref":"Art. 34.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"serán indemnizables los daños producidos en el plazo de los cinco años anteriores a la fecha de la publicación de la sentencia"}]}]},{"n":"6","title":"Responsabilidad de las autoridades y del personal","blocks":[{"text":"El particular no demanda al funcionario: exige la indemnización directamente a la Administración por los daños que causen sus autoridades y personal (art. 36.1 LRJSP). Si la Administración indemniza, debe exigir de oficio en vía administrativa a su personal la responsabilidad en que haya incurrido por dolo, o culpa o negligencia graves, previo procedimiento: es la acción de regreso (art. 36.2 LRJSP). Así, si el conductor de un vehículo oficial causa un accidente por negligencia grave, el perjudicado reclama a la Administración y esta repite después contra el conductor. Se ponderan el resultado dañoso, el grado de culpabilidad y la responsabilidad profesional, y el procedimiento incluye alegaciones de quince días y audiencia de diez (art. 36.4 LRJSP).","refs":[{"ref":"Art. 36.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Para hacer efectiva la responsabilidad patrimonial a que se refiere esta Ley, los particulares exigirán directamente a la Administración Pública correspondiente las indemnizaciones por los daños y perjuicios causados por las autoridades y personal a su servicio."},{"ref":"Art. 36.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"La Administración correspondiente, cuando hubiere indemnizado a los lesionados, exigirá de oficio en vía administrativa de sus autoridades y demás personal a su servicio la responsabilidad en que hubieran incurrido por dolo, o culpa o negligencia graves, previa instrucción del correspondiente procedimiento."},{"ref":"Art. 36.4.a) y c) LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"a) Alegaciones durante un plazo de quince días. […] c) Audiencia durante un plazo de diez días."}]},{"text":"La responsabilidad penal del personal y la civil derivada del delito se exigen según su legislación propia (art. 37.1 LRJSP). La exigencia de responsabilidad penal no suspende los procedimientos de responsabilidad patrimonial, salvo que la determinación de los hechos en el orden penal sea necesaria para fijarla (art. 37.2 LRJSP).","refs":[{"ref":"Art. 37.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"La exigencia de responsabilidad penal del personal al servicio de las Administraciones Públicas no suspenderá los procedimientos de reconocimiento de responsabilidad patrimonial que se instruyan, salvo que la determinación de los hechos en el orden jurisdiccional penal sea necesaria para la fijación de la responsabilidad patrimonial."}]}]},{"n":"7","title":"Procedimiento: iniciación y prescripción","blocks":[{"text":"El procedimiento puede iniciarse de oficio, siempre que no haya prescrito el derecho del interesado; el acuerdo se notifica a los presuntos lesionados, que tienen diez días para alegar y proponer prueba (art. 65 LPAC). Si lo inicia el interesado, el derecho a reclamar prescribe al año de producirse el hecho o acto lesivo o de manifestarse su efecto lesivo; en daños físicos o psíquicos, el año empieza a contar desde la curación o la determinación del alcance de las secuelas (art. 67.1 LPAC). Por eso, quien recibe el alta con secuelas ocho meses después del accidente dispone de un año desde esa fecha.","refs":[{"ref":"Art. 65.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El acuerdo de iniciación del procedimiento se notificará a los particulares presuntamente lesionados, concediéndoles un plazo de diez días para que aporten cuantas alegaciones, documentos o información estimen conveniente a su derecho"},{"ref":"Art. 67.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El derecho a reclamar prescribirá al año de producido el hecho o el acto que motive la indemnización o se manifieste su efecto lesivo. En caso de daños de carácter físico o psíquico a las personas, el plazo empezará a computarse desde la curación o la determinación del alcance de las secuelas."}]},{"text":"Si la indemnización procede por anulación de un acto o disposición, el año cuenta desde la notificación de la resolución o sentencia definitiva; en la responsabilidad del legislador, desde la publicación de la sentencia en el BOE o en el DOUE (art. 67.1 LPAC). La solicitud debe especificar las lesiones, la presunta relación de causalidad, la evaluación económica si es posible y el momento de la lesión (art. 67.2 LPAC).","refs":[{"ref":"Art. 67.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"el derecho a reclamar prescribirá al año de haberse notificado la resolución administrativa o la sentencia definitiva."},{"ref":"Art. 67.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se deberán especificar las lesiones producidas, la presunta relación de causalidad entre éstas y el funcionamiento del servicio público, la evaluación económica de la responsabilidad patrimonial, si fuera posible, y el momento en que la lesión efectivamente se produjo"}]}]},{"n":"7.1","title":"Procedimiento: informes, dictamen, resolución y tramitación simplificada","blocks":[{"text":"Es preceptivo el informe del servicio cuyo funcionamiento causó la presunta lesión, en un plazo no superior a diez días (art. 81.1 LPAC). Si la indemnización reclamada es igual o superior a 50.000 euros (o la cuantía autonómica), es preceptivo el dictamen del Consejo de Estado u órgano consultivo autonómico, que se emite en dos meses y se pronuncia sobre la causalidad, la valoración y la cuantía (art. 81.2 LPAC). Una reclamación de 62.000 euros a un ministerio exige, por tanto, ese dictamen.","refs":[{"ref":"Art. 81.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"será preceptivo solicitar informe al servicio cuyo funcionamiento haya ocasionado la presunta lesión indemnizable, no pudiendo exceder de diez días el plazo de su emisión."},{"ref":"Art. 81.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Cuando las indemnizaciones reclamadas sean de cuantía igual o superior a 50.000 euros o a la que se establezca en la correspondiente legislación autonómica, así como en aquellos casos que disponga la Ley Orgánica 3/1980, de 22 de abril, del Consejo de Estado, será preceptivo solicitar dictamen del Consejo de Estado o, en su caso, del órgano consultivo de la Comunidad Autónoma."},{"ref":"Art. 81.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El dictamen se emitirá en el plazo de dos meses"}]},{"text":"En la AGE resuelve el Ministro respectivo o, en los casos del art. 32.3 LRJSP o cuando una ley lo disponga, el Consejo de Ministros (art. 92 LPAC). Si pasan seis meses desde el inicio sin resolución expresa notificada ni acuerdo formalizado, puede entenderse que la resolución es contraria a la indemnización (art. 91.3 LPAC): el silencio es negativo. Si el órgano considera inequívocas la causalidad, la valoración del daño y la cuantía, puede acordar de oficio la tramitación simplificada (art. 96.4 LPAC), que debe resolverse en treinta días desde el siguiente a la notificación del acuerdo, salvo que reste menos para la ordinaria (art. 96.6 LPAC).","refs":[{"ref":"Art. 92 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"En el ámbito de la Administración General del Estado, los procedimientos de responsabilidad patrimonial se resolverán por el Ministro respectivo o por el Consejo de Ministros en los casos del artículo 32.3 de la Ley de Régimen Jurídico del Sector Público o cuando una ley así lo disponga."},{"ref":"Art. 91.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Transcurridos seis meses desde que se inició el procedimiento sin que haya recaído y se notifique resolución expresa o, en su caso, se haya formalizado el acuerdo, podrá entenderse que la resolución es contraria a la indemnización del particular."},{"ref":"Art. 96.4 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"si una vez iniciado el procedimiento administrativo el órgano competente para su tramitación considera inequívoca la relación de causalidad entre el funcionamiento del servicio público y la lesión, así como la valoración del daño y el cálculo de la cuantía de la indemnización, podrá acordar de oficio la suspensión del procedimiento general y la iniciación de un procedimiento simplificado."},{"ref":"Art. 96.6 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Salvo que reste menos para su tramitación ordinaria, los procedimientos administrativos tramitados de manera simplificada deberán ser resueltos en treinta días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento"}]}]},{"n":"8","title":"Revisión jurisdiccional: el orden contencioso-administrativo","blocks":[{"text":"Todas las cuestiones de responsabilidad patrimonial de las Administraciones corresponden al orden contencioso-administrativo, sea cual sea la actividad o relación de la que deriven. Las Administraciones no pueden ser demandadas por este motivo ante los órdenes civil o social, aunque en el daño concurran particulares o tengan un seguro de responsabilidad (art. 2.e LJCA). Es la llamada unidad jurisdiccional, que completa la unidad de régimen del art. 35 LRJSP.","refs":[{"ref":"Art. 2.e) LJCA","law":"Ley 29/1998","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718","quote":"La responsabilidad patrimonial de las Administraciones públicas, cualquiera que sea la naturaleza de la actividad o el tipo de relación de que derive, no pudiendo ser demandadas aquellas por este motivo ante los órdenes jurisdiccionales civil o social, aun cuando en la producción del daño concurran con particulares o cuenten con un seguro de responsabilidad."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Funcionamiento normal o anormal de los servicios públicos; se excluye la fuerza mayor.","refs":[{"ref":"Art. 106.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"salvo en los casos de fuerza mayor"}]},{"text":"Daño efectivo, evaluable económicamente e individualizado; la anulación de un acto no da derecho por sí sola.","refs":[{"ref":"Art. 32.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"efectivo, evaluable económicamente e individualizado con relación a una persona o grupo de personas."}]},{"text":"Actuación conjunta de varias Administraciones: responsabilidad solidaria; en su defecto de estatutos, tramita la de mayor financiación.","refs":[{"ref":"Art. 33.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"responderán frente al particular, en todo caso, de forma solidaria."}]},{"text":"Cuantía referida al día de la lesión, actualizada con el Índice de Garantía de la Competitividad.","refs":[{"ref":"Art. 34.3 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"con referencia al día en que la lesión efectivamente se produjo"}]},{"text":"Acción de regreso contra el personal solo por dolo, o culpa o negligencia graves.","refs":[{"ref":"Art. 36.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"por dolo, o culpa o negligencia graves"}]},{"text":"Prescripción: un año; en daños personales, desde la curación o determinación de secuelas.","refs":[{"ref":"Art. 67.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"el plazo empezará a computarse desde la curación o la determinación del alcance de las secuelas."}]},{"text":"Informe del servicio en diez días; dictamen del Consejo de Estado desde 50.000 euros, en dos meses.","refs":[{"ref":"Art. 81.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"de cuantía igual o superior a 50.000 euros"}]},{"text":"Seis meses sin resolver: desestimación; resuelve el Ministro; simplificado, treinta días.","refs":[{"ref":"Art. 92 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se resolverán por el Ministro respectivo"}]},{"text":"Error judicial: acción en tres meses; jurisdicción de la responsabilidad patrimonial administrativa: contencioso-administrativa.","refs":[{"ref":"Art. 293.1.a) LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"en el plazo de tres meses, a partir del día en que pudo ejercitarse."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566', null, null, null, 'Otras normas citadas: CE (https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229), Ley 39/2015 (https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565), Ley 29/1998 (https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718)'
  from public.topics t where t.slug = 'age-adm-36-responsabilidad'
