insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto Legislativo 5/2015, de 30 de octubre, texto refundido de la Ley del Estatuto Básico del Empleado Público (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-41-personal', 'IV.1 El personal al servicio de las Administraciones públicas: clases y TREBEP') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-41-personal' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Concepto y clases de empleados públicos (art. 8 TREBEP)"},{"n":"1.1","title":"Funcionarios de carrera y funcionarios interinos (arts. 9-10 TREBEP)"},{"n":"1.2","title":"Personal laboral y personal eventual (arts. 11-12 TREBEP)"},{"n":"1.3","title":"Personal directivo profesional (art. 13 TREBEP)"},{"n":"2","title":"El TREBEP: objeto, fundamentos y ámbito de aplicación (arts. 1-5 TREBEP)"},{"n":"3","title":"Demás normativa de aplicación: leyes de Función Pública, legislación laboral y normas vigentes (arts. 6-7 y disps. finales 1.ª y 4.ª TREBEP)"},{"n":"4","title":"Estructuración del empleo público: relaciones de puestos de trabajo, cuerpos y escalas (arts. 73-75 TREBEP)"},{"n":"5","title":"Competencias en materia de personal en la AGE (arts. 9 y 27 RD 364/1995)"},{"n":"6","title":"Registros de personal y Registro Central de Personal (art. 71 TREBEP; arts. 35.2 y 37 RD 364/1995)"}]'::jsonb, '["Art. 8 TREBEP: «1. Son empleados públicos quienes desempeñan funciones retribuidas en las Administraciones Públicas al servicio de los intereses generales. 2. Los empleados públicos se clasifican en: a) Funcionarios de carrera. b) Funcionarios interinos. c) Personal laboral, ya sea fijo, por tiempo indefinido o temporal. d) Personal eventual.»","Art. 9 TREBEP: «1. Son funcionarios de carrera quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente. 2. En todo caso, el ejercicio de las funciones que impliquen la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales del Estado y de las Administraciones Públicas corresponden exclusivamente a los funcionarios públicos, en los términos que en la ley de desarrollo de cada Administración Pública se establezca.»","Art. 10.1 TREBEP: «Son funcionarios interinos los que, por razones expresamente justificadas de necesidad y urgencia, son nombrados como tales con carácter temporal para el desempeño de funciones propias de funcionarios de carrera, cuando se dé alguna de las siguientes circunstancias:»","Art. 11.1 TREBEP: «Es personal laboral el que en virtud de contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de contratación de personal previstas en la legislación laboral, presta servicios retribuidos por las Administraciones Públicas. En función de la duración del contrato éste podrá ser fijo, por tiempo indefinido o temporal.»","Art. 12.1 y 3 TREBEP: «Es personal eventual el que, en virtud de nombramiento y con carácter no permanente, sólo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, siendo retribuido con cargo a los créditos presupuestarios consignados para este fin. […] 3. El nombramiento y cese serán libres. El cese tendrá lugar, en todo caso, cuando se produzca el de la autoridad a la que se preste la función de confianza o asesoramiento.»","Art. 13.1 TREBEP: «Es personal directivo el que desarrolla funciones directivas profesionales en las Administraciones Públicas, definidas como tales en las normas específicas de cada Administración.»","Art. 1.1-2 TREBEP: «1. El presente Estatuto tiene por objeto establecer las bases del régimen estatutario de los funcionarios públicos incluidos en su ámbito de aplicación. 2. Asimismo tiene por objeto determinar las normas aplicables al personal laboral al servicio de las Administraciones Públicas.»","Art. 2.1 TREBEP: «Este Estatuto se aplica al personal funcionario y en lo que proceda al personal laboral al servicio de las siguientes Administraciones Públicas: a) La Administración General del Estado. b) Las Administraciones de las comunidades autónomas y de las ciudades de Ceuta y Melilla. c) Las Administraciones de las entidades locales. d) Los organismos públicos, agencias y demás entidades de derecho público con personalidad jurídica propia, vinculadas o dependientes de cualquiera de las Administraciones Públicas. e) Las Universidades Públicas.»","Art. 2.5 TREBEP: «El presente Estatuto tiene carácter supletorio para todo el personal de las Administraciones Públicas no incluido en su ámbito de aplicación.»","Art. 7 TREBEP: «El personal laboral al servicio de las Administraciones públicas se rige, además de por la legislación laboral y por las demás normas convencionalmente aplicables, por los preceptos de este Estatuto que así lo dispongan.»","Disp. final 4.ª.2 TREBEP: «Hasta que se dicten las leyes de Función Pública y las normas reglamentarias de desarrollo se mantendrán en vigor en cada Administración Pública las normas vigentes sobre ordenación, planificación y gestión de recursos humanos en tanto no se opongan a lo establecido en este Estatuto.»","Art. 74 TREBEP: «Las Administraciones Públicas estructurarán su organización a través de relaciones de puestos de trabajo u otros instrumentos organizativos similares que comprenderán, al menos, la denominación de los puestos, los grupos de clasificación profesional, los cuerpos o escalas, en su caso, a que estén adscritos, los sistemas de provisión y las retribuciones complementarias. Dichos instrumentos serán públicos.»","Art. 75.2 TREBEP: «Los cuerpos y escalas de funcionarios se crean, modifican y suprimen por ley de las Cortes Generales o de las asambleas legislativas de las comunidades autónomas.»","Art. 9 RD 364/1995: «Aprobada la oferta de empleo público, los Departamentos a los que figuren adscritos los correspondientes Cuerpos y Escalas de funcionarios procederán a la convocatoria de los procedimientos selectivos de acceso para las vacantes previstas de dichos Cuerpos o Escalas, previo informe favorable de la Dirección General de la Función Pública.»","Art. 71.1 y 3 TREBEP: «Cada Administración Pública constituirá un Registro en el que se inscribirán los datos relativos al personal contemplado en los artículos 2 y 5 del presente Estatuto y que tendrá en cuenta las peculiaridades de determinados colectivos. […] 3. Mediante convenio de Conferencia Sectorial se establecerán los contenidos mínimos comunes de los Registros de personal y los criterios que permitan el intercambio homogéneo de la información entre Administraciones, con respeto a lo establecido en la legislación de protección de datos de carácter personal.»","Art. 37 RD 364/1995: «Las diligencias de cese y toma de posesión de los funcionarios que accedan a un puesto de trabajo deberán ser comunicadas al Registro Central de Personal dentro de los tres días hábiles siguientes a su formalización.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Concepto y clases de empleados públicos","blocks":[{"text":"El TREBEP define al empleado público por la función que realiza y no por el tipo de vínculo: es empleado público quien desempeña funciones retribuidas en una Administración Pública al servicio de los intereses generales (art. 8.1 TREBEP). Son, por tanto, tres notas: trabajo retribuido, prestado en una Administración Pública y orientado al interés general. A partir de ese concepto común, el artículo 8.2 distingue cuatro clases: funcionarios de carrera, funcionarios interinos, personal laboral (fijo, por tiempo indefinido o temporal) y personal eventual. El personal directivo profesional no es una quinta clase de la lista del artículo 8, sino una figura que regula aparte el capítulo II del título II (art. 13 TREBEP) y que puede ser funcionario o laboral.","refs":[{"ref":"Art. 8 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"1. Son empleados públicos quienes desempeñan funciones retribuidas en las Administraciones Públicas al servicio de los intereses generales. 2. Los empleados públicos se clasifican en: a) Funcionarios de carrera. b) Funcionarios interinos. c) Personal laboral, ya sea fijo, por tiempo indefinido o temporal. d) Personal eventual."}]},{"text":"Ojo: «por tiempo indefinido» solo se predica del personal laboral, nunca de los funcionarios. El personal directivo tiene un capítulo propio (art. 13).","refs":[{"ref":"Art. 13 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El Gobierno y los órganos de gobierno de las comunidades autónomas podrán establecer, en desarrollo de este Estatuto, el régimen jurídico específico del personal directivo así como los criterios para determinar su condición"}]}]},{"n":"2","title":"Funcionarios de carrera y funcionarios interinos","blocks":[{"text":"Funcionario de carrera es quien, en virtud de nombramiento legal, está unido a una Administración por una relación estatutaria, regulada por el Derecho Administrativo, para prestar servicios profesionales retribuidos de carácter permanente (art. 9.1 TREBEP). La relación no nace de un contrato, sino de un nombramiento, y su contenido lo fija la ley, no el acuerdo de las partes. El artículo 9.2 reserva en exclusiva a los funcionarios las funciones que impliquen participación directa o indirecta en el ejercicio de potestades públicas o en la salvaguardia de los intereses generales, en los términos que fije la ley de desarrollo de cada Administración.","refs":[{"ref":"Art. 9 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"1. Son funcionarios de carrera quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente. 2. En todo caso, el ejercicio de las funciones que impliquen la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales del Estado y de las Administraciones Públicas corresponden exclusivamente a los funcionarios públicos, en los términos que en la ley de desarrollo de cada Administración Pública se establezca."}]},{"text":"Los funcionarios interinos son nombrados con carácter temporal, por razones expresamente justificadas de necesidad y urgencia, para desempeñar funciones propias de funcionarios de carrera en cuatro supuestos tasados (art. 10.1 TREBEP): plazas vacantes que no puedan cubrirse por funcionarios de carrera, por un máximo de tres años; sustitución transitoria de los titulares, durante el tiempo estrictamente necesario; ejecución de programas temporales, de duración no superior a tres años, ampliable hasta doce meses más por ley de Función Pública; y exceso o acumulación de tareas, por un máximo de nueve meses dentro de un periodo de dieciocho. Su selección es pública y se rige por igualdad, mérito, capacidad, publicidad y celeridad, y el nombramiento nunca convierte al interino en funcionario de carrera (art. 10.2). La selección y el cese se estudian con más detalle en el tema A42.","refs":[{"ref":"Art. 10.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"a) La existencia de plazas vacantes, cuando no sea posible su cobertura por funcionarios de carrera, por un máximo de tres años, en los términos previstos en el apartado 4. b) La sustitución transitoria de los titulares, durante el tiempo estrictamente necesario. c) La ejecución de programas de carácter temporal, que no podrán tener una duración superior a tres años, ampliable hasta doce meses más por las leyes de Función Pública que se dicten en desarrollo de este Estatuto. d) El exceso o acumulación de tareas por plazo máximo de nueve meses, dentro de un periodo de dieciocho meses."},{"ref":"Art. 10.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El nombramiento derivado de estos procedimientos de selección en ningún caso dará lugar al reconocimiento de la condición de funcionario de carrera."}]}]},{"n":"3","title":"Personal laboral y personal eventual","blocks":[{"text":"Es personal laboral quien presta servicios retribuidos por una Administración en virtud de un contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de la legislación laboral; según la duración del contrato puede ser fijo, por tiempo indefinido o temporal (art. 11.1 TREBEP). Las leyes de Función Pública deben fijar qué puestos pueden ocupar los laborales, respetando siempre la reserva a funcionarios del artículo 9.2 (art. 11.2). Su selección es pública y se rige por igualdad, mérito y capacidad; en el caso del personal laboral temporal rige además el principio de celeridad, porque su finalidad es atender necesidades expresamente justificadas de necesidad y urgencia (art. 11.3).","refs":[{"ref":"Art. 11.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Es personal laboral el que en virtud de contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de contratación de personal previstas en la legislación laboral, presta servicios retribuidos por las Administraciones Públicas. En función de la duración del contrato éste podrá ser fijo, por tiempo indefinido o temporal."},{"ref":"Art. 11.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los procedimientos de selección del personal laboral serán públicos, rigiéndose en todo caso por los principios de igualdad, mérito y capacidad. En el caso del personal laboral temporal se regirá igualmente por el principio de celeridad, teniendo por finalidad atender razones expresamente justificadas de necesidad y urgencia."}]},{"text":"El personal eventual es nombrado con carácter no permanente y solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, retribuidas con cargo a créditos presupuestarios destinados a ese fin (art. 12.1 TREBEP). Las leyes de Función Pública señalan qué órganos de gobierno pueden tener este personal; el número máximo lo fijan los respectivos órganos de gobierno, y tanto ese número como las condiciones retributivas son públicos (art. 12.2). Nombramiento y cese son libres, y el cese se produce en todo caso cuando cesa la autoridad a la que se asesora (art. 12.3). Haber sido eventual no puede valorarse como mérito para acceder a la Función Pública ni para la promoción interna (art. 12.4), y se le aplica el régimen general de los funcionarios de carrera en lo que sea adecuado (art. 12.5).","refs":[{"ref":"Art. 12 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El número máximo se establecerá por los respectivos órganos de gobierno. Este número y las condiciones retributivas serán públicas. 3. El nombramiento y cese serán libres. El cese tendrá lugar, en todo caso, cuando se produzca el de la autoridad a la que se preste la función de confianza o asesoramiento. 4. La condición de personal eventual no podrá constituir mérito para el acceso a la Función Pública o para la promoción interna."}]}]},{"n":"4","title":"Personal directivo profesional","blocks":[{"text":"El artículo 13 TREBEP permite al Gobierno y a los órganos de gobierno autonómicos establecer el régimen jurídico del personal directivo, con arreglo a unos principios mínimos. Es personal directivo el que desarrolla funciones directivas profesionales definidas como tales en las normas de cada Administración (art. 13.1). Su designación atiende a principios de mérito y capacidad y a criterios de idoneidad, mediante procedimientos que garanticen publicidad y concurrencia (art. 13.2). Está sujeto a evaluación según criterios de eficacia y eficiencia, responsabilidad por su gestión y control de resultados respecto de los objetivos fijados (art. 13.3).","refs":[{"ref":"Art. 13.1-3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"1. Es personal directivo el que desarrolla funciones directivas profesionales en las Administraciones Públicas, definidas como tales en las normas específicas de cada Administración. 2. Su designación atenderá a principios de mérito y capacidad y a criterios de idoneidad, y se llevará a cabo mediante procedimientos que garanticen la publicidad y concurrencia. 3. El personal directivo estará sujeto a evaluación con arreglo a los criterios de eficacia y eficiencia, responsabilidad por su gestión y control de resultados en relación con los objetivos que les hayan sido fijados."}]},{"text":"Sus condiciones de empleo no son materia de negociación colectiva a efectos del Estatuto, y si el directivo es personal laboral queda sometido a la relación laboral especial de alta dirección (art. 13.4 TREBEP). No se confunde con el eventual: el directivo se elige por mérito e idoneidad y se evalúa; el eventual se nombra y cesa libremente.","refs":[{"ref":"Art. 13.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La determinación de las condiciones de empleo del personal directivo no tendrá la consideración de materia objeto de negociación colectiva a los efectos de esta ley. Cuando el personal directivo reúna la condición de personal laboral estará sometido a la relación laboral de carácter especial de alta dirección."}]}]},{"n":"5","title":"El TREBEP: objeto y fundamentos de actuación","blocks":[{"text":"El TREBEP (Real Decreto Legislativo 5/2015) tiene un doble objeto: establecer las bases del régimen estatutario de los funcionarios incluidos en su ámbito y determinar las normas aplicables al personal laboral de las Administraciones Públicas (art. 1.1 y 2). Es, por tanto, una norma básica: fija un mínimo común que luego desarrollan las leyes de Función Pública de cada Administración.","refs":[{"ref":"Art. 1.1-2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"1. El presente Estatuto tiene por objeto establecer las bases del régimen estatutario de los funcionarios públicos incluidos en su ámbito de aplicación. 2. Asimismo tiene por objeto determinar las normas aplicables al personal laboral al servicio de las Administraciones Públicas."}]},{"text":"El artículo 1.3 enumera doce fundamentos de actuación, entre ellos el servicio a los ciudadanos y a los intereses generales; la igualdad, mérito y capacidad en el acceso y la promoción; el sometimiento pleno a la ley y al Derecho; la igualdad de trato entre mujeres y hombres; la transparencia; la evaluación y responsabilidad en la gestión; la jerarquía; la negociación colectiva y la cooperación entre Administraciones. Un dato muy preguntado: la objetividad, profesionalidad e imparcialidad en el servicio se garantizan con la inamovilidad en la condición de funcionario de carrera (art. 1.3.e).","refs":[{"ref":"Art. 1.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"a) Servicio a los ciudadanos y a los intereses generales. b) Igualdad, mérito y capacidad en el acceso y en la promoción profesional. c) Sometimiento pleno a la ley y al Derecho. d) Igualdad de trato entre mujeres y hombres. e) Objetividad, profesionalidad e imparcialidad en el servicio garantizadas con la inamovilidad en la condición de funcionario de carrera."}]}]},{"n":"6","title":"Ámbito de aplicación del TREBEP","blocks":[{"text":"El Estatuto se aplica al personal funcionario y, en lo que proceda, al laboral de cinco tipos de Administraciones: la Administración General del Estado; las de las comunidades autónomas y de Ceuta y Melilla; las entidades locales; los organismos públicos, agencias y demás entidades de derecho público con personalidad jurídica propia vinculadas o dependientes de cualquiera de ellas; y las Universidades Públicas (art. 2.1 TREBEP). El personal docente y el estatutario de los Servicios de Salud se rigen por su legislación específica y por el TREBEP, salvo determinados preceptos (art. 2.3), y el Estatuto es supletorio para todo el personal de las Administraciones no incluido en su ámbito (art. 2.5).","refs":[{"ref":"Art. 2.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Este Estatuto se aplica al personal funcionario y en lo que proceda al personal laboral al servicio de las siguientes Administraciones Públicas: a) La Administración General del Estado. b) Las Administraciones de las comunidades autónomas y de las ciudades de Ceuta y Melilla. c) Las Administraciones de las entidades locales. d) Los organismos públicos, agencias y demás entidades de derecho público con personalidad jurídica propia, vinculadas o dependientes de cualquiera de las Administraciones Públicas. e) Las Universidades Públicas."},{"ref":"Art. 2.5 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El presente Estatuto tiene carácter supletorio para todo el personal de las Administraciones Públicas no incluido en su ámbito de aplicación."}]},{"text":"Hay colectivos con legislación específica propia a los que el TREBEP solo se aplica directamente cuando esa legislación lo disponga (art. 4): personal de las Cortes Generales y de los parlamentos autonómicos, de los demás órganos constitucionales y estatutarios, jueces, magistrados, fiscales y personal de la Administración de Justicia, militares, Fuerzas y Cuerpos de Seguridad, personal retribuido por arancel, personal del Centro Nacional de Inteligencia y del Banco de España y del Fondo de Garantía de Depósitos. Los funcionarios locales se rigen por la legislación estatal, de la que forma parte el TREBEP, y por la autonómica (art. 3). El personal funcionario de Correos y Telégrafos se rige por sus normas específicas y, supletoriamente, por el Estatuto (art. 5).","refs":[{"ref":"Art. 4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las disposiciones de este Estatuto sólo se aplicarán directamente cuando así lo disponga su legislación específica al siguiente personal: […] g) Personal del Centro Nacional de Inteligencia. h) Personal del Banco de España y del Fondo de Garantía de Depósitos de Entidades de Crédito."},{"ref":"Art. 5 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El personal funcionario de la Sociedad Estatal Correos y Telégrafos se regirá por sus normas específicas y supletoriamente por lo dispuesto en este Estatuto."}]}]},{"n":"7","title":"Demás normativa de aplicación","blocks":[{"text":"El TREBEP no agota la regulación del empleo público: las Cortes Generales y los parlamentos autonómicos deben aprobar, en su ámbito, las leyes de Función Pública de la AGE y de las comunidades autónomas (art. 6). El personal laboral se rige por la legislación laboral, por las normas convencionales (convenios colectivos) y por los preceptos del Estatuto que así lo dispongan (art. 7). En los permisos de nacimiento, adopción, del progenitor diferente de la madre biológica, lactancia y parental, el laboral se rige por el TREBEP y no por las suspensiones de contrato del Estatuto de los Trabajadores (art. 7, párrafo segundo, en la redacción del Real Decreto-ley 9/2025).","refs":[{"ref":"Art. 6 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"En desarrollo de este Estatuto, las Cortes Generales y las asambleas legislativas de las comunidades autónomas aprobarán, en el ámbito de sus competencias, las leyes reguladoras de la Función Pública de la Administración General del Estado y de las comunidades autónomas."},{"ref":"Art. 7 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El personal laboral al servicio de las Administraciones públicas se rige, además de por la legislación laboral y por las demás normas convencionalmente aplicables, por los preceptos de este Estatuto que así lo dispongan. No obstante, en materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica, de lactancia y parental, el personal laboral al servicio de las Administraciones públicas se regirá por lo previsto en el presente Estatuto"}]},{"text":"Según la disposición final primera, el Estatuto se dicta al amparo del artículo 149.1.18.ª CE, como bases del régimen estatutario de los funcionarios; del 149.1.7.ª en lo relativo a la legislación laboral, y del 149.1.13.ª, bases y coordinación de la planificación general de la actividad económica. La disposición final cuarta aplaza los efectos de los capítulos II y III del título III (salvo el art. 25.2) y del capítulo III del título V hasta que se aprueben las leyes de Función Pública, y mantiene en vigor entretanto las normas existentes sobre ordenación, planificación y gestión de recursos humanos que no se opongan al Estatuto. Por esa vía siguen aplicándose en la AGE los Reales Decretos 364/1995 y 365/1995, cuyos preceptos deben leerse a la luz del TREBEP.","refs":[{"ref":"Disp. final 1.ª TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las disposiciones de este Estatuto se dictan al amparo del artículo 149.1.18.ª de la Constitución, constituyendo aquellas bases del régimen estatutario de los funcionarios; al amparo del artículo 149.1.7.ª de la Constitución, por lo que se refiere a la legislación laboral, y al amparo del artículo 149.1.13.ª de la Constitución, bases y coordinación de la planificación general de la actividad económica."},{"ref":"Disp. final 4.ª TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"1. Lo establecido en los capítulos II y III del título III, excepto el artículo 25.2, y en el capítulo III del título V producirá efectos a partir de la entrada en vigor de las leyes de Función Pública que se dicten en desarrollo de este Estatuto. […] 2. Hasta que se dicten las leyes de Función Pública y las normas reglamentarias de desarrollo se mantendrán en vigor en cada Administración Pública las normas vigentes sobre ordenación, planificación y gestión de recursos humanos en tanto no se opongan a lo establecido en este Estatuto."}]}]},{"n":"8","title":"Estructuración del empleo público: puestos, RPT, cuerpos y escalas","blocks":[{"text":"Cada Administración estructura sus recursos humanos en el marco de su potestad de autoorganización (art. 72 TREBEP). Los empleados tienen derecho a desempeñar un puesto de trabajo (art. 73.1), pero la Administración puede asignarles funciones, tareas o responsabilidades distintas de las de su puesto siempre que sean adecuadas a su clasificación, grado o categoría, lo justifiquen las necesidades del servicio y no haya merma retributiva (art. 73.2). Los puestos pueden agruparse por sus características para ordenar selección, formación y movilidad (art. 73.3).","refs":[{"ref":"Art. 73.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las Administraciones Públicas podrán asignar a su personal funciones, tareas o responsabilidades distintas a las correspondientes al puesto de trabajo que desempeñen siempre que resulten adecuadas a su clasificación, grado o categoría, cuando las necesidades del servicio lo justifiquen sin merma en las retribuciones."}]},{"text":"El instrumento básico de ordenación es la relación de puestos de trabajo (RPT) u otro instrumento similar, que debe recoger al menos la denominación de los puestos, los grupos de clasificación profesional, los cuerpos o escalas a los que estén adscritos, los sistemas de provisión y las retribuciones complementarias; estos instrumentos son públicos (art. 74 TREBEP).","refs":[{"ref":"Art. 74 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las Administraciones Públicas estructurarán su organización a través de relaciones de puestos de trabajo u otros instrumentos organizativos similares que comprenderán, al menos, la denominación de los puestos, los grupos de clasificación profesional, los cuerpos o escalas, en su caso, a que estén adscritos, los sistemas de provisión y las retribuciones complementarias. Dichos instrumentos serán públicos."}]},{"text":"Los funcionarios se agrupan en cuerpos, escalas, especialidades u otros sistemas que incorporen competencias, capacidades y conocimientos comunes acreditados mediante un proceso selectivo (art. 75.1). Los cuerpos y escalas se crean, modifican y suprimen por ley de las Cortes Generales o de las asambleas legislativas autonómicas (art. 75.2), nunca por reglamento. Se clasifican por la titulación exigida en grupos: A (subgrupos A1 y A2, título de Grado), B (Técnico Superior) y C (C1, Bachiller o Técnico; C2, Graduado en ESO) (art. 76).","refs":[{"ref":"Art. 75.1-2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"1. Los funcionarios se agrupan en cuerpos, escalas, especialidades u otros sistemas que incorporen competencias, capacidades y conocimientos comunes acreditados a través de un proceso selectivo. 2. Los cuerpos y escalas de funcionarios se crean, modifican y suprimen por ley de las Cortes Generales o de las asambleas legislativas de las comunidades autónomas."},{"ref":"Art. 76 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"C1: Título de Bachiller o Técnico. C2: Título de Graduado en Educación Secundaria Obligatoria."}]}]},{"n":"9","title":"Competencias en materia de personal en la AGE","blocks":[{"text":"El RD 364/1995 (Reglamento General de Ingreso, RGI) reparte varias competencias de personal en la AGE. La oferta de empleo público la aprueba el Gobierno, a propuesta del Ministro competente en Administraciones Públicas y con informe favorable de Hacienda, en el primer trimestre de cada año (art. 8.1 RGI). Una vez aprobada, convocan los Departamentos a los que están adscritos los cuerpos y escalas, previo informe favorable de la Dirección General de la Función Pública (art. 9 RGI).","refs":[{"ref":"Art. 9 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Aprobada la oferta de empleo público, los Departamentos a los que figuren adscritos los correspondientes Cuerpos y Escalas de funcionarios procederán a la convocatoria de los procedimientos selectivos de acceso para las vacantes previstas de dichos Cuerpos o Escalas, previo informe favorable de la Dirección General de la Función Pública."},{"ref":"Art. 8.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"La oferta de empleo público será aprobada, en su caso, por el Gobierno a propuesta del Ministro para las Administraciones Públicas con informe favorable del Ministerio de Economía y Hacienda, en el primer trimestre de cada año."}]},{"text":"El nombramiento de funcionarios interinos corresponde, con arreglo a mérito y capacidad, al Subsecretario del Departamento al que estén adscritos los cuerpos y escalas, o al Director General de la Función Pública si se trata de cuerpos dependientes de la Secretaría de Estado para la Administración Pública (art. 27.1 RGI). Los funcionarios de carrera los nombra el Secretario de Estado para la Administración Pública (art. 25.1 RGI). Aviso: el RGI conserva denominaciones de 1995 (Ministerio para las Administraciones Públicas, Ministerio de Economía y Hacienda, Gobernadores civiles); hoy esas funciones las ejercen los órganos que establezca la estructura ministerial vigente, que no figura en las fuentes de este tema.","refs":[{"ref":"Art. 27.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"El nombramiento del personal funcionario interino se efectuará, con arreglo a los principios de mérito y capacidad, por el Subsecretario del Departamento al que figuren adscritos los correspondientes Cuerpos y Escalas o por el Director general de la Función Pública, cuando se trate de Cuerpos y Escalas dependientes de la Secretaría de Estado para la Administración Pública."},{"ref":"Art. 25.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"serán nombrados funcionarios de carrera por el Secretario de Estado para la Administración Pública."}]}]},{"n":"10","title":"Registros de personal y Registro Central de Personal","blocks":[{"text":"Cada Administración debe constituir un Registro en el que se inscriban los datos de su personal (el de los artículos 2 y 5 TREBEP), teniendo en cuenta las peculiaridades de determinados colectivos (art. 71.1). Los Registros pueden contener también información agregada sobre el resto de recursos humanos de su sector público (art. 71.2). Los contenidos mínimos comunes y los criterios de intercambio homogéneo de información entre Administraciones se fijan mediante convenio de Conferencia Sectorial, respetando la protección de datos (art. 71.3). Las Administraciones impulsarán la gestión integrada de recursos humanos, y la AGE y las comunidades autónomas cooperarán con las entidades locales sin capacidad suficiente (art. 71.4 y 5).","refs":[{"ref":"Art. 71.1 y 3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"1. Cada Administración Pública constituirá un Registro en el que se inscribirán los datos relativos al personal contemplado en los artículos 2 y 5 del presente Estatuto y que tendrá en cuenta las peculiaridades de determinados colectivos. […] 3. Mediante convenio de Conferencia Sectorial se establecerán los contenidos mínimos comunes de los Registros de personal y los criterios que permitan el intercambio homogéneo de la información entre Administraciones, con respeto a lo establecido en la legislación de protección de datos de carácter personal."}]},{"text":"En la AGE ese registro es el Registro Central de Personal (RCP), al que deben comunicarse los actos de la vida administrativa del funcionario. Las diligencias de cese y toma de posesión de quien accede a un puesto se comunican al RCP dentro de los tres días hábiles siguientes a su formalización (art. 37 RGI). En cada Departamento existe un Registro de personal laboral no permanente cuyas inscripciones y anotaciones se comunican siempre al RCP (art. 35.2 RGI). También se comunican al RCP los cambios de situación administrativa (art. 23.1 RD 365/1995) y el reconocimiento del grado personal, en los tres días hábiles siguientes (art. 70.11 RGI).","refs":[{"ref":"Art. 37 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Las diligencias de cese y toma de posesión de los funcionarios que accedan a un puesto de trabajo deberán ser comunicadas al Registro Central de Personal dentro de los tres días hábiles siguientes a su formalización."},{"ref":"Art. 35.2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"En cada Departamento existirá un Registro de Personal laboral no permanente. Sus inscripciones y anotaciones deberán comunicarse, en todo caso, al Registro Central de Personal."},{"ref":"Art. 23.1 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"Los cambios de situaciones administrativas deberán ser siempre comunicados al Registro Central de Personal"}]},{"text":"El RCP se reguló en el RD 1405/1986, cuyo capítulo I fue en buena parte derogado por el RD 2073/1999 (no incluido en las fuentes); su lista de actos anotables (tomas de posesión, ceses, cambios de situación, grado…) sirve como orientación.","refs":[{"ref":"Art. 4 RD 1405/1986","law":"RD 1405/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-18101","quote":"a) Tomas de posesión del primer puesto de trabajo y de los sucesivos. b) Ceses en los puestos de trabajo. c) Cambios de situación administrativa. d) Adquisición del grado personal y sus modificaciones."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Cuatro clases de empleados públicos (art. 8.2 TREBEP): funcionarios de carrera, interinos, laborales (fijo, indefinido o temporal) y eventuales; el directivo se regula aparte (art. 13).","refs":[{"ref":"Art. 8.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los empleados públicos se clasifican en: a) Funcionarios de carrera. b) Funcionarios interinos. c) Personal laboral, ya sea fijo, por tiempo indefinido o temporal. d) Personal eventual."}]},{"text":"Interino para sustituir a un titular: durante el tiempo estrictamente necesario; por acumulación de tareas: nueve meses dentro de dieciocho.","refs":[{"ref":"Art. 10.1.b) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"b) La sustitución transitoria de los titulares, durante el tiempo estrictamente necesario."}]},{"text":"Haber sido personal eventual no es mérito para el acceso ni para la promoción interna.","refs":[{"ref":"Art. 12.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La condición de personal eventual no podrá constituir mérito para el acceso a la Función Pública o para la promoción interna."}]},{"text":"La inamovilidad del funcionario de carrera garantiza la objetividad, profesionalidad e imparcialidad (art. 1.3.e).","refs":[{"ref":"Art. 1.3.e) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"e) Objetividad, profesionalidad e imparcialidad en el servicio garantizadas con la inamovilidad en la condición de funcionario de carrera."}]},{"text":"Las Universidades Públicas están dentro del ámbito del TREBEP; el CNI, solo si su legislación específica lo dispone.","refs":[{"ref":"Art. 2.1.e) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"e) Las Universidades Públicas."}]},{"text":"Título competencial básico de los funcionarios: artículo 149.1.18.ª CE.","refs":[{"ref":"Disp. final 1.ª TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las disposiciones de este Estatuto se dictan al amparo del artículo 149.1.18.ª de la Constitución, constituyendo aquellas bases del régimen estatutario de los funcionarios"}]},{"text":"Cuerpos y escalas: se crean, modifican y suprimen solo por ley (Cortes Generales o asambleas autonómicas).","refs":[{"ref":"Art. 75.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los cuerpos y escalas de funcionarios se crean, modifican y suprimen por ley de las Cortes Generales o de las asambleas legislativas de las comunidades autónomas."}]},{"text":"Cese y toma de posesión: comunicación al Registro Central de Personal en tres días hábiles.","refs":[{"ref":"Art. 37 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"dentro de los tres días hábiles siguientes a su formalización."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', null, null, null, 'Otras normas citadas: RD 364/1995 (https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729)'
  from public.topics t where t.slug = 'age-adm-41-personal'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto Legislativo 5/2015, de 30 de octubre, texto refundido de la Ley del Estatuto Básico del Empleado Público (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-42-seleccion', 'IV.2-3 Selección de personal, Oferta de Empleo Público y funcionarios de carrera e interinos') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-42-seleccion' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Principios constitucionales del acceso al empleo público (arts. 23.2 y 103.3 CE)"},{"n":"2","title":"Principios rectores y requisitos generales de acceso (arts. 55-58 TREBEP)"},{"n":"3","title":"Acceso al empleo público de las personas con discapacidad (art. 59 TREBEP)"},{"n":"4","title":"Planificación de recursos humanos y Oferta de Empleo Público (arts. 69-70 TREBEP; arts. 7-9 RD 364/1995)"},{"n":"5","title":"Órganos de selección (art. 60 TREBEP; arts. 10-14 RD 364/1995)"},{"n":"6","title":"Sistemas selectivos, convocatorias y desarrollo de las pruebas (art. 61 TREBEP; arts. 4-5 y 15-23 RD 364/1995)"},{"n":"7","title":"Funcionarios de carrera: adquisición de la condición y nombramiento (art. 62 TREBEP; arts. 24-25 RD 364/1995)"},{"n":"8","title":"Funcionarios interinos: supuestos, selección y cese (art. 10 TREBEP; art. 27 RD 364/1995; disp. adic. 17.ª TREBEP)"}]'::jsonb, '["Art. 23.2 CE: «Asimismo, tienen derecho a acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que señalen las leyes.»","Art. 103.3 CE: «La ley regulará el estatuto de los funcionarios públicos, el acceso a la función pública de acuerdo con los principios de mérito y capacidad, las peculiaridades del ejercicio de su derecho a sindicación, el sistema de incompatibilidades y las garantías para la imparcialidad en el ejercicio de sus funciones.»","Art. 55.1 TREBEP: «Todos los ciudadanos tienen derecho al acceso al empleo público de acuerdo con los principios constitucionales de igualdad, mérito y capacidad, y de acuerdo con lo previsto en el presente Estatuto y en el resto del ordenamiento jurídico.»","Art. 56.1 TREBEP: «Para poder participar en los procesos selectivos será necesario reunir los siguientes requisitos: a) Tener la nacionalidad española, sin perjuicio de lo dispuesto en el artículo siguiente. b) Poseer la capacidad funcional para el desempeño de las tareas. c) Tener cumplidos dieciséis años y no exceder, en su caso, de la edad máxima de jubilación forzosa.»","Art. 57.1 TREBEP: «Los nacionales de los Estados miembros de la Unión Europea podrán acceder, como personal funcionario, en igualdad de condiciones que los españoles a los empleos públicos, con excepción de aquellos que directa o indirectamente impliquen una participación en el ejercicio del poder público o en las funciones que tienen por objeto la salvaguardia de los intereses del Estado o de las Administraciones Públicas.»","Art. 59.1 TREBEP: «En las ofertas de empleo público se reservará un cupo no inferior al siete por ciento de las vacantes para ser cubiertas entre personas con discapacidad»","Art. 70.1 TREBEP: «En todo caso, la ejecución de la oferta de empleo público o instrumento similar deberá desarrollarse dentro del plazo improrrogable de tres años.»","Art. 7 RD 364/1995: «Las necesidades de recursos humanos que no puedan ser cubiertas con los efectivos de personal existentes serán objeto de oferta de empleo público, siempre que exista crédito presupuestario y se considere conveniente su cobertura durante el ejercicio.»","Art. 60.1 TREBEP: «Los órganos de selección serán colegiados y su composición deberá ajustarse a los principios de imparcialidad y profesionalidad de sus miembros, y se tenderá, asimismo, a la paridad entre mujer y hombre.»","Art. 11 RD 364/1995: «Estarán constituidos por un número impar de miembros, funcionarios de carrera, no inferior a cinco, debiendo designarse el mismo número de miembros suplentes y en su composición se velará por el cumplimiento del principio de especialidad.»","Art. 61.6 TREBEP: «Los sistemas selectivos de funcionarios de carrera serán los de oposición y concurso-oposición que deberán incluir, en todo caso, una o varias pruebas para determinar la capacidad de los aspirantes y establecer el orden de prelación. Sólo en virtud de ley podrá aplicarse, con carácter excepcional, el sistema de concurso que consistirá únicamente en la valoración de méritos.»","Art. 4.2 RD 364/1995: «La oposición consiste en la celebración de una o más pruebas para determinar la capacidad y la aptitud de los aspirantes y fijar su orden de prelación; el concurso, en la comprobación y calificación de los méritos de los aspirantes y en el establecimiento del orden de prelación de los mismos, y el concurso-oposición, en la sucesiva celebración de los dos sistemas anteriores.»","Art. 62.1 TREBEP: «La condición de funcionario de carrera se adquiere por el cumplimiento sucesivo de los siguientes requisitos: a) Superación del proceso selectivo. b) Nombramiento por el órgano o autoridad competente, que será publicado en el Diario Oficial correspondiente. c) Acto de acatamiento de la Constitución y, en su caso, del Estatuto de Autonomía correspondiente y del resto del Ordenamiento Jurídico. d) Toma de posesión dentro del plazo que se establezca.»","Art. 10.1.a) y d) TREBEP: «a) La existencia de plazas vacantes, cuando no sea posible su cobertura por funcionarios de carrera, por un máximo de tres años, en los términos previstos en el apartado 4. […] d) El exceso o acumulación de tareas por plazo máximo de nueve meses, dentro de un periodo de dieciocho meses.»","Art. 10.2 TREBEP: «Los procedimientos de selección del personal funcionario interino serán públicos, rigiéndose en todo caso por los principios de igualdad, mérito, capacidad, publicidad y celeridad, y tendrán por finalidad la cobertura inmediata del puesto.»","Disp. adic. 17.ª.4 TREBEP: «El incumplimiento del plazo máximo de permanencia dará lugar a una compensación económica para el personal funcionario interino afectado, que será equivalente a veinte días de sus retribuciones fijas por año de servicio, prorrateándose por meses los períodos de tiempo inferiores a un año, hasta un máximo de doce mensualidades.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Principios constitucionales del acceso al empleo público","blocks":[{"text":"La Constitución contiene dos preceptos clave. El artículo 23.2 reconoce, como derecho fundamental, el de acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que señalen las leyes. El artículo 103.3 encarga a la ley regular el estatuto de los funcionarios y el acceso a la función pública de acuerdo con los principios de mérito y capacidad, además de la sindicación, las incompatibilidades y las garantías de imparcialidad. De ahí sale la tríada igualdad (art. 23.2), mérito y capacidad (art. 103.3), que el TREBEP repite como «principios constitucionales».","refs":[{"ref":"Art. 23.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Asimismo, tienen derecho a acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que señalen las leyes."},{"ref":"Art. 103.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La ley regulará el estatuto de los funcionarios públicos, el acceso a la función pública de acuerdo con los principios de mérito y capacidad, las peculiaridades del ejercicio de su derecho a sindicación, el sistema de incompatibilidades y las garantías para la imparcialidad en el ejercicio de sus funciones."}]}]},{"n":"2","title":"Principios rectores del acceso","blocks":[{"text":"Todos los ciudadanos tienen derecho a acceder al empleo público conforme a la igualdad, el mérito y la capacidad (art. 55.1 TREBEP). Además, las Administraciones deben seleccionar a su personal funcionario y laboral mediante procedimientos que garanticen seis principios adicionales (art. 55.2): publicidad de las convocatorias y sus bases; transparencia; imparcialidad y profesionalidad de los miembros de los órganos de selección; independencia y discrecionalidad técnica en su actuación; adecuación entre el contenido de las pruebas y las funciones a desarrollar; y agilidad, sin perjuicio de la objetividad.","refs":[{"ref":"Art. 55.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Todos los ciudadanos tienen derecho al acceso al empleo público de acuerdo con los principios constitucionales de igualdad, mérito y capacidad, y de acuerdo con lo previsto en el presente Estatuto y en el resto del ordenamiento jurídico."},{"ref":"Art. 55.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"a) Publicidad de las convocatorias y de sus bases. b) Transparencia. c) Imparcialidad y profesionalidad de los miembros de los órganos de selección. d) Independencia y discrecionalidad técnica en la actuación de los órganos de selección. e) Adecuación entre el contenido de los procesos selectivos y las funciones o tareas a desarrollar. f) Agilidad, sin perjuicio de la objetividad, en los procesos de selección."}]}]},{"n":"3","title":"Requisitos generales de acceso y nacionalidad","blocks":[{"text":"Para participar en un proceso selectivo se exigen cinco requisitos (art. 56.1 TREBEP): nacionalidad española (con las excepciones del art. 57); capacidad funcional para las tareas; tener dieciséis años cumplidos y no superar la edad de jubilación forzosa (solo una ley puede fijar otra edad máxima); no haber sido separado por expediente disciplinario ni estar inhabilitado; y poseer la titulación exigida. Pueden exigirse requisitos específicos que guarden relación objetiva y proporcionada con las funciones, siempre establecidos de forma abstracta y general (art. 56.3).","refs":[{"ref":"Art. 56.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"a) Tener la nacionalidad española, sin perjuicio de lo dispuesto en el artículo siguiente. b) Poseer la capacidad funcional para el desempeño de las tareas. c) Tener cumplidos dieciséis años y no exceder, en su caso, de la edad máxima de jubilación forzosa. Sólo por ley podrá establecerse otra edad máxima, distinta de la edad de jubilación forzosa, para el acceso al empleo público."},{"ref":"Art. 56.1.e) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"e) Poseer la titulación exigida."}]},{"text":"Los nacionales de la Unión Europea acceden como funcionarios en igualdad con los españoles, salvo a los empleos que impliquen participación en el poder público o en la salvaguardia de los intereses del Estado (art. 57.1); lo mismo vale para sus cónyuges y descendientes en los términos del art. 57.2. Los extranjeros con residencia legal en España pueden acceder solo como personal laboral, en igualdad de condiciones que los españoles (art. 57.4). Únicamente una ley de las Cortes Generales o de una asamblea autonómica puede eximir del requisito de nacionalidad, por interés general, para acceder como funcionario (art. 57.5). Los funcionarios españoles de organismos internacionales pueden quedar exentos de las pruebas sobre conocimientos ya exigidos en su puesto (art. 58).","refs":[{"ref":"Art. 57.4-5 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"4. Los extranjeros a los que se refieren los apartados anteriores, así como los extranjeros con residencia legal en España podrán acceder a las Administraciones Públicas, como personal laboral, en igualdad de condiciones que los españoles. 5. Sólo por ley de las Cortes Generales o de las asambleas legislativas de las comunidades autónomas podrá eximirse del requisito de la nacionalidad por razones de interés general para el acceso a la condición de personal funcionario."},{"ref":"Art. 57.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los nacionales de los Estados miembros de la Unión Europea podrán acceder, como personal funcionario, en igualdad de condiciones que los españoles a los empleos públicos, con excepción de aquellos que directa o indirectamente impliquen una participación en el ejercicio del poder público"}]}]},{"n":"4","title":"Acceso de las personas con discapacidad","blocks":[{"text":"En las ofertas de empleo público se reserva un cupo no inferior al siete por ciento de las vacantes para personas con discapacidad, siempre que superen el proceso selectivo y acrediten la discapacidad y su compatibilidad con las tareas, con el objetivo de que progresivamente se alcance el dos por ciento de los efectivos totales de cada Administración (art. 59.1 TREBEP). Dentro de ese siete por ciento, al menos el dos por ciento de las plazas ofertadas se destina a personas con discapacidad intelectual y el resto a cualquier otro tipo de discapacidad.","refs":[{"ref":"Art. 59.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"En las ofertas de empleo público se reservará un cupo no inferior al siete por ciento de las vacantes para ser cubiertas entre personas con discapacidad […] La reserva del mínimo del siete por ciento se realizará de manera que, al menos, el dos por ciento de las plazas ofertadas lo sea para ser cubiertas por personas que acrediten discapacidad intelectual y el resto de las plazas ofertadas lo sea para personas que acrediten cualquier otro tipo de discapacidad."}]},{"text":"Cada Administración debe adoptar las adaptaciones y ajustes razonables de tiempos y medios en el proceso selectivo (por ejemplo, más tiempo o medios técnicos) y, superado el proceso, las adaptaciones del puesto de trabajo (art. 59.2). En la provisión de puestos también se prevé que, en los concursos con entrevista, el aspirante con discapacidad pida en su solicitud adaptaciones de tiempo y medios (art. 45.4 RGI).","refs":[{"ref":"Art. 59.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Cada Administración Pública adoptará las medidas precisas para establecer las adaptaciones y ajustes razonables de tiempos y medios en el proceso selectivo y, una vez superado dicho proceso, las adaptaciones en el puesto de trabajo a las necesidades de las personas con discapacidad."},{"ref":"Art. 45.4 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Los aspirantes con alguna discapacidad podrán pedir en la solicitud de participación las posibles adaptaciones de tiempo y medios para la realización de las entrevistas."}]}]},{"n":"5","title":"Planificación de recursos humanos y Oferta de Empleo Público","blocks":[{"text":"La planificación busca la eficacia en los servicios y la eficiencia en el uso de los recursos mediante la dimensión adecuada de los efectivos, su distribución, formación, promoción y movilidad (art. 69.1 TREBEP). Las Administraciones pueden aprobar Planes de ordenación de recursos humanos con medidas como el análisis de necesidades, la movilidad, la promoción interna o la previsión de incorporaciones mediante la Oferta de empleo público (art. 69.2).","refs":[{"ref":"Art. 69.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La planificación de los recursos humanos en las Administraciones Públicas tendrá como objetivo contribuir a la consecución de la eficacia en la prestación de los servicios y de la eficiencia en la utilización de los recursos económicos disponibles mediante la dimensión adecuada de sus efectivos, su mejor distribución, formación, promoción profesional y movilidad."}]},{"text":"Las necesidades de personal con asignación presupuestaria que deban cubrirse con personal de nuevo ingreso son objeto de la Oferta de empleo público (OEP), que obliga a convocar los procesos para las plazas comprometidas y hasta un diez por cien adicional; su ejecución debe hacerse en el plazo improrrogable de tres años (art. 70.1). La OEP se aprueba anualmente por los órganos de Gobierno y se publica en el diario oficial (art. 70.2). En la AGE, el RGI añade que van a la OEP las necesidades no cubiertas con los efectivos existentes, siempre que haya crédito y se considere conveniente su cobertura en el ejercicio (art. 7), que la aprueba el Gobierno en el primer trimestre de cada año (art. 8.1) y que, aprobada, convocan los Departamentos de adscripción de los cuerpos, previo informe favorable de la Dirección General de la Función Pública (art. 9).","refs":[{"ref":"Art. 70.1-2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"lo que comportará la obligación de convocar los correspondientes procesos selectivos para las plazas comprometidas y hasta un diez por cien adicional, fijando el plazo máximo para la convocatoria de los mismos. En todo caso, la ejecución de la oferta de empleo público o instrumento similar deberá desarrollarse dentro del plazo improrrogable de tres años. 2. La Oferta de empleo público o instrumento similar, que se aprobará anualmente por los órganos de Gobierno de las Administraciones Públicas, deberá ser publicada en el Diario oficial correspondiente."},{"ref":"Art. 7 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Las necesidades de recursos humanos que no puedan ser cubiertas con los efectivos de personal existentes serán objeto de oferta de empleo público, siempre que exista crédito presupuestario y se considere conveniente su cobertura durante el ejercicio."},{"ref":"Art. 8.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"La oferta de empleo público será aprobada, en su caso, por el Gobierno a propuesta del Ministro para las Administraciones Públicas con informe favorable del Ministerio de Economía y Hacienda, en el primer trimestre de cada año."}]}]},{"n":"6","title":"Órganos de selección","blocks":[{"text":"Los órganos de selección son colegiados, su composición se ajusta a la imparcialidad y profesionalidad de sus miembros y se tiende a la paridad entre mujer y hombre (art. 60.1 TREBEP). No pueden formar parte de ellos el personal de elección o designación política, los funcionarios interinos ni el personal eventual (art. 60.2), y se pertenece siempre a título individual, nunca en representación o por cuenta de nadie (art. 60.3).","refs":[{"ref":"Art. 60 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"1. Los órganos de selección serán colegiados y su composición deberá ajustarse a los principios de imparcialidad y profesionalidad de sus miembros, y se tenderá, asimismo, a la paridad entre mujer y hombre. 2. El personal de elección o de designación política, los funcionarios interinos y el personal eventual no podrán formar parte de los órganos de selección. 3. La pertenencia a los órganos de selección será siempre a título individual, no pudiendo ostentarse ésta en representación o por cuenta de nadie."}]},{"text":"En la AGE hay dos clases: Tribunales y Comisiones Permanentes de Selección (art. 10 RGI). Los Tribunales se nombran en cada convocatoria y tienen un número impar de miembros, funcionarios de carrera, no inferior a cinco, con igual número de suplentes y titulación igual o superior a la exigida (art. 11). Las Comisiones Permanentes actúan cuando lo aconsejan el elevado número de aspirantes y la titulación o especialización (art. 12). Reglas adicionales (art. 13): no pueden estar formados mayoritariamente por miembros del mismo cuerpo objeto de selección; no puede ser miembro quien haya preparado aspirantes en los cinco años anteriores a la convocatoria; pueden incorporar asesores especialistas; y rigen la abstención y recusación. Sus resoluciones vinculan a la Administración, que puede revisarlas de oficio (art. 14.1).","refs":[{"ref":"Art. 11 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Estarán constituidos por un número impar de miembros, funcionarios de carrera, no inferior a cinco, debiendo designarse el mismo número de miembros suplentes y en su composición se velará por el cumplimiento del principio de especialidad."},{"ref":"Art. 13.1-2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"1. Los órganos de selección no podrán estar formados mayoritariamente por funcionarios pertenecientes al mismo Cuerpo o Escala objeto de la selección […] 2. No podrán formar parte de los órganos de selección aquellos funcionarios que hubiesen realizado tareas de preparación de aspirantes a pruebas selectivas en los cinco años anteriores a la publicación de la correspondiente convocatoria."}]},{"text":"Aviso de actualización: el artículo 14.2 RGI habla de «recurso ordinario» ante quien nombró al presidente y el 13.4 remite a la Ley 30/1992; ambas referencias deben entenderse hechas hoy a la Ley 39/2015 (recurso de alzada) y a la Ley 40/2015, que no se desarrollan en este tema.","refs":[{"ref":"Art. 14.2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Contra las resoluciones y actos de los órganos de selección y sus actos de trámite que impidan continuar el procedimiento o produzcan indefensión podrá interponerse recurso ordinario ante la autoridad que haya nombrado a su presidente."}]}]},{"n":"7","title":"Sistemas selectivos","blocks":[{"text":"Los procesos son abiertos y garantizan la libre concurrencia, salvo la promoción interna y las medidas de discriminación positiva (art. 61.1 TREBEP). Las pruebas deben conectar con las tareas de los puestos y pueden comprobar conocimientos y capacidad analítica, habilidades, idiomas y, en su caso, aptitud física (art. 61.2); pueden completarse con cursos, prácticas, exposición curricular, psicotécnicos, entrevistas o reconocimientos médicos (art. 61.5). Si además se valoran méritos, esa valoración debe ser proporcionada y nunca determinará por sí sola el resultado (art. 61.3).","refs":[{"ref":"Art. 61.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los procesos selectivos que incluyan, además de las preceptivas pruebas de capacidad, la valoración de méritos de los aspirantes sólo podrán otorgar a dicha valoración una puntuación proporcionada que no determinará, en ningún caso, por sí misma el resultado del proceso selectivo."}]},{"text":"Para funcionarios de carrera los sistemas son la oposición y el concurso-oposición; el concurso (solo méritos) únicamente puede aplicarse con carácter excepcional y en virtud de ley (art. 61.6). El RGI define la oposición como una o más pruebas para determinar capacidad y aptitud y fijar el orden de prelación; el concurso, como la calificación de méritos; y el concurso-oposición, como la sucesión de ambos (art. 4.2). La oposición es el sistema ordinario de ingreso (art. 4.1 RGI). Ojo: el art. 4.1 RGI menciona el «concurso libre» como sistema excepcional, pero tras el TREBEP solo cabe si una ley lo prevé. El RGI exige además que, si hay varios ejercicios, al menos uno sea práctico, salvo excepción justificada (art. 5.2).","refs":[{"ref":"Art. 61.6 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los sistemas selectivos de funcionarios de carrera serán los de oposición y concurso-oposición que deberán incluir, en todo caso, una o varias pruebas para determinar la capacidad de los aspirantes y establecer el orden de prelación. Sólo en virtud de ley podrá aplicarse, con carácter excepcional, el sistema de concurso que consistirá únicamente en la valoración de méritos."},{"ref":"Art. 4 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"La oposición será el sistema ordinario de ingreso, salvo cuando, por la naturaleza de las funciones a desempeñar, sea más adecuada la utilización del concurso-oposición y, excepcionalmente, del concurso. 2. La oposición consiste en la celebración de una o más pruebas para determinar la capacidad y la aptitud de los aspirantes y fijar su orden de prelación"},{"ref":"Art. 5.2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Salvo excepciones debidamente justificadas, en los procedimientos de selección que consten de varios ejercicios, al menos uno deberá tener carácter práctico."}]}]},{"n":"8","title":"Convocatorias y desarrollo de las pruebas","blocks":[{"text":"Las convocatorias y sus bases se publican en el BOE y vinculan a la Administración, a los órganos de selección y a los participantes (art. 15 RGI). Deben contener, entre otros extremos, el número de plazas, la declaración de que no se aprobará a más aspirantes que plazas, los requisitos, el sistema selectivo, el tribunal, el programa y la duración máxima del proceso: entre el final de un ejercicio y el comienzo del siguiente deben pasar entre setenta y dos horas y cuarenta y cinco días naturales (art. 16). El orden de actuación se fija por un único sorteo público anual (art. 17).","refs":[{"ref":"Art. 16.j) RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"j) Duración máxima del proceso de celebración de los ejercicios. Desde la total conclusión de un ejercicio o prueba hasta el comienzo del siguiente deberá transcurrir un plazo mínimo de setenta y dos horas y máximo de cuarenta y cinco días naturales."}]},{"text":"Las solicitudes se presentan en veinte días naturales desde el día siguiente a la publicación en el BOE, y basta declarar que se reúnen los requisitos a la fecha de fin de plazo (art. 18). En un mes se aprueban las listas de admitidos y excluidos, con diez días hábiles para subsanar (art. 20.1). Iniciado el proceso, los anuncios de las siguientes pruebas pueden hacerse en los locales del examen con doce horas de antelación si es el mismo ejercicio o veinticuatro si es uno nuevo (art. 21). Los aprobados se publican por orden de puntuación (art. 22.1) y aportan la documentación en veinte días naturales; quien no la presente o no reúna los requisitos no puede ser nombrado (art. 23).","refs":[{"ref":"Art. 18.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"deberá presentarse en el plazo de veinte días naturales a partir del siguiente al de publicación de la convocatoria respectiva en el «Boletín Oficial del Estado»."},{"ref":"Art. 21 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"con doce horas, al menos, de antelación al comienzo de éste, si se trata del mismo ejercicio, o de veinticuatro horas, si se trata de uno nuevo."}]},{"text":"Los órganos de selección no pueden proponer más aprobados que plazas, salvo previsión de la convocatoria; pero si han propuesto tantos como plazas y hay renuncias antes del nombramiento o la toma de posesión, el órgano convocante puede pedir una relación complementaria de los siguientes aspirantes (art. 61.8 TREBEP).","refs":[{"ref":"Art. 61.8 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"cuando se produzcan renuncias de los aspirantes seleccionados, antes de su nombramiento o toma de posesión, el órgano convocante podrá requerir del órgano de selección relación complementaria de los aspirantes que sigan a los propuestos, para su posible nombramiento como funcionarios de carrera."}]}]},{"n":"9","title":"Adquisición de la condición de funcionario de carrera","blocks":[{"text":"La condición de funcionario de carrera se adquiere por el cumplimiento sucesivo de cuatro requisitos: superar el proceso selectivo; nombramiento por el órgano competente, publicado en el diario oficial; acto de acatamiento de la Constitución (y, en su caso, del Estatuto de Autonomía) y del resto del ordenamiento; y toma de posesión en plazo (art. 62.1 TREBEP). Quien no acredite los requisitos de la convocatoria no podrá ser nombrado y sus actuaciones quedan sin efecto (art. 62.2).","refs":[{"ref":"Art. 62.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"a) Superación del proceso selectivo. b) Nombramiento por el órgano o autoridad competente, que será publicado en el Diario Oficial correspondiente. c) Acto de acatamiento de la Constitución y, en su caso, del Estatuto de Autonomía correspondiente y del resto del Ordenamiento Jurídico. d) Toma de posesión dentro del plazo que se establezca."}]},{"text":"Si la convocatoria prevé periodo de prácticas o curso selectivo, los aspirantes son nombrados funcionarios en prácticas, y quien no supere el curso pierde el derecho al nombramiento (art. 24.1 RGI). Solo cuando hay curso selectivo puede haber más aprobados en las pruebas que plazas (art. 22.3). Los nombramientos, que nunca pueden exceder del número de plazas (cualquier resolución contraria es nula de pleno derecho), se publican en el BOE (art. 25 RGI).","refs":[{"ref":"Art. 25 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"cuyo número no podrá exceder en ningún caso al de plazas convocadas, serán nombrados funcionarios de carrera por el Secretario de Estado para la Administración Pública. Cualquier resolución que contravenga lo anteriormente establecido será nula de pleno derecho. 2. Los nombramientos deberán publicarse en el «Boletín Oficial del Estado»."}]}]},{"n":"10","title":"Funcionarios interinos: supuestos, selección y cese","blocks":[{"text":"El interino se nombra por razones justificadas de necesidad y urgencia en cuatro supuestos (art. 10.1 TREBEP): vacantes no cubribles por funcionarios de carrera (máximo tres años), sustitución transitoria de titulares, programas temporales (máximo tres años, ampliable doce meses por ley) y exceso o acumulación de tareas (nueve meses en un periodo de dieciocho). Su selección es pública y se rige por igualdad, mérito, capacidad, publicidad y celeridad; el nombramiento nunca da la condición de funcionario de carrera (art. 10.2). En la AGE lo nombra el Subsecretario del Departamento de adscripción del cuerpo, o el Director General de la Función Pública para los cuerpos de la Secretaría de Estado (art. 27.1 RGI), y debe reunir los requisitos de titulación del acceso como funcionario de carrera (art. 27.2).","refs":[{"ref":"Art. 10.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los procedimientos de selección del personal funcionario interino serán públicos, rigiéndose en todo caso por los principios de igualdad, mérito, capacidad, publicidad y celeridad, y tendrán por finalidad la cobertura inmediata del puesto."},{"ref":"Art. 27.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"El nombramiento del personal funcionario interino se efectuará, con arreglo a los principios de mérito y capacidad, por el Subsecretario del Departamento al que figuren adscritos los correspondientes Cuerpos y Escalas"}]},{"text":"La interinidad termina de oficio, sin compensación, por cobertura reglada de la plaza por funcionario de carrera, supresión o amortización del puesto, fin del plazo autorizado o fin de la causa del nombramiento (art. 10.3). En vacantes, a los tres años se produce el cese; excepcionalmente puede seguir hasta la resolución de la convocatoria si esta se publicó dentro de esos tres años (art. 10.4). Si la Administración incumple el plazo máximo de permanencia, el interino tiene derecho a una compensación de veinte días de retribuciones fijas por año de servicio, hasta doce mensualidades, salvo cese disciplinario o renuncia voluntaria (disp. adic. 17.ª.4).","refs":[{"ref":"Art. 10.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Excepcionalmente, el personal funcionario interino podrá permanecer en la plaza que ocupe temporalmente, siempre que se haya publicado la correspondiente convocatoria dentro del plazo de los tres años, a contar desde la fecha del nombramiento del funcionario interino y sea resuelta conforme a los plazos establecidos en el artículo 70 del TREBEP."},{"ref":"Disp. adic. 17.ª.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El incumplimiento del plazo máximo de permanencia dará lugar a una compensación económica para el personal funcionario interino afectado, que será equivalente a veinte días de sus retribuciones fijas por año de servicio, prorrateándose por meses los períodos de tiempo inferiores a un año, hasta un máximo de doce mensualidades."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Igualdad (art. 23.2 CE) + mérito y capacidad (art. 103.3 CE).","refs":[{"ref":"Art. 103.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"el acceso a la función pública de acuerdo con los principios de mérito y capacidad"}]},{"text":"Extranjero no comunitario con residencia legal: solo como personal laboral.","refs":[{"ref":"Art. 57.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"así como los extranjeros con residencia legal en España podrán acceder a las Administraciones Públicas, como personal laboral, en igualdad de condiciones que los españoles."}]},{"text":"Discapacidad: cupo mínimo del 7 %, del que al menos el 2 % de las plazas es para discapacidad intelectual.","refs":[{"ref":"Art. 59.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"al menos, el dos por ciento de las plazas ofertadas lo sea para ser cubiertas por personas que acrediten discapacidad intelectual"}]},{"text":"OEP: anual, con hasta un 10 % adicional y ejecución en tres años improrrogables.","refs":[{"ref":"Art. 70.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"En todo caso, la ejecución de la oferta de empleo público o instrumento similar deberá desarrollarse dentro del plazo improrrogable de tres años."}]},{"text":"Tribunal AGE: impar, mínimo cinco funcionarios de carrera; nadie que haya preparado opositores en los cinco años anteriores.","refs":[{"ref":"Art. 13.2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"en los cinco años anteriores a la publicación de la correspondiente convocatoria."}]},{"text":"Entre ejercicios: mínimo 72 horas, máximo 45 días naturales.","refs":[{"ref":"Art. 16.j) RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"plazo mínimo de setenta y dos horas y máximo de cuarenta y cinco días naturales."}]},{"text":"Ninguna pertenencia a un tribunal es en representación de nadie; interinos, eventuales y cargos políticos quedan excluidos.","refs":[{"ref":"Art. 60.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El personal de elección o de designación política, los funcionarios interinos y el personal eventual no podrán formar parte de los órganos de selección."}]},{"text":"Concurso puro para funcionarios: solo por ley y con carácter excepcional; la oposición es el sistema ordinario en la AGE.","refs":[{"ref":"Art. 4.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"La oposición será el sistema ordinario de ingreso"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', null, null, null, 'Otras normas citadas: CE (https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229), RD 364/1995 (https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729)'
