insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Clases de situaciones administrativas (art. 85 TREBEP; art. 2 RD 365/1995)"},{"n":"2","title":"Servicio activo: supuestos (art. 86 TREBEP; art. 3 RD 365/1995)"},{"n":"3","title":"Servicios especiales: supuestos, efectos y reingreso (art. 87 TREBEP; arts. 4-9 RD 365/1995)"},{"n":"4","title":"Servicio en otras Administraciones Públicas (art. 88 TREBEP; arts. 10-11 RD 365/1995)"},{"n":"5","title":"Excedencias: interés particular, agrupación familiar, cuidado de familiares, violencia de género y terrorista (art. 89 TREBEP)"},{"n":"6","title":"Excedencia por prestación de servicios en el sector público y excedencia forzosa en la AGE (arts. 13 y 15 RD 365/1995)"},{"n":"7","title":"Suspensión de funciones provisional y firme (art. 90 TREBEP; arts. 20-22 RD 365/1995)"},{"n":"8","title":"Reingreso y cambios de situación (art. 91 TREBEP; art. 23 RD 365/1995)"},{"n":"9","title":"Situaciones del personal laboral (art. 92 TREBEP)"}]'::jsonb, '["Art. 85.1 TREBEP: «Los funcionarios de carrera se hallarán en alguna de las siguientes situaciones: a) Servicio activo. b) Servicios especiales. c) Servicio en otras Administraciones Públicas. d) Excedencia. e) Suspensión de funciones.»","Art. 3 RD 365/1995: «Los funcionarios se hallan en situación de servicio activo: […] c) Cuando se encuentren en comisión de servicios.»","Art. 87.2 TREBEP: «Quienes se encuentren en situación de servicios especiales percibirán las retribuciones del puesto o cargo que desempeñen y no las que les correspondan como funcionarios de carrera, sin perjuicio del derecho a percibir los trienios que tengan reconocidos en cada momento.»","Art. 87.3 TREBEP: «Quienes se encuentren en situación de servicios especiales tendrán derecho, al menos, a reingresar al servicio activo en la misma localidad, en las condiciones y con las retribuciones correspondientes a la categoría, nivel o escalón de la carrera consolidados»","Art. 9.1 RD 365/1995: «Quienes pierdan la condición, en virtud de la cual hubieran sido declarados en la situación de servicios especiales deberán solicitar el reingreso al servicio activo en el plazo de un mes, declarándoseles, de no hacerlo en la situación de excedencia voluntaria por interés particular»","Art. 88.1 TREBEP: «Los funcionarios de carrera que, en virtud de los procesos de transferencias o por los procedimientos de provisión de puestos de trabajo, obtengan destino en una Administración Pública distinta, serán declarados en la situación de servicio en otras Administraciones Públicas.»","Art. 89.2 TREBEP: «Los funcionarios de carrera podrán obtener la excedencia voluntaria por interés particular cuando hayan prestado servicios efectivos en cualquiera de las Administraciones Públicas durante un periodo mínimo de cinco años inmediatamente anteriores.»","Art. 89.4 TREBEP: «El puesto de trabajo desempeñado se reservará, al menos, durante dos años. Transcurrido este periodo, dicha reserva lo será a un puesto en la misma localidad y de igual retribución.»","Art. 89.5 TREBEP: «Durante los seis primeros meses tendrán derecho a la reserva del puesto de trabajo que desempeñarán, siendo computable dicho período a efectos de antigüedad, carrera y derechos del régimen de Seguridad Social que sea de aplicación.»","Art. 15.1 RD 365/1995: «Procederá declarar, de oficio o a instancia de parte, en la situación regulada en este artículo a los funcionarios de carrera que se encuentren en servicio activo en otro cuerpo o escala de cualquiera de las Administraciones públicas, salvo que hubieran obtenido la oportuna compatibilidad»","Art. 90.1 TREBEP: «La suspensión determinará la pérdida del puesto de trabajo cuando exceda de seis meses.»","Art. 90.2 TREBEP: «La suspensión firme se impondrá en virtud de sentencia dictada en causa criminal o en virtud de sanción disciplinaria. La suspensión firme por sanción disciplinaria no podrá exceder de seis años.»","Art. 22.3 RD 365/1995: «El funcionario que haya perdido su puesto de trabajo como consecuencia de condena o sanción deberá solicitar el reingreso al servicio activo con un mes de antelación a la finalización del período de duración de la suspensión.»","Art. 23.1 RD 365/1995: «Los cambios de situaciones administrativas deberán ser siempre comunicados al Registro Central de Personal»","Art. 92 TREBEP: «El personal laboral se regirá por el Estatuto de los Trabajadores y por los Convenios Colectivos que les sean de aplicación.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Clases de situaciones administrativas","blocks":[{"text":"La situación administrativa describe en qué posición está el funcionario de carrera respecto de su relación de servicio en cada momento. El TREBEP fija cinco situaciones básicas: servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones (art. 85.1). Las leyes de Función Pública pueden crear otras, por ejemplo cuando por reestructuración o exceso de personal no sea posible asignar un puesto, o cuando el funcionario acceda a otro cuerpo y no le corresponda otra situación (art. 85.2).","refs":[{"ref":"Art. 85.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los funcionarios de carrera se hallarán en alguna de las siguientes situaciones: a) Servicio activo. b) Servicios especiales. c) Servicio en otras Administraciones Públicas. d) Excedencia. e) Suspensión de funciones."}]},{"text":"En la AGE sigue vigente el RD 365/1995, cuyo artículo 2 enumera once situaciones porque desdobla la excedencia en varias modalidades e incluye la expectativa de destino y la excedencia voluntaria incentivada. Ese reglamento se dictó en desarrollo de la Ley 30/1984; se aplica en lo que no se oponga al TREBEP (disp. final 4.ª.2 TREBEP), de modo que, si hay contradicción, prevalece el Estatuto.","refs":[{"ref":"Art. 2 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"a) Servicio activo. b) Servicios especiales. c) Servicio en Comunidades Autónomas. d) Expectativa de destino. e) Excedencia forzosa. f) Excedencia para el cuidado de hijos. g) Excedencia voluntaria por servicios en el sector público. h) Excedencia voluntaria por interés particular. i) Excedencia voluntaria por agrupación familiar. j) Excedencia voluntaria incentivada. k) Suspensión de funciones."},{"ref":"Disp. final 4.ª.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"se mantendrán en vigor en cada Administración Pública las normas vigentes sobre ordenación, planificación y gestión de recursos humanos en tanto no se opongan a lo establecido en este Estatuto."}]}]},{"n":"2","title":"Servicio activo","blocks":[{"text":"Está en servicio activo quien presta servicios como funcionario en cualquier Administración u organismo y no le corresponde quedar en otra situación (art. 86.1 TREBEP); goza de todos los derechos y queda sujeto a todos los deberes de su condición (art. 86.2). El RD 365/1995 concreta los supuestos (art. 3): desempeñar un puesto de la RPT; prestar servicios en Corporaciones Locales o Universidades en puestos abiertos a funcionarios del Estado; estar en comisión de servicios; trabajar en gabinetes ministeriales optando por el activo; quedar a disposición del Subsecretario; estar en el plazo posesorio tras cesar por haber obtenido otro puesto; encontrarse en las dos primeras fases de reasignación de efectivos; o la cesación progresiva de actividades.","refs":[{"ref":"Art. 86.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los funcionarios de carrera en situación de servicio activo gozan de todos los derechos inherentes a su condición de funcionarios y quedan sujetos a los deberes y responsabilidades derivados de la misma."},{"ref":"Art. 3 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"c) Cuando se encuentren en comisión de servicios. […] i) Cuando cesen en un puesto de trabajo por haber obtenido otro mediante procedimientos de provisión de puestos de trabajo, durante el plazo posesorio. j) Cuando se encuentren en las dos primeras fases de reasignación de efectivos."}]}]},{"n":"3","title":"Servicios especiales: supuestos","blocks":[{"text":"Pasan a servicios especiales los funcionarios de carrera que asumen otra función pública relevante (art. 87.1 TREBEP), entre otros: miembros del Gobierno o de gobiernos autonómicos, de instituciones de la UE u organizaciones internacionales y altos cargos; misiones de más de seis meses en organismos internacionales o programas de cooperación; puestos asimilados a altos cargos; adscripción al Tribunal Constitucional, Defensor del Pueblo o Tribunal de Cuentas; Diputados, Senadores y parlamentarios autonómicos que perciban retribuciones periódicas; cargos electivos locales retribuidos y con dedicación exclusiva; miembros del CGPJ y de órganos constitucionales; asesores de grupos parlamentarios; y reservistas voluntarios activados.","refs":[{"ref":"Art. 87.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"e) Cuando accedan a la condición de Diputado o Senador de las Cortes Generales o miembros de las asambleas legislativas de las comunidades autónomas si perciben retribuciones periódicas por la realización de la función."},{"ref":"Art. 87.1.a) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"a) Cuando sean designados miembros del Gobierno o de los órganos de gobierno de las comunidades autónomas y ciudades de Ceuta y Melilla, miembros de las Instituciones de la Unión Europea o de las organizaciones internacionales, o sean nombrados altos cargos de las citadas Administraciones Públicas o Instituciones."}]},{"text":"Un caso que se pregunta mucho: el funcionario nombrado personal eventual para un puesto de confianza o asesoramiento político pasa a servicios especiales solo si no opta por seguir en servicio activo (art. 87.1.i). La situación se declara de oficio o a instancia del interesado, una vez verificado el supuesto, con efectos desde que se produjo (art. 6.1 RD 365/1995). Ojo: el art. 4 RD 365/1995 conserva supuestos ya superados, como el servicio militar o la prestación social sustitutoria (letra k), que hoy carecen de aplicación práctica.","refs":[{"ref":"Art. 87.1.i) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"i) Cuando sean designados como personal eventual por ocupar puestos de trabajo con funciones expresamente calificadas como de confianza o asesoramiento político y no opten por permanecer en la situación de servicio activo."},{"ref":"Art. 6.1 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"El pase a la situación de servicios especiales se declarará de oficio o a instancia del interesado, una vez verificado el supuesto que la ocasione, con efectos desde el momento en que se produjo."},{"ref":"Art. 4.k) RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"k) Cuando cumplan el servicio militar o prestación social sustitutoria equivalente."}]}]},{"n":"4","title":"Servicios especiales: efectos y reingreso","blocks":[{"text":"En servicios especiales se cobran las retribuciones del cargo que se desempeña, no las de funcionario, aunque se mantiene el derecho a percibir los trienios reconocidos; el tiempo computa para ascensos, trienios, promoción interna y Seguridad Social (art. 87.2 TREBEP). Al reingresar se tiene derecho, al menos, a hacerlo en la misma localidad, con las condiciones y retribuciones de la categoría, nivel o escalón consolidados (art. 87.3). En la AGE, si el puesto anterior era de libre designación se adjudica provisionalmente uno de igual nivel y similares retribuciones en el mismo municipio; en los demás casos, con carácter definitivo, en el mismo Ministerio y municipio (art. 7.1 RD 365/1995).","refs":[{"ref":"Art. 87.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Quienes se encuentren en situación de servicios especiales percibirán las retribuciones del puesto o cargo que desempeñen y no las que les correspondan como funcionarios de carrera, sin perjuicio del derecho a percibir los trienios que tengan reconocidos en cada momento. El tiempo que permanezcan en tal situación se les computará a efectos de ascensos, reconocimiento de trienios, promoción interna y derechos en el régimen de Seguridad Social que les sea de aplicación."},{"ref":"Art. 87.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Quienes se encuentren en situación de servicios especiales tendrán derecho, al menos, a reingresar al servicio activo en la misma localidad, en las condiciones y con las retribuciones correspondientes a la categoría, nivel o escalón de la carrera consolidados"}]},{"text":"Quien pierde la condición que motivó los servicios especiales (por ejemplo, el alto cargo cesado) debe pedir el reingreso en el plazo de un mes; si no lo hace, se le declara en excedencia voluntaria por interés particular desde el día en que perdió esa condición (art. 9.1 RD 365/1995). Los parlamentarios que pierdan su condición por disolución o fin del mandato pueden seguir en servicios especiales hasta la nueva constitución de la cámara (art. 87.1.e TREBEP; art. 9.2 RD 365/1995).","refs":[{"ref":"Art. 9.1 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"Quienes pierdan la condición, en virtud de la cual hubieran sido declarados en la situación de servicios especiales deberán solicitar el reingreso al servicio activo en el plazo de un mes, declarándoseles, de no hacerlo en la situación de excedencia voluntaria por interés particular, con efectos desde el día en que perdieron aquella condición."}]}]},{"n":"5","title":"Servicio en otras Administraciones Públicas","blocks":[{"text":"Se declara esta situación cuando el funcionario obtiene destino en otra Administración por transferencias o por los procedimientos de provisión (art. 88.1 TREBEP). Los transferidos a las comunidades autónomas se integran plenamente en su función pública, en servicio activo en ella, conservando grupo y derechos económicos (art. 88.2). Quien llega por concurso o libre designación se rige por la legislación de la Administración de destino, pero conserva su condición de funcionario de origen y el derecho a concursar en ella, y el tiempo le computa como servicio activo en su cuerpo de origen (art. 88.3).","refs":[{"ref":"Art. 88.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los funcionarios de carrera que, en virtud de los procesos de transferencias o por los procedimientos de provisión de puestos de trabajo, obtengan destino en una Administración Pública distinta, serán declarados en la situación de servicio en otras Administraciones Públicas."},{"ref":"Art. 88.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"se rigen por la legislación de la Administración en la que estén destinados de forma efectiva y conservan su condición de funcionario de la Administración de origen y el derecho a participar en las convocatorias para la provisión de puestos de trabajo que se efectúen por esta última. El tiempo de servicio en la Administración Pública en la que estén destinados se les computará como de servicio activo en su cuerpo o escala de origen."}]},{"text":"El RD 365/1995 (que aún la llama «servicio en Comunidades Autónomas») añade que a estos funcionarios se les aplica el régimen disciplinario de la comunidad de destino, salvo la separación del servicio, que acuerda el Ministro del Departamento de adscripción del cuerpo, previa incoación del expediente por la comunidad autónoma (art. 11.2). Para los transferidos, la separación la acuerda el órgano autonómico, previo dictamen del Consejo de Estado (art. 10.2).","refs":[{"ref":"Art. 11.2 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"con excepción de la sanción de separación del servicio, que se acordará por el Ministro del Departamento al que esté adscrito el Cuerpo o Escala al que pertenezca el funcionario, previa incoación de expediente disciplinario por la Administración de la Comunidad Autónoma de destino."}]}]},{"n":"6","title":"Excedencia voluntaria por interés particular y por agrupación familiar","blocks":[{"text":"El TREBEP prevé cinco modalidades de excedencia: interés particular, agrupación familiar, cuidado de familiares, violencia de género o sexual y violencia terrorista (art. 89.1). La de interés particular exige cinco años de servicios efectivos inmediatamente anteriores en cualquier Administración, salvo que la ley de Función Pública fije un periodo menor; se subordina a las necesidades del servicio y no puede declararse mientras se instruya expediente disciplinario. Se declara de oficio cuando, finalizada otra situación, no se pide el reingreso en plazo. No se cobra ni computa a efectos de ascensos, trienios y Seguridad Social (art. 89.2).","refs":[{"ref":"Art. 89.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los funcionarios de carrera podrán obtener la excedencia voluntaria por interés particular cuando hayan prestado servicios efectivos en cualquiera de las Administraciones Públicas durante un periodo mínimo de cinco años inmediatamente anteriores. […] La concesión de excedencia voluntaria por interés particular quedará subordinada a las necesidades del servicio debidamente motivadas. No podrá declararse cuando al funcionario público se le instruya expediente disciplinario."}]},{"text":"En la AGE el art. 16.3 RD 365/1995 fija cada periodo entre dos años y un máximo de quince; esa duración procede de la normativa anterior al TREBEP, que remite la permanencia mínima a las leyes de Función Pública, por lo que conviene contrastarla con la convocatoria y la normativa vigente. La excedencia por agrupación familiar no exige servicios previos y se concede a quien tiene a su cónyuge residiendo en otra localidad por desempeñar allí un puesto definitivo como funcionario de carrera o laboral fijo en cualquier Administración, órgano constitucional, UE u organización internacional; tampoco se retribuye ni computa (art. 89.3 TREBEP).","refs":[{"ref":"Art. 16.3 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"Cada período de excedencia tendrá una duración no inferior a dos años continuados ni superior a un número de años equivalente a los que el funcionario acredite haber prestado en cualquiera de las Administraciones Públicas, con un máximo de quince."},{"ref":"Art. 89.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Podrá concederse la excedencia voluntaria por agrupación familiar sin el requisito de haber prestado servicios efectivos en cualquiera de las Administraciones Públicas durante el periodo establecido a los funcionarios cuyo cónyuge resida en otra localidad por haber obtenido y estar desempeñando un puesto de trabajo de carácter definitivo"}]}]},{"n":"7","title":"Excedencia por cuidado de familiares y por violencia","blocks":[{"text":"Se tiene derecho a una excedencia de hasta tres años por cada hijo (natural, adoptado, en guarda con fines de adopción o acogimiento permanente), a contar desde el nacimiento o la resolución judicial o administrativa, y de hasta tres años para cuidar a un familiar a cargo hasta el segundo grado que no pueda valerse por sí mismo y no trabaje (art. 89.4 TREBEP). Es única por sujeto causante y una nueva excedencia pone fin a la anterior. Computa para trienios, carrera y Seguridad Social; el puesto se reserva al menos dos años y, después, la reserva es de un puesto en la misma localidad y de igual retribución. El RD 365/1995 (art. 14.2) habla de reserva del puesto sin ese límite: prevalece el TREBEP.","refs":[{"ref":"Art. 89.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los funcionarios de carrera tendrán derecho a un período de excedencia de duración no superior a tres años para atender al cuidado de cada hijo […] El tiempo de permanencia en esta situación será computable a efectos de trienios, carrera y derechos en el régimen de Seguridad Social que sea de aplicación. El puesto de trabajo desempeñado se reservará, al menos, durante dos años. Transcurrido este periodo, dicha reserva lo será a un puesto en la misma localidad y de igual retribución."}]},{"text":"Las funcionarias víctimas de violencia de género o sexual pueden pedir la excedencia sin servicios previos ni plazo de permanencia. Durante los seis primeros meses se reserva su puesto y computa a efectos de antigüedad, carrera y Seguridad Social; si lo exigen las actuaciones judiciales, el periodo puede prorrogarse por tres meses, hasta un máximo de dieciocho; los dos primeros meses perciben retribuciones íntegras (art. 89.5). Las víctimas del terrorismo y amenazados tienen excedencia en las mismas condiciones, mientras sea necesaria para su protección (art. 89.6).","refs":[{"ref":"Art. 89.5 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Durante los seis primeros meses tendrán derecho a la reserva del puesto de trabajo que desempeñarán, siendo computable dicho período a efectos de antigüedad, carrera y derechos del régimen de Seguridad Social que sea de aplicación. Cuando las actuaciones judiciales lo exigieran se podrá prorrogar este periodo por tres meses, con un máximo de dieciocho"},{"ref":"Art. 89.5 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Durante los dos primeros meses de esta excedencia la funcionaria tendrá derecho a percibir las retribuciones íntegras"}]}]},{"n":"8","title":"Excedencia por servicios en el sector público, forzosa y otras situaciones de la AGE","blocks":[{"text":"El RD 365/1995 mantiene la excedencia voluntaria por prestación de servicios en el sector público: se declara, de oficio o a instancia de parte, al funcionario que está en servicio activo en otro cuerpo de cualquier Administración (salvo compatibilidad) o pasa a ser laboral fijo en el sector público; no habilita el desempeño como interino o laboral temporal; y al cesar debe pedir el reingreso en un mes, o pasa a interés particular (art. 15). Ninguna excedencia voluntaria reserva puesto, devenga retribuciones ni computa a efectos de promoción, trienios y derechos pasivos (art. 19).","refs":[{"ref":"Art. 15.1 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"Procederá declarar, de oficio o a instancia de parte, en la situación regulada en este artículo a los funcionarios de carrera que se encuentren en servicio activo en otro cuerpo o escala de cualquiera de las Administraciones públicas, salvo que hubieran obtenido la oportuna compatibilidad"},{"ref":"Art. 19 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"Las distintas modalidades de excedencia voluntaria no producen, en ningún caso, reserva de puesto de trabajo y los funcionarios que se encuentren en las mismas no devengarán retribuciones"}]},{"text":"La excedencia forzosa se produce cuando el funcionario en expectativa de destino agota el año máximo o incumple sus obligaciones, o cuando el suspenso firme sin reserva de puesto pide el reingreso y no se le concede en seis meses (art. 13.1). Da derecho a las retribuciones básicas y a computar el tiempo a efectos de derechos pasivos y trienios, pero obliga a concursar y aceptar el reingreso (arts. 13.3 y 13.6). La expectativa de destino dura como máximo un año (art. 12.2). Estas figuras, como la excedencia incentivada (art. 18), no aparecen en el art. 85 TREBEP y subsisten por la vía de la disp. final 4.ª.2.","refs":[{"ref":"Art. 13.1 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"b) Cuando el funcionario declarado en la situación de suspensión firme, que no tenga reservado puesto de trabajo, solicite el reingreso y no se le conceda en el plazo de seis meses contados a partir de la extinción de la responsabilidad penal o disciplinaria"},{"ref":"Art. 13.6 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"Los funcionarios en esta situación tendrán derecho a percibir las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo, así como al cómputo del tiempo en dicha situación a efectos de derechos pasivos y de trienios."}]}]},{"n":"9","title":"Suspensión de funciones provisional y firme","blocks":[{"text":"El suspenso queda privado del ejercicio de sus funciones y de los derechos inherentes a su condición, y la suspensión implica pérdida del puesto cuando excede de seis meses (art. 90.1 TREBEP). La suspensión firme se impone por sentencia en causa criminal o por sanción disciplinaria; en este último caso no puede superar seis años (art. 90.2). Mientras dura, no se puede trabajar en ninguna Administración ni en sus entes (art. 90.3).","refs":[{"ref":"Art. 90.1-2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La suspensión determinará la pérdida del puesto de trabajo cuando exceda de seis meses. 2. La suspensión firme se impondrá en virtud de sentencia dictada en causa criminal o en virtud de sanción disciplinaria. La suspensión firme por sanción disciplinaria no podrá exceder de seis años."}]},{"text":"La suspensión provisional se acuerda preventivamente durante un procedimiento judicial o disciplinario (art. 90.4 TREBEP; art. 21.1 RD 365/1995). En el expediente disciplinario la acuerda la autoridad que ordenó incoarlo y no puede exceder de seis meses, salvo paralización imputable al interesado (art. 21.3 RD 365/1995; art. 98.3 TREBEP). Contradicción a vigilar: el art. 21.4 RD 365/1995 reconoce al suspenso provisional el 75 % del sueldo, trienios y pagas extraordinarias, mientras que el art. 98.3 TREBEP le reconoce las retribuciones básicas y, en su caso, las prestaciones por hijo a cargo; prevalece el TREBEP. Si la suspensión no llega a ser firme, el tiempo computa como servicio activo.","refs":[{"ref":"Art. 21.3 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"La suspensión provisional como medida preventiva durante la tramitación de un expediente disciplinario podrá ser acordada por la autoridad que ordenó la incoación del expediente, no pudiendo exceder esta suspensión de seis meses, salvo en caso de paralización del procedimiento imputable al interesado."},{"ref":"Art. 98.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El funcionario suspenso provisional tendrá derecho a percibir durante la suspensión las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo."},{"ref":"Art. 21.4 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"El suspenso provisional tendrá derecho a percibir el 75 por 100 de su sueldo, trienios y pagas extraordinarias"}]},{"text":"Quien pierde el puesto por condena o sanción debe pedir el reingreso con un mes de antelación al fin de la suspensión, con efectos desde la extinción de la responsabilidad (art. 22.3 RD 365/1995). Si no lo pide, pasa de oficio a excedencia voluntaria por interés particular (art. 22.4); si lo pide y no se le concede en seis meses, a excedencia forzosa (art. 22.5).","refs":[{"ref":"Art. 22.3 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"El funcionario que haya perdido su puesto de trabajo como consecuencia de condena o sanción deberá solicitar el reingreso al servicio activo con un mes de antelación a la finalización del período de duración de la suspensión."}]}]},{"n":"10","title":"Reingreso y cambios de situación","blocks":[{"text":"El TREBEP remite al reglamento los plazos, procedimientos y condiciones del reingreso según la situación de procedencia, respetando la reserva de puesto cuando proceda (art. 91). Los cambios de situación se comunican siempre al Registro Central de Personal y pueden producirse sin reingreso previo al servicio activo si se reúnen los requisitos (art. 23.1 RD 365/1995). Quien no tiene reserva de puesto reingresa concursando, por libre designación o por adscripción provisional según las necesidades del servicio (art. 62 RGI).","refs":[{"ref":"Art. 91 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Reglamentariamente se regularán los plazos, procedimientos y condiciones, según las situaciones administrativas de procedencia, para solicitar el reingreso al servicio activo de los funcionarios de carrera, con respeto al derecho a la reserva del puesto de trabajo en los casos en que proceda conforme al presente Estatuto."},{"ref":"Art. 23.1 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"Los cambios de situaciones administrativas deberán ser siempre comunicados al Registro Central de Personal y podrán tener lugar, siempre que se reúnan los requisitos exigidos en cada caso, sin necesidad del reingreso previo al servicio activo."},{"ref":"Art. 62.2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Asimismo, el reingreso podrá efectuarse por adscripción provisional, condicionado a las necesidades del servicio"}]}]},{"n":"11","title":"Situaciones del personal laboral","blocks":[{"text":"El personal laboral se rige por el Estatuto de los Trabajadores y por los convenios colectivos aplicables, que pueden extenderle el capítulo de situaciones del TREBEP en lo compatible con el Estatuto de los Trabajadores (art. 92 TREBEP).","refs":[{"ref":"Art. 92 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El personal laboral se regirá por el Estatuto de los Trabajadores y por los Convenios Colectivos que les sean de aplicación. Los convenios colectivos podrán determinar la aplicación de este capítulo al personal incluido en su ámbito de aplicación en lo que resulte compatible con el Estatuto de los Trabajadores."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Comisión de servicios y plazo posesorio = servicio activo.","refs":[{"ref":"Art. 3 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"c) Cuando se encuentren en comisión de servicios."}]},{"text":"Diputado o Senador = servicios especiales; cobra el cargo, conserva trienios.","refs":[{"ref":"Art. 87.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"sin perjuicio del derecho a percibir los trienios que tengan reconocidos en cada momento."}]},{"text":"Fin de servicios especiales o de sector público: un mes para pedir reingreso o excedencia por interés particular.","refs":[{"ref":"Art. 15.3 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"deberán solicitar el reingreso al servicio activo en el plazo máximo de un mes, declarándoseles, de no hacerlo, en la situación de excedencia voluntaria por interés particular."}]},{"text":"Interés particular: cinco años de servicios previos; nunca con expediente disciplinario abierto.","refs":[{"ref":"Art. 89.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"No podrá declararse cuando al funcionario público se le instruya expediente disciplinario."}]},{"text":"Cuidado de hijos: hasta tres años; reserva del puesto al menos dos años, luego puesto en la misma localidad.","refs":[{"ref":"Art. 89.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El puesto de trabajo desempeñado se reservará, al menos, durante dos años."}]},{"text":"Violencia de género: seis meses de reserva, prorrogables por tres hasta dieciocho.","refs":[{"ref":"Art. 89.5 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"se podrá prorrogar este periodo por tres meses, con un máximo de dieciocho"}]},{"text":"Suspensión: pérdida del puesto si excede de seis meses; firme disciplinaria máximo seis años.","refs":[{"ref":"Art. 90.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La suspensión firme por sanción disciplinaria no podrá exceder de seis años."}]},{"text":"Suspenso firme sin puesto: pedir reingreso un mes antes de terminar la suspensión.","refs":[{"ref":"Art. 22.3 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"con un mes de antelación a la finalización del período de duración de la suspensión."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', null, null, null, 'Otras normas citadas: RD 365/1995 (https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730)'
