insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Derechos de los empleados públicos: individuales y ejercidos colectivamente (arts. 14-15 TREBEP)"},{"n":"2","title":"Deberes de los empleados públicos y Código de Conducta: principios éticos y de conducta (arts. 52-54 TREBEP)"},{"n":"3","title":"Provisión de puestos de trabajo: principios y procedimientos (arts. 78-81 TREBEP; arts. 36-38 RD 364/1995)"},{"n":"3.1","title":"El concurso: requisitos, méritos, comisiones de valoración, resolución y toma de posesión (arts. 39-50 RD 364/1995)"},{"n":"3.2","title":"La libre designación (arts. 51-58 RD 364/1995)"},{"n":"3.3","title":"Otras formas de provisión: redistribución y reasignación de efectivos, adscripción provisional y comisión de servicios (arts. 59-66 ter RD 364/1995)"},{"n":"4","title":"La carrera administrativa: concepto y modalidades; evaluación del desempeño (arts. 16-20 TREBEP)"},{"n":"4.1","title":"El grado personal y los intervalos de niveles (arts. 70-72 RD 364/1995)"},{"n":"5","title":"La promoción interna (art. 18 TREBEP; arts. 73-80 y disp. adic. 9.ª RD 364/1995)"}]'::jsonb, '["Art. 14.c) TREBEP: «c) A la progresión en la carrera profesional y promoción interna según principios constitucionales de igualdad, mérito y capacidad mediante la implantación de sistemas objetivos y transparentes de evaluación.»","Art. 52 TREBEP: «Los empleados públicos deberán desempeñar con diligencia las tareas que tengan asignadas y velar por los intereses generales con sujeción y observancia de la Constitución y del resto del ordenamiento jurídico»","Art. 53.5 TREBEP: «Se abstendrán en aquellos asuntos en los que tengan un interés personal, así como de toda actividad privada o interés que pueda suponer un riesgo de plantear conflictos de intereses con su puesto público.»","Art. 54.3 TREBEP: «Obedecerán las instrucciones y órdenes profesionales de los superiores, salvo que constituyan una infracción manifiesta del ordenamiento jurídico, en cuyo caso las pondrán inmediatamente en conocimiento de los órganos de inspección procedentes.»","Art. 78.1-2 TREBEP: «1. Las Administraciones Públicas proveerán los puestos de trabajo mediante procedimientos basados en los principios de igualdad, mérito, capacidad y publicidad. 2. La provisión de puestos de trabajo en cada Administración Pública se llevará a cabo por los procedimientos de concurso y de libre designación con convocatoria pública.»","Art. 36 RD 364/1995: «1. Los puestos de trabajo adscritos a funcionarios se proveerán de acuerdo con los procedimientos de concurso, que es el sistema normal de provisión, o de libre designación, de conformidad con lo que determinen las relaciones de puestos de trabajo en atención a la naturaleza de sus funciones. 2. Cuando las necesidades del servicio lo exijan, los puestos de trabajo podrán cubrirse mediante redistribución de efectivos o por reasignación de efectivos como consecuencia de un Plan de Empleo. 3. Temporalmente podrán ser cubiertos mediante comisión de servicios y adscripción provisional, en los supuestos previstos en este Reglamento.»","Art. 42.2 RD 364/1995: «El plazo de presentación de instancias será de quince días hábiles, contados a partir del siguiente al de la publicación de la convocatoria en el «Boletín Oficial del Estado».»","Art. 47.1 RD 364/1995: «El plazo para la resolución del concurso será de dos meses contados desde el día siguiente al de la finalización del de la presentación de solicitudes, salvo que la propia convocatoria establezca otro distinto.»","Art. 48.1 RD 364/1995: «El plazo para tomar posesión será de tres días hábiles si no implica cambio de residencia del funcionario, o de un mes si comporta cambio de residencia o el reingreso al servicio activo.»","Art. 58.1 RD 364/1995: «Los funcionarios nombrados para puestos de trabajo de libre designación podrán ser cesados con carácter discrecional. La motivación de esta resolución se referirá a la competencia para adoptarla.»","Art. 64.1 RD 364/1995: «Cuando un puesto de trabajo quede vacante podrá ser cubierto, en caso de urgente e inaplazable necesidad, en comisión de servicios de carácter voluntario, con un funcionario que reúna los requisitos establecidos para su desempeño en la relación de puestos de trabajo.»","Art. 16.2 TREBEP: «La carrera profesional es el conjunto ordenado de oportunidades de ascenso y expectativas de progreso profesional conforme a los principios de igualdad, mérito y capacidad.»","Art. 16.3.a)-b) TREBEP: «a) Carrera horizontal, que consiste en la progresión de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo […] b) Carrera vertical, que consiste en el ascenso en la estructura de puestos de trabajo por los procedimientos de provisión establecidos en el capítulo III del título V de este Estatuto.»","Art. 70.1-2 RD 364/1995: «1. Los puestos de trabajo se clasifican en 30 niveles. 2. Todos los funcionarios de carrera adquirirán un grado personal por el desempeño de uno o más puestos del nivel correspondiente durante dos años continuados o tres con interrupción»","Art. 73 RD 364/1995: «La promoción interna consiste en el ascenso desde Cuerpos o Escalas de un Grupo de titulación a otro del inmediato superior o en el acceso a Cuerpos o Escalas del mismo Grupo de titulación.»","Art. 76 RD 364/1995: «Para participar en pruebas de promoción interna los funcionarios deberán tener una antigüedad de, al menos, dos años en el Cuerpo o Escala a que pertenezcan el día de la finalización del plazo de presentación de solicitudes de participación y poseer la titulación y el resto de los requisitos establecidos con carácter general para el acceso al Cuerpo o Escala en el que aspiran a ingresar.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Derechos individuales de los empleados públicos","blocks":[{"text":"El artículo 14 TREBEP enumera los derechos de carácter individual, en correspondencia con la naturaleza de la relación de servicio. Destacan: la inamovilidad en la condición de funcionario de carrera; el desempeño efectivo de las funciones propias; la progresión en la carrera y la promoción interna mediante sistemas objetivos y transparentes de evaluación; percibir retribuciones e indemnizaciones; la defensa jurídica por la Administración por actos en ejercicio legítimo del cargo; la formación continua, preferentemente en horario laboral; el respeto a la intimidad y dignidad frente al acoso; la no discriminación; la conciliación; la intimidad digital y la desconexión digital; la libertad de expresión dentro del ordenamiento; la seguridad y salud; vacaciones, permisos y licencias; jubilación; Seguridad Social; y libre asociación profesional.","refs":[{"ref":"Art. 14 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"c) A la progresión en la carrera profesional y promoción interna según principios constitucionales de igualdad, mérito y capacidad mediante la implantación de sistemas objetivos y transparentes de evaluación."},{"ref":"Art. 14.g) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"g) A la formación continua y a la actualización permanente de sus conocimientos y capacidades profesionales, preferentemente en horario laboral."},{"ref":"Art. 14.f) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"f) A la defensa jurídica y protección de la Administración Pública en los procedimientos que se sigan ante cualquier orden jurisdiccional como consecuencia del ejercicio legítimo de sus funciones o cargos públicos."}]}]},{"n":"2","title":"Derechos individuales ejercidos colectivamente","blocks":[{"text":"Son derechos de titularidad individual pero de ejercicio colectivo (art. 15 TREBEP): la libertad sindical; la negociación colectiva y la participación en las condiciones de trabajo; la huelga, con garantía de los servicios esenciales; el planteamiento de conflictos colectivos; y la reunión, en los términos del artículo 46. Para el examen, distingue la libre asociación profesional (individual, art. 14.p) de la libertad sindical (colectiva, art. 15.a).","refs":[{"ref":"Art. 15 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"a) A la libertad sindical. b) A la negociación colectiva y a la participación en la determinación de las condiciones de trabajo. c) Al ejercicio de la huelga, con la garantía del mantenimiento de los servicios esenciales de la comunidad. d) Al planteamiento de conflictos colectivos de trabajo, de acuerdo con la legislación aplicable en cada caso. e) Al de reunión, en los términos establecidos en el artículo 46 de este Estatuto."},{"ref":"Art. 14.p) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"p) A la libre asociación profesional."}]}]},{"n":"3","title":"Deberes y Código de Conducta","blocks":[{"text":"Los empleados públicos deben desempeñar con diligencia sus tareas y velar por los intereses generales con sujeción a la Constitución y al ordenamiento, actuando conforme a principios como objetividad, integridad, neutralidad, responsabilidad, imparcialidad, confidencialidad, dedicación, transparencia, ejemplaridad, austeridad, accesibilidad, eficacia, honradez, promoción del entorno cultural y medioambiental e igualdad entre mujeres y hombres (art. 52). Estos principios forman el Código de Conducta, integrado por principios éticos (art. 53) y de conducta (art. 54), e informan la interpretación del régimen disciplinario.","refs":[{"ref":"Art. 52 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"objetividad, integridad, neutralidad, responsabilidad, imparcialidad, confidencialidad, dedicación al servicio público, transparencia, ejemplaridad, austeridad, accesibilidad, eficacia, honradez, promoción del entorno cultural y medioambiental, y respeto a la igualdad entre mujeres y hombres"}]},{"text":"Entre los principios éticos: abstenerse en asuntos con interés personal y de actividades que generen conflicto de intereses (art. 53.5), no aceptar tratos de favor (53.7) y guardar secreto y discreción (53.12). Entre los de conducta: obedecer las órdenes profesionales de los superiores salvo infracción manifiesta del ordenamiento, en cuyo caso deben ponerlo inmediatamente en conocimiento de la inspección (art. 54.3); rechazar regalos que excedan los usos sociales y de cortesía (54.6); mantener actualizada la formación (54.8); y atender al ciudadano en la lengua que solicite si es oficial en el territorio (54.11).","refs":[{"ref":"Art. 54.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Obedecerán las instrucciones y órdenes profesionales de los superiores, salvo que constituyan una infracción manifiesta del ordenamiento jurídico, en cuyo caso las pondrán inmediatamente en conocimiento de los órganos de inspección procedentes."},{"ref":"Art. 54.11 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Garantizarán la atención al ciudadano en la lengua que lo solicite siempre que sea oficial en el territorio."},{"ref":"Art. 53.5 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Se abstendrán en aquellos asuntos en los que tengan un interés personal, así como de toda actividad privada o interés que pueda suponer un riesgo de plantear conflictos de intereses con su puesto público."}]}]},{"n":"4","title":"Provisión de puestos: principios y procedimientos","blocks":[{"text":"Los puestos se proveen mediante procedimientos basados en igualdad, mérito, capacidad y publicidad, y los procedimientos ordinarios son el concurso y la libre designación con convocatoria pública (art. 78 TREBEP). El concurso es el procedimiento normal y lo resuelven órganos colegiados técnicos (art. 79.1). Importante: según la disp. final 4.ª.1, el capítulo III del título V (arts. 78 a 84) y los capítulos II y III del título III (carrera y retribuciones) solo producen efectos cuando se aprueben las leyes de Función Pública; por eso en la AGE la regulación aplicable sigue siendo el RD 364/1995 (RGI).","refs":[{"ref":"Art. 78.1-2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"1. Las Administraciones Públicas proveerán los puestos de trabajo mediante procedimientos basados en los principios de igualdad, mérito, capacidad y publicidad. 2. La provisión de puestos de trabajo en cada Administración Pública se llevará a cabo por los procedimientos de concurso y de libre designación con convocatoria pública."},{"ref":"Disp. final 4.ª.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Lo establecido en los capítulos II y III del título III, excepto el artículo 25.2, y en el capítulo III del título V producirá efectos a partir de la entrada en vigor de las leyes de Función Pública que se dicten en desarrollo de este Estatuto."}]},{"text":"El RGI coincide: concurso (sistema normal) o libre designación según la RPT; redistribución o reasignación de efectivos cuando lo exijan las necesidades del servicio; y, temporalmente, comisión de servicios y adscripción provisional (art. 36). Convocatorias y resoluciones se publican en el BOE (art. 38.2) y los ceses y tomas de posesión se comunican al Registro Central de Personal en tres días hábiles (art. 37).","refs":[{"ref":"Art. 36 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"1. Los puestos de trabajo adscritos a funcionarios se proveerán de acuerdo con los procedimientos de concurso, que es el sistema normal de provisión, o de libre designación, de conformidad con lo que determinen las relaciones de puestos de trabajo en atención a la naturaleza de sus funciones. 2. Cuando las necesidades del servicio lo exijan, los puestos de trabajo podrán cubrirse mediante redistribución de efectivos o por reasignación de efectivos como consecuencia de un Plan de Empleo. 3. Temporalmente podrán ser cubiertos mediante comisión de servicios y adscripción provisional, en los supuestos previstos en este Reglamento."}]}]},{"n":"5","title":"El concurso: participación y méritos","blocks":[{"text":"Cada Ministerio convoca y resuelve los concursos de sus puestos (art. 40.1 RGI). Pueden participar los funcionarios en cualquier situación salvo los suspensos firmes mientras dure la suspensión (art. 41.1), pero deben llevar un mínimo de dos años en su destino definitivo, salvo dentro de la misma Secretaría de Estado o Departamento o por supresión del puesto (art. 41.2). Dos funcionarios pueden condicionar su petición a obtener destino en el mismo municipio por convivencia familiar (art. 41.3). Las solicitudes se presentan en quince días hábiles desde el siguiente a la publicación en el BOE (art. 42.2).","refs":[{"ref":"Art. 41.2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Los funcionarios deberán permanecer en cada puesto de trabajo de destino definitivo un mínimo de dos años para poder participar en los concursos de provisión"},{"ref":"Art. 42.2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"El plazo de presentación de instancias será de quince días hábiles, contados a partir del siguiente al de la publicación de la convocatoria en el «Boletín Oficial del Estado»."}]},{"text":"Se valoran los méritos específicos del puesto, el grado personal consolidado, el trabajo desarrollado, los cursos de formación incluidos en la convocatoria y la antigüedad (art. 44.1). Pueden puntuarse, hasta el máximo fijado para la antigüedad, el destino previo del cónyuge, el cuidado de hijos hasta los doce años y el cuidado de familiares (art. 44.2). Cada concepto no puede superar el 40 % ni ser inferior al 10 % de la puntuación máxima total (art. 44.3), y la convocatoria fija una puntuación mínima (art. 44.6). En los concursos específicos hay dos fases, con memorias o entrevistas en la segunda (art. 45).","refs":[{"ref":"Art. 44.3 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"La puntuación de cada uno de los conceptos enunciados en los apartados anteriores no podrá exceder en ningún caso del 40 por 100 de la puntuación máxima total ni ser inferior al 10 por 100 de la misma."}]}]},{"n":"6","title":"El concurso: comisiones, resolución y toma de posesión","blocks":[{"text":"Las Comisiones de Valoración tienen como mínimo cuatro miembros designados por la autoridad convocante; los sindicatos más representativos pueden participar, pero sus representantes nunca pueden igualar o superar a los de la Administración, y los miembros deben pertenecer a grupos iguales o superiores al exigido (art. 46.1 RGI). El concurso se resuelve en dos meses desde el día siguiente al fin del plazo de solicitudes, salvo otro plazo en la convocatoria, con motivación referida a las normas y bases (art. 47).","refs":[{"ref":"Art. 46.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Las Comisiones de Valoración estarán constituidas como mínimo por cuatro miembros designados por la autoridad convocante"},{"ref":"Art. 47.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"El plazo para la resolución del concurso será de dos meses contados desde el día siguiente al de la finalización del de la presentación de solicitudes, salvo que la propia convocatoria establezca otro distinto."}]},{"text":"El cese se produce en los tres días hábiles siguientes a la publicación de la resolución, y la toma de posesión, en tres días hábiles si no hay cambio de residencia o en un mes si lo hay o si se reingresa (art. 48.1); el cese puede diferirse hasta veinte días hábiles por necesidades del servicio (art. 48.2). Los destinos son irrenunciables salvo que antes de terminar el plazo posesorio se obtenga otro por convocatoria pública, y no generan indemnización (art. 49). El adjudicatario puede ser removido por alteración del puesto o rendimiento insuficiente, con audiencia y parecer de la Junta de Personal (art. 50).","refs":[{"ref":"Art. 48.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"El plazo para tomar posesión será de tres días hábiles si no implica cambio de residencia del funcionario, o de un mes si comporta cambio de residencia o el reingreso al servicio activo."},{"ref":"Art. 49.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Los destinos adjudicados serán irrenunciables, salvo que, antes de finalizar el plazo de toma de posesión, se hubiere obtenido otro destino mediante convocatoria pública."}]}]},{"n":"7","title":"La libre designación","blocks":[{"text":"Consiste en la apreciación discrecional por el órgano competente de la idoneidad de los candidatos (art. 80.1 TREBEP). En la AGE la ejercen los Ministros y los Secretarios de Estado (art. 51.1 RGI) y solo para Subdirectores generales, Delegados y Directores territoriales o provinciales, secretarías de altos cargos y puestos directivos o de especial responsabilidad que fije la RPT (art. 51.2). Se exige convocatoria pública, y las solicitudes se presentan en quince días hábiles (arts. 52-53). Si el nombramiento recae en un funcionario de otro Departamento, se requiere informe favorable de este, que se entiende favorable si no se emite en quince días naturales (art. 54.1). El nombramiento se hace en un mes, prorrogable otro (art. 56.1).","refs":[{"ref":"Art. 54.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Si fuera a recaer en un funcionario destinado en otro Departamento, se requerirá informe favorable de éste. De no emitirse en el plazo de quince días naturales se considerará favorable."}]},{"text":"Los funcionarios de libre designación pueden ser cesados discrecionalmente y la motivación se refiere solo a la competencia (art. 58.1 RGI). El cesado queda adscrito provisionalmente a un puesto de su cuerpo no inferior en más de dos niveles a su grado y en el mismo municipio (art. 58.2), en línea con el art. 80.4 TREBEP.","refs":[{"ref":"Art. 58.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Los funcionarios nombrados para puestos de trabajo de libre designación podrán ser cesados con carácter discrecional. La motivación de esta resolución se referirá a la competencia para adoptarla."}]}]},{"n":"8","title":"Otras formas de provisión","blocks":[{"text":"Redistribución de efectivos: quien ocupa con carácter definitivo un puesto no singularizado puede ser adscrito, por necesidades del servicio, a otro de la misma naturaleza, nivel de complemento de destino y complemento específico, con igual forma de provisión y sin cambio de municipio (art. 59.1 RGI). Reasignación de efectivos: para funcionarios cuyo puesto se suprime por un Plan de Empleo, en fases de seis y tres meses, y después en expectativa de destino (art. 60).","refs":[{"ref":"Art. 59.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Los funcionarios que ocupen con carácter definitivo puestos no singularizados podrán ser adscritos, por necesidades del servicio, a otros de la misma naturaleza, nivel de complemento de destino y complemento específico, siempre que para la provisión de los referidos puestos esté previsto el mismo procedimiento y sin que ello suponga cambio de municipio."}]},{"text":"La adscripción provisional solo cabe por remoción o cese en concurso o libre designación, supresión del puesto o reingreso sin reserva (art. 63). La comisión de servicios cubre una vacante por urgente e inaplazable necesidad, de forma voluntaria o, si el concurso quedó desierto, forzosa (art. 64.1-2); dura como máximo un año prorrogable por otro si no se ha cubierto el puesto (art. 64.3), reserva el puesto de origen y se cobran las retribuciones del puesto desempeñado (art. 64.6). Existen también la atribución temporal de funciones (art. 66), la movilidad por salud o rehabilitación (art. 66 bis) y la de la funcionaria víctima de violencia de género (art. 66 ter).","refs":[{"ref":"Art. 64.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Cuando un puesto de trabajo quede vacante podrá ser cubierto, en caso de urgente e inaplazable necesidad, en comisión de servicios de carácter voluntario, con un funcionario que reúna los requisitos establecidos para su desempeño en la relación de puestos de trabajo."},{"ref":"Art. 64.3 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Las citadas comisiones de servicios tendrán una duración máxima de un año prorrogable por otro en caso de no haberse cubierto el puesto con carácter definitivo"}]}]},{"n":"9","title":"La carrera administrativa y la evaluación del desempeño","blocks":[{"text":"La carrera profesional es el conjunto ordenado de oportunidades de ascenso y expectativas de progreso conforme a igualdad, mérito y capacidad (art. 16.2 TREBEP). Sus modalidades son: carrera horizontal (progresión de grado, categoría o escalón sin cambiar de puesto); carrera vertical (ascenso en la estructura de puestos mediante la provisión); promoción interna vertical (a un subgrupo o grupo superior); y promoción interna horizontal (a cuerpos del mismo subgrupo) (art. 16.3). Horizontal y vertical pueden simultanearse (art. 16.4).","refs":[{"ref":"Art. 16.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La carrera profesional es el conjunto ordenado de oportunidades de ascenso y expectativas de progreso profesional conforme a los principios de igualdad, mérito y capacidad."},{"ref":"Art. 16.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"a) Carrera horizontal, que consiste en la progresión de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo […] b) Carrera vertical, que consiste en el ascenso en la estructura de puestos de trabajo por los procedimientos de provisión establecidos en el capítulo III del título V de este Estatuto."}]},{"text":"La evaluación del desempeño mide y valora la conducta profesional y el rendimiento o logro de resultados, con criterios de transparencia, objetividad, imparcialidad y no discriminación (art. 20.1-2). Cada Administración fija sus efectos en la carrera horizontal, la formación, la provisión y las retribuciones complementarias (art. 20.3). Como la carrera (capítulo II del título III) depende de las leyes de Función Pública (disp. final 4.ª.1), en la AGE la carrera horizontal se sigue articulando a través del grado personal del RGI.","refs":[{"ref":"Art. 20.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La evaluación del desempeño es el procedimiento mediante el cual se mide y valora la conducta profesional y el rendimiento o el logro de resultados."}]}]},{"n":"10","title":"El grado personal y los intervalos de niveles","blocks":[{"text":"Los puestos se clasifican en 30 niveles, y el grado personal se adquiere desempeñando puestos del nivel correspondiente durante dos años continuados o tres con interrupción, cualquiera que sea el sistema de provisión (art. 70.1-2 RGI). Quien ocupa un puesto superior en más de dos niveles a su grado consolida cada dos años un grado dos niveles superior. El grado inicial es el del puesto adjudicado tras el proceso selectivo (art. 70.3). Lo reconoce el Subsecretario y se comunica al RCP en tres días hábiles (art. 70.11), y da derecho a percibir como mínimo el complemento de destino del nivel correspondiente (art. 70.12).","refs":[{"ref":"Art. 70.1-2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"1. Los puestos de trabajo se clasifican en 30 niveles. 2. Todos los funcionarios de carrera adquirirán un grado personal por el desempeño de uno o más puestos del nivel correspondiente durante dos años continuados o tres con interrupción"},{"ref":"Art. 70.12 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"El grado personal comporta el derecho a la percepción como mínimo del complemento de destino de los puestos del nivel correspondiente al mismo."}]},{"text":"Los intervalos por grupo son: A, 20-30; B, 16-26; C, 11-22; D, 9-18; E, 7-14, y nadie puede obtener puestos fuera de su intervalo (art. 71 RGI). El RGI usa los grupos antiguos; según la disp. transitoria 3.ª TREBEP equivalen a A1, A2, C1, C2 y agrupaciones profesionales. Al cesado o removido se le garantiza un puesto no inferior en más de dos niveles a su grado en el mismo municipio (art. 72).","refs":[{"ref":"Art. 71.2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"En ningún caso los funcionarios podrán obtener puestos de trabajo no incluidos en los niveles del intervalo correspondiente al Grupo en el que figure clasificado su Cuerpo o Escala."},{"ref":"Disp. trans. 3.ª.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Grupo A: Subgrupo A1. Grupo B: Subgrupo A2. Grupo C: Subgrupo C1. Grupo D: Subgrupo C2."}]}]},{"n":"11","title":"La promoción interna","blocks":[{"text":"La promoción interna consiste en ascender a un cuerpo del grupo inmediato superior o acceder a otro del mismo grupo (art. 73 RGI). Se hace por oposición o concurso-oposición; la convocatoria puede fijar una nota mínima en el concurso para pasar a la oposición, pero los puntos del concurso nunca sirven para aprobar los ejercicios (art. 74). Se exigen dos años de antigüedad en el cuerpo de origen y los requisitos generales del cuerpo de destino (art. 76 RGI; art. 18.2 TREBEP).","refs":[{"ref":"Art. 73 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"La promoción interna consiste en el ascenso desde Cuerpos o Escalas de un Grupo de titulación a otro del inmediato superior o en el acceso a Cuerpos o Escalas del mismo Grupo de titulación."},{"ref":"Art. 74.2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"En ningún caso la puntuación obtenida en la fase de concurso podrá aplicarse para superar los ejercicios de la fase de oposición."},{"ref":"Art. 18.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los funcionarios deberán poseer los requisitos exigidos para el ingreso, tener una antigüedad de, al menos, dos años de servicio activo en el inferior Subgrupo"}]},{"text":"Quienes promocionan tienen preferencia sobre los de acceso libre para elegir vacantes de la convocatoria (art. 78.1 RGI) y pueden conservar su grado si está en el intervalo del nuevo cuerpo (art. 78.3). Las vacantes de promoción interna desiertas se acumulan al turno libre, salvo convocatorias independientes (art. 79). Para pasar del grupo D al C (hoy de C2 a C1) sin la titulación exigida bastan diez años de antigüedad en el grupo D, o cinco años más un curso específico de formación (disp. adic. 9.ª RGI).","refs":[{"ref":"Art. 78.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Los funcionarios que accedan a otros Cuerpos y Escalas por el turno de promoción interna tendrán, en todo caso, preferencia para cubrir los puestos vacantes de la respectiva convocatoria sobre los aspirantes que no procedan de este turno."},{"ref":"Disp. adic. 9.ª RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"A estos efectos se requerirá la titulación establecida en el artículo 25 de la Ley 30/1984, de 2 de agosto, o una antigüedad de diez años en un Cuerpo o Escala del Grupo D, o de cinco años y la superación de un curso específico de formación al que se accederá por criterios objetivos."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Ejemplaridad es uno de los principios del Código de Conducta.","refs":[{"ref":"Art. 52 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"transparencia, ejemplaridad, austeridad"}]},{"text":"Orden manifiestamente ilegal: no se cumple y se comunica a la inspección.","refs":[{"ref":"Art. 54.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"salvo que constituyan una infracción manifiesta del ordenamiento jurídico"}]},{"text":"Concurso: dos años en el destino; solicitudes en quince días hábiles; resolución en dos meses.","refs":[{"ref":"Art. 42.2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"quince días hábiles"}]},{"text":"Toma de posesión: tres días hábiles sin cambio de residencia; un mes con cambio o reingreso.","refs":[{"ref":"Art. 48.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"o de un mes si comporta cambio de residencia o el reingreso al servicio activo."}]},{"text":"Comisión de servicios: máximo un año, prorrogable otro.","refs":[{"ref":"Art. 64.3 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"duración máxima de un año prorrogable por otro"}]},{"text":"Grado: dos años continuados o tres con interrupción.","refs":[{"ref":"Art. 70.2 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"durante dos años continuados o tres con interrupción"}]},{"text":"Libre designación: cese discrecional; informe de otro Departamento favorable si no se emite en quince días naturales.","refs":[{"ref":"Art. 58.1 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"podrán ser cesados con carácter discrecional"}]},{"text":"Promoción interna: dos años de antigüedad; el concurso no salva la oposición.","refs":[{"ref":"Art. 76 RGI","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"deberán tener una antigüedad de, al menos, dos años en el Cuerpo o Escala a que pertenezcan"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729', null, null, null, 'Otras normas citadas: TREBEP (https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719)'
  from public.topics t where t.slug = 'age-adm-45-provision-carrera'
