insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 53/1984, de 26 de diciembre, de Incompatibilidades del personal al servicio de las Administraciones Públicas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-46-incompatibilidades', 'IV.6 Las incompatibilidades y el régimen disciplinario') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-46-incompatibilidades' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Las incompatibilidades: principios generales y ámbito de aplicación (arts. 1-2 Ley 53/1984)"},{"n":"2","title":"Actividades públicas: segundo puesto, cargos electivos, límites retributivos y autorización (arts. 3-10 Ley 53/1984)"},{"n":"3","title":"Actividades privadas: prohibiciones y reconocimiento de compatibilidad (arts. 11-15 Ley 53/1984)"},{"n":"4","title":"Disposiciones comunes: complemento específico, registro, actividades exceptuadas e incumplimiento (arts. 16-20 Ley 53/1984)"},{"n":"5","title":"Régimen disciplinario: responsabilidad y principios de la potestad disciplinaria (arts. 93-94 TREBEP)"},{"n":"6","title":"Faltas disciplinarias: muy graves, graves y leves (art. 95 TREBEP)"},{"n":"7","title":"Sanciones y prescripción (arts. 96-97 TREBEP)"},{"n":"8","title":"Procedimiento disciplinario y medidas provisionales (art. 98 TREBEP)"}]'::jsonb, '["Art. 1.1 Ley 53/1984: «El personal comprendido en el ámbito de aplicación de esta Ley no podrá compatibilizar sus actividades con el desempeño, por sí o mediante sustitución, de un segundo puesto de trabajo, cargo o actividad en el sector público, salvo en los supuestos previstos en la misma.»","Art. 1.3 Ley 53/1984: «En cualquier caso, el desempeño de un puesto de trabajo por el personal incluido en el ámbito de aplicación de esta Ley será incompatible con el ejercicio de cualquier cargo, profesión o actividad, público o privado, que pueda impedir o menoscabar el estricto cumplimiento de sus deberes o comprometer su imparcialidad o independencia.»","Art. 3.1 Ley 53/1984: «Para el ejercicio de la segunda actividad será indispensable la previa y expresa autorización de compatibilidad, que no supondrá modificación de la jornada de trabajo y horario de los dos puestos y que se condiciona a su estricto cumplimiento en ambos. En todo caso la autorización de compatibilidad se efectuará en razón del interés público.»","Art. 10 Ley 53/1984: «Quienes accedan por cualquier título a un nuevo puesto del sector público que con arreglo a esta Ley resulte incompatible con el que vinieran desempeñando habrán de optar por uno de ellos dentro del plazo de toma de posesión. A falta de opción en el plazo señalado se entenderá que optan por el nuevo puesto, pasando a la situación de excedencia voluntaria en los que vinieran desempeñando.»","Art. 12.1.a) Ley 53/1984: «a) El desempeño de actividades privadas, incluidas las de carácter profesional, sea por cuenta propia o bajo la dependencia o al servicio de Entidades o particulares, en los asuntos en que esté interviniendo, haya intervenido en los dos últimos años o tenga que intervenir por razón del puesto público.»","Art. 14 Ley 53/1984: «El ejercicio de actividades profesionales, laborales, mercantiles o industriales fuera de las Administraciones Públicas requerirá el previo reconocimiento de compatibilidad.»","Art. 18 Ley 53/1984: «Todas las resoluciones de compatibilidad para desempeñar un segundo puesto o actividad en el sector público o el ejercicio de actividades privadas se inscribirán en los Registros de Personal correspondientes.»","Art. 19.b)-c) Ley 53/1984: «b) La dirección de seminarios o el dictado de cursos o conferencias en Centros oficiales destinados a la formación de funcionarios o profesorado, cuando no tenga carácter permanente o habitual ni supongan más de setenta y cinco horas al año, así como la preparación para el acceso a la función pública en los casos y forma que reglamentariamente se determine. c) La participación en Tribunales calificadores de pruebas selectivas para ingreso en las Administraciones Públicas.»","Art. 94.2 TREBEP: «La potestad disciplinaria se ejercerá de acuerdo con los siguientes principios: a) Principio de legalidad y tipicidad de las faltas y sanciones, a través de la predeterminación normativa o, en el caso del personal laboral, de los convenios colectivos. b) Principio de irretroactividad de las disposiciones sancionadoras no favorables y de retroactividad de las favorables al presunto infractor. c) Principio de proporcionalidad, aplicable tanto a la clasificación de las infracciones y sanciones como a su aplicación. d) Principio de culpabilidad. e) Principio de presunción de inocencia.»","Art. 95.1 TREBEP: «Las faltas disciplinarias pueden ser muy graves, graves y leves.»","Art. 95.2.c) y n) TREBEP: «c) El abandono del servicio, así como no hacerse cargo voluntariamente de las tareas o funciones que tienen encomendadas. […] n) El incumplimiento de las normas sobre incompatibilidades cuando ello dé lugar a una situación de incompatibilidad.»","Art. 96.1 TREBEP: «Por razón de las faltas cometidas podrán imponerse las siguientes sanciones: a) Separación del servicio de los funcionarios, que en el caso de los funcionarios interinos comportará la revocación de su nombramiento, y que sólo podrá sancionar la comisión de faltas muy graves.»","Art. 97.1 TREBEP: «Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses; las sanciones impuestas por faltas muy graves prescribirán a los tres años, las impuestas por faltas graves a los dos años y las impuestas por faltas leves al año.»","Art. 98.1 TREBEP: «No podrá imponerse sanción por la comisión de faltas muy graves o graves sino mediante el procedimiento previamente establecido. La imposición de sanciones por faltas leves se llevará a cabo por procedimiento sumario con audiencia al interesado.»","Art. 98.3 TREBEP: «La suspensión provisional como medida cautelar en la tramitación de un expediente disciplinario no podrá exceder de 6 meses, salvo en caso de paralización del procedimiento imputable al interesado.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Las incompatibilidades: principios generales (art. 1 Ley 53/1984)","blocks":[{"text":"La Ley 53/1984, de 26 de diciembre, de Incompatibilidades del personal al servicio de las Administraciones Públicas, parte de una regla general: quien está en su ámbito no puede compatibilizar su actividad con un segundo puesto, cargo o actividad en el sector público, ni por sí ni mediante sustitución, salvo en los supuestos que la propia ley prevé (art. 1.1). A estos efectos, también es actividad del sector público la de los miembros electivos de las Asambleas Legislativas autonómicas y de las Corporaciones Locales y la de los altos cargos y el personal de los órganos constitucionales y de todas las Administraciones.","refs":[{"ref":"Art. 1.1 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"El personal comprendido en el ámbito de aplicación de esta Ley no podrá compatibilizar sus actividades con el desempeño, por sí o mediante sustitución, de un segundo puesto de trabajo, cargo o actividad en el sector público, salvo en los supuestos previstos en la misma."},{"ref":"Art. 1.1 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"se considerará actividad en el sector público la desarrollada por los miembros electivos de las Asambleas Legislativas de las Comunidades Autónomas y de las Corporaciones Locales"}]},{"text":"Además, no se puede percibir más de una remuneración con cargo a presupuestos públicos, salvo en los supuestos legales; y remuneración es cualquier derecho económico derivado de una prestación o servicio personal, fijo o variable, periódico u ocasional (art. 1.2). Por encima de todo rige una cláusula de cierre: el puesto público es incompatible con cualquier cargo, profesión o actividad, pública o privada, que pueda impedir o menoscabar el estricto cumplimiento de los deberes o comprometer la imparcialidad o independencia (art. 1.3).","refs":[{"ref":"Art. 1.2 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"no se podrá percibir, salvo en los supuestos previstos en esta Ley, más de una remuneración con cargo a los presupuestos de las Administraciones Públicas"},{"ref":"Art. 1.3 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"será incompatible con el ejercicio de cualquier cargo, profesión o actividad, público o privado, que pueda impedir o menoscabar el estricto cumplimiento de sus deberes o comprometer su imparcialidad o independencia."}]}]},{"n":"2","title":"Ámbito de aplicación (art. 2 Ley 53/1984)","blocks":[{"text":"La ley se aplica, entre otros, al personal civil y militar de la Administración del Estado y sus organismos públicos, al de las Comunidades Autónomas y Corporaciones Locales, al de la Seguridad Social, al que percibe sus retribuciones mediante arancel, al del Banco de España y al de entidades, fundaciones y consorcios cuyos presupuestos se doten en más de un 50 por cien con fondos públicos, así como al de empresas con participación pública superior al 50 por 100 (art. 2.1). Dentro de ese ámbito se incluye todo el personal, cualquiera que sea la naturaleza jurídica de su relación de empleo: funcionarios, laborales, eventuales o interinos (art. 2.2).","refs":[{"ref":"Art. 2.1.a) Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"a) El personal civil y militar al servicio de la Administración del Estado y de sus Organismos Públicos."},{"ref":"Art. 2.1.h) Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"h) El personal que preste servicios en Empresas en que la participación del capital, directa o indirectamente, de las Administraciones Públicas sea superior al 50 por 100."},{"ref":"Art. 2.2 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"En el ámbito delimitado en el apartado anterior se entenderá incluido todo el personal, cualquiera que sea la naturaleza jurídica de la relación de empleo."}]}]},{"n":"3","title":"Actividades públicas: segundo puesto, pensiones y cargos electivos (arts. 3-6 Ley 53/1984)","blocks":[{"text":"Solo se puede desempeñar un segundo puesto público en los casos tasados: funciones docente y sanitaria, los de los arts. 5 y 6 y los que por interés público determine el Consejo de Ministros o el órgano de gobierno autonómico, en este último caso solo en régimen laboral, a tiempo parcial y con duración determinada (art. 3.1). Siempre es indispensable la previa y expresa autorización de compatibilidad, que no modifica la jornada ni el horario de los dos puestos, se condiciona a su estricto cumplimiento y se concede en razón del interés público. El puesto público es incompatible con cobrar pensión de jubilación o retiro de Derechos Pasivos o de cualquier régimen público y obligatorio de Seguridad Social: la pensión queda en suspenso mientras dure el desempeño, sin afectar a sus actualizaciones; por excepción, en el ámbito laboral, la jubilación parcial es compatible con un puesto a tiempo parcial (art. 3.2).","refs":[{"ref":"Art. 3.1 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"Para el ejercicio de la segunda actividad será indispensable la previa y expresa autorización de compatibilidad, que no supondrá modificación de la jornada de trabajo y horario de los dos puestos y que se condiciona a su estricto cumplimiento en ambos. En todo caso la autorización de compatibilidad se efectuará en razón del interés público."},{"ref":"Art. 3.2 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"La percepción de las pensiones indicadas quedará en suspenso por el tiempo que dure el desempeño de dicho puesto, sin que ello afecte a sus actualizaciones."}]},{"text":"El art. 4 regula compatibilidades docentes y sanitarias (por ejemplo, profesor universitario asociado a tiempo parcial). Por excepción, el art. 5.1 permite compatibilizar el puesto con cargos electivos: miembro de una Asamblea Legislativa autonómica, salvo que perciba retribuciones periódicas o se establezca la incompatibilidad, y miembro de una Corporación local, salvo que desempeñe un cargo retribuido en dedicación exclusiva. En estos casos solo se cobra la retribución de una actividad, sin perjuicio de dietas, indemnizaciones o asistencias por la otra (art. 5.2). El art. 6 permite autorizar, excepcionalmente, actividades de investigación no permanente o de asesoramiento científico o técnico en supuestos concretos.","refs":[{"ref":"Art. 5.1 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"b) Miembros de las Corporaciones locales, salvo que desempeñen en las mismas cargos retribuidos en régimen de dedicación exclusiva."},{"ref":"Art. 5.2 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"En los supuestos comprendidos en este artículo sólo podrá percibirse la retribución correspondiente a una de las dos actividades, sin perjuicio de las dietas, indemnizaciones o asistencias que correspondan por la otra."}]}]},{"n":"4","title":"Límites retributivos, consejos de administración, autorización y opción (arts. 7-10 Ley 53/1984)","blocks":[{"text":"Para autorizar la compatibilidad de actividades públicas, lo percibido por ambos puestos no puede superar la remuneración del Director General en los Presupuestos Generales del Estado, ni la del puesto principal incrementada en un 30 % (grupo A), 35 % (B), 40 % (C), 45 % (D) o 50 % (E) (art. 7.1). Superar estos límites exige acuerdo expreso del Gobierno, del órgano autonómico o del Pleno local. Los servicios del segundo puesto no computan para trienios ni derechos pasivos, y las pagas extraordinarias y prestaciones familiares solo se perciben por uno de los puestos (art. 7.2). Quien representa al sector público en consejos de administración solo cobra dietas o indemnizaciones por asistencia y no puede pertenecer a más de dos, salvo autorización excepcional (art. 8). Ten en cuenta que estos grupos A-E son la clasificación anterior al TREBEP.","refs":[{"ref":"Art. 7.1 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"– Un 40 por 100, para los funcionarios del grupo C o personal de nivel equivalente."},{"ref":"Art. 7.2 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"Los servicio prestados en el segundo puesto o actividad no se computarán a efectos de trienios ni de derechos pasivos"},{"ref":"Art. 8 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"No se podrá pertenecer a más de dos Consejos de Administración u órganos de gobierno"}]},{"text":"La autorización o denegación de compatibilidad para un segundo puesto público corresponde, en el Estado, al Ministerio que la ley denomina «de la Presidencia», a propuesta de la Subsecretaría del Departamento, con informe favorable del órgano del segundo puesto (art. 9); la denominación ministerial ha cambiado desde 1984. Quien accede a un nuevo puesto incompatible con el que tenía debe optar dentro del plazo de toma de posesión; si no opta, se entiende que elige el nuevo y pasa a excedencia voluntaria en el anterior. Si los puestos son compatibilizables, debe pedir la autorización en los diez primeros días de ese plazo (art. 10).","refs":[{"ref":"Art. 9 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"La autorización o denegación de compatibilidad para un segundo puesto o actividad del sector público corresponde al Ministerio de la Presidencia, a propuesta de la Subsecretaría del Departamento correspondiente"},{"ref":"Art. 10 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"A falta de opción en el plazo señalado se entenderá que optan por el nuevo puesto, pasando a la situación de excedencia voluntaria en los que vinieran desempeñando."}]}]},{"n":"5","title":"Actividades privadas: prohibiciones y reconocimiento de compatibilidad (arts. 11-15 Ley 53/1984)","blocks":[{"text":"No se pueden ejercer actividades privadas que se relacionen directamente con las que desarrolla el Departamento u organismo de destino (art. 11.1). En todo caso están prohibidas: actuar privadamente en asuntos en que se esté interviniendo, se haya intervenido en los dos últimos años o se tenga que intervenir por razón del puesto; pertenecer a consejos de administración de empresas privadas relacionadas con lo que gestiona el Departamento; desempeñar cargos en empresas concesionarias, contratistas o con participación o aval del sector público; y participar en más de un 10 por 100 del capital de esas empresas (art. 12.1). Tampoco cabe compatibilidad privada si, con un segundo puesto público, la suma de jornadas iguala o supera la máxima (art. 13).","refs":[{"ref":"Art. 12.1.a) Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"a) El desempeño de actividades privadas, incluidas las de carácter profesional, sea por cuenta propia o bajo la dependencia o al servicio de Entidades o particulares, en los asuntos en que esté interviniendo, haya intervenido en los dos últimos años o tenga que intervenir por razón del puesto público."},{"ref":"Art. 12.1.d) Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"d) La participación superior al 10 por 100 en el capital de las Empresas o Sociedades a que se refiere el párrafo anterior."}]},{"text":"El ejercicio de actividades profesionales, laborales, mercantiles o industriales fuera de las Administraciones requiere el previo reconocimiento de compatibilidad (art. 14). La resolución motivada que lo reconozca o declare la incompatibilidad se dicta en el plazo de dos meses; no puede modificar la jornada ni el horario y queda sin efecto automáticamente si se cambia de puesto en el sector público. Además, nadie puede invocar o hacer uso de su condición pública para ejercer una actividad mercantil, industrial o profesional (art. 15).","refs":[{"ref":"Art. 14 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"El ejercicio de actividades profesionales, laborales, mercantiles o industriales fuera de las Administraciones Públicas requerirá el previo reconocimiento de compatibilidad."},{"ref":"Art. 14 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"La resolución motivada reconociendo la compatibilidad o declarando la incompatibilidad, que se dictará en el plazo de dos meses"},{"ref":"Art. 15 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"El personal a que se refiere esta Ley no podrá invocar o hacer uso de su condición pública para el ejercicio de actividad mercantil, industrial o profesional."}]}]},{"n":"6","title":"Disposiciones comunes: complemento específico, registro, actividades exceptuadas e incumplimiento (arts. 16-20 Ley 53/1984)","blocks":[{"text":"El art. 16.1 impide autorizar o reconocer compatibilidad a quien percibe complemento específico o concepto equiparable. Atención a la versión: el texto consolidado recoge una redacción dada por el TREBEP (referida a retribuciones complementarias con factor de incompatibilidad) que solo producirá efectos cuando se aprueben las leyes de función pública de desarrollo, y transcribe la redacción anterior. Por excepción, puede reconocerse compatibilidad para actividades privadas cuando el complemento específico no supera el 30 por 100 de la retribución básica, excluida la antigüedad (art. 16.4). Todas las resoluciones de compatibilidad se inscriben en los Registros de Personal (art. 18).","refs":[{"ref":"Art. 16.1 Ley 53/1984 (redacción anterior)","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"No podrá autorizarse o reconocerse compatibilidad alguna al personal que desempeñe puestos que comporten la percepción de complementos específicos o concepto equiparable, y al retribuido por arancel."},{"ref":"Art. 16.4 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"cuya cuantía no supere el 30 por 100 de su retribución básica, excluidos los conceptos que tengan su origen en la antigüedad."},{"ref":"Art. 18 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"Todas las resoluciones de compatibilidad para desempeñar un segundo puesto o actividad en el sector público o el ejercicio de actividades privadas se inscribirán en los Registros de Personal correspondientes."}]},{"text":"Quedan fuera del régimen de incompatibilidades (art. 19), entre otras: la administración del patrimonio personal o familiar; la dirección de seminarios o cursos en centros oficiales de formación de funcionarios que no sean permanentes ni superen setenta y cinco horas al año; la participación en tribunales calificadores de pruebas selectivas; la creación literaria, artística, científica y técnica no derivada de una relación de empleo; y la participación ocasional en medios de comunicación o congresos. El incumplimiento se sanciona conforme al régimen disciplinario (art. 20.1) y la autorización queda revocada si una falta se califica de grave o muy grave (art. 20.2).","refs":[{"ref":"Art. 19.b)-c) Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"b) La dirección de seminarios o el dictado de cursos o conferencias en Centros oficiales destinados a la formación de funcionarios o profesorado, cuando no tenga carácter permanente o habitual ni supongan más de setenta y cinco horas al año"},{"ref":"Art. 19.c) Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"c) La participación en Tribunales calificadores de pruebas selectivas para ingreso en las Administraciones Públicas."},{"ref":"Art. 20.1 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"El incumplimiento de lo dispuesto en los artículos anteriores será sancionado conforme al régimen disciplinario de aplicación, sin perjuicio de la ejecutividad de la incompatibilidad en que se haya incurrido."}]}]},{"n":"7","title":"Régimen disciplinario: responsabilidad y principios de la potestad disciplinaria (arts. 93-94 TREBEP)","blocks":[{"text":"Funcionarios y personal laboral quedan sujetos al régimen disciplinario del Título VII del TREBEP y de las leyes de función pública (art. 93.1). Quien induzca a otros a cometer una falta incurre en la misma responsabilidad que ellos (art. 93.2), y también responde quien encubre faltas consumadas muy graves o graves si de ello se deriva daño grave para la Administración o los ciudadanos (art. 93.3). Para el personal laboral, en lo no previsto, rige la legislación laboral (art. 93.4).","refs":[{"ref":"Art. 93.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los funcionarios públicos o el personal laboral que indujeren a otros a la realización de actos o conductas constitutivos de falta disciplinaria incurrirán en la misma responsabilidad que éstos."},{"ref":"Art. 93.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"incurrirán en responsabilidad los funcionarios públicos o personal laboral que encubrieren las faltas consumadas muy graves o graves, cuando de dichos actos se derive daño grave para la Administración o los ciudadanos."}]},{"text":"La potestad disciplinaria se ejerce sin perjuicio de la responsabilidad patrimonial o penal (art. 94.1) y conforme a cinco principios: legalidad y tipicidad; irretroactividad de lo desfavorable y retroactividad de lo favorable; proporcionalidad; culpabilidad; y presunción de inocencia (art. 94.2). Si en la instrucción aparecen indicios fundados de criminalidad, se suspende la tramitación y se pone en conocimiento del Ministerio Fiscal; los hechos declarados probados por sentencia firme vinculan a la Administración (art. 94.3).","refs":[{"ref":"Art. 94.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"d) Principio de culpabilidad. e) Principio de presunción de inocencia."},{"ref":"Art. 94.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Cuando de la instrucción de un procedimiento disciplinario resulte la existencia de indicios fundados de criminalidad, se suspenderá su tramitación poniéndolo en conocimiento del Ministerio Fiscal."}]}]},{"n":"8","title":"Faltas disciplinarias: muy graves, graves y leves (art. 95 TREBEP)","blocks":[{"text":"Las faltas son muy graves, graves y leves (art. 95.1). El art. 95.2 enumera directamente las muy graves, entre ellas: incumplir el deber de respeto a la Constitución; la discriminación y el acoso; el abandono del servicio o no hacerse cargo voluntariamente de las tareas; adoptar acuerdos manifiestamente ilegales con perjuicio grave; el uso indebido de información; el notorio incumplimiento de funciones esenciales; la desobediencia abierta a órdenes no manifiestamente ilegales; prevalerse de la condición de empleado público; no atender los servicios esenciales en huelga; el incumplimiento de las normas sobre incompatibilidades cuando dé lugar a una situación de incompatibilidad; y el acoso laboral.","refs":[{"ref":"Art. 95.2.c) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"c) El abandono del servicio, así como no hacerse cargo voluntariamente de las tareas o funciones que tienen encomendadas."},{"ref":"Art. 95.2.n) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"n) El incumplimiento de las normas sobre incompatibilidades cuando ello dé lugar a una situación de incompatibilidad."},{"ref":"Art. 95.2.o) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"o) El acoso laboral."}]},{"text":"Las faltas graves no las enumera el TREBEP: las establece la ley de las Cortes Generales o de la asamblea autonómica o, para el personal laboral, los convenios colectivos, atendiendo al grado de vulneración de la legalidad, la gravedad de los daños y el descrédito para la imagen de la Administración (art. 95.3). Las leves las regulan las leyes de función pública de desarrollo (art. 95.4). En la AGE sigue aplicándose el Reglamento de Régimen Disciplinario (RD 33/1986), que se estudia en el tema A46D.","refs":[{"ref":"Art. 95.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las faltas graves serán establecidas por ley de las Cortes Generales o de la asamblea legislativa de la correspondiente comunidad autónoma o por los convenios colectivos en el caso de personal laboral"},{"ref":"Art. 95.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las leyes de Función Pública que se dicten en desarrollo del presente Estatuto determinarán el régimen aplicable a las faltas leves"}]}]},{"n":"9","title":"Sanciones y prescripción (arts. 96-97 TREBEP)","blocks":[{"text":"Las sanciones posibles son: separación del servicio (revocación del nombramiento si es interino), solo por faltas muy graves; despido disciplinario del personal laboral, también solo por muy graves e inhabilitante para un nuevo contrato con funciones similares; suspensión firme de funciones (o de empleo y sueldo en el laboral) de hasta 6 años; traslado forzoso, con o sin cambio de localidad; demérito, que es la penalización a efectos de carrera, promoción o movilidad voluntaria; apercibimiento; y cualquier otra que fije la ley (art. 96.1). Su alcance se gradúa por intencionalidad, daño al interés público, reiteración o reincidencia y grado de participación (art. 96.3).","refs":[{"ref":"Art. 96.1.c) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"c) Suspensión firme de funciones, o de empleo y sueldo en el caso del personal laboral, con una duración máxima de 6 años."},{"ref":"Art. 96.1.e) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"e) Demérito, que consistirá en la penalización a efectos de carrera, promoción o movilidad voluntaria."}]},{"text":"Las faltas muy graves prescriben a los tres años, las graves a los dos y las leves a los seis meses; las sanciones por faltas muy graves, a los tres años, por graves a los dos y por leves al año (art. 97.1). El plazo de las faltas corre desde su comisión o, si son continuadas, desde el cese de su comisión; el de las sanciones, desde la firmeza de la resolución sancionadora (art. 97.2).","refs":[{"ref":"Art. 97.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses; las sanciones impuestas por faltas muy graves prescribirán a los tres años, las impuestas por faltas graves a los dos años y las impuestas por faltas leves al año."},{"ref":"Art. 97.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El plazo de prescripción de las faltas comenzará a contarse desde que se hubieran cometido, y desde el cese de su comisión cuando se trate de faltas continuadas."}]}]},{"n":"10","title":"Procedimiento disciplinario y medidas provisionales (art. 98 TREBEP)","blocks":[{"text":"Las faltas muy graves y graves solo se sancionan mediante el procedimiento previamente establecido; las leves, por procedimiento sumario con audiencia al interesado (art. 98.1). El procedimiento se rige por los principios de eficacia, celeridad y economía procesal, con pleno respeto a las garantías de defensa, y debe separar la fase instructora de la sancionadora, encomendándolas a órganos distintos (art. 98.2).","refs":[{"ref":"Art. 98.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La imposición de sanciones por faltas leves se llevará a cabo por procedimiento sumario con audiencia al interesado."},{"ref":"Art. 98.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"En el procedimiento quedará establecida la debida separación entre la fase instructora y la sancionadora, encomendándose a órganos distintos."}]},{"text":"Pueden adoptarse medidas provisionales por resolución motivada. La suspensión provisional no puede exceder de 6 meses, salvo paralización imputable al interesado; durante ella se perciben las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo (art. 98.3). Si se eleva a definitiva, se devuelve lo percibido y el tiempo se abona para cumplir la suspensión firme; si no, la Administración restituye la diferencia y el tiempo cuenta como servicio activo (art. 98.4).","refs":[{"ref":"Art. 98.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La suspensión provisional como medida cautelar en la tramitación de un expediente disciplinario no podrá exceder de 6 meses, salvo en caso de paralización del procedimiento imputable al interesado."},{"ref":"Art. 98.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El funcionario suspenso provisional tendrá derecho a percibir durante la suspensión las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Regla general: prohibido el segundo puesto público salvo excepciones y siempre con autorización previa y expresa.","refs":[{"ref":"Art. 3.1 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"Para el ejercicio de la segunda actividad será indispensable la previa y expresa autorización de compatibilidad"}]},{"text":"Si no se opta en plazo de toma de posesión, se entiende elegido el nuevo puesto y excedencia voluntaria en el anterior.","refs":[{"ref":"Art. 10 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"habrán de optar por uno de ellos dentro del plazo de toma de posesión."}]},{"text":"Límite de compatibilidad pública para el grupo C: puesto principal más un 40 %.","refs":[{"ref":"Art. 7.1 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"– Un 40 por 100, para los funcionarios del grupo C o personal de nivel equivalente."}]},{"text":"Actividades privadas: reconocimiento previo, resolución en dos meses; participación máxima del 10 % en contratistas; complemento específico no superior al 30 % de la retribución básica.","refs":[{"ref":"Art. 12.1.d) Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"La participación superior al 10 por 100 en el capital"}]},{"text":"Exceptuados: tribunales de oposiciones y cursos de formación hasta 75 horas al año no permanentes.","refs":[{"ref":"Art. 19.c) Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"La participación en Tribunales calificadores de pruebas selectivas"}]},{"text":"Faltas graves y leves no están en el TREBEP: graves por ley o convenio, leves por las leyes de función pública.","refs":[{"ref":"Art. 95.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las faltas disciplinarias pueden ser muy graves, graves y leves."}]},{"text":"Separación del servicio y despido disciplinario: solo por faltas muy graves; suspensión firme hasta 6 años.","refs":[{"ref":"Art. 96.1.a) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"y que sólo podrá sancionar la comisión de faltas muy graves."}]},{"text":"Prescripción: faltas 3 años, 2 años y 6 meses; sanciones 3 años, 2 años y 1 año.","refs":[{"ref":"Art. 97.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"las impuestas por faltas graves a los dos años y las impuestas por faltas leves al año."}]},{"text":"Suspensión provisional: máximo 6 meses salvo paralización imputable al interesado.","refs":[{"ref":"Art. 98.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"no podrá exceder de 6 meses, salvo en caso de paralización del procedimiento imputable al interesado."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151', null, null, null, 'Otras normas citadas: TREBEP (https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719)'
  from public.topics t where t.slug = 'age-adm-46-incompatibilidades'
