insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-46-regimen-disciplinario' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Ámbito y responsabilidad disciplinaria (arts. 1-4 y 9-13 RD 33/1986)"},{"n":"2","title":"Faltas muy graves, graves y leves (arts. 5-8 RD 33/1986)"},{"n":"3","title":"Sanciones y su graduación (arts. 14-18 RD 33/1986)"},{"n":"4","title":"Extinción de la responsabilidad disciplinaria (arts. 19-22 RD 33/1986; prescripción, art. 97 TREBEP)"},{"n":"5","title":"Iniciación: información reservada, órgano competente, instructor y secretario (arts. 27-31 RD 33/1986)"},{"n":"6","title":"Abstención, recusación y medidas provisionales (arts. 32-33 RD 33/1986)"},{"n":"7","title":"Instrucción: pliego de cargos, prueba, vista y propuesta de resolución (arts. 34-44 RD 33/1986)"},{"n":"8","title":"Terminación, órganos competentes, ejecución y anotación (arts. 45-51 RD 33/1986)"}]'::jsonb, '["Art. 5 RD 33/1986: «Las faltas cometidas por los funcionarios en el ejercicio de sus cargos podrán ser muy graves, graves y leves.»","Art. 7.1.l) RD 33/1986: «l) El incumplimiento injustificado de la jornada de trabajo que acumulado suponga un mínimo de diez horas al mes.»","Art. 8 RD 33/1986: «b) La falta de asistencia injustificada de un día.»","Art. 16 RD 33/1986: «Los funcionarios sancionados con traslado con cambio de residencia, no podrán obtener nuevo destino por ningún procedimiento en la localidad desde la que fueron trasladados, durante tres años, cuando hubiere sido impuesta por falta muy grave, y durante uno cuando hubiere correspondido a la comisión de una falta grave.»","Art. 18.2 RD 33/1986: «Para la imposición de sanciones por faltas leves no será preceptiva la previa instrucción del expediente al que se refiere el apartado anterior, salvo el trámite de audiencia al inculpado que deberá evacuarse en todo caso.»","Art. 27 RD 33/1986: «El procedimiento se iniciará siempre de oficio, por acuerdo del órgano competente, bien por propia iniciativa o como consecuencia de orden superior, moción razonada de los subordinados o denuncia.»","Art. 28 RD 33/1986: «El órgano competente para incoar el procedimiento podrá acordar previamente la realización de una información reservada.»","Art. 29.1 RD 33/1986: «Será competente para ordenar la incoación del expediente disciplinario, el Subsecretario del Departamento en que esté destinado el funcionario, en todo caso.»","Art. 30 RD 33/1986: «En la resolución por la que se incoe el procedimiento se nombrará Instructor, que deberá ser un funcionario público perteneciente a un cuerpo o escala de igual o superior grupo al del inculpado»","Art. 32.3 RD 33/1986: «La abstención y la recusación se plantearán ante la Autoridad que acordó el nombramiento, quien deberá resolver en el término de tres días.»","Art. 35.1 RD 33/1986: «A la vista de las actuaciones practicadas y en un plazo no superior a un mes, contados a partir de la incoación del procedimiento, el Instructor formulará el correspondiente pliego de cargos»","Art. 36 RD 33/1986: «El pliego de cargos se notificará al inculpado concediéndosele un plazo de diez días para que pueda contestarlo»","Art. 45.2 RD 33/1986: «La resolución habrá de ser motivada y en ella no se podrán aceptar hechos distintos de los que sirvieron de base al pliego de cargos y a la propuesta de resolución, sin perjuicio de su distinta valoración jurídica.»","Art. 49 RD 33/1986: «Las sanciones disciplinarias se ejecutarán según los términos de la resolución en que se imponga, y en el plazo máximo de un mes, salvo que, cuando por causas justificadas, se establezca otro distinto en dicha resolución.»","Art. 97.1 TREBEP: «Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses; las sanciones impuestas por faltas muy graves prescribirán a los tres años, las impuestas por faltas graves a los dos años y las impuestas por faltas leves al año.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Ámbito del Reglamento y relación con el TREBEP (arts. 1-4 RD 33/1986)","blocks":[{"text":"El Real Decreto 33/1986, de 10 de enero, aprueba el Reglamento de Régimen Disciplinario de los Funcionarios de la Administración del Estado. Se aplica al personal funcionario incluido en el art. 1.1 de la Ley 30/1984 (art. 1), a los funcionarios en prácticas en la medida en que les sea aplicable (art. 2) y con carácter supletorio a los demás funcionarios del Estado y de otras Administraciones (art. 3). El régimen disciplinario no excluye la responsabilidad civil o penal (art. 4). Muy importante: el Reglamento es anterior al TREBEP, cuyos arts. 93 a 98 son legislación básica posterior. Por eso, donde ambos difieren (faltas muy graves del art. 95, sanciones del art. 96, prescripción del art. 97 y suspensión provisional del art. 98) prevalece el TREBEP, y el RD 33/1986 sigue aplicándose en lo que no lo contradiga, en especial en faltas graves, leves y procedimiento.","refs":[{"ref":"Art. 1 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"El presente Reglamento será de aplicación al personal funcionario comprendido en el artículo 1, 1, de la Ley 30/1984, de 2 de agosto, de Medidas para la Reforma de la Función Pública."},{"ref":"Art. 3 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"Las disposiciones del presente Reglamento tendrán carácter supletorio para los demás funcionarios al servicio del Estado y de las Administraciones Públicas no incluidos en su ámbito de aplicación."},{"ref":"Art. 93.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los funcionarios públicos y el personal laboral quedan sujetos al régimen disciplinario establecido en el presente título y en las normas que las leyes de Función Pública dicten en desarrollo de este Estatuto."}]}]},{"n":"2","title":"Personas responsables (arts. 9-13 RD 33/1986)","blocks":[{"text":"Los funcionarios incurren en responsabilidad disciplinaria en los supuestos del Reglamento (art. 9), incluso si están en una situación distinta del servicio activo, por las faltas que puedan cometer en ella; si la sanción no puede cumplirse por su situación, se hará efectiva cuando cambie, salvo que haya prescrito (art. 10). No hay responsabilidad disciplinaria por actos posteriores a la pérdida de la condición de funcionario, aunque esa pérdida no libera de la responsabilidad civil o penal por hechos anteriores (art. 11). Quien induce a otro a cometer una falta incurre en su misma responsabilidad (art. 12), y también responde quien encubre faltas muy graves o graves consumadas si causan graves daños a la Administración o a los ciudadanos (art. 13).","refs":[{"ref":"Art. 11.1 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"No podrá exigirse responsabilidad disciplinaria por actos posteriores a la pérdida de la condición de funcionario."},{"ref":"Art. 12 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"Los funcionarios que indujeren a otros a la realización de actos o conducta constitutivos de falta disciplinaria, incurrirán en la misma responsabilidad que éstos."},{"ref":"Art. 13 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"Igualmente incurrirán en responsabilidad los funcionarios que encubrieren las faltas consumadas muy graves y graves cuando de dicho acto se deriven graves daños para la Administración o los ciudadanos"}]}]},{"n":"3","title":"Faltas muy graves (arts. 5-6 RD 33/1986 y art. 95.2 TREBEP)","blocks":[{"text":"Las faltas cometidas en el ejercicio del cargo pueden ser muy graves, graves y leves (art. 5). El art. 6 del Reglamento enumera como muy graves, entre otras, el incumplimiento del deber de fidelidad a la Constitución, la discriminación, el abandono de servicio, los acuerdos manifiestamente ilegales con perjuicio grave, la notoria falta de rendimiento y haber sido sancionado por tres faltas graves en un año. Esta lista debe leerse hoy junto al art. 95.2 TREBEP, que es la norma básica posterior y prevalece: incluye, por ejemplo, el acoso laboral, el acoso sexual y por razón de sexo y la desobediencia abierta a órdenes, y limita la falta de incompatibilidades a cuando dé lugar a una situación de incompatibilidad.","refs":[{"ref":"Art. 5 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"Las faltas cometidas por los funcionarios en el ejercicio de sus cargos podrán ser muy graves, graves y leves."},{"ref":"Art. 6.n) RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"n) Haber sido sancionado por la comisión de tres faltas graves en un período de un año."},{"ref":"Art. 95.2.o) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"o) El acoso laboral."}]}]},{"n":"4","title":"Faltas graves y leves (arts. 7-8 RD 33/1986)","blocks":[{"text":"Son faltas graves (art. 7.1), entre otras: la falta de obediencia debida, el abuso de autoridad, la tolerancia de los superiores ante faltas graves o muy graves de sus subordinados, la grave desconsideración con superiores, compañeros o subordinados, intervenir en un procedimiento administrativo cuando concurra causa legal de abstención, no guardar el sigilo debido con perjuicio o provecho propio, y el incumplimiento de plazos o trámites de incompatibilidades sin mantener la incompatibilidad. Por su frecuencia en examen: es grave el incumplimiento injustificado de la jornada que acumulado suponga un mínimo de diez horas al mes, y la tercera falta injustificada de asistencia en tres meses cuando las dos anteriores se sancionaron como leves; también eludir los sistemas de control horario. El mes es el natural, del día primero al último (art. 7.2).","refs":[{"ref":"Art. 7.1.g) RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"g) Intervenir en un procedimiento administrativo cuando se dé alguna de las causas de abstención legalmente señaladas."},{"ref":"Art. 7.1.l) RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"l) El incumplimiento injustificado de la jornada de trabajo que acumulado suponga un mínimo de diez horas al mes."},{"ref":"Art. 7.1.m) RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"m) La tercera falta injustificada de asistencia en un período de tres meses, cuando las dos anteriores hubieren sido objeto de sanción por falta leve."},{"ref":"Art. 7.2 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"se entenderá por mes el período comprendido desde el día primero al último de cada uno de los doce que componen el año."}]},{"text":"Son faltas leves (art. 8): el incumplimiento injustificado del horario cuando no sea grave, la falta de asistencia injustificada de un día, la incorrección con el público, superiores, compañeros o subordinados, el descuido o negligencia en las funciones y el incumplimiento de deberes que no sea grave ni muy grave. Recuerda la escala: un día de ausencia es leve; la tercera en tres meses, con dos leves sancionadas, es grave.","refs":[{"ref":"Art. 8 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"a) El incumplimiento injustificado del horario de trabajo, cuando no suponga falta grave. b) La falta de asistencia injustificada de un día."}]}]},{"n":"5","title":"Sanciones y su graduación (arts. 14-18 RD 33/1986)","blocks":[{"text":"El Reglamento prevé la separación del servicio, la suspensión de funciones, el traslado con cambio de residencia y el apercibimiento; la letra d) del art. 14 figura como derogada en el texto consolidado (art. 14). La separación solo cabe por faltas muy graves (art. 15). Suspensión y traslado pueden imponerse por faltas graves o muy graves; la suspensión por falta muy grave va de tres a seis años y por falta grave no excede de tres años (art. 16). Quien es trasladado con cambio de residencia no puede obtener destino en la localidad de origen durante tres años si la falta fue muy grave y un año si fue grave, contados desde que se efectuó el traslado. El TREBEP (art. 96) añade otras sanciones, como el demérito, y fija la suspensión firme en un máximo de 6 años.","refs":[{"ref":"Art. 15 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"La sanción de separación de servicio, únicamente podrá imponerse por faltas muy graves."},{"ref":"Art. 16 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"La sanción de suspensión de funciones impuesta por comisión de falta muy grave, no podrá ser superior a seis años ni inferior a tres. Si se impone por falta grave, no excederá de tres años."},{"ref":"Art. 16 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"durante tres años, cuando hubiere sido impuesta por falta muy grave, y durante uno cuando hubiere correspondido a la comisión de una falta grave. Dicho plazo se computará desde el momento en que se efectuó el traslado."}]},{"text":"Las faltas graves y muy graves solo se sancionan mediante expediente instruido conforme al título II (art. 18.1). Para las leves no es preceptivo instruir expediente, pero sí, en todo caso, dar audiencia al inculpado (art. 18.2), en línea con el procedimiento sumario con audiencia del art. 98.1 TREBEP.","refs":[{"ref":"Art. 18.2 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"Para la imposición de sanciones por faltas leves no será preceptiva la previa instrucción del expediente al que se refiere el apartado anterior, salvo el trámite de audiencia al inculpado que deberá evacuarse en todo caso."},{"ref":"Art. 98.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La imposición de sanciones por faltas leves se llevará a cabo por procedimiento sumario con audiencia al interesado."}]}]},{"n":"6","title":"Extinción de la responsabilidad y prescripción (arts. 19-22 RD 33/1986; art. 97 TREBEP)","blocks":[{"text":"La responsabilidad disciplinaria se extingue por cumplimiento de la sanción, muerte, prescripción de la falta o de la sanción, indulto y amnistía (art. 19.1). Si el inculpado pierde la condición de funcionario durante el procedimiento, se declara extinguido y se archiva, salvo que el interesado pida continuar (art. 19.2). Los plazos de prescripción del Reglamento (seis años, dos años y un mes, arts. 20 y 21) han sido desplazados por el art. 97 TREBEP: faltas muy graves a los tres años, graves a los dos y leves a los seis meses; sanciones por muy graves a los tres años, por graves a los dos y por leves al año. Del Reglamento sigue siendo útil que la prescripción se interrumpe al iniciarse el procedimiento y vuelve a correr si el expediente se paraliza más de seis meses por causa no imputable al funcionario (art. 20.2).","refs":[{"ref":"Art. 19.1 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"La responsabilidad disciplinaria se extingue con el cumplimiento de la sanción, muerte, prescripción de la falta o de la sanción, indulto y amnistía."},{"ref":"Art. 97.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses; las sanciones impuestas por faltas muy graves prescribirán a los tres años, las impuestas por faltas graves a los dos años y las impuestas por faltas leves al año."},{"ref":"Art. 20.2 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"volviendo a correr el plazo si el expediente permaneciere paralizado durante más de seis meses por causa no imputable al funcionario sujeto al procedimiento."}]}]},{"n":"7","title":"Disposiciones generales y concurrencia con el proceso penal (arts. 23-26 RD 33/1986)","blocks":[{"text":"Si el instructor aprecia que los hechos pueden ser delito, lo comunica a la autoridad que ordenó la incoación para que se traslade al Ministerio Fiscal, aunque según el Reglamento el expediente puede continuar (art. 23). Hoy debe tenerse en cuenta el art. 94.3 TREBEP, que ordena suspender la tramitación cuando haya indicios fundados de criminalidad. El procedimiento se impulsa de oficio en todos sus trámites (art. 25). Las remisiones del Reglamento a la Ley de Procedimiento Administrativo de 1958 o a la Ley de Funcionarios de 1964 deben entenderse hechas a la normativa vigente.","refs":[{"ref":"Art. 23 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"lo pondrá en conocimiento de la autoridad que hubiere ordenado la incoación del expediente para su oportuna comunicación al Ministerio Fiscal."},{"ref":"Art. 94.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Cuando de la instrucción de un procedimiento disciplinario resulte la existencia de indicios fundados de criminalidad, se suspenderá su tramitación poniéndolo en conocimiento del Ministerio Fiscal."},{"ref":"Art. 25 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"El procedimiento para la sanción de faltas disciplinarias se impulsará de oficio en todos sus trámites."}]}]},{"n":"8","title":"Iniciación: información reservada, órgano competente, instructor y secretario (arts. 27-31 RD 33/1986)","blocks":[{"text":"El procedimiento se inicia siempre de oficio, por acuerdo del órgano competente, por propia iniciativa o por orden superior, moción razonada de los subordinados o denuncia; si hubo denuncia, se comunica al firmante (art. 27). Antes, puede acordarse una información reservada (art. 28). Es competente para ordenar la incoación, en todo caso, el Subsecretario del Departamento de destino del funcionario; también los Directores generales respecto de su personal y los Delegados del Gobierno en su ámbito territorial (art. 29.1). La resolución de incoación nombra instructor, que debe ser funcionario de un cuerpo o escala de igual o superior grupo al del inculpado; si es de otro Departamento, hace falta autorización de su Subsecretario. Si la complejidad lo exige se nombra secretario, que también debe ser funcionario (art. 30). La incoación y los nombramientos se notifican al expedientado y a los designados (art. 31).","refs":[{"ref":"Art. 27 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"El procedimiento se iniciará siempre de oficio, por acuerdo del órgano competente, bien por propia iniciativa o como consecuencia de orden superior, moción razonada de los subordinados o denuncia."},{"ref":"Art. 28 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"El órgano competente para incoar el procedimiento podrá acordar previamente la realización de una información reservada."},{"ref":"Art. 29.1 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"Será competente para ordenar la incoación del expediente disciplinario, el Subsecretario del Departamento en que esté destinado el funcionario, en todo caso."},{"ref":"Art. 30 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"En la resolución por la que se incoe el procedimiento se nombrará Instructor, que deberá ser un funcionario público perteneciente a un cuerpo o escala de igual o superior grupo al del inculpado"}]}]},{"n":"9","title":"Abstención, recusación y medidas provisionales (arts. 32-33 RD 33/1986)","blocks":[{"text":"Al instructor y al secretario se les aplican las causas de abstención y recusación de la ley de procedimiento; la recusación puede ejercerse desde que el interesado conoce quiénes son (art. 32.2), y abstención y recusación se plantean ante la autoridad que hizo el nombramiento, que resuelve en tres días (art. 32.3). Iniciado el procedimiento, quien acordó la incoación puede adoptar medidas provisionales para asegurar la eficacia de la resolución, incluida la suspensión provisional, pero nunca medidas que causen perjuicios irreparables o violen derechos legales (art. 33). La suspensión provisional no puede superar 6 meses salvo paralización imputable al interesado, y el suspenso cobra las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo (art. 98.3 TREBEP).","refs":[{"ref":"Art. 32.3 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"La abstención y la recusación se plantearán ante la Autoridad que acordó el nombramiento, quien deberá resolver en el término de tres días."},{"ref":"Art. 33.3 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"No se podrán dictar medidas provisionales que puedan causar perjuicios irreparables o impliquen violación de derechos amparados por las Leyes."},{"ref":"Art. 98.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La suspensión provisional como medida cautelar en la tramitación de un expediente disciplinario no podrá exceder de 6 meses, salvo en caso de paralización del procedimiento imputable al interesado."}]}]},{"n":"10","title":"Instrucción: pliego de cargos, prueba, vista y propuesta de resolución (arts. 34-44 RD 33/1986)","blocks":[{"text":"El instructor practica las diligencias necesarias y, como primeras actuaciones, toma declaración al inculpado (art. 34). En un plazo no superior a un mes desde la incoación formula el pliego de cargos, con los hechos imputados, la falta presunta y las sanciones aplicables, en párrafos separados y numerados; el plazo puede ampliarse por causas justificadas (art. 35). El pliego se notifica al inculpado, que tiene diez días para contestarlo, aportar documentos y pedir pruebas (art. 36). Para practicar la prueba hay un mes; el instructor puede denegar las pruebas innecesarias motivándolo, sin que quepa recurso del inculpado (art. 37). La intervención del instructor en las pruebas es esencial y no puede suplirla el secretario (art. 40).","refs":[{"ref":"Art. 35.1 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"A la vista de las actuaciones practicadas y en un plazo no superior a un mes, contados a partir de la incoación del procedimiento, el Instructor formulará el correspondiente pliego de cargos"},{"ref":"Art. 36 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"El pliego de cargos se notificará al inculpado concediéndosele un plazo de diez días para que pueda contestarlo"},{"ref":"Art. 37.2 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"El Instructor podrá denegar la admisión y práctica de las pruebas para averiguar cuestiones que considere innecesarias, debiendo motivar la denegación, sin que contra esta resolución queda recurso del inculpado."}]},{"text":"Concluidas las diligencias, se da vista inmediata del expediente al inculpado para que en diez días alegue y aporte documentos, facilitándole copia completa si la pide (art. 41). En los diez días siguientes, el instructor formula la propuesta de resolución con los hechos, su valoración jurídica, la falta, la responsabilidad y la sanción (art. 42), que se notifica al interesado para que alegue en diez días (art. 43). Después el expediente completo se remite al órgano que acordó la incoación, que lo pasa al competente para resolver (art. 44).","refs":[{"ref":"Art. 41 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"se dará vista del expediente al inculpado con carácter inmediato para que en el plazo de diez días alegue lo que estime pertinente a su defensa y aporte cuantos documentos considere de interés. Se facilitará copia completa del expediente al inculpado cuando éste así lo solicite."},{"ref":"Art. 43 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"La propuesta de resolución se notificará por el Instructor al interesado para que, en el plazo de diez días, pueda alegar ante el Instructor cuanto considere conveniente en su defensa."}]}]},{"n":"11","title":"Terminación, órganos competentes, ejecución y anotación (arts. 45-51 RD 33/1986)","blocks":[{"text":"La resolución se adopta en diez días, salvo en caso de separación del servicio; debe ser motivada y no puede aceptar hechos distintos de los del pliego de cargos y la propuesta, aunque sí valorarlos jurídicamente de otro modo (art. 45). Son competentes para sancionar: el Consejo de Ministros, para la separación del servicio; los Ministros y Secretarios de Estado del Departamento, o los Subsecretarios por delegación, para la suspensión de funciones y el traslado con cambio de residencia; y el Subsecretario, los Directores generales y los Delegados del Gobierno para las sanciones leves (art. 47). La referencia al «Ministro de la Presidencia» y a los «Gobernadores civiles» responde a la organización de 1986.","refs":[{"ref":"Art. 45.2 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"La resolución habrá de ser motivada y en ella no se podrán aceptar hechos distintos de los que sirvieron de base al pliego de cargos y a la propuesta de resolución, sin perjuicio de su distinta valoración jurídica."},{"ref":"Art. 47.2 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"Los Ministros y Secretarios de Estado del Departamento en el que esté destinado el funcionario, o los Subsecretarios por delegación de éstos, para imponer las sanciones de los apartados b) y c) del artículo 14."}]},{"text":"La resolución se notifica con indicación de recursos, órgano y plazos, y también al denunciante si lo hubo (art. 48). Las sanciones se ejecutan en el plazo máximo de un mes, salvo que la resolución fije otro por causas justificadas (art. 49); puede acordarse su inejecución o su suspensión temporal (art. 50). Se anotan en el Registro Central de Personal con indicación de las faltas, y las sanciones canceladas o que hubieran podido serlo no computan a efectos de reincidencia (art. 51).","refs":[{"ref":"Art. 49 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"Las sanciones disciplinarias se ejecutarán según los términos de la resolución en que se imponga, y en el plazo máximo de un mes, salvo que, cuando por causas justificadas, se establezca otro distinto en dicha resolución."},{"ref":"Art. 51 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"Las sanciones disciplinarías que se impongan a los funcionarios se anotarán en el Registro Central de Personal, con indicación de las faltas que los motivaron."},{"ref":"Art. 51 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"En ningún caso se computarán a efectos de reincidencia las sanciones canceladas o que hubieran podido serlo."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Diez horas al mes de incumplimiento de jornada o la tercera ausencia en tres meses con dos leves sancionadas: falta grave.","refs":[{"ref":"Art. 7.1.l) RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"l) El incumplimiento injustificado de la jornada de trabajo que acumulado suponga un mínimo de diez horas al mes."}]},{"text":"Una falta de asistencia injustificada de un día: falta leve.","refs":[{"ref":"Art. 8 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"b) La falta de asistencia injustificada de un día."}]},{"text":"Traslado con cambio de residencia: sin destino en la localidad de origen 3 años (muy grave) o 1 año (grave).","refs":[{"ref":"Art. 16 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"Dicho plazo se computará desde el momento en que se efectuó el traslado."}]},{"text":"Prescripción: rige el TREBEP (3 años, 2 años y 6 meses para faltas), no los plazos del RD 33/1986.","refs":[{"ref":"Art. 97.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses"}]},{"text":"Incoación siempre de oficio; competente en todo caso el Subsecretario del Departamento.","refs":[{"ref":"Art. 29.1 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"el Subsecretario del Departamento en que esté destinado el funcionario, en todo caso."}]},{"text":"Instructor de igual o superior grupo; abstención y recusación resueltas en tres días.","refs":[{"ref":"Art. 32.3 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"quien deberá resolver en el término de tres días."}]},{"text":"Plazos de instrucción: pliego en un mes, contestación en diez días, prueba en un mes, vista diez días, propuesta diez días.","refs":[{"ref":"Art. 37.1 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"Para la práctica de las pruebas se dispondrá del plazo de un mes."}]},{"text":"Separación del servicio: la impone el Consejo de Ministros y solo por faltas muy graves.","refs":[{"ref":"Art. 47.1 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"El Consejo de Ministros, a propuesta del Ministro de la Presidencia, quien con carácter previo oirá a la Comisión Superior de Personal, para imponer la separación del servicio."}]},{"text":"Ejecución de la sanción en un mes como máximo y anotación en el Registro Central de Personal.","refs":[{"ref":"Art. 49 RD 33/1986","law":"RD 33/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216","quote":"en el plazo máximo de un mes"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216', null, null, null, 'Otras normas citadas: TREBEP (https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719)'
  from public.topics t where t.slug = 'age-adm-46-regimen-disciplinario'
