insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto Legislativo 4/2000, de 23 de junio, texto refundido de la Ley sobre Seguridad Social de los Funcionarios Civiles del Estado (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-47-muface', 'IV.7 La Seguridad Social de los funcionarios: MUFACE y clases pasivas') on conflict (slug) do nothing;
