insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Régimen especial de Seguridad Social de los Funcionarios Civiles del Estado: mecanismos de cobertura y campo de aplicación (arts. 1-3 RDLeg 4/2000)"},{"n":"2","title":"Las Clases Pasivas y la inclusión en el Régimen General de los funcionarios de nuevo ingreso desde 2011 (art. 2.2 RDLeg 4/2000; DA 3.ª LGSS)"},{"n":"3","title":"MUFACE: competencia, naturaleza y régimen de personal (arts. 4-6)"},{"n":"4","title":"Incorporación: afiliación, altas, bajas y mutualistas voluntarios (arts. 7-9)"},{"n":"5","title":"Cotización (art. 10)"},{"n":"6","title":"Contingencias y prestaciones (arts. 11-12)"},{"n":"7","title":"Asistencia sanitaria (arts. 13-17)"},{"n":"8","title":"Incapacidad temporal y riesgo durante el embarazo y la lactancia natural (arts. 18-22)"},{"n":"9","title":"Incapacidad permanente, gran invalidez y lesiones permanentes no invalidantes (arts. 23-28)"},{"n":"10","title":"Protección a la familia, servicios sociales y asistencia social (arts. 29-32)"},{"n":"11","title":"Régimen económico, patrimonial y de recursos (arts. 33-37)"}]'::jsonb, '["Art. 1 RDLeg 4/2000: «El Régimen especial de la Seguridad Social de los Funcionarios Civiles del Estado se rige por lo dispuesto en la presente Ley y en sus normas de aplicación y desarrollo, así como por la legislación de Clases Pasivas del Estado.»","Art. 2 RDLeg 4/2000: «1. Este Régimen especial queda integrado por los siguientes mecanismos de cobertura: a) El Régimen de Clases Pasivas del Estado, de acuerdo con sus normas específicas. b) El Régimen del Mutualismo Administrativo que se regula en la presente Ley. 2. No obstante lo anterior, los funcionarios de carrera de la Administración Civil del Estado que hayan ingresado a partir del 1 de enero de 2011, quedarán integrados en el Régimen General de la Seguridad Social a los exclusivos efectos de pensiones»","Art. 3.1 RDLeg 4/2000: «1. Quedan obligatoriamente incluidos en el campo de aplicación de este Régimen especial: a) Los funcionarios de carrera de la Administración Civil del Estado. b) Los funcionarios en prácticas que aspiren a incorporarse a Cuerpos de la Administración Civil del Estado, en la forma que reglamentariamente se determine.»","DA 3.ª.1 LGSS: «1. Con efectos de 1 de enero de 2011, el personal que se relaciona en el artículo 2.1 del texto refundido de la Ley de Clases Pasivas del Estado, aprobado por el Real Decreto Legislativo 670/1987, de 30 de abril, excepción hecha del comprendido en la letra i), estará obligatoriamente incluido, a los exclusivos efectos de lo dispuesto en dicha norma y en sus disposiciones de desarrollo, en el Régimen General de la Seguridad Social siempre que el acceso a la condición de que se trate se produzca a partir de aquella fecha.»","Art. 5.1 RDLeg 4/2000: «1. La Mutualidad General de Funcionarios Civiles del Estado es un organismo público con personalidad jurídica pública diferenciada, patrimonio y tesorería propios y autonomía de gestión»","Art. 7.1 RDLeg 4/2000: «1. Los funcionarios de carrera de la Administración Civil del Estado se incorporarán obligatoriamente, como mutualistas, a la Mutualidad General de Funcionarios Civiles del Estado, en el momento de la toma de posesión de su cargo, cuando adquieran la condición de funcionario, o sean rehabilitados en dicha condición, o reingresen al servicio activo»","Art. 8.2 RDLeg 4/2000: «2. Podrán mantener facultativamente la situación de alta como mutualistas voluntarios, con igualdad de derechos, los funcionarios a que se refieren los párrafos a), b) y c) del apartado 1 de este artículo, siempre que abonen exclusivamente a su cargo las cuotas correspondientes al funcionario y al Estado.»","Art. 10.4 RDLeg 4/2000: «4. La cuota mensual de cotización se obtendrá dividiendo por catorce la cantidad resultante de aplicar a la base de cotización anual, reducida en su caso, el tipo porcentual establecido y se abonará doblemente en los meses de junio y diciembre.»","Art. 11 RDLeg 4/2000: «Los mutualistas y, en su caso, los familiares o asimilados a su cargo quedan concretamente protegidos, de acuerdo con lo previsto en esta Ley, en las siguientes contingencias: a) Necesidad de asistencia sanitaria. b) Incapacidad temporal, derivada bien de enfermedad común o profesional, bien de accidente común o en acto de servicio o como consecuencia de él. c) Incapacidad permanente en los mismos supuestos del apartado anterior. d) Cargas familiares. e) Situación especial de incapacidad temporal por donación de órganos o tejidos para su trasplante, prevista en el artículo 18.»","Art. 17.1 RDLeg 4/2000: «1. La asistencia sanitaria se facilitará por la Mutualidad General de Funcionarios Civiles del Estado, bien directamente o por concierto con otras entidades o establecimientos públicos o privados. Estos conciertos se establecerán preferentemente con instituciones de la Seguridad Social.»","Art. 21.1 RDLeg 4/2000: «b) Desde el cuarto mes percibirá las retribuciones básicas, la prestación por hijo a cargo, en su caso, y un subsidio por incapacidad temporal a cargo de la Mutualidad General de Funcionarios Civiles del Estado, cuya cuantía, fija e invariable mientras dure la incapacidad, será la mayor de las dos cantidades siguientes: 1.ª El 80 por ciento de las retribuciones básicas (sueldo, trienios y grado, en su caso), incrementadas en la sexta parte de una paga extraordinaria, correspondientes al tercer mes de licencia. 2.ª El 75 por ciento de las retribuciones complementarias devengadas en el tercer mes de licencia.»","Art. 23.2 RDLeg 4/2000: «2. La incapacidad permanente se clasifica con arreglo a los siguientes grados: a) Incapacidad permanente parcial para la función habitual: es la que, sin alcanzar el grado de total, produce al funcionario una limitación para el desempeño de las funciones de su Cuerpo, Escala o plaza.»","Art. 26 RDLeg 4/2000: «La gran invalidez originará la jubilación del funcionario y dará derecho a una cantidad mensual equivalente al 50 por 100 de la pensión de jubilación que le corresponda con arreglo al Régimen de Clases Pasivas, destinada a remunerar a la persona encargada de su asistencia.»","Art. 29.1 RDLeg 4/2000: «1. Las prestaciones económicas de protección a la familia serán de pago periódico y de pago único. Las primeras corresponden a las prestaciones familiares por hijo a cargo y las segundas a ayudas económicas en los casos de parto múltiple y por nacimiento de hijo.»","Art. 33.1 RDLeg 4/2000: «1. Salvo las excepciones que puedan establecerse en las normas reguladoras de este Régimen especial de la Seguridad Social, el sistema financiero del mismo será de reparto y su cuota revisable periódicamente.»","Art. 37.1 RDLeg 4/2000: «1. Los actos y resoluciones del Director general de la Mutualidad General de Funcionarios Civiles del Estado no ponen fin a la vía administrativa, pudiéndose recurrir en alzada ante el Ministro de Administraciones Públicas.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El Régimen especial de Seguridad Social de los Funcionarios Civiles del Estado: mecanismos de cobertura y campo de aplicación","blocks":[{"text":"La protección social de los funcionarios civiles del Estado no se articula, como la del personal laboral, a través del Régimen General, sino mediante un Régimen especial regulado por el texto refundido aprobado por el Real Decreto Legislativo 4/2000 (en adelante, RDLeg 4/2000), por sus normas de desarrollo y por la legislación de Clases Pasivas (art. 1). Este Régimen especial está integrado por dos mecanismos de cobertura distintos: el Régimen de Clases Pasivas del Estado, que se rige por sus normas específicas y cubre fundamentalmente las pensiones, y el Régimen del Mutualismo Administrativo, que es el que regula la propia ley y gestiona MUFACE (art. 2.1).","refs":[{"ref":"Art. 1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"El Régimen especial de la Seguridad Social de los Funcionarios Civiles del Estado se rige por lo dispuesto en la presente Ley y en sus normas de aplicación y desarrollo, así como por la legislación de Clases Pasivas del Estado."},{"ref":"Art. 2.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Este Régimen especial queda integrado por los siguientes mecanismos de cobertura: a) El Régimen de Clases Pasivas del Estado, de acuerdo con sus normas específicas. b) El Régimen del Mutualismo Administrativo que se regula en la presente Ley."}]},{"text":"Quedan incluidos obligatoriamente los funcionarios de carrera de la Administración Civil del Estado y los funcionarios en prácticas que aspiren a ingresar en sus Cuerpos (art. 3.1). La ley excluye expresamente, y remite a sus normas propias, a los funcionarios de la Administración Local, de organismos autónomos, de la Administración Militar, de la Administración de Justicia y de la Administración de la Seguridad Social; a los funcionarios de nuevo ingreso y en prácticas de las Comunidades Autónomas; a los funcionarios estatales transferidos que ingresen en Cuerpos o Escalas propios de la comunidad de destino; y al personal de administración y servicios propio de las universidades (art. 3.2).","refs":[{"ref":"Art. 3.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Quedan obligatoriamente incluidos en el campo de aplicación de este Régimen especial: a) Los funcionarios de carrera de la Administración Civil del Estado. b) Los funcionarios en prácticas que aspiren a incorporarse a Cuerpos de la Administración Civil del Estado, en la forma que reglamentariamente se determine."},{"ref":"Art. 3.2 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Quedan excluidos de este Régimen especial y se regirán por sus normas específicas: a) Los funcionarios de la Administración Local. b) Los funcionarios de organismos autónomos. c) Los funcionarios de Administración Militar. d) Los funcionarios de la Administración de Justicia. e) Los funcionarios de la Administración de la Seguridad Social. f) Los funcionarios de nuevo ingreso y en prácticas de las Comunidades Autónomas."},{"ref":"Art. 3.2.h) RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"h) El personal de administración y servicios propio de las universidades."}]}]},{"n":"2","title":"Las Clases Pasivas y la inclusión en el Régimen General de los funcionarios de nuevo ingreso desde 2011","blocks":[{"text":"El Régimen de Clases Pasivas es el mecanismo tradicional de pensiones de los funcionarios del Estado. Desde el 1 de enero de 2011 se produjo un cambio decisivo: los funcionarios de carrera de la Administración Civil del Estado que ingresen a partir de esa fecha quedan integrados en el Régimen General de la Seguridad Social, pero solo «a los exclusivos efectos de pensiones» (art. 2.2 RDLeg 4/2000). Es decir, siguen siendo mutualistas de MUFACE para el resto de prestaciones (asistencia sanitaria, incapacidad temporal, etc.), y las pensiones las causarán en el Régimen General en lugar de en Clases Pasivas.","refs":[{"ref":"Art. 2.2 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"los funcionarios de carrera de la Administración Civil del Estado que hayan ingresado a partir del 1 de enero de 2011, quedarán integrados en el Régimen General de la Seguridad Social a los exclusivos efectos de pensiones"}]},{"text":"La misma regla aparece en la disposición adicional tercera de la Ley General de la Seguridad Social (LGSS): el personal relacionado en el artículo 2.1 del texto refundido de Clases Pasivas (salvo el de la letra i) que acceda a su condición desde el 1 de enero de 2011 queda incluido obligatoriamente en el Régimen General, a los exclusivos efectos de lo dispuesto en la normativa de Clases Pasivas. Quien ya estaba en Clases Pasivas a 31 de diciembre de 2010 y, sin solución de continuidad, ingresa o reingresa en otro Cuerpo que entonces daba lugar a ese encuadramiento, continúa en Clases Pasivas (DA 3.ª.3 LGSS). Advertencia: el texto refundido de la Ley de Clases Pasivas (RDLeg 670/1987) no figura entre las fuentes consolidadas de estos apuntes, por lo que su contenido (clases de pensiones, cálculo, haberes reguladores) no se desarrolla aquí y debe estudiarse en el BOE.","refs":[{"ref":"DA 3.ª.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Con efectos de 1 de enero de 2011, el personal que se relaciona en el artículo 2.1 del texto refundido de la Ley de Clases Pasivas del Estado, aprobado por el Real Decreto Legislativo 670/1987, de 30 de abril, excepción hecha del comprendido en la letra i), estará obligatoriamente incluido, a los exclusivos efectos de lo dispuesto en dicha norma y en sus disposiciones de desarrollo, en el Régimen General de la Seguridad Social siempre que el acceso a la condición de que se trate se produzca a partir de aquella fecha."},{"ref":"DA 3.ª.3 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"El personal incluido en el ámbito personal de cobertura del Régimen de Clases Pasivas a 31 de diciembre de 2010 que, con posterioridad a dicha fecha y sin solución de continuidad, ingrese, cualquiera que sea el sistema de acceso, o reingrese, en otro Cuerpo que hubiera motivado en dicha fecha su encuadramiento en el Régimen de Clases Pasivas, continuará incluido en dicho régimen."}]}]},{"n":"3","title":"MUFACE: competencia, naturaleza y régimen de personal","blocks":[{"text":"El mutualismo administrativo se gestiona y presta a través de la Mutualidad General de Funcionarios Civiles del Estado (MUFACE), de forma unitaria, sin perjuicio de las obligaciones de las comunidades autónomas respecto de los funcionarios estatales transferidos (art. 4). La ley la adscribe al «Ministerio de Administraciones Públicas», denominación histórica: hoy depende del departamento con competencias en función pública. MUFACE es un organismo público con personalidad jurídica pública diferenciada, patrimonio y tesorería propios y autonomía de gestión, que se rige por las normas de los organismos autónomos (el art. 5.1 todavía cita la derogada Ley 6/1997, LOFAGE), salvo en su régimen económico-financiero, patrimonial, presupuestario, contable y de conciertos sanitarios, que sigue la propia ley y la Ley General Presupuestaria. Goza del mismo tratamiento fiscal que el Estado (art. 5.3).","refs":[{"ref":"Art. 4.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"El sistema de mutualismo administrativo, al que se refiere esta Ley, se gestionará y prestará a través de la Mutualidad General de Funcionarios Civiles del Estado (MUFACE), dependiente del Ministerio de Administraciones Públicas."},{"ref":"Art. 5.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"La Mutualidad General de Funcionarios Civiles del Estado es un organismo público con personalidad jurídica pública diferenciada, patrimonio y tesorería propios y autonomía de gestión, y se regirá por las previsiones de la Ley 6/1997, de 14 de abril, de Organización y Funcionamiento de la Administración General del Estado, relativas a los organismos autónomos"},{"ref":"Art. 5.3 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"La Mutualidad General de Funcionarios Civiles del Estado gozará del mismo tratamiento fiscal que la Ley establezca para el Estado."}]},{"text":"El personal de MUFACE puede ser funcionario o laboral, en los mismos términos que en la Administración General del Estado (art. 6).","refs":[{"ref":"Art. 6 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"El personal al servicio de la Mutualidad General de Funcionarios Civiles del Estado será funcionario o laboral en los mismos términos que los establecidos para la Administración General del Estado."}]}]},{"n":"4","title":"Incorporación: afiliación, altas, bajas y mutualistas voluntarios","blocks":[{"text":"La incorporación a MUFACE es obligatoria y se produce en el momento de la toma de posesión, cuando se adquiere la condición de funcionario, se es rehabilitado o se reingresa al servicio activo. Se conserva la condición de mutualista, con los mismos derechos y obligaciones que en activo, en servicios especiales, servicios en Comunidades Autónomas, expectativa de destino, excedencia forzosa, excedencia por cuidado de familiares y suspensión provisional o firme de funciones (art. 7.1). También la conservan los jubilados, ya sea por edad, voluntariamente o por incapacidad permanente para el servicio (art. 7.2).","refs":[{"ref":"Art. 7.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Los funcionarios de carrera de la Administración Civil del Estado se incorporarán obligatoriamente, como mutualistas, a la Mutualidad General de Funcionarios Civiles del Estado, en el momento de la toma de posesión de su cargo, cuando adquieran la condición de funcionario, o sean rehabilitados en dicha condición, o reingresen al servicio activo"},{"ref":"Art. 7.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"a) Servicios especiales, salvo lo dispuesto en el párrafo c) del apartado 1 y en el apartado 3 del artículo 8. b) Servicios en Comunidades Autónomas. c) Expectativa de destino. d) Excedencia forzosa. e) Excedencia por el cuidado de familiares. f) Suspensión provisional o firme de funciones."}]},{"text":"Quien accede por promoción interna a Escalas de organismos autónomos queda incluido obligatoriamente en el Régimen General, aunque puede mantener la condición de mutualista; para ello debe optar una sola vez, en el plazo de quince días desde la toma de posesión en el nuevo Cuerpo o Escala, y ese mantenimiento no supone inclusión en Clases Pasivas (art. 7.3).","refs":[{"ref":"Art. 7.3 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"En el caso de que deseen mantener su condición de mutualistas, deberán ejercitar esta opción, por una sola vez, en el plazo de quince días desde la toma de posesión en el nuevo Cuerpo o Escala."}]},{"text":"Causan baja como mutualistas obligatorios, entre otros, quienes pasan a excedencia voluntaria en cualquiera de sus modalidades y quienes pierden la condición de funcionario (art. 8.1). En esos casos pueden seguir en alta como mutualistas voluntarios, con igualdad de derechos, si abonan a su exclusivo cargo las cuotas del funcionario y del Estado (art. 8.2). Cuando una misma prestación de servicios obliga a estar en más de un régimen, el funcionario puede optar una sola vez por pertenecer solo al régimen especial de funcionarios que le corresponda (art. 9.3).","refs":[{"ref":"Art. 8.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"a) Los funcionarios que pasen a la situación de excedencia voluntaria, en cualquiera de sus modalidades, salvo que ejerciten la opción de mantener la condición de mutualistas, en los supuestos establecidos en el apartado 3 del artículo 7. b) Los funcionarios que pierdan tal condición, cualquiera que sea la causa."},{"ref":"Art. 8.2 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Podrán mantener facultativamente la situación de alta como mutualistas voluntarios, con igualdad de derechos, los funcionarios a que se refieren los párrafos a), b) y c) del apartado 1 de este artículo, siempre que abonen exclusivamente a su cargo las cuotas correspondientes al funcionario y al Estado."},{"ref":"Art. 9.3 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Cuando una única prestación de servicios sea causa de la inclusión obligatoria de un funcionario público en más de un Régimen de la Seguridad Social, podrá optar, por una sola vez, por pertenecer exclusivamente al Régimen especial de la Seguridad Social de los funcionarios públicos que le corresponda."}]}]},{"n":"5","title":"Cotización","blocks":[{"text":"Cotizar a MUFACE es obligatorio para todos los mutualistas salvo dos excepciones: los jubilados y quienes estén en excedencia voluntaria para el cuidado de hijos o familiares (art. 10.1). La base de cotización es el haber regulador que fija cada año la Ley de Presupuestos Generales del Estado, que también fija el tipo porcentual, cifras que cambian cada ejercicio (art. 10.2 y 10.3). La cuota mensual resulta de dividir entre catorce la cantidad obtenida al aplicar el tipo a la base anual, y se paga doble en junio y diciembre (art. 10.4).","refs":[{"ref":"Art. 10.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"La cotización a la Mutualidad General de Funcionarios Civiles del Estado será obligatoria para todos los mutualistas, con excepción de los mutualistas jubilados y de quienes se encuentren en la situación de excedencia voluntaria para atender al cuidado de hijos o familiares."},{"ref":"Art. 10.2 y 10.3 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"La base de cotización será la que anualmente se establezca como haber regulador en la Ley de Presupuestos Generales del Estado. […] El tipo porcentual de cotización será fijado en la Ley de Presupuestos Generales del Estado para cada ejercicio económico."},{"ref":"Art. 10.4 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"La cuota mensual de cotización se obtendrá dividiendo por catorce la cantidad resultante de aplicar a la base de cotización anual, reducida en su caso, el tipo porcentual establecido y se abonará doblemente en los meses de junio y diciembre."}]},{"text":"La obligación de pagar cotizaciones prescribe a los cuatro años desde la fecha en que debieron ingresarse, y se interrumpe, en particular, por el requerimiento al deudor (art. 10.6). El mutualista dispone de cuatro años para pedir la devolución de cuotas ingresadas indebidamente (art. 10.7).","refs":[{"ref":"Art. 10.6 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"La obligación de pago de las cotizaciones a la Mutualidad prescribirá a los cuatro años a contar desde la fecha en que preceptivamente debieron ser ingresadas."},{"ref":"Art. 10.7 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"El plazo para ejercitar este derecho será de cuatro años a partir de la fecha en que se hubiesen hecho efectivas."}]}]},{"n":"6","title":"Contingencias y prestaciones","blocks":[{"text":"El mutualismo protege a los mutualistas y, en su caso, a sus familiares o asimilados a cargo frente a cinco contingencias: necesidad de asistencia sanitaria; incapacidad temporal derivada de enfermedad común o profesional o de accidente común o en acto de servicio; incapacidad permanente en esos mismos supuestos; cargas familiares; y la situación especial de incapacidad temporal por donación de órganos o tejidos (art. 11). Obsérvese que la jubilación, la viudedad o la orfandad no aparecen en la lista: son pensiones de Clases Pasivas (o del Régimen General para quienes ingresaron desde 2011).","refs":[{"ref":"Art. 11 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"a) Necesidad de asistencia sanitaria. b) Incapacidad temporal, derivada bien de enfermedad común o profesional, bien de accidente común o en acto de servicio o como consecuencia de él. c) Incapacidad permanente en los mismos supuestos del apartado anterior. d) Cargas familiares. e) Situación especial de incapacidad temporal por donación de órganos o tejidos para su trasplante, prevista en el artículo 18."}]},{"text":"Las prestaciones son: asistencia sanitaria; subsidios por incapacidad temporal, riesgo durante el embarazo y riesgo durante la lactancia natural; prestaciones recuperadoras por incapacidad permanente total, absoluta y gran invalidez; prestación para remunerar a quien asiste al gran inválido; indemnizaciones por lesiones permanentes; servicios sociales; asistencia social; prestaciones por hijo a cargo con discapacidad y ayudas por parto múltiple (art. 12.1). Las que exigen un pago se abonan únicamente en cuenta corriente o libreta abierta a nombre del beneficiario (art. 12.2).","refs":[{"ref":"Art. 12.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"a) Asistencia sanitaria. b) Subsidios por incapacidad temporal, incluida la situación especial de incapacidad temporal por donación de órganos o tejidos para su trasplante prevista en el artículo 18, riesgo durante el embarazo o riesgo durante la lactancia natural. c) Prestaciones recuperadoras por incapacidad permanente total, absoluta y gran invalidez."},{"ref":"Art. 12.2 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"serán abonadas únicamente en la cuenta corriente o libreta ordinaria abierta a su nombre."}]}]},{"n":"7","title":"Asistencia sanitaria","blocks":[{"text":"La asistencia sanitaria comprende los servicios médicos, quirúrgicos y farmacéuticos para conservar o restablecer la salud y la aptitud para el trabajo, con especial atención a la rehabilitación (art. 13). Cubre la enfermedad común o profesional, los accidentes comunes o en acto de servicio, la donación de órganos y el embarazo, parto y puerperio (art. 14). Su contenido incluye atención primaria y especializada análogas a las del Sistema Nacional de Salud, la prestación farmacéutica (con participación del beneficiario mediante un porcentaje por receta o medicamento) y prestaciones complementarias (art. 16).","refs":[{"ref":"Art. 13.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"La asistencia sanitaria tiene por objeto la prestación de los servicios médicos, quirúrgicos y farmacéuticos conducentes a conservar o restablecer la salud de los beneficiarios de este Régimen especial, así como su aptitud para el trabajo."},{"ref":"Art. 16.b) RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Los beneficiarios participarán mediante el pago de una cantidad porcentual por receta o, en su caso, por medicamento, que se determinará reglamentariamente."}]},{"text":"Son beneficiarios los mutualistas en activo y jubilados y sus beneficiarios a cargo; ser beneficiario de MUFACE es incompatible con serlo del Sistema Nacional de Salud por otro organismo (art. 15.1 y 15.2). MUFACE no presta asistencia a familiares sin la condición de beneficiario, con una excepción: el recién nacido de madre mutualista o beneficiaria, y los casos de adopción o acogimiento, durante los primeros quince días (art. 15.3). La asistencia se presta directamente o mediante conciertos con entidades públicas o privadas, preferentemente con instituciones de la Seguridad Social (art. 17.1).","refs":[{"ref":"Art. 15.3 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"salvo en el caso del recién nacido cuando la madre sea mutualista o beneficiaria y en los supuestos de adopción o acogimiento, durante los primeros quince días desde el momento del parto"},{"ref":"Art. 17.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"La asistencia sanitaria se facilitará por la Mutualidad General de Funcionarios Civiles del Estado, bien directamente o por concierto con otras entidades o establecimientos públicos o privados. Estos conciertos se establecerán preferentemente con instituciones de la Seguridad Social."}]}]},{"n":"8","title":"Incapacidad temporal y riesgo durante el embarazo y la lactancia natural","blocks":[{"text":"Está en incapacidad temporal el funcionario que padece un proceso patológico o lesión que le impide temporalmente desempeñar sus funciones (o está en observación por enfermedad profesional), siempre que reciba asistencia sanitaria de MUFACE y haya obtenido licencia por enfermedad (art. 19.1). Los permisos por parto, adopción o acogimiento no son incapacidad temporal (art. 18.2). Las licencias y prórrogas las conceden los órganos con competencia en gestión de personal (art. 19.3), aunque MUFACE puede controlar la situación desde el inicio con sus Unidades Médicas de Seguimiento (art. 19.4). Hay nuevo proceso patológico, a efectos de plazos, si las enfermedades son distintas o no relacionadas y, en todo caso, si las licencias se interrumpen al menos 6 meses (art. 20.2).","refs":[{"ref":"Art. 19.3 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"La concesión de las licencias y sus posibles prórrogas a los que tendrán derecho los funcionarios que se encuadren en la situación establecida en el apartado 1 corresponderá a los órganos administrativos con competencia en materias de gestión de personal."},{"ref":"Art. 20.2 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"se considerará que existe nuevo proceso patológico cuando las enfermedades que padezca el funcionario sean diferentes o no tengan relación directa con las del proceso anterior y, en todo caso, cuando se hayan interrumpido las licencias durante un periodo mínimo de 6 meses."}]},{"text":"Durante los tres primeros meses el mutualista cobra la totalidad de sus retribuciones, a cargo de su órgano de personal. Desde el cuarto mes percibe las retribuciones básicas, la prestación por hijo a cargo, en su caso, y un subsidio de MUFACE fijo e invariable, que será la mayor de dos cantidades: el 80 % de las retribuciones básicas (más la sexta parte de una paga extraordinaria) o el 75 % de las complementarias, ambas del tercer mes de licencia (art. 21.1). La suma nunca puede superar lo que se percibía en el tercer mes (art. 21.3). En la donación de órganos el subsidio es el 100 % de las complementarias (art. 21.1.c).","refs":[{"ref":"Art. 21.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Durante los tres primeros meses la persona mutualista tendrá derecho al percibo de la totalidad de las retribuciones previstas en las Leyes y Reglamentos aplicables según su respectiva Carrera, Cuerpo y Escala, a cargo de los órganos de personal correspondientes."},{"ref":"Art. 21.1.b) RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Desde el cuarto mes percibirá las retribuciones básicas, la prestación por hijo a cargo, en su caso, y un subsidio por incapacidad temporal a cargo de la Mutualidad General de Funcionarios Civiles del Estado, cuya cuantía, fija e invariable mientras dure la incapacidad, será la mayor de las dos cantidades siguientes: 1.ª El 80 por ciento de las retribuciones básicas (sueldo, trienios y grado, en su caso), incrementadas en la sexta parte de una paga extraordinaria, correspondientes al tercer mes de licencia. 2.ª El 75 por ciento de las retribuciones complementarias devengadas en el tercer mes de licencia."},{"ref":"Art. 21.3 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"En ningún caso la suma resultante de las cantidades a cargo del órgano para el que presta sus funciones el mutualista y la del subsidio podrá exceder del importe de las percepciones que el funcionario tuviera en el tercer mes de licencia."}]},{"text":"El riesgo durante el embarazo y durante la lactancia natural de hijos menores de 9 meses se equipara a la incapacidad temporal por enfermedad profesional, de modo que no exige carencia (art. 22.1). Las licencias también las conceden los órganos de personal (art. 22.2), y el subsidio de MUFACE equivale al 100 % de las retribuciones complementarias devengadas en el tercer mes de licencia (art. 22.4).","refs":[{"ref":"Art. 22.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Las situaciones de riesgo durante el embarazo o durante la lactancia natural de hijos menores de 9 meses tendrán la misma consideración que la situación de incapacidad temporal derivada de enfermedad profesional, por lo que no requerirán de periodo de carencia"},{"ref":"Art. 22.4 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"la prestación económica equivalente al subsidio por incapacidad temporal consistirá en un subsidio a cargo de la Mutualidad General de Funcionarios Civiles del Estado en cuantía igual al 100 por ciento de las retribuciones complementarias devengadas en el tercer mes de licencia."}]}]},{"n":"9","title":"Incapacidad permanente, gran invalidez y lesiones permanentes no invalidantes","blocks":[{"text":"La incapacidad permanente es la situación del funcionario que, tras el tratamiento y el alta médica, presenta reducciones anatómicas o funcionales graves que disminuyen o anulan su capacidad para el servicio; debe derivar siempre de una incapacidad temporal (art. 23.1). Tiene cuatro grados: parcial para la función habitual, total para la función habitual, absoluta para todo trabajo y gran invalidez (art. 23.2). El incapacitado parcial cobra la totalidad de los haberes del puesto que desempeña (art. 24); la total y la absoluta dan lugar a la jubilación y, si hay posibilidad razonable de recuperación, a prestaciones recuperadoras de MUFACE (art. 25).","refs":[{"ref":"Art. 23.2 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"a) Incapacidad permanente parcial para la función habitual: es la que, sin alcanzar el grado de total, produce al funcionario una limitación para el desempeño de las funciones de su Cuerpo, Escala o plaza."},{"ref":"Art. 23.2 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"d) Gran invalidez: es la situación del funcionario afecto de incapacidad permanente absoluta que, como consecuencia de pérdidas anatómicas o funcionales, necesita de la asistencia de otra persona para realizar los actos más elementales de la vida, tales como vestirse, desplazarse, comer o análogos."},{"ref":"Art. 25 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"La incapacidad permanente total y la incapacidad permanente absoluta darán lugar a la jubilación del funcionario de acuerdo con la legislación en vigor."}]},{"text":"La gran invalidez origina la jubilación y da derecho, además, a una cantidad mensual del 50 % de la pensión de jubilación de Clases Pasivas, destinada a pagar a la persona que asiste al gran inválido (art. 26). La calificación y revisión se hacen conforme a las normas de derechos pasivos (art. 27.1). Las lesiones, mutilaciones o deformaciones definitivas causadas por enfermedad profesional o en acto de servicio que no llegan a incapacidad total, absoluta o gran invalidez dan derecho a una indemnización por una sola vez (art. 28).","refs":[{"ref":"Art. 26 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"La gran invalidez originará la jubilación del funcionario y dará derecho a una cantidad mensual equivalente al 50 por 100 de la pensión de jubilación que le corresponda con arreglo al Régimen de Clases Pasivas, destinada a remunerar a la persona encargada de su asistencia."},{"ref":"Art. 28 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"darán derecho a la percepción por una sola vez de las cantidades que se establezcan reglamentariamente."}]}]},{"n":"10","title":"Protección a la familia, servicios sociales, asistencia social y régimen económico","blocks":[{"text":"Las prestaciones familiares son de pago periódico (por hijo a cargo) o de pago único (parto múltiple y nacimiento de hijo) y son incompatibles con las análogas de otros regímenes (art. 29.1 y 29.2). MUFACE gestiona la prestación por hijo a cargo con discapacidad (art. 29.4). El art. 29.3 remite todavía al Real Decreto-ley 1/2000 para la prestación por nacimiento; esa remisión puede estar superada por reformas posteriores. MUFACE dispensa además ayudas de asistencia social ante estados de necesidad, con el límite de sus créditos y sin comprometer el ejercicio siguiente (art. 31.1 y 31.2).","refs":[{"ref":"Art. 29.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Las prestaciones económicas de protección a la familia serán de pago periódico y de pago único. Las primeras corresponden a las prestaciones familiares por hijo a cargo y las segundas a ayudas económicas en los casos de parto múltiple y por nacimiento de hijo."},{"ref":"Art. 31.2 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Dichos servicios y auxilios económicos tendrán como límite los créditos que a tal fin se consignen en el presupuesto de gastos de la Mutualidad General de Funcionarios Civiles del Estado, y su concesión no podrá comprometer recursos del ejercicio siguiente a aquel en que la misma tenga lugar."}]},{"text":"El sistema financiero es de reparto, con cuota revisable periódicamente (art. 33.1). Los recursos de MUFACE son las aportaciones del Estado, las cuotas de los mutualistas, subvenciones, el patrimonio del Fondo especial, rentas y otros recursos (art. 34); la aportación estatal se fija cada año en la Ley de Presupuestos como porcentaje sobre los haberes reguladores (art. 35.2). Los actos del Director general no ponen fin a la vía administrativa y se recurren en alzada ante el Ministro; agotada esa vía, cabe el contencioso-administrativo (art. 37.1). El art. 37.2 y 37.3 remite aún a la Ley 30/1992, hoy sustituida por la Ley 39/2015.","refs":[{"ref":"Art. 33.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"el sistema financiero del mismo será de reparto y su cuota revisable periódicamente."},{"ref":"Art. 35.2 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"La cuantía de las aportaciones estatales se fijará anualmente en la Ley de Presupuestos Generales del Estado, mediante el establecimiento de un porcentaje aplicable sobre los haberes reguladores a que se refiere el apartado 2 del artículo 10."},{"ref":"Art. 37.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"Los actos y resoluciones del Director general de la Mutualidad General de Funcionarios Civiles del Estado no ponen fin a la vía administrativa, pudiéndose recurrir en alzada ante el Ministro de Administraciones Públicas."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Dos mecanismos de cobertura: Clases Pasivas y Mutualismo Administrativo (art. 2.1).","refs":[{"ref":"Art. 2.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"a) El Régimen de Clases Pasivas del Estado, de acuerdo con sus normas específicas. b) El Régimen del Mutualismo Administrativo que se regula en la presente Ley."}]},{"text":"Ingreso desde el 1 de enero de 2011: Régimen General solo a efectos de pensiones; MUFACE para lo demás.","refs":[{"ref":"Art. 2.2 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"quedarán integrados en el Régimen General de la Seguridad Social a los exclusivos efectos de pensiones"}]},{"text":"El PAS propio de las universidades queda excluido del Régimen especial.","refs":[{"ref":"Art. 3.2.h) RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"h) El personal de administración y servicios propio de las universidades."}]},{"text":"Alta en MUFACE: en la toma de posesión. Opción tras promoción interna a Escalas de organismos autónomos: una sola vez, en quince días.","refs":[{"ref":"Art. 7.3 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"por una sola vez, en el plazo de quince días desde la toma de posesión en el nuevo Cuerpo o Escala."}]},{"text":"No cotizan los jubilados ni los excedentes voluntarios por cuidado de hijos o familiares; cuota anual entre 14, doble en junio y diciembre; prescripción en cuatro años.","refs":[{"ref":"Art. 10.6 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"prescribirá a los cuatro años a contar desde la fecha en que preceptivamente debieron ser ingresadas."}]},{"text":"Recién nacido de madre mutualista o beneficiaria: asistencia durante los primeros quince días aunque no sea beneficiario.","refs":[{"ref":"Art. 15.3 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"durante los primeros quince días desde el momento del parto"}]},{"text":"Incapacidad temporal: tres meses con retribuciones íntegras; desde el cuarto mes, subsidio de MUFACE (80 % básicas o 75 % complementarias). Riesgo en embarazo o lactancia: 100 % de las complementarias.","refs":[{"ref":"Art. 22.4 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"en cuantía igual al 100 por ciento de las retribuciones complementarias devengadas en el tercer mes de licencia."}]},{"text":"Gran invalidez: 50 % de la pensión de jubilación de Clases Pasivas para la persona que asiste.","refs":[{"ref":"Art. 26 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"una cantidad mensual equivalente al 50 por 100 de la pensión de jubilación que le corresponda con arreglo al Régimen de Clases Pasivas"}]},{"text":"Resoluciones del Director general de MUFACE: alzada ante el Ministro.","refs":[{"ref":"Art. 37.1 RDLeg 4/2000","law":"RDLeg 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140","quote":"no ponen fin a la vía administrativa, pudiéndose recurrir en alzada ante el Ministro de Administraciones Públicas."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-12140', null, null, null, 'Otras normas citadas: LGSS (https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724)'
