insert into public.sources (title, url, kind, publisher, published_on) values ('Resolución de 13 de mayo de 2019, de la Dirección General de Trabajo, por la que se registra y publica el IV Convenio colectivo único para el personal laboral de la Administración General del Estado (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-48-convenio-unico', 'IV.8 El IV Convenio único para el personal laboral de la AGE: ámbito, clasificación profesional y condiciones de trabajo') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-48-convenio-unico' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Ámbito de aplicación, personal excluido y vigencia (arts. 1-4 IV Convenio único)"},{"n":"2","title":"Igualdad y conciliación (arts. 5-6)"},{"n":"3","title":"Clasificación profesional: grupos, familias profesionales y especialidades (arts. 7-11)"},{"n":"4","title":"Órganos de seguimiento: Comisión Negociadora, Comisión Paritaria y Subcomisiones (arts. 12-21)"},{"n":"5","title":"Ingreso, promoción interna y período de prueba (arts. 27-33)"},{"n":"6","title":"Provisión y movilidad: concurso abierto y permanente, movilidad funcional y de distinto grupo (arts. 34-53)"},{"n":"7","title":"Jornada, vacaciones, licencias y permisos (arts. 64-75)"},{"n":"8","title":"Suspensión del contrato, excedencias y reingreso (arts. 93-98)"},{"n":"9","title":"Régimen disciplinario: faltas, sanciones, prescripción y procedimiento (arts. 99-123)"}]'::jsonb, '["Art. 1.1 IV Convenio único AGE: «El presente Convenio colectivo será de aplicación al personal laboral de la Administración General del Estado y sus organismos autónomos.»","Art. 2 IV Convenio único AGE: «Quedan excluidos del ámbito de aplicación del presente Convenio: a) El personal laboral que presta servicios en el exterior.»","Art. 7.1 IV Convenio único AGE: «El sistema de clasificación que se contempla en el presente Convenio se estructura en grupos profesionales, familias profesionales y/o especialidades»","Art. 8.1 IV Convenio único AGE: «a) Grupo profesional M3: Título clasificado en el Nivel 3 del Marco Español de Cualificaciones para la Educación Superior o equivalentes.»","Art. 8.1 IV Convenio único AGE: «d) Grupo profesional E2: Título de Bachiller o Técnico o equivalentes.»","Art. 8.1 IV Convenio único AGE: «e) Grupo profesional E1: Título de Graduado en Educación Secundaria Obligatoria o Título Profesional Básico o equivalentes.»","Art. 8.1 IV Convenio único AGE: «f) Grupo profesional E0: Sin titulación prevista en el sistema educativo.»","Art. 32.1 IV Convenio único AGE: «cuya duración será de tres meses para los grupos profesionales M3 y M2 y de un mes para los demás trabajadores o trabajadoras, excepto para el personal sin titulación, para el que será de quince días laborables.»","Art. 36.1 IV Convenio único AGE: «El concurso de traslados abierto y permanente constituye el sistema ordinario de provisión y movilidad de los puestos de trabajo vacantes y de movilidad para el personal laboral fijo.»","Art. 48.4 IV Convenio único AGE: «La atribución del desempeño de un puesto de trabajo de dicho grupo profesional no podrá ser superior a ocho meses de duración en el plazo de dos años, computados de fecha a fecha»","Art. 73.1 IV Convenio único AGE: «Las vacaciones anuales retribuidas serán de veintidós días hábiles por año completo de servicios»","Art. 75 IV Convenio único AGE: «o) Hasta seis días cada año natural, por asuntos particulares no incluidos en los puntos anteriores.»","Art. 95.1 IV Convenio único AGE: «Una vez concedida, la duración mínima de permanencia en la misma es de cuatro meses y su duración máxima será indefinida.»","Art. 105 IV Convenio único AGE: «Por la comisión de faltas disciplinarias se pueden imponer las siguientes sanciones: a) Despido disciplinario. b) Suspensión de empleo y sueldo.»","Art. 112.1 IV Convenio único AGE: «Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses.»","Art. 117.1 IV Convenio único AGE: «La duración del procedimiento disciplinario no excederá de seis meses, a contar desde su incoación. Vencido este plazo sin que se haya dictado y notificado la resolución se producirá su caducidad.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Ámbito de aplicación, personal excluido y vigencia (arts. 1-4 IV Convenio único)","blocks":[{"text":"El IV Convenio colectivo único para el personal laboral de la Administración General del Estado se publicó por Resolución de 13 de mayo de 2019 de la Dirección General de Trabajo. Se aplica al personal laboral de la AGE y sus organismos autónomos (art. 1.1) y, además, al que presta servicios en la Administración de Justicia no transferida, la Administración de la Seguridad Social, el Consejo de Seguridad Nuclear, la Agencia Española de Protección de Datos, el Museo Reina Sofía y Trabajo Penitenciario y Formación para el Empleo (art. 1.2). Quedan excluidos, entre otros, el personal laboral en el exterior, el incluido en otros convenios de la AGE, el de alta dirección, el vinculado por contratos administrativos, el contratado expresamente fuera de convenio y el profesorado de religión (art. 2).","refs":[{"ref":"Art. 1.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"El presente Convenio colectivo será de aplicación al personal laboral de la Administración General del Estado y sus organismos autónomos."},{"ref":"Art. 1.2 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"c) El Consejo de Seguridad Nuclear."},{"ref":"Art. 2 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Quedan excluidos del ámbito de aplicación del presente Convenio: a) El personal laboral que presta servicios en el exterior."}]},{"text":"Entró en vigor al día siguiente de su publicación en el BOE, con efectos económicos desde el 1 de enero de 2019, y su vigencia se fijó hasta el 31 de diciembre de 2021; si no se denuncia se prorroga por años, y una vez denunciado mantiene todo su contenido hasta que lo sustituya otro (art. 3). Es un todo orgánico e indivisible y sustituye al III Convenio único (art. 4). Atención: las cuantías salariales del convenio se han revisado después mediante resoluciones posteriores que modifican sus anexos retributivos, por lo que no deben memorizarse las tablas de 2019.","refs":[{"ref":"Art. 3.2 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"La vigencia del COnvenio se extiende hasta el 31 de diciembre de 2021, pudiendo ser denunciado por cualquiera de las partes, dentro de los dos meses inmediatos anteriores a la terminación de su vigencia."},{"ref":"Art. 3.3 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"De no efectuarse denuncia expresa, el Convenio se prorrogará automáticamente por períodos anuales."},{"ref":"Art. 4.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"El presente Convenio colectivo forma un todo orgánico e indivisible y, a efectos de su aplicación, será considerado globalmente."}]}]},{"n":"2","title":"Igualdad y conciliación (arts. 5-6)","blocks":[{"text":"La igualdad de trato y oportunidades es un principio básico y transversal del convenio y un criterio para interpretarlo (art. 5.1); las actuaciones se ajustan al plan de igualdad vigente y la protección frente al acoso sexual y por razón de sexo, a los protocolos vigentes. La conciliación de la vida familiar, personal y laboral es también principio básico de la política de recursos humanos, y se concreta en especial en jornada y permisos, provisión y movilidad, y formación (art. 6).","refs":[{"ref":"Art. 5.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"constituye un principio básico que informa con carácter transversal el contenido del presente convenio y se configura como un criterio interpretativo en la aplicación del mismo."},{"ref":"Art. 6.2 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"a) Jornada y permisos. b) Provisión y movilidad. c) Formación y perfeccionamiento profesional."}]}]},{"n":"3","title":"Clasificación profesional: grupos, familias profesionales y especialidades (arts. 7-11)","blocks":[{"text":"La clasificación se estructura en grupos profesionales, familias profesionales y/o especialidades, en relación con el sistema educativo y el Sistema Nacional de Cualificaciones Profesionales (art. 7.1). El grupo reúne aptitudes, titulaciones y contenido general de la prestación; la familia agrupa titulaciones y oficios afines; la especialidad fija el contenido concreto y el perfil del puesto (art. 7.3-7.5). Todo puesto tiene asignada una especialidad (art. 10.1), y la modificación de la clasificación de un colectivo solo la aprueba la Comisión Negociadora, a propuesta de la Subcomisión Paritaria y con informe favorable de la Comisión Paritaria (art. 11.2).","refs":[{"ref":"Art. 7.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"El sistema de clasificación que se contempla en el presente Convenio se estructura en grupos profesionales, familias profesionales y/o especialidades"},{"ref":"Art. 10.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Todos los puestos de trabajo tendrán asignada una especialidad."}]},{"text":"Los grupos se definen por la titulación exigida para el ingreso (art. 8.1): M3, título del Nivel 3 del Marco Español de Cualificaciones para la Educación Superior (MECES); M2, Nivel 2 del MECES; M1, Nivel 1 del MECES; E2, Bachiller o Técnico; E1, Graduado en ESO o Título Profesional Básico; y E0, sin titulación prevista en el sistema educativo. Si un puesto exige título de Doctor, así constará en la convocatoria (art. 8.3).","refs":[{"ref":"Art. 8.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"a) Grupo profesional M3: Título clasificado en el Nivel 3 del Marco Español de Cualificaciones para la Educación Superior o equivalentes."},{"ref":"Art. 8.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"d) Grupo profesional E2: Título de Bachiller o Técnico o equivalentes. e) Grupo profesional E1: Título de Graduado en Educación Secundaria Obligatoria o Título Profesional Básico o equivalentes. f) Grupo profesional E0: Sin titulación prevista en el sistema educativo."}]}]},{"n":"4","title":"Órganos de seguimiento: Comisión Negociadora, Comisión Paritaria y Subcomisiones (arts. 12-21)","blocks":[{"text":"La Comisión Negociadora negocia en el marco del convenio conforme al art. 88 del Estatuto de los Trabajadores; la Comisión Paritaria es el órgano máximo de interpretación, vigilancia, seguimiento, estudio y aplicación de lo pactado (art. 12). La Negociadora tiene treinta miembros con voz y voto, quince por la Administración y quince por el personal (art. 13). La Paritaria se constituyó en los quince días siguientes a la publicación y tiene quince representantes por cada parte (art. 14). Dependiendo de ella, como órganos delegados, hay Subcomisiones Paritarias en cada Departamento y en otros ámbitos (CSN, CSIC, Seguridad Social, Justicia, Instituciones Penitenciarias…), con un máximo de quince miembros por parte (art. 19).","refs":[{"ref":"Art. 12.3 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"La Comisión Paritaria es el órgano máximo de interpretación, vigilancia, seguimiento, estudio y aplicación de lo pactado en el presente Convenio colectivo durante su vigencia."},{"ref":"Art. 13.2 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"De ellos, quince representarán a la Administración y quince al personal laboral al servicio de las Administraciones Públicas."},{"ref":"Art. 19.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Dependiente de la Comisión Paritaria, y como órgano delegado de la misma, en el ámbito de cada Departamento"}]}]},{"n":"5","title":"Ingreso, promoción interna y período de prueba (arts. 27-33)","blocks":[{"text":"Las vacantes se cubren por concurso abierto y permanente, promoción profesional e ingreso libre; antes de incluir un puesto en ingreso libre debe haberse ofertado en el concurso o en promoción interna (art. 27.2). Las convocatorias incluyen las plazas autorizadas en la Oferta de Empleo Público (art. 28.1). En promoción puede participar el personal fijo del grupo inmediatamente inferior con dos años de servicios efectivos en él y la titulación exigida (art. 28.2). Los sistemas son oposición, concurso y concurso-oposición; la oposición incluye siempre una prueba práctica y en el concurso-oposición hay que superar la oposición para pasar al concurso (art. 29). El órgano de selección tiene como mínimo cuatro representantes de la Administración y tres de los trabajadores, todos de grupo igual o superior; no puede formar parte el personal temporal (art. 31).","refs":[{"ref":"Art. 27.2 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Con anterioridad a la inclusión de un puesto de trabajo en una convocatoria de ingreso libre deberá haberse ofertado previamente el mismo en una convocatoria del concurso abierto y permanente o a través del procedimiento de promoción interna."},{"ref":"Art. 28.2 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"En los procesos de promoción podrá participar todo el personal laboral fijo, del grupo profesional inmediatamente inferior, siempre que haya prestado dos años de servicios efectivos en dicho grupo profesional"},{"ref":"Art. 31.3 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"No podrá formar parte de los órganos de selección el personal laboral temporal."}]},{"text":"El personal de nuevo ingreso por turno libre tiene un período de prueba pactado por escrito: tres meses para los grupos M3 y M2, un mes para los demás y quince días laborables para el personal sin titulación (art. 32.1). Superado, la admisión se formaliza automáticamente y computa a todos los efectos; la condición de fijo depende de superarlo (art. 32.2). Durante la prueba cualquiera de las partes puede terminar la relación sin indemnización (art. 32.3), y es nulo el período de prueba si ya se desempeñaron las mismas funciones dentro del convenio (art. 32.4).","refs":[{"ref":"Art. 32.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"cuya duración será de tres meses para los grupos profesionales M3 y M2 y de un mes para los demás trabajadores o trabajadoras, excepto para el personal sin titulación, para el que será de quince días laborables."},{"ref":"Art. 32.3 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Durante este período, tanto la Administración como el trabajador o trabajadora podrán poner fin a la relación laboral, sin que ninguna de las partes tenga por ello derecho a indemnización alguna."}]}]},{"n":"6","title":"Provisión y movilidad: concurso abierto y permanente, movilidad funcional y de distinto grupo (arts. 34-53)","blocks":[{"text":"El concurso de traslados abierto y permanente, de carácter interdepartamental, es el sistema ordinario de provisión y movilidad del personal laboral fijo (arts. 34-36). Para participar hay que haber permanecido un mínimo de dos años en el último puesto obtenido con carácter definitivo, salvo que se pida un puesto en la misma Secretaría de Estado o, en su defecto, en el mismo Departamento u organismo (art. 36). Existen además permutas, movilidad por violencia de género o terrorista, por protección de la maternidad o de la salud y por conciliación (arts. 38-45).","refs":[{"ref":"Art. 36.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"El concurso de traslados abierto y permanente constituye el sistema ordinario de provisión y movilidad de los puestos de trabajo vacantes y de movilidad para el personal laboral fijo."},{"ref":"Art. 36 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"deberá haber permanecido en el último puesto obtenido con carácter definitivo un mínimo de dos años, salvo en el caso que soliciten un puesto ubicado en la misma Secretaría de Estado en la que tenga su destino definitivo"}]},{"text":"La Subsecretaría puede acordar motivadamente la movilidad funcional dentro del mismo grupo profesional, con comunicación a la representación y a la Subcomisión Paritaria (art. 47). Si un puesto se ocupa así durante un año continuado o dos alternos en tres años, debe cubrirse definitivamente por el concurso abierto y permanente (art. 47.5). Por necesidades del servicio cabe desempeñar puestos de grupo superior o inferior (art. 48): en el inferior, solo por necesidades perentorias o imprevisibles, un máximo de un mes en un año y manteniendo la retribución de origen; en el superior, preferentemente por el grupo inmediatamente inferior y como máximo ocho meses en dos años, computados de fecha a fecha. Nunca se cambia así de grupo ni computa como mérito (art. 48.7).","refs":[{"ref":"Art. 47.5 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"En el caso de que un puesto de trabajo sea ocupado mediante movilidad funcional durante un año continuado o dos alternos en un plazo de tres años, se procederá a su cobertura definitiva a través del concurso abierto y permanente"},{"ref":"Art. 48.2 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"salvo en los casos de encomienda de funciones de grupo inferior en los que mantendrán la retribución de origen."},{"ref":"Art. 48.3 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"no pudiendo ser su duración en su totalidad superior a un mes en un período de un año."},{"ref":"Art. 48.4 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"La atribución del desempeño de un puesto de trabajo de dicho grupo profesional no podrá ser superior a ocho meses de duración en el plazo de dos años, computados de fecha a fecha"}]}]},{"n":"7","title":"Jornada, vacaciones y licencias (arts. 64-74)","blocks":[{"text":"La jornada general máxima es de treinta y siete horas y media semanales de trabajo efectivo de promedio en cómputo anual, equivalentes a 1.642 horas anuales, y puede llegar a cuarenta horas en determinados supuestos con los complementos correspondientes (art. 64). Lo no previsto se rige por la resolución vigente de la Secretaría de Estado de Función Pública sobre jornada y horarios, que puede haber cambiado desde 2019. Las vacaciones son de veintidós días hábiles por año completo, a disfrutar en el año natural y hasta el 31 de enero siguiente; con antigüedad aumentan a 23 días (15 años), 24 (20), 25 (25) y 26 (30 o más) (art. 73.1). Pueden tomarse en períodos mínimos de cinco días hábiles consecutivos (art. 73.2). La licencia sin sueldo por asuntos propios exige un año de servicios y no puede superar tres meses cada dos años (art. 74.1).","refs":[{"ref":"Art. 64.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"La duración máxima de la jornada general de trabajo será de treinta y siete horas y media semanales de trabajo efectivo de promedio en cómputo anual"},{"ref":"Art. 73.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Las vacaciones anuales retribuidas serán de veintidós días hábiles por año completo de servicios"},{"ref":"Art. 73.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Quince años de servicios: Veintitrés días hábiles. Veinte años de servicios: Veinticuatro días hábiles."},{"ref":"Art. 74.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"su duración acumulada no podrá exceder de tres meses cada dos años."}]}]},{"n":"8","title":"Permisos (art. 75)","blocks":[{"text":"El art. 75 reconoce permisos retribuidos, entre ellos: quince días naturales por matrimonio; tres días hábiles por muerte, enfermedad grave u hospitalización de cónyuge, pareja o familiar de primer grado (cinco si es en distinta localidad) y dos días hábiles para el segundo grado (cuatro en distinta localidad); un día por traslado de domicilio en la misma localidad y dos en distinta; el tiempo indispensable para deberes inexcusables; y hasta seis días cada año natural por asuntos particulares, más dos adicionales al cumplir el sexto trienio. También los días 24 y 31 de diciembre. Ojo: estas cifras son de 2019 y difieren de las del art. 48 TREBEP en su redacción actual (por ejemplo, cinco y cuatro días hábiles por enfermedad grave de familiares); además, en nacimiento, adopción, progenitor distinto, lactancia y permiso parental el personal laboral se rige directamente por el TREBEP (art. 7 TREBEP). Comprueba la normativa vigente aplicable.","refs":[{"ref":"Art. 75 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"a) Quince días naturales en caso de matrimonio."},{"ref":"Art. 75 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"e) Un día por traslado del domicilio habitual dentro de una misma localidad y dos días en distinta localidad."},{"ref":"Art. 75 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"o) Hasta seis días cada año natural, por asuntos particulares no incluidos en los puntos anteriores."},{"ref":"Art. 7 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"en materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica, de lactancia y parental, el personal laboral al servicio de las Administraciones públicas se regirá por lo previsto en el presente Estatuto"}]}]},{"n":"9","title":"Suspensión del contrato, excedencias y reingreso (arts. 93-98)","blocks":[{"text":"La suspensión del contrato reserva el puesto y computa a efectos de antigüedad (art. 93); entre sus causas están nacimiento y adopción (remitidas al art. 49 TREBEP), riesgo durante el embarazo o la lactancia, incapacidad permanente revisable, nombramiento como funcionario en prácticas, suspensión provisional de empleo y privación de libertad sin condena firme. Para el personal fijo también suspenden el contrato el nombramiento como alto cargo o personal eventual y los servicios en organismos internacionales (art. 94).","refs":[{"ref":"Art. 93 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Los trabajadores y trabajadoras tendrán derecho a la suspensión de su contrato de trabajo, con reserva de su puesto de trabajo y cómputo del período a efectos de antigüedad"}]},{"text":"La excedencia voluntaria por interés particular exige al personal fijo al menos un año de antigüedad continuada e inmediatamente anterior; se pide con un mes de antelación, no se concede con un expediente disciplinario en curso y, una vez concedida, dura como mínimo cuatro meses y como máximo de forma indefinida; no computa a efectos de antigüedad (art. 95.1). La de cuidado de hijos o familiares dura hasta tres años, con reserva del puesto los dos primeros (art. 95.2). La de agrupación familiar no exige tiempo mínimo de servicios y la permanencia mínima es de dos años (art. 95.3). Hay además excedencias por incompatibilidad, por violencia de género (retribuciones íntegras los dos primeros meses), por violencia terrorista y forzosa (art. 95.4-7). El reingreso desde situaciones sin reserva de puesto se hace mediante el concurso abierto y permanente (art. 96.1).","refs":[{"ref":"Art. 95.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Podrá solicitarse por el personal laboral fijo la excedencia voluntaria por interés particular con, al menos, un año de antigüedad continuada e inmediatamente anterior a la fecha de la solicitud"},{"ref":"Art. 95.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Una vez concedida, la duración mínima de permanencia en la misma es de cuatro meses y su duración máxima será indefinida."},{"ref":"Art. 95.3 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Podrá concederse excedencia voluntaria por agrupación familiar sin el requisito de haber prestado un tiempo mínimo de servicios efectivos"},{"ref":"Art. 95.3 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"El tiempo mínimo de permanencia en dicha situación es de dos años y su duración máxima es indefinida."},{"ref":"Art. 96.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"El reingreso al servicio activo desde situaciones que no conlleven derecho a la reserva del puesto de trabajo se efectuará, en todo caso, mediante la participación en el concurso abierto y permanente."}]}]},{"n":"10","title":"Régimen disciplinario: faltas y sanciones (arts. 99-111)","blocks":[{"text":"La potestad disciplinaria se ejerce conforme al título VII del TREBEP (art. 99). Las faltas pueden ser muy graves, graves o leves (art. 101). Son muy graves, además de las del TREBEP, por ejemplo, la transgresión de la buena fe contractual, faltar sin justificar cinco o más días al mes o incumplir el horario más de diez veces al mes (art. 102); graves, faltar tres o cuatro días al mes o incumplir el horario entre seis y diez veces al mes con un mínimo de diez horas, o intervenir en un procedimiento con causa de abstención (art. 103); y leves, faltar uno o dos días al mes o incumplir el horario de tres a cinco veces al mes (art. 104).","refs":[{"ref":"Art. 102 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Son faltas muy graves, además de las establecidas en el texto refundido de la Ley del Estatuto Básico del Empleado Público, las siguientes:"},{"ref":"Art. 103 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"e) La falta de asistencia al trabajo sin causa justificada de tres o cuatro días en el período de un mes."},{"ref":"Art. 104 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"d) La falta de asistencia al trabajo sin causa justificada de uno o dos días al mes."}]},{"text":"Las sanciones son despido disciplinario, suspensión de empleo y sueldo, traslado forzoso, demérito y apercibimiento escrito; no existe la separación del servicio, propia de funcionarios (art. 105). Por faltas muy graves: despido (con inhabilitación para un nuevo contrato con funciones similares), suspensión de tres meses y un día a dos años, traslado forzoso o demérito de un año y un día a cinco años (art. 106); por graves, suspensión de tres días a tres meses o demérito de hasta un año (art. 107); por leves, suspensión de hasta dos días o apercibimiento escrito (art. 108). Sanciona la Subsecretaría las faltas muy graves y graves (art. 110.1), y si el despido de un fijo es improcedente procede la readmisión (art. 111).","refs":[{"ref":"Art. 105 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"a) Despido disciplinario. b) Suspensión de empleo y sueldo."},{"ref":"Art. 106 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"b) Suspensión de empleo y sueldo de tres meses y un día a dos años."},{"ref":"Art. 110.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Para las sanciones impuestas por faltas muy graves y graves, la persona titular de la Subsecretaría del Ministerio respectivo."}]}]},{"n":"11","title":"Prescripción, cancelación y procedimiento (arts. 112-123)","blocks":[{"text":"Las faltas muy graves prescriben a los tres años, las graves a los dos y las leves a los seis meses; las sanciones, a los tres años, dos años y un año, respectivamente (art. 112), igual que en el TREBEP. Las sanciones se anotan en el Registro Central de Personal y se cancelan a los tres meses (leves), al año (graves) y a los dos años (muy graves) desde su cumplimiento (art. 114). Las faltas graves y muy graves exigen procedimiento con audiencia; las leves, procedimiento abreviado con audiencia (arts. 116 y 123). El procedimiento se inicia siempre de oficio (art. 119) y no puede durar más de seis meses desde la incoación: vencido ese plazo sin resolución notificada caduca, salvo paralización imputable al inculpado, pero la caducidad no implica la prescripción de la falta, de modo que puede abrirse un nuevo expediente si no ha prescrito (art. 117). La suspensión provisional de empleo, solo en faltas muy graves, no puede exceder de seis meses salvo paralización imputable al interesado (art. 120).","refs":[{"ref":"Art. 112.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses."},{"ref":"Art. 117.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"La duración del procedimiento disciplinario no excederá de seis meses, a contar desde su incoación. Vencido este plazo sin que se haya dictado y notificado la resolución se producirá su caducidad."},{"ref":"Art. 117.3 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"La declaración de caducidad que, en su caso, se dicte no implica la prescripción de la falta cometida"},{"ref":"Art. 120.2 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"La suspensión provisional no podrá exceder de seis meses, salvo en caso de paralización del procedimiento imputable a la persona interesada."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Ámbito: AGE y organismos autónomos, más CSN, AEPD, Justicia no transferida, Seguridad Social, Reina Sofía y TPFE; excluido el personal en el exterior.","refs":[{"ref":"Art. 2 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"a) El personal laboral que presta servicios en el exterior."}]},{"text":"Grupos: M3, M2, M1 (niveles MECES), E2 (Bachiller o Técnico), E1 (ESO o Profesional Básico), E0 (sin titulación).","refs":[{"ref":"Art. 8.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"f) Grupo profesional E0: Sin titulación prevista en el sistema educativo."}]},{"text":"Período de prueba: 3 meses M3 y M2, 1 mes los demás, 15 días laborables sin titulación.","refs":[{"ref":"Art. 32.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"excepto para el personal sin titulación, para el que será de quince días laborables."}]},{"text":"Concurso abierto y permanente: sistema ordinario; dos años en el último destino definitivo para participar.","refs":[{"ref":"Art. 35.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"El concurso abierto y permanente de carácter interdepartamental es el procedimiento ordinario de provisión de puestos de trabajo mediante movilidad del personal laboral fijo"}]},{"text":"Grupo superior: máximo 8 meses en 2 años; grupo inferior: máximo 1 mes al año con retribución de origen.","refs":[{"ref":"Art. 48.4 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"no podrá ser superior a ocho meses de duración en el plazo de dos años"}]},{"text":"Vacaciones: 22 días hábiles, 24 con veinte años de servicios; asuntos particulares: hasta seis días al año.","refs":[{"ref":"Art. 73.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"Veinte años de servicios: Veinticuatro días hábiles."}]},{"text":"Excedencia por interés particular: un año de antigüedad, mínimo cuatro meses; por agrupación familiar: sin servicios mínimos y mínimo dos años.","refs":[{"ref":"Art. 95.1 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"la duración mínima de permanencia en la misma es de cuatro meses"}]},{"text":"Sanciones: despido, suspensión de empleo y sueldo, traslado forzoso, demérito y apercibimiento; no hay separación del servicio.","refs":[{"ref":"Art. 105 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"e) Apercibimiento escrito."}]},{"text":"Procedimiento: máximo seis meses; la caducidad no supone la prescripción de la falta.","refs":[{"ref":"Art. 117.3 IV Convenio único","law":"IV Convenio único AGE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414","quote":"si el plazo exigido para ello no hubiera prescrito la falta se podrá iniciar un nuevo expediente sancionador."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-7414', null, null, null, null
  from public.topics t where t.slug = 'age-adm-48-convenio-unico'
