insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Concepto y clases de personal laboral (art. 11 TREBEP)"},{"n":"2","title":"Normativa aplicable al personal laboral (arts. 7 y 92 TREBEP)"},{"n":"3","title":"Funciones reservadas a funcionarios y puestos de personal laboral (arts. 9.2 y 11.2 TREBEP)"},{"n":"4","title":"Selección: principios, acceso de extranjeros y sistemas selectivos (arts. 11.3, 55, 57.4 y 61.7 TREBEP)"},{"n":"4.1","title":"Selección del personal laboral en la AGE (arts. 28-35 RD 364/1995)"},{"n":"5","title":"Derechos: retribuciones, carrera y promoción, negociación colectiva y provisión (arts. 19, 27, 32 y 83 TREBEP)"},{"n":"6","title":"Deberes y código de conducta (arts. 52-54 TREBEP)"},{"n":"7","title":"Régimen disciplinario del personal laboral (arts. 93 y 96 TREBEP)"},{"n":"8","title":"Incompatibilidades del personal laboral (arts. 2 y 3 Ley 53/1984)"},{"n":"9","title":"Control de la temporalidad (DA 17.ª TREBEP)"}]'::jsonb, '["Art. 11.1 TREBEP: «1. Es personal laboral el que en virtud de contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de contratación de personal previstas en la legislación laboral, presta servicios retribuidos por las Administraciones Públicas. En función de la duración del contrato éste podrá ser fijo, por tiempo indefinido o temporal.»","Art. 7 TREBEP: «El personal laboral al servicio de las Administraciones públicas se rige, además de por la legislación laboral y por las demás normas convencionalmente aplicables, por los preceptos de este Estatuto que así lo dispongan.»","Art. 9.2 TREBEP: «2. En todo caso, el ejercicio de las funciones que impliquen la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales del Estado y de las Administraciones Públicas corresponden exclusivamente a los funcionarios públicos, en los términos que en la ley de desarrollo de cada Administración Pública se establezca.»","Art. 11.3 TREBEP: «3. Los procedimientos de selección del personal laboral serán públicos, rigiéndose en todo caso por los principios de igualdad, mérito y capacidad. En el caso del personal laboral temporal se regirá igualmente por el principio de celeridad, teniendo por finalidad atender razones expresamente justificadas de necesidad y urgencia.»","Art. 57.4 TREBEP: «4. Los extranjeros a los que se refieren los apartados anteriores, así como los extranjeros con residencia legal en España podrán acceder a las Administraciones Públicas, como personal laboral, en igualdad de condiciones que los españoles.»","Art. 61.7 TREBEP: «7. Los sistemas selectivos de personal laboral fijo serán los de oposición, concurso-oposición, con las características establecidas en el apartado anterior, o concurso de valoración de méritos.»","Art. 30 RD 364/1995: «Los órganos de selección se constituirán en cada convocatoria y deberán estar formados por un número impar de miembros, uno de los cuales, al menos, será designado a propuesta de la representación de los trabajadores.»","Art. 33.2 RD 364/1995: «2. Transcurrido el período de prueba que se determine en cada convocatoria, el personal que lo supere satisfactoriamente adquirirá la condición de personal laboral fijo.»","Art. 27 TREBEP: «Las retribuciones del personal laboral se determinarán de acuerdo con la legislación laboral, el convenio colectivo que sea aplicable y el contrato de trabajo, respetando en todo caso lo establecido en el artículo 21 del presente Estatuto.»","Art. 32.1 TREBEP: «1. La negociación colectiva, representación y participación de los empleados públicos con contrato laboral se regirá por la legislación laboral, sin perjuicio de los preceptos de este capítulo que expresamente les son de aplicación.»","Art. 83 TREBEP: «La provisión de puestos y movilidad del personal laboral se realizará de conformidad con lo que establezcan los convenios colectivos que sean de aplicación y, en su defecto por el sistema de provisión de puestos y movilidad del personal funcionario de carrera.»","Art. 92 TREBEP: «El personal laboral se regirá por el Estatuto de los Trabajadores y por los Convenios Colectivos que les sean de aplicación.»","Art. 93.4 TREBEP: «4. El régimen disciplinario del personal laboral se regirá, en lo no previsto en el presente título, por la legislación laboral.»","Art. 96.2 TREBEP: «2. Procederá la readmisión del personal laboral fijo cuando sea declarado improcedente el despido acordado como consecuencia de la incoación de un expediente disciplinario por la comisión de una falta muy grave.»","Art. 2.2 Ley 53/1984: «2. En el ámbito delimitado en el apartado anterior se entenderá incluido todo el personal, cualquiera que sea la naturaleza jurídica de la relación de empleo.»","DA 17.ª.5 TREBEP: «5. En el caso del personal laboral temporal, el incumplimiento de los plazos máximos de permanencia dará derecho a percibir la compensación económica prevista en este apartado, sin perjuicio de la indemnización que pudiera corresponder por vulneración de la normativa laboral específica.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Concepto y clases de personal laboral (art. 11.1 TREBEP)","blocks":[{"text":"El TREBEP define al personal laboral como el que presta servicios retribuidos para las Administraciones Públicas en virtud de un contrato de trabajo formalizado por escrito, en cualquiera de las modalidades previstas en la legislación laboral (art. 11.1). Lo que lo distingue del funcionario es el vínculo: el funcionario de carrera está unido a la Administración por una relación estatutaria regulada por el Derecho Administrativo, nacida de un nombramiento legal (art. 9.1), mientras que el laboral lo está por un contrato. Según la duración del contrato, el personal laboral puede ser fijo, por tiempo indefinido o temporal.","refs":[{"ref":"Art. 11.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Es personal laboral el que en virtud de contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de contratación de personal previstas en la legislación laboral, presta servicios retribuidos por las Administraciones Públicas. En función de la duración del contrato éste podrá ser fijo, por tiempo indefinido o temporal."},{"ref":"Art. 9.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Son funcionarios de carrera quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo"}]}]},{"n":"2","title":"Normativa aplicable al personal laboral (arts. 7, 51 y 92 TREBEP)","blocks":[{"text":"El régimen jurídico del personal laboral es mixto. Se rige por la legislación laboral, por las normas convencionales aplicables (convenios colectivos) y por los preceptos del TREBEP que así lo dispongan (art. 7). Hay una excepción importante: en materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica, de lactancia y parental, se aplica lo previsto en el propio Estatuto, y no las suspensiones del contrato del Estatuto de los Trabajadores para esos mismos supuestos. En jornada, permisos y vacaciones se aplica el capítulo correspondiente del TREBEP y la legislación laboral (art. 51).","refs":[{"ref":"Art. 7 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El personal laboral al servicio de las Administraciones públicas se rige, además de por la legislación laboral y por las demás normas convencionalmente aplicables, por los preceptos de este Estatuto que así lo dispongan."},{"ref":"Art. 7 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"en materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica, de lactancia y parental, el personal laboral al servicio de las Administraciones públicas se regirá por lo previsto en el presente Estatuto"},{"ref":"Art. 51 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Para el régimen de jornada de trabajo, permisos y vacaciones del personal laboral se estará a lo establecido en este capítulo y en la legislación laboral correspondiente."}]},{"text":"En cuanto a las situaciones (excedencias, suspensiones, etc.), el personal laboral se rige por el Estatuto de los Trabajadores y por los convenios colectivos aplicables, aunque estos pueden extenderle el régimen de situaciones de los funcionarios en lo que sea compatible con el Estatuto de los Trabajadores (art. 92). En la AGE, el convenio de referencia es el IV Convenio colectivo único, que se estudia en el tema A48C.","refs":[{"ref":"Art. 92 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El personal laboral se regirá por el Estatuto de los Trabajadores y por los Convenios Colectivos que les sean de aplicación."},{"ref":"Art. 92 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los convenios colectivos podrán determinar la aplicación de este capítulo al personal incluido en su ámbito de aplicación en lo que resulte compatible con el Estatuto de los Trabajadores."}]}]},{"n":"3","title":"Funciones reservadas a funcionarios y puestos de personal laboral (arts. 9.2 y 11.2 TREBEP)","blocks":[{"text":"No cualquier puesto puede ocuparlo un trabajador laboral. Las funciones que impliquen participación directa o indirecta en el ejercicio de potestades públicas o en la salvaguardia de los intereses generales del Estado y de las Administraciones corresponden exclusivamente a funcionarios, en los términos de la ley de desarrollo de cada Administración (art. 9.2). Por eso, las leyes de función pública deben fijar los criterios para determinar qué puestos puede desempeñar el personal laboral, respetando siempre esa reserva (art. 11.2).","refs":[{"ref":"Art. 9.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"el ejercicio de las funciones que impliquen la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales del Estado y de las Administraciones Públicas corresponden exclusivamente a los funcionarios públicos"},{"ref":"Art. 11.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las leyes de Función Pública que se dicten en desarrollo de este Estatuto establecerán los criterios para la determinación de los puestos de trabajo que pueden ser desempeñados por personal laboral, respetando en todo caso lo establecido en el artículo 9.2."}]}]},{"n":"4","title":"Selección: principios, acceso de extranjeros y sistemas selectivos (arts. 11.3, 55, 57.4 y 61.7 TREBEP)","blocks":[{"text":"Los procedimientos de selección del personal laboral son públicos y se rigen por los principios de igualdad, mérito y capacidad; para el personal temporal se añade el principio de celeridad, pues su finalidad es atender razones expresamente justificadas de necesidad y urgencia (art. 11.3). Como al resto del personal, se le aplican los principios del art. 55.2: publicidad de convocatorias y bases, transparencia, imparcialidad y profesionalidad de los órganos de selección, independencia y discrecionalidad técnica, y adecuación de las pruebas a las funciones.","refs":[{"ref":"Art. 11.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los procedimientos de selección del personal laboral serán públicos, rigiéndose en todo caso por los principios de igualdad, mérito y capacidad. En el caso del personal laboral temporal se regirá igualmente por el principio de celeridad, teniendo por finalidad atender razones expresamente justificadas de necesidad y urgencia."},{"ref":"Art. 55.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"seleccionarán a su personal funcionario y laboral mediante procedimientos en los que se garanticen los principios constitucionales antes expresados"}]},{"text":"En cuanto a la nacionalidad, los nacionales de la UE acceden como funcionarios salvo a empleos que impliquen ejercicio de poder público (art. 57.1); pero como personal laboral pueden acceder en igualdad de condiciones que los españoles tanto ellos y sus familiares como cualquier extranjero con residencia legal en España (art. 57.4). Así, un nacional de un país de fuera de la UE con residencia legal puede presentarse a plazas laborales, no a plazas de funcionario. Los sistemas selectivos de personal laboral fijo son la oposición, el concurso-oposición o el concurso de valoración de méritos (art. 61.7); los funcionarios de carrera, en cambio, solo por oposición o concurso-oposición (art. 61.6).","refs":[{"ref":"Art. 57.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los extranjeros a los que se refieren los apartados anteriores, así como los extranjeros con residencia legal en España podrán acceder a las Administraciones Públicas, como personal laboral, en igualdad de condiciones que los españoles."},{"ref":"Art. 61.7 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los sistemas selectivos de personal laboral fijo serán los de oposición, concurso-oposición, con las características establecidas en el apartado anterior, o concurso de valoración de méritos."}]}]},{"n":"5","title":"Selección del personal laboral en la AGE (arts. 28-35 RD 364/1995)","blocks":[{"text":"El Reglamento General de Ingreso (RD 364/1995) concreta el procedimiento en la AGE. Los Departamentos ministeriales convocan los procesos selectivos de personal laboral fijo de nuevo ingreso para las vacantes adscritas a ellos, previo informe favorable de la Dirección General de la Función Pública y de acuerdo con la oferta de empleo público (art. 28.1). La promoción interna y la cobertura de vacantes por personal que no es de nuevo ingreso se rigen por los convenios (art. 28.2). En el BOE se anuncian al menos el número de plazas por categorías y dónde están expuestas las bases, y los sistemas son oposición, concurso-oposición y concurso (art. 29).","refs":[{"ref":"Art. 28.1 RD 364/1995","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Los Departamentos ministeriales convocarán, previo informe favorable de la Dirección General de la Función Pública, los procesos selectivos para el acceso a las plazas vacantes adscritas a los mismos que deban cubrirse con personal laboral fijo de nuevo ingreso, de acuerdo con lo previsto en la oferta de empleo público."},{"ref":"Art. 29 RD 364/1995","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Los sistemas selectivos serán la oposición, el concurso-oposición y el concurso."}]},{"text":"Los órganos de selección se constituyen en cada convocatoria, con número impar de miembros y al menos uno designado a propuesta de la representación de los trabajadores (art. 30). En el plazo máximo de un mes desde que termina el plazo de instancias se publica en el BOE la fecha, lugar y hora de las pruebas y dónde están las listas de admitidos (art. 31.2). La propuesta de candidatos no puede exceder del número de plazas convocadas, bajo sanción de nulidad de pleno derecho (art. 32). Tras formalizar el contrato, el aspirante adquiere la condición de personal laboral fijo cuando supera satisfactoriamente el período de prueba fijado en la convocatoria (art. 33.2). Los Departamentos pueden contratar personal laboral no permanente para trabajos que no pueda atender el personal fijo, conforme a mérito y capacidad (art. 35.1). Algunas denominaciones ministeriales de este Reglamento están desactualizadas.","refs":[{"ref":"Art. 30 RD 364/1995","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Los órganos de selección se constituirán en cada convocatoria y deberán estar formados por un número impar de miembros, uno de los cuales, al menos, será designado a propuesta de la representación de los trabajadores."},{"ref":"Art. 31.2 RD 364/1995","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"En el plazo máximo de un mes, a partir de la fecha de terminación del plazo previsto en cada convocatoria para la presentación de instancias, se publicará en el «Boletín Oficial del Estado» la fecha, lugar y hora de realización de las pruebas"},{"ref":"Art. 33.2 RD 364/1995","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"Transcurrido el período de prueba que se determine en cada convocatoria, el personal que lo supere satisfactoriamente adquirirá la condición de personal laboral fijo."}]}]},{"n":"6","title":"Derechos: retribuciones, carrera y promoción, negociación colectiva y provisión (arts. 19, 27, 32 y 83 TREBEP)","blocks":[{"text":"El personal laboral tiene derecho a la promoción profesional, que junto con la carrera se hace efectiva mediante los procedimientos del Estatuto de los Trabajadores o de los convenios colectivos (art. 19). Sus retribuciones se fijan conforme a la legislación laboral, el convenio aplicable y el contrato, respetando siempre el art. 21 TREBEP, que sujeta los incrementos de la masa salarial a la Ley de Presupuestos (art. 27).","refs":[{"ref":"Art. 19.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La carrera profesional y la promoción del personal laboral se hará efectiva a través de los procedimientos previstos en el Estatuto de los Trabajadores o en los convenios colectivos."},{"ref":"Art. 27 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Las retribuciones del personal laboral se determinarán de acuerdo con la legislación laboral, el convenio colectivo que sea aplicable y el contrato de trabajo, respetando en todo caso lo establecido en el artículo 21 del presente Estatuto."},{"ref":"Art. 21.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"así como el incremento de la masa salarial del personal laboral, deberán reflejarse para cada ejercicio presupuestario en la correspondiente ley de presupuestos."}]},{"text":"La negociación colectiva, representación y participación del personal laboral se rigen por la legislación laboral, salvo los preceptos del TREBEP que les sean expresamente aplicables (art. 32.1). Se garantiza el cumplimiento de los convenios firmados, salvo que, excepcionalmente y por causa grave de interés público derivada de una alteración sustancial de las circunstancias económicas, los órganos de gobierno los suspendan o modifiquen en la medida estrictamente necesaria, informando a los sindicatos (art. 32.2). La provisión de puestos y la movilidad se rigen por los convenios y, en su defecto, por el sistema de los funcionarios de carrera (art. 83).","refs":[{"ref":"Art. 32.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"salvo cuando excepcionalmente y por causa grave de interés público derivada de una alteración sustancial de las circunstancias económicas, los órganos de gobierno de las Administraciones Públicas suspendan o modifiquen el cumplimiento de convenios colectivos o acuerdos ya firmados en la medida estrictamente necesaria para salvaguardar el interés público."},{"ref":"Art. 83 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La provisión de puestos y movilidad del personal laboral se realizará de conformidad con lo que establezcan los convenios colectivos que sean de aplicación y, en su defecto por el sistema de provisión de puestos y movilidad del personal funcionario de carrera."}]}]},{"n":"7","title":"Deberes y código de conducta (arts. 52-54 TREBEP)","blocks":[{"text":"El código de conducta se aplica a todos los empleados públicos, también a los laborales. Deben desempeñar con diligencia sus tareas y velar por los intereses generales con sujeción a la Constitución y al ordenamiento, conforme a los principios de objetividad, integridad, neutralidad, responsabilidad, imparcialidad, confidencialidad, dedicación al servicio público, transparencia, ejemplaridad, austeridad, accesibilidad, eficacia, honradez, promoción del entorno cultural y medioambiental y respeto a la igualdad entre mujeres y hombres (art. 52). Estos principios informan la interpretación del régimen disciplinario.","refs":[{"ref":"Art. 52 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"objetividad, integridad, neutralidad, responsabilidad, imparcialidad, confidencialidad, dedicación al servicio público, transparencia, ejemplaridad, austeridad, accesibilidad, eficacia, honradez, promoción del entorno cultural y medioambiental, y respeto a la igualdad entre mujeres y hombres"},{"ref":"Art. 52 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los principios y reglas establecidos en este capítulo informarán la interpretación y aplicación del régimen disciplinario de los empleados públicos."}]},{"text":"Entre los principios éticos (art. 53) destacan abstenerse en asuntos con interés personal y no aceptar tratos de favor; entre los de conducta (art. 54), tratar con respeto a ciudadanos y compañeros, cumplir jornada y horario, obedecer las órdenes salvo infracción manifiesta del ordenamiento, administrar los recursos con austeridad y rechazar regalos que vayan más allá de los usos habituales, sociales y de cortesía.","refs":[{"ref":"Art. 53.5 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Se abstendrán en aquellos asuntos en los que tengan un interés personal"},{"ref":"Art. 54.6 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Se rechazará cualquier regalo, favor o servicio en condiciones ventajosas que vaya más allá de los usos habituales, sociales y de cortesía, sin perjuicio de lo establecido en el Código Penal."}]}]},{"n":"8","title":"Régimen disciplinario del personal laboral (arts. 93-96 TREBEP)","blocks":[{"text":"El personal laboral está sujeto al régimen disciplinario del Título VII del TREBEP y, en lo no previsto, a la legislación laboral (art. 93.1 y 93.4). Para él, el principio de tipicidad se cumple mediante la predeterminación normativa o los convenios colectivos (art. 94.2.a), que también pueden tipificar faltas muy graves y graves (art. 95.2.p y 95.3). La sanción máxima es el despido disciplinario, que solo cabe por faltas muy graves e inhabilita para ser titular de un nuevo contrato con funciones similares (art. 96.1.b); la suspensión es de empleo y sueldo, con un máximo de 6 años (art. 96.1.c).","refs":[{"ref":"Art. 93.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El régimen disciplinario del personal laboral se regirá, en lo no previsto en el presente título, por la legislación laboral."},{"ref":"Art. 96.1.b) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"b) Despido disciplinario del personal laboral, que sólo podrá sancionar la comisión de faltas muy graves y comportará la inhabilitación para ser titular de un nuevo contrato de trabajo con funciones similares a las que desempeñaban."}]},{"text":"Una regla propia del empleo público: si se declara improcedente el despido de un trabajador laboral fijo acordado tras un expediente disciplinario por falta muy grave, procede su readmisión (art. 96.2).","refs":[{"ref":"Art. 96.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Procederá la readmisión del personal laboral fijo cuando sea declarado improcedente el despido acordado como consecuencia de la incoación de un expediente disciplinario por la comisión de una falta muy grave."}]}]},{"n":"9","title":"Incompatibilidades del personal laboral (arts. 2 y 3 Ley 53/1984)","blocks":[{"text":"La Ley 53/1984 se aplica a todo el personal incluido en su ámbito, cualquiera que sea la naturaleza jurídica de su relación de empleo, de modo que alcanza plenamente al personal laboral (art. 2.2). Por tanto, también necesita autorización de compatibilidad para un segundo puesto público y reconocimiento previo para actividades privadas. Cuando el Consejo de Ministros, por razón de interés público y mediante real decreto, determina un supuesto de compatibilidad para un segundo puesto, esa actividad solo puede prestarse en régimen laboral, a tiempo parcial y con duración determinada (art. 3.1). Además, en el ámbito laboral es compatible la pensión de jubilación parcial con un puesto a tiempo parcial (art. 3.2).","refs":[{"ref":"Art. 2.2 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"En el ámbito delimitado en el apartado anterior se entenderá incluido todo el personal, cualquiera que sea la naturaleza jurídica de la relación de empleo."},{"ref":"Art. 3.1 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"en este último supuesto la actividad sólo podrá prestarse en régimen laboral, a tiempo parcial y con duración determinada, en las condiciones establecidas por la legislación laboral."},{"ref":"Art. 3.2 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"Por excepción, en el ámbito laboral, será compatible la pensión de jubilación parcial con un puesto de trabajo a tiempo parcial."}]}]},{"n":"10","title":"Control de la temporalidad (DA 17.ª TREBEP)","blocks":[{"text":"Las Administraciones deben evitar irregularidades en la contratación laboral temporal y en los nombramientos de interinos, y las actuaciones irregulares generan responsabilidades (DA 17.ª.1 y 2). Es nulo de pleno derecho todo acto, pacto o disposición que suponga incumplir los plazos máximos de permanencia como personal temporal (DA 17.ª.3). Si se incumplen, el laboral temporal tiene derecho a una compensación económica equivalente a la diferencia entre un máximo de veinte días de salario fijo por año de servicio (con tope de doce mensualidades) y la indemnización por extinción del contrato, sin perjuicio de otra indemnización por vulneración de la normativa laboral. No hay compensación si el contrato termina por despido disciplinario procedente o por renuncia voluntaria (DA 17.ª.5).","refs":[{"ref":"DA 17.ª.3 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"cuyo contenido directa o indirectamente suponga el incumplimiento por parte de la Administración de los plazos máximos de permanencia como personal temporal será nulo de pleno derecho."},{"ref":"DA 17.ª.5 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"En el caso del personal laboral temporal, el incumplimiento de los plazos máximos de permanencia dará derecho a percibir la compensación económica prevista en este apartado, sin perjuicio de la indemnización que pudiera corresponder por vulneración de la normativa laboral específica."},{"ref":"DA 17.ª.5 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"No habrá derecho a la compensación descrita en caso de que la finalización de la relación de servicio sea por despido disciplinario declarado procedente o por renuncia voluntaria."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Personal laboral: contrato escrito; puede ser fijo, por tiempo indefinido o temporal.","refs":[{"ref":"Art. 11.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"En función de la duración del contrato éste podrá ser fijo, por tiempo indefinido o temporal."}]},{"text":"Permisos de nacimiento, adopción, progenitor distinto, lactancia y parental del laboral: se rigen por el TREBEP, no por el Estatuto de los Trabajadores.","refs":[{"ref":"Art. 7 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"no siendo de aplicación a este personal, por tanto, las previsiones del texto refundido de la Ley del Estatuto de los Trabajadores sobre las suspensiones de los contratos de trabajo"}]},{"text":"Potestades públicas e intereses generales: reservados a funcionarios.","refs":[{"ref":"Art. 9.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"corresponden exclusivamente a los funcionarios públicos"}]},{"text":"Extranjeros con residencia legal: acceso como personal laboral en igualdad con los españoles.","refs":[{"ref":"Art. 57.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"como personal laboral, en igualdad de condiciones que los españoles."}]},{"text":"Laboral fijo: oposición, concurso-oposición o concurso de valoración de méritos.","refs":[{"ref":"Art. 61.7 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"o concurso de valoración de méritos."}]},{"text":"AGE: convoca el Departamento con informe favorable de la Dirección General de la Función Pública; tribunal impar con un miembro propuesto por los trabajadores; fijeza tras superar el período de prueba.","refs":[{"ref":"Art. 30 RD 364/1995","law":"RD 364/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729","quote":"uno de los cuales, al menos, será designado a propuesta de la representación de los trabajadores."}]},{"text":"Provisión y movilidad: convenio colectivo y, en su defecto, sistema de los funcionarios de carrera.","refs":[{"ref":"Art. 83 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"en su defecto por el sistema de provisión de puestos y movilidad del personal funcionario de carrera."}]},{"text":"Despido improcedente del laboral fijo tras expediente por falta muy grave: readmisión.","refs":[{"ref":"Art. 96.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Procederá la readmisión del personal laboral fijo"}]},{"text":"Incompatibilidades: la Ley 53/1984 se aplica cualquiera que sea la naturaleza de la relación de empleo.","refs":[{"ref":"Art. 2.2 Ley 53/1984","law":"Ley 53/1984","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-151","quote":"cualquiera que sea la naturaleza jurídica de la relación de empleo."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', null, null, null, 'Otras normas citadas: RD 364/1995 (https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729), Ley 53/1984 (https://www.boe.es/buscar/act.php?id=BOE-A-1985-151)'
  from public.topics t where t.slug = 'age-adm-48-personal-laboral'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto Legislativo 8/2015, de 30 de octubre, texto refundido de la Ley General de la Seguridad Social (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-49-seguridad-social', 'IV.9 La Seguridad Social del personal laboral: acción protectora y prestaciones') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-49-seguridad-social' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El personal laboral de las Administraciones públicas en el Régimen General (art. 136 LGSS)"},{"n":"2","title":"La acción protectora del sistema y del Régimen General (arts. 42 y 155 LGSS)"},{"n":"3","title":"Contingencias: accidente de trabajo, enfermedad profesional, accidente no laboral y enfermedad común (arts. 156-160 LGSS)"},{"n":"4","title":"Requisitos generales: afiliación, alta, situaciones asimiladas y carencia (arts. 165-166 LGSS)"},{"n":"5","title":"Incapacidad temporal (arts. 169-176 LGSS)"},{"n":"6","title":"Nacimiento y cuidado de menor, riesgo durante el embarazo y la lactancia natural (arts. 177-189 LGSS)"},{"n":"7","title":"Incapacidad permanente contributiva (arts. 193-200 LGSS)"},{"n":"8","title":"Jubilación contributiva (arts. 204-215 LGSS)"},{"n":"9","title":"Muerte y supervivencia (arts. 216-234 LGSS)"},{"n":"10","title":"Protección por desempleo: niveles contributivo y asistencial (arts. 262-280 LGSS)"}]'::jsonb, '["Art. 136.2.k) LGSS: «k) El personal civil no funcionario de las administraciones públicas y de las entidades y organismos vinculados o dependientes de ellas siempre que no estén incluidos en virtud de una ley especial en otro régimen obligatorio de previsión social.»","Art. 42.1 LGSS: «1. La acción protectora del sistema de la Seguridad Social comprenderá: a) La asistencia sanitaria en los casos de maternidad, de enfermedad común o profesional y de accidente, sea o no de trabajo. b) La recuperación profesional, cuya procedencia se aprecie en cualquiera de los casos que se mencionan en la letra anterior.»","Art. 155.1 LGSS: «1. La acción protectora del Régimen General será la establecida en el artículo 42, con excepción de la protección por cese de actividad y las prestaciones no contributivas.»","Art. 156.1 y 3 LGSS: «1. Se entiende por accidente de trabajo toda lesión corporal que el trabajador sufra con ocasión o por consecuencia del trabajo que ejecute por cuenta ajena. […] 3. Se presumirá, salvo prueba en contrario, que son constitutivas de accidente de trabajo las lesiones que sufra el trabajador durante el tiempo y en el lugar del trabajo.»","Art. 157 LGSS: «Se entenderá por enfermedad profesional la contraída a consecuencia del trabajo ejecutado por cuenta ajena en las actividades que se especifiquen en el cuadro que se apruebe por las disposiciones de aplicación y desarrollo de esta ley, y que esté provocada por la acción de los elementos o sustancias que en dicho cuadro se indiquen para cada enfermedad profesional.»","Art. 165.1 LGSS: «1. Para causar derecho a las prestaciones del Régimen General, las personas incluidas en su campo de aplicación habrán de cumplir, además de los requisitos particulares exigidos para acceder a cada una de ellas, el requisito general de estar afiliadas y en alta en dicho Régimen o en situación asimilada a la de alta al sobrevenir la contingencia o situación protegida, salvo disposición legal expresa en contrario.»","Art. 165.4 LGSS: «4. No se exigirán períodos previos de cotización para el derecho a las prestaciones derivadas de accidente, sea o no de trabajo, o de enfermedad profesional, salvo disposición legal expresa en contrario.»","Art. 169.1.a) LGSS: «a) Las debidas a enfermedad común o profesional y a accidente, sea o no de trabajo, mientras el trabajador reciba asistencia sanitaria de la Seguridad Social y esté impedido para el trabajo, con una duración máxima de trescientos sesenta y cinco días, prorrogables por otros 180 días cuando se presuma que durante ellos puede el trabajador ser dado de alta médica por curación.»","Art. 173.1 LGSS: «En caso de enfermedad común o de accidente no laboral, el subsidio se abonará a partir del cuarto día de baja en el trabajo, si bien desde el día cuarto al decimoquinto de baja, ambos inclusive, el subsidio estará a cargo del empresario.»","Art. 177 LGSS: «A efectos de la prestación por nacimiento y cuidado de menor prevista en esta sección, se consideran situaciones protegidas el nacimiento, la adopción, la guarda con fines de adopción y el acogimiento familiar»","Art. 186 LGSS: «La prestación correspondiente a la situación de riesgo durante el embarazo tendrá la naturaleza de prestación derivada de contingencias profesionales.»","DT 26.ª (art. 194.1 transitorio) LGSS: «1. La incapacidad permanente, cualquiera que sea su causa determinante, se clasificará con arreglo a los siguientes grados: a) Incapacidad permanente parcial para la profesión habitual. b) Incapacidad permanente total para la profesión habitual. c) Incapacidad permanente absoluta para todo trabajo. d) Gran incapacidad.»","Art. 205.1.b) LGSS: «b) Tener cubierto un período mínimo de cotización de quince años, de los cuales al menos dos deberán estar comprendidos dentro de los quince años inmediatamente anteriores al momento de causar el derecho.»","Art. 216.1 LGSS: «1. En caso de muerte, cualquiera que fuera su causa, cuando concurran los requisitos exigibles se reconocerán, según los supuestos, alguna o algunas de las prestaciones siguientes: a) Un auxilio por defunción. b) Una pensión vitalicia de viudedad. c) Una prestación temporal de viudedad. d) Una pensión de orfandad. e) Una pensión vitalicia o, en su caso, subsidio temporal en favor de familiares.»","Art. 263.1 LGSS: «1. La protección por desempleo se estructura en un nivel contributivo y en un nivel asistencial, ambos de carácter público y obligatorio.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El personal laboral de las Administraciones públicas en el Régimen General","blocks":[{"text":"A diferencia de los funcionarios civiles del Estado, que tienen su Régimen especial con MUFACE y Clases Pasivas, el personal laboral de las Administraciones públicas está protegido por el Régimen General de la Seguridad Social, regulado en el texto refundido de la Ley General de la Seguridad Social (LGSS, Real Decreto Legislativo 8/2015). En este Régimen están obligatoriamente incluidos los trabajadores por cuenta ajena y asimilados, salvo que su actividad los lleve a un régimen especial (art. 136.1 LGSS). La ley declara expresamente comprendido «el personal civil no funcionario de las administraciones públicas», siempre que una ley especial no lo incluya en otro régimen obligatorio de previsión social (art. 136.2.k).","refs":[{"ref":"Art. 136.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Estarán obligatoriamente incluidos en el campo de aplicación del Régimen General de la Seguridad Social los trabajadores por cuenta ajena y los asimilados a los que se refiere el artículo 7.1.a) de esta ley, salvo que por razón de su actividad deban quedar comprendidos en el campo de aplicación de algún régimen especial de la Seguridad Social."},{"ref":"Art. 136.2.k) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"k) El personal civil no funcionario de las administraciones públicas y de las entidades y organismos vinculados o dependientes de ellas siempre que no estén incluidos en virtud de una ley especial en otro régimen obligatorio de previsión social."}]},{"text":"El mismo artículo incluye también al personal funcionario que no esté en Clases Pasivas ni en otro régimen especial, y a los funcionarios de nuevo ingreso a que se refiere la disposición adicional tercera (art. 136.2.l y m), lo que conecta este tema con el de MUFACE.","refs":[{"ref":"Art. 136.2.l) y m) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"l)\tEl personal funcionario al servicio de las administraciones públicas y de las entidades y organismos vinculados o dependientes de ellas, incluido su periodo de prácticas, salvo que estén incluidos en el Régimen de Clases Pasivas del Estado o en otro régimen en virtud de una ley especial. m)\tEl personal funcionario a que se refiere la disposición adicional tercera, en los términos previstos en ella."}]}]},{"n":"2","title":"La acción protectora del sistema y del Régimen General","blocks":[{"text":"La acción protectora del sistema comprende la asistencia sanitaria por maternidad, enfermedad o accidente; la recuperación profesional; las prestaciones económicas por incapacidad temporal, nacimiento y cuidado de menor, riesgos durante el embarazo y la lactancia, incapacidad permanente, jubilación, desempleo, muerte y supervivencia o ingreso mínimo vital, entre otras; las prestaciones familiares; y los servicios sociales (art. 42.1). Como complemento pueden otorgarse los beneficios de la asistencia social (art. 42.2).","refs":[{"ref":"Art. 42.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"a) La asistencia sanitaria en los casos de maternidad, de enfermedad común o profesional y de accidente, sea o no de trabajo. b) La recuperación profesional, cuya procedencia se aprecie en cualquiera de los casos que se mencionan en la letra anterior."},{"ref":"Art. 42.2 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Igualmente, y como complemento de las prestaciones comprendidas en el apartado anterior, podrán otorgarse los beneficios de la asistencia social."}]},{"text":"El Régimen General tiene la misma acción protectora del artículo 42, con dos excepciones que conviene memorizar: la protección por cese de actividad (propia de los autónomos) y las prestaciones no contributivas (art. 155.1).","refs":[{"ref":"Art. 155.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"La acción protectora del Régimen General será la establecida en el artículo 42, con excepción de la protección por cese de actividad y las prestaciones no contributivas."}]}]},{"n":"3","title":"Contingencias: accidente de trabajo, enfermedad profesional, accidente no laboral y enfermedad común","blocks":[{"text":"Accidente de trabajo es toda lesión corporal que el trabajador sufra con ocasión o por consecuencia del trabajo por cuenta ajena (art. 156.1). Lo son también, entre otros, el accidente al ir o volver del trabajo (accidente «in itinere»), los sufridos en cargos electivos sindicales, en tareas distintas ordenadas por el empresario o en actos de salvamento (art. 156.2). Se presume, salvo prueba en contrario, que son accidente de trabajo las lesiones sufridas en tiempo y lugar de trabajo (art. 156.3).","refs":[{"ref":"Art. 156.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Se entiende por accidente de trabajo toda lesión corporal que el trabajador sufra con ocasión o por consecuencia del trabajo que ejecute por cuenta ajena."},{"ref":"Art. 156.2.a) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"a) Los que sufra el trabajador al ir o al volver del lugar de trabajo."},{"ref":"Art. 156.3 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Se presumirá, salvo prueba en contrario, que son constitutivas de accidente de trabajo las lesiones que sufra el trabajador durante el tiempo y en el lugar del trabajo."}]},{"text":"No son accidente de trabajo los debidos a fuerza mayor extraña al trabajo (sin que lo sean la insolación o el rayo) ni los debidos a dolo o imprudencia temeraria del trabajador (art. 156.4). En cambio, no impiden la calificación la imprudencia profesional derivada de la confianza en el trabajo habitual ni la culpa del empresario, un compañero o un tercero (art. 156.5).","refs":[{"ref":"Art. 156.4.b) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"b) Los que sean debidos a dolo o a imprudencia temeraria del trabajador accidentado."},{"ref":"Art. 156.5.a) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"a) La imprudencia profesional que sea consecuencia del ejercicio habitual de un trabajo y se derive de la confianza que este inspira."}]},{"text":"Enfermedad profesional es la contraída a consecuencia del trabajo por cuenta ajena en las actividades del cuadro reglamentario y provocada por los elementos o sustancias que ese cuadro indique (art. 157). Por exclusión, es accidente no laboral el que no sea de trabajo, y enfermedad común la alteración de la salud que no sea accidente de trabajo ni enfermedad profesional (art. 158).","refs":[{"ref":"Art. 157 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Se entenderá por enfermedad profesional la contraída a consecuencia del trabajo ejecutado por cuenta ajena en las actividades que se especifiquen en el cuadro que se apruebe por las disposiciones de aplicación y desarrollo de esta ley, y que esté provocada por la acción de los elementos o sustancias que en dicho cuadro se indiquen para cada enfermedad profesional."},{"ref":"Art. 158.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Se considerará accidente no laboral el que, conforme a lo establecido en el artículo 156, no tenga el carácter de accidente de trabajo."}]}]},{"n":"4","title":"Requisitos generales: afiliación, alta, situaciones asimiladas y carencia","blocks":[{"text":"Para causar derecho a cualquier prestación hay que cumplir, además de los requisitos propios de cada una, el requisito general de estar afiliado y en alta, o en situación asimilada al alta, al sobrevenir la contingencia (art. 165.1). Cuando se exige carencia, solo computan las cotizaciones efectivas o las asimiladas por ley (art. 165.2). No se exige carencia para las prestaciones derivadas de accidente, sea o no de trabajo, o de enfermedad profesional, salvo disposición en contrario (art. 165.4).","refs":[{"ref":"Art. 165.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Para causar derecho a las prestaciones del Régimen General, las personas incluidas en su campo de aplicación habrán de cumplir, además de los requisitos particulares exigidos para acceder a cada una de ellas, el requisito general de estar afiliadas y en alta en dicho Régimen o en situación asimilada a la de alta al sobrevenir la contingencia o situación protegida, salvo disposición legal expresa en contrario."},{"ref":"Art. 165.4 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"No se exigirán períodos previos de cotización para el derecho a las prestaciones derivadas de accidente, sea o no de trabajo, o de enfermedad profesional, salvo disposición legal expresa en contrario."}]},{"text":"Es situación asimilada al alta, entre otras, el desempleo total con percepción de prestación (art. 166.1). Además rige el alta de pleno derecho: los trabajadores se consideran en alta a efectos de accidentes de trabajo, enfermedades profesionales y desempleo aunque el empresario haya incumplido sus obligaciones (art. 166.4). Durante la huelga y el cierre patronal el trabajador está en alta especial (art. 166.7).","refs":[{"ref":"Art. 166.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"la situación legal de desempleo total durante la que el trabajador perciba prestación por dicha contingencia será asimilada a la de alta."},{"ref":"Art. 166.4 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Los trabajadores comprendidos en el campo de aplicación de este Régimen General se considerarán, de pleno derecho, en situación de alta a efectos de accidentes de trabajo, enfermedades profesionales y desempleo, aunque su empresario hubiera incumplido sus obligaciones."}]}]},{"n":"5","title":"Incapacidad temporal","blocks":[{"text":"Son situaciones de incapacidad temporal las debidas a enfermedad o accidente mientras el trabajador recibe asistencia sanitaria y está impedido para trabajar, con una duración máxima de 365 días prorrogables por otros 180 si se presume el alta por curación; y los periodos de observación por enfermedad profesional, de hasta 180 días prorrogables otros 180 (art. 169.1). Para la duración máxima se computan las recaídas, que existen si hay nueva baja por la misma o similar patología dentro de los 180 días naturales siguientes al alta (art. 169.2). La ley añade situaciones especiales por contingencias comunes, como la menstruación incapacitante secundaria o la gestación desde la semana trigésima novena.","refs":[{"ref":"Art. 169.1.a) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"a) Las debidas a enfermedad común o profesional y a accidente, sea o no de trabajo, mientras el trabajador reciba asistencia sanitaria de la Seguridad Social y esté impedido para el trabajo, con una duración máxima de trescientos sesenta y cinco días, prorrogables por otros 180 días cuando se presuma que durante ellos puede el trabajador ser dado de alta médica por curación."},{"ref":"Art. 169.1.b) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"b) Los períodos de observación por enfermedad profesional en los que se prescriba la baja en el trabajo durante los mismos, con una duración máxima de ciento ochenta días, prorrogables por otros ciento ochenta días cuando se estime necesario para el estudio y diagnóstico de la enfermedad."}]},{"text":"Agotados los 365 días, la inspección médica del INSS es la única competente para emitir el alta médica, y también una nueva baja por la misma patología en los 180 días siguientes (art. 170.2). Frente a esa alta cabe manifestar disconformidad ante la inspección del servicio público de salud en un máximo de cuatro días naturales (art. 170.3).","refs":[{"ref":"Art. 170.2 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Agotado el plazo de duración de trescientos sesenta y cinco días indicado en el apartado anterior, la inspección médica del Instituto Nacional de la Seguridad Social será la única competente para emitir el alta médica por curación, por mejoría que permita la reincorporación al trabajo, con propuesta de incapacidad permanente o por incomparecencia injustificada a los reconocimientos médicos convocados por dicha entidad gestora."},{"ref":"Art. 170.3 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"el interesado podrá manifestar, en el plazo máximo de cuatro días naturales, su disconformidad ante la inspección médica del servicio público de salud."}]},{"text":"La carencia es de 180 días cotizados en los cinco años anteriores si la causa es enfermedad común; no se exige en caso de accidente o enfermedad profesional (art. 172). En enfermedad común o accidente no laboral el subsidio se paga desde el cuarto día de baja, y del cuarto al decimoquinto lo paga el empresario; en accidente de trabajo o enfermedad profesional, desde el día siguiente a la baja (art. 173.1). En huelga o cierre patronal no hay prestación (art. 173.3).","refs":[{"ref":"Art. 172.a) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"a) En caso de enfermedad común, 180 días dentro de los cinco años inmediatamente anteriores al hecho causante."},{"ref":"Art. 173.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"En caso de enfermedad común o de accidente no laboral, el subsidio se abonará a partir del cuarto día de baja en el trabajo, si bien desde el día cuarto al decimoquinto de baja, ambos inclusive, el subsidio estará a cargo del empresario."}]},{"text":"El subsidio se extingue, entre otras causas, por el transcurso de 545 días naturales desde la baja, por alta médica, por jubilación o por fallecimiento (art. 174.1). Agotados los 545 días, el estado del trabajador se examina en un máximo de 90 días para calificar la incapacidad permanente; la calificación puede demorarse si conviene, sin rebasar nunca 730 días naturales sumando incapacidad temporal y prolongación de efectos (art. 174.2).","refs":[{"ref":"Art. 174.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"El derecho al subsidio se extinguirá por el transcurso del plazo máximo de quinientos cuarenta y cinco días naturales desde la baja médica"},{"ref":"Art. 174.2 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"sin que en ningún caso se puedan rebasar los setecientos treinta días naturales sumados los de incapacidad temporal y los de prolongación de sus efectos."}]}]},{"n":"6","title":"Nacimiento y cuidado de menor, riesgo durante el embarazo y la lactancia natural","blocks":[{"text":"Son situaciones protegidas por la prestación de nacimiento y cuidado de menor el nacimiento, la adopción, la guarda con fines de adopción y el acogimiento familiar, durante los descansos del Estatuto de los Trabajadores o del TREBEP (art. 177). La carencia depende de la edad: ninguna con menos de 21 años; 90 días en los siete años anteriores (o 180 en la vida laboral) entre 21 y 26; y 180 días en siete años (o 360 en la vida laboral) desde los 26 (art. 178.1). El subsidio es el 100 % de la base reguladora (art. 179.1).","refs":[{"ref":"Art. 177 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"se consideran situaciones protegidas el nacimiento, la adopción, la guarda con fines de adopción y el acogimiento familiar"},{"ref":"Art. 178.1.a) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Si la persona trabajadora tiene menos de veintiún años de edad en la fecha del nacimiento"},{"ref":"Art. 179.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"La prestación económica por nacimiento y cuidado de menor consistirá en un subsidio equivalente al 100 por ciento de la base reguladora correspondiente."}]},{"text":"El riesgo durante el embarazo protege la suspensión del contrato cuando la trabajadora debe cambiar a un puesto compatible y el cambio no es posible (art. 186). Esta prestación tiene naturaleza de contingencia profesional y consiste en el 100 % de la base reguladora de la incapacidad temporal por contingencias profesionales (arts. 186 y 187.3). El riesgo durante la lactancia natural se rige por las mismas reglas y se extingue cuando el hijo cumple nueve meses, salvo reincorporación anterior (art. 189).","refs":[{"ref":"Art. 186 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"La prestación correspondiente a la situación de riesgo durante el embarazo tendrá la naturaleza de prestación derivada de contingencias profesionales."},{"ref":"Art. 187.3 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"La prestación económica consistirá en un subsidio equivalente al 100 por cien de la base reguladora correspondiente."},{"ref":"Art. 189 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"se extinguirá en el momento en que el hijo cumpla nueve meses"}]}]},{"n":"7","title":"Incapacidad permanente contributiva","blocks":[{"text":"Es la situación de quien, tras el tratamiento prescrito, presenta reducciones anatómicas o funcionales graves, objetivables y previsiblemente definitivas que disminuyen o anulan su capacidad laboral (art. 193.1); como regla, deriva de una incapacidad temporal (art. 193.2). Mientras no se desarrolle el nuevo art. 194, se aplica la redacción transitoria de la DT 26.ª: grados de parcial para la profesión habitual (disminución no inferior al 33 % del rendimiento sin impedir las tareas fundamentales), total para la profesión habitual (inhabilita para todas o las fundamentales tareas, pudiendo dedicarse a otra), absoluta para todo trabajo y gran incapacidad (necesita asistencia de otra persona para los actos más esenciales).","refs":[{"ref":"Art. 193.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"La incapacidad permanente contributiva es la situación de la persona trabajadora que, después de haber estado sometida al tratamiento prescrito, presenta reducciones anatómicas o funcionales graves, susceptibles de determinación objetiva y previsiblemente definitivas, que disminuyan o anulen su capacidad laboral."},{"ref":"DT 26.ª LGSS (art. 194.4)","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Se entenderá por incapacidad permanente total para la profesión habitual la que inhabilite al trabajador para la realización de todas o de las fundamentales tareas de dicha profesión, siempre que pueda dedicarse a otra distinta."},{"ref":"DT 26.ª LGSS (art. 194.3)","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"ocasione al trabajador una disminución no inferior al 33 por ciento en su rendimiento normal para dicha profesión"}]},{"text":"Si deriva de accidente o enfermedad profesional no se exige carencia; para la parcial se exigen 1.800 días en los diez años anteriores (art. 195.1 y 195.2). La parcial da una cantidad a tanto alzado; la total y la absoluta, una pensión vitalicia; la gran incapacidad, pensión más un complemento para remunerar a quien atiende al inválido (art. 196).","refs":[{"ref":"Art. 195.2 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"En el caso de incapacidad permanente parcial, el período mínimo de cotización exigible será de mil ochocientos días"},{"ref":"Art. 196.1 y 196.3 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"La prestación económica correspondiente a la incapacidad permanente parcial, consistirá en una cantidad a tanto alzado. […] La prestación económica correspondiente a la incapacidad permanente absoluta consistirá en una pensión vitalicia."}]}]},{"n":"8","title":"Jubilación contributiva","blocks":[{"text":"La pensión de jubilación contributiva es única para cada beneficiario y vitalicia, y se reconoce cuando, alcanzada la edad, se cesa en el trabajo por cuenta ajena (art. 204). Requiere 67 años, o 65 si se acreditan 38 años y 6 meses cotizados (art. 205.1.a), edades que se aplican de forma gradual según la disposición transitoria séptima; y un periodo mínimo de 15 años cotizados, de los cuales al menos dos dentro de los 15 inmediatamente anteriores (art. 205.1.b). Puede causarse incluso sin estar en alta si se reúnen edad y cotización (art. 205.3).","refs":[{"ref":"Art. 204 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"La prestación económica por causa de jubilación, en su modalidad contributiva, será única para cada beneficiario y consistirá en una pensión vitalicia"},{"ref":"Art. 205.1.a) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"a) Haber cumplido sesenta y siete años de edad, o sesenta y cinco años cuando se acrediten treinta y ocho años y seis meses de cotización"},{"ref":"Art. 205.1.b) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"b) Tener cubierto un período mínimo de cotización de quince años, de los cuales al menos dos deberán estar comprendidos dentro de los quince años inmediatamente anteriores al momento de causar el derecho."},{"ref":"DT 7.ª LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Las edades de jubilación y el período de cotización a que se refiere el artículo 205.1.a)"}]}]},{"n":"9","title":"Muerte y supervivencia","blocks":[{"text":"En caso de muerte, cualquiera que sea su causa, pueden reconocerse un auxilio por defunción, una pensión vitalicia de viudedad, una prestación temporal de viudedad, una pensión de orfandad y una pensión o subsidio en favor de familiares; si la muerte se debe a accidente de trabajo o enfermedad profesional, además una indemnización a tanto alzado (art. 216). El auxilio por defunción cubre los gastos de sepelio de quien los haya soportado (art. 218).","refs":[{"ref":"Art. 216.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"a) Un auxilio por defunción. b) Una pensión vitalicia de viudedad. c) Una prestación temporal de viudedad. d) Una pensión de orfandad. e) Una pensión vitalicia o, en su caso, subsidio temporal en favor de familiares."},{"ref":"Art. 216.2 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"En caso de muerte causada por accidente de trabajo o enfermedad profesional se reconocerá, además, una indemnización a tanto alzado."}]},{"text":"Para la viudedad del cónyuge, si el causante estaba en alta, se exigen 500 días cotizados en los cinco años anteriores, salvo muerte por accidente o enfermedad profesional; sin alta, 15 años cotizados (art. 219.1). Si la muerte deriva de enfermedad común no sobrevenida tras el matrimonio, se exige además un año de matrimonio o hijos comunes (art. 219.2). La pensión de orfandad corresponde a los hijos menores de 21 años o incapacitados (art. 224.1), ampliable hasta 25 sin trabajo lucrativo o con ingresos inferiores al salario mínimo (art. 224.3).","refs":[{"ref":"Art. 219.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"hubiera completado un período de cotización de quinientos días, dentro de los cinco años inmediatamente anteriores a la fecha del hecho causante de la pensión."},{"ref":"Art. 224.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"siempre que, en el momento de la muerte, sean menores de veintiún años o estén incapacitados para el trabajo"}]}]},{"n":"10","title":"Protección por desempleo: niveles contributivo y asistencial","blocks":[{"text":"Se protege a quienes, pudiendo y queriendo trabajar, pierden su empleo o ven suspendido su contrato o reducida su jornada (art. 262.1). La protección tiene un nivel contributivo, que sustituye las rentas salariales perdidas, y un nivel asistencial complementario, ambos públicos y obligatorios (art. 263). Están protegidos, entre otros, los trabajadores por cuenta ajena del Régimen General y los funcionarios interinos y el personal eventual (art. 264.1).","refs":[{"ref":"Art. 263.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"La protección por desempleo se estructura en un nivel contributivo y en un nivel asistencial, ambos de carácter público y obligatorio."},{"ref":"Art. 264.1.d) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"d) Los funcionarios interinos, el personal eventual, así como el personal contratado en su momento en régimen de derecho administrativo al servicio de las administraciones públicas."}]},{"text":"La prestación contributiva exige alta, carencia dentro de los seis años anteriores, situación legal de desempleo con acuerdo de actividad, no tener la edad ordinaria de jubilación e inscripción como demandante (art. 266). La duración sigue una escala: de 360 a 539 días cotizados, 120 días de prestación, hasta 720 días con 2.160 o más cotizados (art. 269.1). Se cobra el 70 % de la base reguladora los primeros 180 días y el 60 % después (art. 270.2). El subsidio asistencial se dirige, entre otros, a quien agota la prestación o no reúne la carencia contributiva habiendo cotizado al menos tres meses (art. 274.1). Los topes ligados al IPREM varían cada año y no se recogen aquí.","refs":[{"ref":"Art. 269.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"| Desde 360 hasta 539 | 120 |"},{"ref":"Art. 270.2 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"el 70 por ciento durante los ciento ochenta primeros días y el 60 por ciento a partir del día ciento ochenta y uno."},{"ref":"Art. 274.1.b) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"b) Encontrarse en situación legal de desempleo sin tener cubierto el periodo mínimo de cotización para tener derecho a la prestación contributiva, siempre que hayan cotizado al menos tres meses."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Personal laboral de las Administraciones: Régimen General (art. 136.2.k).","refs":[{"ref":"Art. 136.2.k) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"El personal civil no funcionario de las administraciones públicas"}]},{"text":"El Régimen General no incluye cese de actividad ni prestaciones no contributivas.","refs":[{"ref":"Art. 155.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"con excepción de la protección por cese de actividad y las prestaciones no contributivas."}]},{"text":"Accidente in itinere: es accidente de trabajo; dolo o imprudencia temeraria lo excluyen.","refs":[{"ref":"Art. 156.2.a) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"Los que sufra el trabajador al ir o al volver del lugar de trabajo."}]},{"text":"Alta de pleno derecho: accidentes de trabajo, enfermedades profesionales y desempleo.","refs":[{"ref":"Art. 166.4 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"en situación de alta a efectos de accidentes de trabajo, enfermedades profesionales y desempleo"}]},{"text":"IT: 365 + 180 días; enfermedad común, 180 días cotizados en cinco años; subsidio desde el 4.º día, del 4.º al 15.º a cargo del empresario; tope de 730 días con demora de calificación.","refs":[{"ref":"Art. 174.2 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"los setecientos treinta días naturales"}]},{"text":"Nacimiento y cuidado de menor: 100 % de la base reguladora; riesgo en embarazo: contingencia profesional; lactancia: hasta los nueve meses.","refs":[{"ref":"Art. 179.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"un subsidio equivalente al 100 por ciento de la base reguladora correspondiente."}]},{"text":"Jubilación: 15 años cotizados, dos en los últimos quince.","refs":[{"ref":"Art. 205.1.b) LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"un período mínimo de cotización de quince años"}]},{"text":"Viudedad por enfermedad común: 500 días en los cinco años anteriores.","refs":[{"ref":"Art. 219.1 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"un período de cotización de quinientos días"}]},{"text":"Desempleo: escala desde 360 días cotizados (120 de prestación); 70 % y luego 60 %.","refs":[{"ref":"Art. 270.2 LGSS","law":"LGSS","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724","quote":"el 70 por ciento durante los ciento ochenta primeros días"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724', null, null, null, null
  from public.topics t where t.slug = 'age-adm-49-seguridad-social'
