insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El presupuesto: concepto y principios presupuestarios (art. 134 CE; arts. 26-27 y 32 LGP)"},{"n":"1.1","title":"Anualidad, universalidad, presupuesto bruto y especialidad (arts. 27, 34 y 42 LGP)"},{"n":"2","title":"Programación plurianual y ciclo presupuestario: escenarios, elaboración y prórroga (arts. 28-31 y 36-38 LGP)"},{"n":"3","title":"El presupuesto por programas: créditos y programas presupuestarios (art. 35 LGP)"},{"n":"4","title":"Estructura de los Presupuestos Generales del Estado: clasificaciones orgánica, por programas y económica (arts. 39-41 LGP)"},{"n":"5","title":"Los créditos presupuestarios: especialidad, especificación, limitación y temporalidad (arts. 42-49 LGP)"},{"n":"5.1","title":"Gastos plurianuales (art. 47 LGP)"},{"n":"5.2","title":"Fondo de Contingencia (art. 50 LGP)"},{"n":"6","title":"Modificaciones presupuestarias: transferencias, generaciones, ampliaciones, créditos extraordinarios y suplementos, e incorporaciones (arts. 51-59 LGP)"},{"n":"7","title":"Anticipos de Tesorería (art. 60 LGP)"},{"n":"8","title":"Competencias en materia de modificaciones de crédito (arts. 61-63 LGP)"}]'::jsonb, '["Art. 134.2 CE: «Los Presupuestos Generales del Estado tendrán carácter anual, incluirán la totalidad de los gastos e ingresos del sector público estatal y en ellos se consignará el importe de los beneficios fiscales que afecten a los tributos del Estado.»","Art. 27.4 Ley 47/2003: «Los derechos liquidados y las obligaciones reconocidas se aplicarán a los presupuestos por su importe íntegro, sin que puedan atenderse obligaciones mediante minoración de los derechos a liquidar o ya ingresados, salvo que la ley lo autorice de modo expreso.»","Art. 28.1 Ley 47/2003: «Los escenarios presupuestarios plurianuales determinarán los límites, referidos a los tres ejercicios siguientes, que la acción de gobierno debe respetar en los casos en que sus decisiones tengan incidencia presupuestaria.»","Art. 35.1 Ley 47/2003: «Son créditos presupuestarios cada una de las asignaciones individualizadas de gasto, que figuran en los presupuestos de los órganos y entidades a que se refiere el artículo 33.1.ª) de esta ley, puestas a disposición de los centros gestores para la cobertura de las necesidades para las que hayan sido aprobados.»","Art. 35.4 Ley 47/2003: «Constituye un programa de gasto del presupuesto anual el conjunto de créditos que, para el logro de los objetivos anuales que el mismo establezca, se ponen a disposición del gestor responsable de su ejecución.»","Art. 40.1 Ley 47/2003: «a) La clasificación orgánica que agrupará por secciones y servicios los créditos asignados a los distintos centros gestores de gasto»","Art. 42 Ley 47/2003: «Los créditos para gastos se destinarán exclusivamente a la finalidad específica para la que hayan sido autorizados por la Ley de Presupuestos o a la que resulte de las modificaciones aprobadas conforme a esta ley.»","Art. 43.1 Ley 47/2003: «En el presupuesto del Estado los créditos se especificarán a nivel de concepto, salvo los créditos destinados a gastos de personal y los gastos corrientes en bienes y servicios, que se especificarán a nivel de artículo y las inversiones reales a nivel de capítulo.»","Art. 47.2 Ley 47/2003: «El número de ejercicios a que pueden aplicarse los gastos no será superior a cuatro. El gasto que se impute a cada uno de los ejercicios posteriores no podrá exceder de la cantidad que resulte de aplicar al crédito inicial a que corresponda la operación los siguientes porcentajes: en el ejercicio inmediato siguiente, el 70 por ciento, en el segundo ejercicio, el 60 por ciento, y en los ejercicios tercero y cuarto, el 50 por ciento.»","Art. 49.2 Ley 47/2003: «Los créditos para gastos que en el último día del ejercicio presupuestario no estén afectados al cumplimiento de obligaciones ya reconocidas, quedarán anulados de pleno derecho, sin perjuicio de lo establecido en el artículo 58 de esta ley.»","Art. 51 Ley 47/2003: «La cuantía y finalidad de los créditos contenidos en los presupuestos de gastos sólo podrán ser modificadas durante el ejercicio, dentro de los límites y con arreglo al procedimiento establecido en los artículos siguientes, mediante: a) Transferencias. b) Generaciones. c) Ampliaciones. d) Créditos extraordinarios y suplementos de crédito. e) Incorporaciones.»","Art. 52.1 Ley 47/2003: «Las transferencias son traspasos de dotaciones entre créditos. Pueden realizarse entre los diferentes créditos del presupuesto incluso con la creación de créditos nuevos, con las siguientes restricciones: a) No podrán realizarse desde créditos para operaciones financieras al resto de los créditos, ni desde créditos para operaciones de capital a créditos para operaciones corrientes. b) No podrán realizarse entre créditos de distintas secciones presupuestarias.»","Art. 53.1 Ley 47/2003: «Las generaciones son modificaciones que incrementan los créditos como consecuencia de la realización de determinados ingresos no previstos o superiores a los contemplados en el presupuesto inicial.»","Art. 55.1 Ley 47/2003: «Cuando haya de realizarse con cargo al Presupuesto del Estado algún gasto que no pueda demorarse hasta el ejercicio siguiente, y no exista crédito adecuado o sea insuficiente y no ampliable el consignado y su dotación no resulte posible a través de las restantes figuras previstas en el artículo 51, deberá procederse a la tramitación de un crédito extraordinario o suplementario del inicialmente previsto.»","Art. 60.1 Ley 47/2003: «Con carácter excepcional, el Gobierno, a propuesta del Ministro de Economía, podrá conceder anticipos de Tesorería para atender gastos inaplazables, con el límite máximo en cada ejercicio del uno por ciento de los créditos autorizados al Estado por la Ley de Presupuestos Generales del Estado»","Art. 63.1 Ley 47/2003: «Los titulares de los distintos ministerios podrán autorizar, previo informe favorable de la Intervención Delegada competente en el ministerio o, en su caso, en las entidades a que se refiere el artículo 3.1 de esta ley, las siguientes modificaciones presupuestarias: a) Transferencias entre créditos de un mismo programa o entre programas de un mismo servicio»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El presupuesto: concepto y principios presupuestarios","blocks":[{"text":"La Constitución reparte los papeles: el Gobierno elabora los Presupuestos Generales del Estado y las Cortes Generales los examinan, enmiendan y aprueban (art. 134.1 CE). Los Presupuestos tienen carácter anual, incluyen la totalidad de los gastos e ingresos del sector público estatal y consignan el importe de los beneficios fiscales que afectan a los tributos del Estado (art. 134.2 CE). El Gobierno debe presentarlos al Congreso al menos tres meses antes de que expiren los del año anterior (art. 134.3 CE), y la Ley de Presupuestos no puede crear tributos (art. 134.7 CE).","refs":[{"ref":"Art. 134.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Corresponde al Gobierno la elaboración de los Presupuestos Generales del Estado y a las Cortes Generales, su examen, enmienda y aprobación."},{"ref":"Art. 134.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los Presupuestos Generales del Estado tendrán carácter anual, incluirán la totalidad de los gastos e ingresos del sector público estatal y en ellos se consignará el importe de los beneficios fiscales que afecten a los tributos del Estado."},{"ref":"Art. 134.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Gobierno deberá presentar ante el Congreso de los Diputados los Presupuestos Generales del Estado al menos tres meses antes de la expiración de los del año anterior."}]},{"text":"La Ley 47/2003, General Presupuestaria (LGP), define los Presupuestos Generales del Estado como la expresión cifrada, conjunta y sistemática de los derechos y obligaciones a liquidar durante el ejercicio por los órganos y entidades del sector público estatal (art. 32). La programación presupuestaria se rige por los principios de estabilidad presupuestaria, sostenibilidad financiera, plurianualidad, transparencia, eficiencia, responsabilidad y lealtad institucional (art. 26.1 LGP), y toda actuación que afecte al gasto debe supeditarse a las disponibilidades presupuestarias (art. 26.2).","refs":[{"ref":"Art. 32 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los Presupuestos Generales del Estado constituyen la expresión cifrada, conjunta y sistemática de los derechos y obligaciones a liquidar durante el ejercicio por cada uno de los órganos y entidades que forman parte del sector público estatal."},{"ref":"Art. 26.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La programación presupuestaria se regirá por los principios de estabilidad presupuestaria, sostenibilidad financiera, plurianualidad, transparencia, eficiencia en la asignación y utilización de los recursos públicos, responsabilidad y lealtad institucional"}]}]},{"n":"1.1","title":"Anualidad, universalidad, presupuesto bruto, no afectación y especialidad","blocks":[{"text":"Anualidad: la gestión se somete a un presupuesto anual aprobado por las Cortes y enmarcado en un escenario plurianual (art. 27.1), y el ejercicio coincide con el año natural; a él se imputan los derechos liquidados en el ejercicio y las obligaciones reconocidas hasta fin de diciembre por gastos realizados dentro del año (art. 34.1). No afectación: los recursos se destinan a satisfacer el conjunto de las obligaciones, salvo que una ley los afecte a fines concretos (art. 27.3). Presupuesto bruto: derechos y obligaciones se aplican por su importe íntegro, sin compensar obligaciones minorando derechos, salvo autorización legal expresa (art. 27.4).","refs":[{"ref":"Art. 27.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La gestión del sector público estatal está sometida al régimen de presupuesto anual aprobado por las Cortes Generales y enmarcado en los límites de un escenario plurianual."},{"ref":"Art. 34.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El ejercicio presupuestario coincidirá con el año natural"},{"ref":"Art. 27.4 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los derechos liquidados y las obligaciones reconocidas se aplicarán a los presupuestos por su importe íntegro, sin que puedan atenderse obligaciones mediante minoración de los derechos a liquidar o ya ingresados, salvo que la ley lo autorice de modo expreso."}]},{"text":"Especialidad: los créditos solo pueden destinarse a la finalidad específica para la que fueron autorizados por la Ley de Presupuestos o por sus modificaciones legales, y su carácter limitativo y vinculante es el de su nivel de especificación (arts. 27.2 y 42 LGP).","refs":[{"ref":"Art. 42 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los créditos para gastos se destinarán exclusivamente a la finalidad específica para la que hayan sido autorizados por la Ley de Presupuestos o a la que resulte de las modificaciones aprobadas conforme a esta ley."}]}]},{"n":"2","title":"Programación plurianual y ciclo presupuestario: escenarios, elaboración y prórroga","blocks":[{"text":"Los escenarios presupuestarios plurianuales programan la actividad del sector público estatal con presupuesto limitativo y fijan los límites, referidos a los tres ejercicios siguientes, que debe respetar la acción de gobierno con incidencia presupuestaria (art. 28.1). Los confecciona el Ministerio de Hacienda, se ajustan al objetivo de estabilidad y constan de un escenario de ingresos y otro de gastos (art. 28.3 y 28.4). Se desarrollan en programas plurianuales ministeriales, también a tres años, que aprueba cada Ministro (art. 29).","refs":[{"ref":"Art. 28.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los escenarios presupuestarios plurianuales determinarán los límites, referidos a los tres ejercicios siguientes, que la acción de gobierno debe respetar en los casos en que sus decisiones tengan incidencia presupuestaria."},{"ref":"Art. 28.4 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los escenarios presupuestarios plurianuales estarán integrados por un escenario de ingresos y un escenario de gastos."}]},{"text":"En la elaboración, el Ministro de Hacienda fija las directrices de distribución del gasto, con apoyo de la Comisión de Políticas de Gasto; los ministerios remiten sus propuestas ajustadas a esos límites, acompañadas de memorias de objetivos por programa; y el Ministro de Hacienda eleva el anteproyecto al Gobierno (art. 36). El proyecto se remite a las Cortes antes del 1 de octubre del año anterior, con documentación complementaria como las memorias de programas, el informe de impacto de género o el de alineamiento con la Agenda 2030 (art. 37).","refs":[{"ref":"Art. 36.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las directrices para la distribución del gasto, estableciendo los criterios de elaboración de las propuestas de presupuestos y sus límites cuantitativos con las prioridades y limitaciones que deban respetarse, se determinarán por el Ministro de Hacienda."},{"ref":"Art. 37.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"será remitido a las Cortes Generales antes del día 1 de octubre del año anterior al que se refiera."}]},{"text":"Si la ley no se aprueba antes del primer día del ejercicio, se prorrogan automáticamente los presupuestos iniciales del anterior hasta la publicación de los nuevos (art. 38.1 LGP; art. 134.4 CE). La prórroga no alcanza a los créditos de programas que terminen ese ejercicio y la estructura orgánica se adapta a la organización vigente (art. 38.2 y 38.3).","refs":[{"ref":"Art. 38.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Si la Ley de Presupuestos Generales del Estado no se aprobara antes del primer día del ejercicio económico correspondiente, se considerarán automáticamente prorrogados los presupuestos iniciales del ejercicio anterior"},{"ref":"Art. 38.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La prórroga no afectará a los créditos para gastos correspondientes a programas o actuaciones que terminen en el ejercicio cuyos presupuestos se prorrogan o para obligaciones que se extingan en el mismo."}]}]},{"n":"3","title":"El presupuesto por programas: créditos y programas presupuestarios","blocks":[{"text":"El crédito presupuestario es cada asignación individualizada de gasto puesta a disposición de los centros gestores para cubrir las necesidades para las que se aprobó (art. 35.1). El programa presupuestario, plurianual y bajo responsabilidad del titular del centro gestor, es el conjunto de gastos necesarios para alcanzar objetivos preestablecidos: producir bienes y servicios, cumplir obligaciones específicas u otras actividades encomendadas (art. 35.2). El programa de gasto anual es su concreción anual. El cumplimiento se comprueba por resultados cuando son mensurables y, si no lo son, mediante indicadores de medición indirecta (art. 35.4).","refs":[{"ref":"Art. 35.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Son créditos presupuestarios cada una de las asignaciones individualizadas de gasto, que figuran en los presupuestos de los órganos y entidades a que se refiere el artículo 33.1.ª) de esta ley, puestas a disposición de los centros gestores para la cobertura de las necesidades para las que hayan sido aprobados."},{"ref":"Art. 35.4 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Cuando los resultados no sean mensurables la efectividad del programa se hará mediante indicadores que permitan su medición indirecta."}]}]},{"n":"4","title":"Estructura de los Presupuestos Generales del Estado: clasificaciones","blocks":[{"text":"Los estados de gastos se estructuran con tres clasificaciones (art. 40.1): orgánica (por secciones y servicios), por programas (conforme al art. 35) y económica, por capítulos que separan operaciones corrientes, de capital, financieras y el Fondo de Contingencia. Los capítulos se desglosan en artículos, conceptos y subconceptos. Además existe una clasificación funcional según la finalidad (art. 40.2).","refs":[{"ref":"Art. 40.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La clasificación económica, que agrupará los créditos por capítulos separando las operaciones corrientes, las de capital, las financieras y el Fondo de Contingencia de ejecución presupuestaria."},{"ref":"Art. 40.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los capítulos se desglosarán en artículos y estos, a su vez, en conceptos que podrán dividirse en subconceptos."}]},{"text":"Los estados de ingresos siguen las clasificaciones orgánica y económica (art. 41). En la económica, los ingresos corrientes comprenden impuestos directos y cotizaciones sociales, impuestos indirectos, tasas, precios públicos y otros ingresos, transferencias corrientes e ingresos patrimoniales; los de capital, enajenación de inversiones reales y transferencias de capital; y las operaciones financieras, activos y pasivos financieros.","refs":[{"ref":"Art. 41.b) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En los ingresos corrientes se distinguirán: impuestos directos y cotizaciones sociales, impuestos indirectos, tasas, precios públicos y otros ingresos, transferencias corrientes e ingresos patrimoniales."}]}]},{"n":"5","title":"Los créditos: especificación, limitación y temporalidad","blocks":[{"text":"En el presupuesto del Estado los créditos se especifican a nivel de concepto, salvo los de personal y gastos corrientes en bienes y servicios (a nivel de artículo) y las inversiones reales (a nivel de capítulo) (art. 43.1). Algunos créditos se especifican siempre a su nivel concreto, como atenciones protocolarias y representativas, gastos reservados, arrendamientos de edificios, créditos ampliables o créditos extraordinarios (art. 43.2). En organismos autónomos y Seguridad Social, personal, bienes corrientes e inversiones se especifican a nivel de capítulo (art. 44.1).","refs":[{"ref":"Art. 43.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En el presupuesto del Estado los créditos se especificarán a nivel de concepto, salvo los créditos destinados a gastos de personal y los gastos corrientes en bienes y servicios, que se especificarán a nivel de artículo y las inversiones reales a nivel de capítulo."}]},{"text":"Limitación: los créditos son limitativos y no pueden adquirirse compromisos por encima de ellos; los actos y disposiciones de rango inferior a ley que lo incumplan son nulos de pleno derecho (art. 46). Temporalidad: solo se imputan obligaciones por gastos del propio ejercicio (art. 49.1), y los créditos no afectados el último día a obligaciones reconocidas quedan anulados de pleno derecho, salvo incorporación (art. 49.2).","refs":[{"ref":"Art. 46 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los créditos para gastos son limitativos. No podrán adquirirse compromisos de gasto ni adquirirse obligaciones por cuantía superior al importe de los créditos autorizados en los estados de gastos, siendo nulos de pleno derecho los actos administrativos y las disposiciones generales con rango inferior a ley que incumplan esta limitación"},{"ref":"Art. 49.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los créditos para gastos que en el último día del ejercicio presupuestario no estén afectados al cumplimiento de obligaciones ya reconocidas, quedarán anulados de pleno derecho, sin perjuicio de lo establecido en el artículo 58 de esta ley."}]}]},{"n":"5.1","title":"Gastos plurianuales y Fondo de Contingencia","blocks":[{"text":"Pueden adquirirse compromisos que se extiendan a ejercicios posteriores si su ejecución empieza en el propio ejercicio (art. 47.1). El número de ejercicios no puede superar cuatro, con límites sobre el crédito inicial: 70 % el año siguiente, 60 % el segundo y 50 % el tercero y el cuarto (art. 47.2). El Gobierno, en casos especialmente justificados, puede modificar esos porcentajes o aumentar las anualidades (art. 47.3).","refs":[{"ref":"Art. 47.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El número de ejercicios a que pueden aplicarse los gastos no será superior a cuatro. El gasto que se impute a cada uno de los ejercicios posteriores no podrá exceder de la cantidad que resulte de aplicar al crédito inicial a que corresponda la operación los siguientes porcentajes: en el ejercicio inmediato siguiente, el 70 por ciento, en el segundo ejercicio, el 60 por ciento, y en los ejercicios tercero y cuarto, el 50 por ciento."},{"ref":"Art. 47.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El Gobierno, en casos especialmente justificados, podrá acordar la modificación de los porcentajes anteriores, incrementar el número de anualidades"}]},{"text":"El Fondo de Contingencia, del dos por ciento del gasto no financiero (excluida la financiación territorial), atiende necesidades inaplazables y no discrecionales; solo financia ampliaciones, créditos extraordinarios y suplementos, e incorporaciones, nunca decisiones discrecionales sin cobertura (art. 50.1). Su aplicación la aprueba el Consejo de Ministros (art. 50.2).","refs":[{"ref":"Art. 50.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"incluirá una sección bajo la rúbrica «Fondo de Contingencia de ejecución presupuestaria», por importe del dos por ciento del total de gastos para operaciones no financieras"},{"ref":"Art. 50.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La aplicación del Fondo de Contingencia se aprobará, a propuesta del Ministro de Economía y Hacienda, mediante acuerdo del Consejo de Ministros, previamente a la autorización de las respectivas modificaciones de crédito."}]}]},{"n":"6","title":"Modificaciones presupuestarias","blocks":[{"text":"La cuantía y finalidad de los créditos solo se modifican mediante transferencias, generaciones, ampliaciones, créditos extraordinarios y suplementos de crédito, e incorporaciones (art. 51); los anticipos de caja fija o de Tesorería no son modificaciones. Las transferencias son traspasos entre créditos, con restricciones: no desde operaciones financieras al resto ni de capital a corrientes; no entre secciones distintas; y no minorando créditos extraordinarios o ya suplementados o ampliados (art. 52.1), salvo reorganizaciones administrativas y otros supuestos (art. 52.2).","refs":[{"ref":"Art. 51 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) Transferencias. b) Generaciones. c) Ampliaciones. d) Créditos extraordinarios y suplementos de crédito. e) Incorporaciones."},{"ref":"Art. 52.1.a) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) No podrán realizarse desde créditos para operaciones financieras al resto de los créditos, ni desde créditos para operaciones de capital a créditos para operaciones corrientes."}]},{"text":"Las generaciones incrementan créditos por ingresos no previstos o superiores a los presupuestados (art. 53.1). Son ampliables, excepcionalmente, los créditos para pensiones de Clases Pasivas, los de obligaciones derivadas de normas con rango de ley que se relacionen en el estado de gastos y los de la Deuda (art. 54.1). Si un gasto no puede demorarse al ejercicio siguiente y no hay crédito, procede un crédito extraordinario; si el crédito es insuficiente y no ampliable, un suplemento (art. 55.1). Los financiados con el Fondo de Contingencia los autoriza el Consejo de Ministros (art. 55.3). Las incorporaciones trasladan remanentes del ejercicio anterior en supuestos tasados, como los créditos extraordinarios o suplementos concedidos por ley en el último mes del año (art. 58.d).","refs":[{"ref":"Art. 53.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las generaciones son modificaciones que incrementan los créditos como consecuencia de la realización de determinados ingresos no previstos o superiores a los contemplados en el presupuesto inicial."},{"ref":"Art. 54.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Excepcionalmente tendrán la condición de ampliables los créditos destinados al pago de pensiones de Clases Pasivas del Estado"},{"ref":"Art. 55.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Cuando haya de realizarse con cargo al Presupuesto del Estado algún gasto que no pueda demorarse hasta el ejercicio siguiente, y no exista crédito adecuado o sea insuficiente y no ampliable el consignado y su dotación no resulte posible a través de las restantes figuras previstas en el artículo 51, deberá procederse a la tramitación de un crédito extraordinario o suplementario del inicialmente previsto."},{"ref":"Art. 55.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El Consejo de Ministros autorizará los créditos extraordinarios y suplementos de crédito para atender obligaciones del ejercicio corriente o de ejercicios anteriores si se hubiera anulado crédito en el ejercicio de procedencia, cuando se financien con cargo al Fondo de Contingencia."},{"ref":"Art. 58.d) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"d) Los que resulten de créditos extraordinarios y suplementos de crédito que hayan sido concedidos mediante norma con rango de ley en el último mes del ejercicio presupuestario anterior."}]}]},{"n":"7","title":"Anticipos de Tesorería","blocks":[{"text":"Con carácter excepcional, el Gobierno puede conceder anticipos de Tesorería para gastos inaplazables, con un límite anual del uno por ciento de los créditos autorizados al Estado por la Ley de Presupuestos, en dos casos: cuando, en tramitación un crédito extraordinario o suplemento, haya dictaminado favorablemente el Consejo de Estado, o cuando se haya promulgado una ley cuyas obligaciones exijan ese crédito (art. 60.1). Si las Cortes no aprueban el proyecto de ley, el anticipo se cancela con cargo a los créditos del departamento cuya minoración cause menos trastornos (art. 60.3).","refs":[{"ref":"Art. 60.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Con carácter excepcional, el Gobierno, a propuesta del Ministro de Economía, podrá conceder anticipos de Tesorería para atender gastos inaplazables, con el límite máximo en cada ejercicio del uno por ciento de los créditos autorizados al Estado por la Ley de Presupuestos Generales del Estado"},{"ref":"Art. 60.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Si las Cortes Generales no aprobasen el proyecto de Ley de concesión del crédito extraordinario o del suplemento de crédito el Gobierno, a propuesta del Ministro de Hacienda, dispondrá la cancelación del anticipo de Tesorería"}]}]},{"n":"8","title":"Competencias en materia de modificaciones de crédito","blocks":[{"text":"Corresponde al Gobierno autorizar las transferencias entre secciones por reorganizaciones administrativas y los créditos extraordinarios y suplementos del art. 55.3, entre otras (art. 61). El Ministro de Hacienda autoriza las transferencias que no correspondan a los ministros, ciertas generaciones, las incorporaciones de remanentes y las ampliaciones del art. 54.1 (art. 62.1). Los ministros, previo informe favorable de la Intervención Delegada, autorizan transferencias dentro de un mismo programa o entre programas de un mismo servicio, si no afectan a personal ni incrementan los créditos del art. 43.2, y algunas generaciones (art. 63.1).","refs":[{"ref":"Art. 61.a) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) Autorizar las transferencias entre distintas secciones presupuestarias como consecuencia de reorganizaciones administrativas."},{"ref":"Art. 62.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"c) Las incorporaciones de remanentes reguladas en el artículo 58."},{"ref":"Art. 63.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los titulares de los distintos ministerios podrán autorizar, previo informe favorable de la Intervención Delegada competente en el ministerio"},{"ref":"Art. 63.1.a) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) Transferencias entre créditos de un mismo programa o entre programas de un mismo servicio, incluso con la creación de créditos nuevos en el caso de los destinados a compra de bienes corrientes y servicios o inversiones reales"}]},{"text":"En los organismos autónomos, el presidente o director autoriza créditos extraordinarios o suplementos de hasta el 10 % del capítulo y 500.000 euros (sin afectar a personal), dando cuenta al Ministro del que dependa y al de Hacienda; el Ministro de Hacienda, hasta el 20 % y 1.000.000 de euros; y el Consejo de Ministros, en los demás casos (art. 56.3).","refs":[{"ref":"Art. 56.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a. A los Presidentes o Directores de los organismos hasta un importe del 10 % del correspondiente capítulo de su presupuesto inicial de gastos, cuando no supere la cuantía de 500.000 euros, excluidos los que afecten a gastos de personal o a los contemplados en el apartado 2 del artículo 44 de esta Ley, dando cuenta de los acuerdos al Ministro de que dependan y al Ministro de Hacienda."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Presupuestos: anuales y con la totalidad de gastos e ingresos del sector público estatal (art. 134.2 CE).","refs":[{"ref":"Art. 134.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"tendrán carácter anual, incluirán la totalidad de los gastos e ingresos del sector público estatal"}]},{"text":"Escenarios plurianuales: tres ejercicios siguientes.","refs":[{"ref":"Art. 28.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"referidos a los tres ejercicios siguientes"}]},{"text":"Proyecto a las Cortes antes del 1 de octubre; prórroga automática si no se aprueba a 1 de enero.","refs":[{"ref":"Art. 37.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"antes del día 1 de octubre del año anterior al que se refiera."}]},{"text":"Especificación en el Estado: concepto; personal y bienes corrientes, artículo; inversiones reales, capítulo.","refs":[{"ref":"Art. 43.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"las inversiones reales a nivel de capítulo."}]},{"text":"Plurianuales: máximo cuatro ejercicios; 70-60-50-50 %; el Gobierno puede modificarlo.","refs":[{"ref":"Art. 47.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"en el ejercicio inmediato siguiente, el 70 por ciento"}]},{"text":"Cinco modificaciones del art. 51; el anticipo de caja fija no es una de ellas.","refs":[{"ref":"Art. 51 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"d) Créditos extraordinarios y suplementos de crédito. e) Incorporaciones."}]},{"text":"Prohibido transferir de capital a corriente o entre secciones.","refs":[{"ref":"Art. 52.1.b) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"b) No podrán realizarse entre créditos de distintas secciones presupuestarias."}]},{"text":"Anticipos de Tesorería: límite del 1 % de los créditos del Estado.","refs":[{"ref":"Art. 60.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"del uno por ciento de los créditos autorizados al Estado"}]},{"text":"Transferencias dentro del programa: el ministro, con informe favorable de la Intervención Delegada.","refs":[{"ref":"Art. 63.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"previo informe favorable de la Intervención Delegada competente"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614', null, null, null, 'Otras normas citadas: CE (https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229)'
