insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Créditos y programas presupuestarios (art. 35 LGP)"},{"n":"2","title":"Estructura de los estados de gastos: clasificaciones orgánica, por programas y económica (arts. 39-40 LGP)"},{"n":"3","title":"Especialidad y especificación de los créditos (arts. 42-44 LGP)"},{"n":"4","title":"Modificaciones de crédito: clases (art. 51 LGP)"},{"n":"5","title":"Transferencias y sus restricciones (art. 52 LGP)"},{"n":"6","title":"Generaciones y ampliaciones (arts. 53-54 LGP)"},{"n":"7","title":"Créditos extraordinarios y suplementos de crédito: Estado, organismos autónomos y Seguridad Social (arts. 55-57 LGP)"},{"n":"8","title":"Incorporaciones, Fondo de Contingencia y anticipos de Tesorería (arts. 50, 58-60 LGP)"},{"n":"9","title":"Competencias en materia de modificaciones (arts. 61-63 LGP)"},{"n":"10","title":"Códigos de la clasificación económica del gasto (Resolución DGP de 20/01/2014)"}]'::jsonb, '["Art. 40.1.c) Ley 47/2003: «En los créditos para operaciones corrientes se distinguirán los gastos de personal, los gastos corrientes en bienes y servicios, los gastos financieros y las transferencias corrientes. En los créditos para operaciones de capital se distinguirán las inversiones reales y las transferencias de capital.»","Art. 40.1.c) Ley 47/2003: «Los capítulos se desglosarán en artículos y estos, a su vez, en conceptos que podrán dividirse en subconceptos.»","Art. 42 Ley 47/2003: «Los créditos para gastos se destinarán exclusivamente a la finalidad específica para la que hayan sido autorizados por la Ley de Presupuestos o a la que resulte de las modificaciones aprobadas conforme a esta ley.»","Art. 52.1 Ley 47/2003: «a) No podrán realizarse desde créditos para operaciones financieras al resto de los créditos, ni desde créditos para operaciones de capital a créditos para operaciones corrientes.»","Art. 52.1 Ley 47/2003: «c) No minorarán créditos extraordinarios o créditos que se hayan suplementado o ampliado en el ejercicio.»","Art. 53.1 Ley 47/2003: «Las generaciones son modificaciones que incrementan los créditos como consecuencia de la realización de determinados ingresos no previstos o superiores a los contemplados en el presupuesto inicial.»","Art. 53.3 Ley 47/2003: «La generación sólo podrá realizarse cuando se hayan efectuado los correspondientes ingresos que la justifican.»","Art. 54.3 Ley 47/2003: «Las ampliaciones de crédito que afecten a operaciones del presupuesto del Estado se financiarán con cargo al Fondo de Contingencia, conforme a lo previsto en el artículo 50 de esta ley, o con baja en otros créditos del presupuesto no financiero.»","Art. 55.1 Ley 47/2003: «a) Si la necesidad surgiera en operaciones no financieras del presupuesto, el crédito extraordinario o suplementario se financiará mediante baja en los créditos del Fondo de Contingencia o en otros no financieros que se consideren adecuados.»","Art. 55.3 Ley 47/2003: «El Consejo de Ministros autorizará los créditos extraordinarios y suplementos de crédito para atender obligaciones del ejercicio corriente o de ejercicios anteriores si se hubiera anulado crédito en el ejercicio de procedencia, cuando se financien con cargo al Fondo de Contingencia.»","Art. 60.1 Ley 47/2003: «Con carácter excepcional, el Gobierno, a propuesta del Ministro de Economía, podrá conceder anticipos de Tesorería para atender gastos inaplazables, con el límite máximo en cada ejercicio del uno por ciento de los créditos autorizados al Estado por la Ley de Presupuestos Generales del Estado»","Art. 62.1 Ley 47/2003: «c) Las incorporaciones de remanentes reguladas en el artículo 58.»","Anexo IV, cap. 1 Resolución DGP 20/01/2014 (clasificación económica): «No se incluyen en este capítulo las indemnizaciones por razón del servicio.»","Anexo IV, cap. 2 Resolución DGP 20/01/2014 (clasificación económica): «Son imputables a este capítulo los gastos originados por la adquisición de bienes que reúnan algunas de las características siguientes: a) Ser bienes fungibles b) Tener una duración previsiblemente inferior al ejercicio presupuestario c) No ser susceptibles de inclusión en inventario d) Ser, previsiblemente, gastos reiterativos»","Anexo IV, concepto 227 Resolución DGP 20/01/2014 (clasificación económica): «Se incluirán aquellos gastos que correspondan a actividades que siendo de la competencia de los organismos públicos se ejecuten mediante contrato con empresas externas o profesionales independientes.»","Anexo IV, cap. 6 Resolución DGP 20/01/2014 (clasificación económica): «Un gasto se considerará amortizable cuando contribuya al mantenimiento de la actividad del sujeto que lo realiza en ejercicios futuros.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Créditos y programas presupuestarios","blocks":[{"text":"El crédito presupuestario es la pieza básica de la gestión del gasto: cada una de las asignaciones individualizadas de gasto que figuran en los presupuestos y se ponen a disposición de los centros gestores para cubrir las necesidades para las que fueron aprobadas (art. 35.1 de la Ley 47/2003, General Presupuestaria, LGP). Su especificación viene dada por la combinación de las clasificaciones orgánica, por programas y económica. Los créditos se agrupan en programas: conjuntos de gastos orientados a objetivos preestablecidos bajo la responsabilidad del titular del centro gestor (art. 35.2), cuya concreción anual es el programa de gasto del presupuesto (art. 35.4).","refs":[{"ref":"Art. 35.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Son créditos presupuestarios cada una de las asignaciones individualizadas de gasto, que figuran en los presupuestos de los órganos y entidades a que se refiere el artículo 33.1.ª) de esta ley, puestas a disposición de los centros gestores para la cobertura de las necesidades para las que hayan sido aprobados."},{"ref":"Art. 35.4 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Constituye un programa de gasto del presupuesto anual el conjunto de créditos que, para el logro de los objetivos anuales que el mismo establezca, se ponen a disposición del gestor responsable de su ejecución."}]},{"text":"Los programas pueden perseguir tres tipos de finalidad: la producción de bienes y servicios, el cumplimiento de obligaciones específicas o la realización de las demás actividades encomendadas a los centros gestores (art. 35.2). Las actividades de servicios horizontales e instrumentales pueden configurarse como programas de apoyo, que facilitan la ordenación y gestión de los créditos necesarios para realizarlas (art. 35.3). Esta lógica de objetivos explica que la clasificación por programas sea una de las tres que estructuran los estados de gastos.","refs":[{"ref":"Art. 35.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) la producción de bienes y servicios, b) el cumplimiento de obligaciones específicas o c) la realización de las demás actividades encomendadas a los centros gestores del gasto."},{"ref":"Art. 35.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las actividades propias de servicios horizontales y las instrumentales podrán configurarse como programas de apoyo para una mejor ordenación y gestión de los créditos necesarios para su realización."}]}]},{"n":"2","title":"Estructura de los estados de gastos: clasificaciones orgánica, por programas y económica","blocks":[{"text":"La estructura de los Presupuestos la determina el Ministerio de Hacienda según la organización del sector público, la naturaleza económica de ingresos y gastos y sus finalidades (art. 39). La clasificación orgánica agrupa los créditos por secciones y servicios; la de programas, según los objetivos de los centros gestores; y la económica, por capítulos (art. 40.1).","refs":[{"ref":"Art. 40.1.a) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) La clasificación orgánica que agrupará por secciones y servicios los créditos asignados a los distintos centros gestores de gasto"}]},{"text":"En la clasificación económica, las operaciones corrientes comprenden gastos de personal, gastos corrientes en bienes y servicios, gastos financieros y transferencias corrientes; las de capital, inversiones reales y transferencias de capital; las financieras, activos y pasivos financieros; y aparte figura el Fondo de Contingencia. Cada capítulo se desglosa en artículos, estos en conceptos y estos, si procede, en subconceptos (art. 40.1.c). Por tanto, las inversiones reales no son operaciones corrientes, sino de capital.","refs":[{"ref":"Art. 40.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En los créditos para operaciones corrientes se distinguirán los gastos de personal, los gastos corrientes en bienes y servicios, los gastos financieros y las transferencias corrientes. En los créditos para operaciones de capital se distinguirán las inversiones reales y las transferencias de capital."},{"ref":"Art. 40.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los capítulos se desglosarán en artículos y estos, a su vez, en conceptos que podrán dividirse en subconceptos."}]}]},{"n":"3","title":"Especialidad y especificación de los créditos","blocks":[{"text":"Por el principio de especialidad, los créditos se destinan exclusivamente a la finalidad para la que fueron autorizados por la Ley de Presupuestos o por sus modificaciones (art. 42). El nivel de especificación determina hasta dónde vincula el crédito: en el Estado, concepto como regla; artículo para personal y bienes corrientes; capítulo para inversiones reales (art. 43.1). Se especifican siempre a su nivel concreto las atenciones protocolarias y representativas y los gastos reservados, los arrendamientos de edificios, los créditos ampliables, los que identifican perceptor, los que fije la Ley de Presupuestos y los créditos extraordinarios (art. 43.2). En organismos autónomos y Seguridad Social, personal, bienes corrientes e inversiones vinculan a nivel de capítulo (art. 44.1).","refs":[{"ref":"Art. 42 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los créditos para gastos se destinarán exclusivamente a la finalidad específica para la que hayan sido autorizados por la Ley de Presupuestos o a la que resulte de las modificaciones aprobadas conforme a esta ley."},{"ref":"Art. 43.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En el presupuesto del Estado los créditos se especificarán a nivel de concepto, salvo los créditos destinados a gastos de personal y los gastos corrientes en bienes y servicios, que se especificarán a nivel de artículo y las inversiones reales a nivel de capítulo."},{"ref":"Art. 43.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) Los destinados a atenciones protocolarias y representativas y los gastos reservados. b) Los destinados a arrendamientos de edificios y otras construcciones. c) Los declarados ampliables conforme a lo establecido en el artículo 54 de esta Ley."}]}]},{"n":"4","title":"Modificaciones de crédito: clases","blocks":[{"text":"Durante el ejercicio, la cuantía y la finalidad de los créditos solo pueden alterarse dentro de los límites y procedimientos legales y únicamente mediante cinco figuras: transferencias, generaciones, ampliaciones, créditos extraordinarios y suplementos de crédito, e incorporaciones (art. 51). Es una lista cerrada; otras técnicas de gestión, como los anticipos de caja fija, no modifican créditos.","refs":[{"ref":"Art. 51 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La cuantía y finalidad de los créditos contenidos en los presupuestos de gastos sólo podrán ser modificadas durante el ejercicio, dentro de los límites y con arreglo al procedimiento establecido en los artículos siguientes, mediante: a) Transferencias. b) Generaciones. c) Ampliaciones. d) Créditos extraordinarios y suplementos de crédito. e) Incorporaciones."}]}]},{"n":"5","title":"Transferencias y sus restricciones","blocks":[{"text":"Las transferencias son traspasos de dotaciones entre créditos, incluso creando créditos nuevos (art. 52.1). Tienen restricciones: no pueden ir desde operaciones financieras al resto ni de capital a corrientes; no pueden hacerse entre secciones presupuestarias distintas (salvo el programa de contratación centralizada); y no pueden minorar créditos extraordinarios ni créditos suplementados o ampliados en el ejercicio. Así, si un concepto recibió un suplemento en mayo, no puede darse de baja en octubre para transferirlo a otro.","refs":[{"ref":"Art. 52.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las transferencias son traspasos de dotaciones entre créditos. Pueden realizarse entre los diferentes créditos del presupuesto incluso con la creación de créditos nuevos, con las siguientes restricciones:"},{"ref":"Art. 52.1.b) y c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"b) No podrán realizarse entre créditos de distintas secciones presupuestarias. Esta restricción no afectará a los créditos del programa de contratación centralizada. c) No minorarán créditos extraordinarios o créditos que se hayan suplementado o ampliado en el ejercicio."}]},{"text":"Estas restricciones no se aplican a las transferencias derivadas de reorganizaciones administrativas o traspasos a comunidades autónomas, de convenios entre departamentos, del cumplimiento de la Ley del Patrimonio Histórico Español o desde el programa de imprevistos (art. 52.2). En ningún caso pueden crear o aumentar subvenciones nominativas, salvo que sea conforme con la Ley General de Subvenciones o se trate de aportaciones a otros entes del sector público (art. 52.3).","refs":[{"ref":"Art. 52.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las anteriores restricciones no afectarán a las transferencias de crédito que hayan de realizarse como consecuencia de reorganizaciones administrativas o traspaso de competencias a comunidades autónomas"},{"ref":"Art. 52.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En ningún caso las transferencias podrán crear créditos destinados a subvenciones nominativas o aumentar los ya existentes salvo que sean conformes con lo dispuesto en la Ley General de Subvenciones o se trate de subvenciones o aportaciones a otros entes del sector público."}]}]},{"n":"6","title":"Generaciones y ampliaciones","blocks":[{"text":"Las generaciones aumentan los créditos por ingresos no previstos o superiores a los presupuestados (art. 53.1), procedentes de aportaciones para financiar gastos conjuntos, ventas de bienes y prestación de servicios, enajenaciones de inmovilizado, reembolsos de préstamos, ingresos legalmente afectados y reintegros de pagos indebidos del presupuesto corriente (art. 53.2). Como regla, solo se generan crédito cuando el ingreso se ha realizado (art. 53.3). Hay reglas de destino: la venta de bienes genera en créditos de igual naturaleza, y el reembolso de préstamos solo en créditos para conceder nuevos préstamos (art. 53.4). Excepcionalmente, generan crédito los ingresos del último trimestre del ejercicio anterior (art. 53.5).","refs":[{"ref":"Art. 53.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La generación sólo podrá realizarse cuando se hayan efectuado los correspondientes ingresos que la justifican."},{"ref":"Art. 53.4 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los ingresos procedentes de reembolso de préstamos únicamente podrán dar lugar a generaciones en aquellos créditos destinados a la concesión de nuevos préstamos."},{"ref":"Art. 53.5 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Con carácter excepcional podrán generar crédito en el Presupuesto del ejercicio los ingresos realizados en el último trimestre del ejercicio anterior."}]},{"text":"Los créditos ampliables son excepcionales: pensiones de Clases Pasivas, obligaciones derivadas de normas con rango de ley que figuren relacionadas en el estado de gastos, y la Deuda del Estado (art. 54.1); en la Seguridad Social, entre otros, pensiones e incapacidad temporal (art. 54.2). En el Estado, las ampliaciones se financian con el Fondo de Contingencia o con baja en otros créditos no financieros (art. 54.3). No pueden ampliarse créditos previamente minorados, salvo excepciones (art. 54.4).","refs":[{"ref":"Art. 54.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las ampliaciones de crédito que afecten a operaciones del presupuesto del Estado se financiarán con cargo al Fondo de Contingencia, conforme a lo previsto en el artículo 50 de esta ley, o con baja en otros créditos del presupuesto no financiero."},{"ref":"Art. 54.4 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"No podrán ampliarse créditos que hayan sido previamente minorados"}]}]},{"n":"7","title":"Créditos extraordinarios y suplementos de crédito: Estado, organismos autónomos y Seguridad Social","blocks":[{"text":"Cuando un gasto no puede esperar al ejercicio siguiente y no hay otra figura posible, se tramita un crédito extraordinario (si no existe crédito adecuado) o un suplemento (si es insuficiente y no ampliable). En operaciones no financieras se financian con baja en el Fondo de Contingencia o en otros créditos no financieros; en operaciones financieras, con Deuda Pública o baja en créditos de la misma naturaleza (art. 55.1).","refs":[{"ref":"Art. 55.1.a) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) Si la necesidad surgiera en operaciones no financieras del presupuesto, el crédito extraordinario o suplementario se financiará mediante baja en los créditos del Fondo de Contingencia o en otros no financieros que se consideren adecuados."}]},{"text":"Se requiere proyecto de ley a las Cortes, previo informe de la Dirección General de Presupuestos y dictamen del Consejo de Estado, en tres casos: obligaciones de ejercicios anteriores sin crédito anulado; obligaciones del propio ejercicio financiadas con baja en otros créditos; y operaciones financieras (art. 55.2). En cambio, autoriza el Consejo de Ministros los financiados con el Fondo de Contingencia (art. 55.3).","refs":[{"ref":"Art. 55.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El Ministro de Hacienda y Administraciones Públicas propondrá al Consejo de Ministros la remisión de un proyecto de ley a las Cortes Generales, previo informe de la Dirección General de Presupuestos y dictamen del Consejo de Estado en los siguientes casos:"},{"ref":"Art. 55.2.b) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"b) Cuando se trate de créditos extraordinarios o suplementarios para atender obligaciones del propio ejercicio cuando se financien con baja en otros créditos."}]},{"text":"En los organismos autónomos se financian con remanente de tesorería no aplicado o con mayores ingresos (art. 56.2) y los autoriza el presidente o director hasta el 10 % del capítulo y 500.000 euros, el Ministro de Hacienda hasta el 20 % y 1.000.000 de euros, y el Consejo de Ministros en el resto (art. 56.3). En la Seguridad Social, el Gobierno si superan el dos por ciento del presupuesto inicial de la entidad y, si no, el ministro competente (art. 57.2).","refs":[{"ref":"Art. 56.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La financiación de los créditos extraordinarios o suplementarios únicamente podrá realizarse con cargo a la parte del remanente de tesorería al fin del ejercicio anterior que no haya sido aplicada en el presupuesto del organismo, o con mayores ingresos sobre los previstos inicialmente."},{"ref":"Art. 57.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"al Gobierno cuando su importe sea superior al dos por ciento del presupuesto inicial de gastos de la respectiva Entidad"}]}]},{"n":"8","title":"Incorporaciones, Fondo de Contingencia y anticipos de Tesorería","blocks":[{"text":"Como excepción a la anulación de créditos al cierre (art. 49), pueden incorporarse remanentes del ejercicio anterior cuando lo disponga una ley, en generaciones por aportaciones o ingresos afectados, en retenciones para créditos extraordinarios cuyo pago se anticipó y en créditos extraordinarios o suplementos concedidos por ley en el último mes del ejercicio anterior (art. 58). En el Estado se financian con baja en el Fondo de Contingencia o en otros créditos no financieros.","refs":[{"ref":"Art. 58 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"se podrán incorporar a los correspondientes créditos de un ejercicio los remanentes de crédito del ejercicio anterior, en los siguientes casos: a) Cuando así lo disponga una norma de rango legal."},{"ref":"Art. 58 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las incorporaciones de crédito que afecten al presupuesto del Estado se financiarán mediante baja en el Fondo de Contingencia conforme a lo previsto en el artículo 50 de esta ley o con baja en otros créditos de operaciones no financieras."}]},{"text":"El Fondo de Contingencia, del dos por ciento del gasto no financiero, solo financia ampliaciones, créditos extraordinarios y suplementos, e incorporaciones, y nunca gastos discrecionales (art. 50.1). Los anticipos de Tesorería los concede el Gobierno, excepcionalmente, para gastos inaplazables, hasta el uno por ciento de los créditos del Estado, cuando el Consejo de Estado ya dictaminó favorablemente el expediente o se promulgó una ley que exige el crédito (art. 60.1).","refs":[{"ref":"Art. 50.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En ningún caso podrá utilizarse el Fondo para financiar modificaciones destinadas a dar cobertura a gastos o actuaciones que deriven de decisiones discrecionales de la Administración, que carezcan de cobertura presupuestaria."},{"ref":"Art. 60.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"con el límite máximo en cada ejercicio del uno por ciento de los créditos autorizados al Estado por la Ley de Presupuestos Generales del Estado"}]},{"text":"Si el crédito extraordinario o el suplemento que se tramita en el presupuesto del Estado va a financiar necesidades de un organismo autónomo, el anticipo autoriza a atender esos pagos en el organismo mediante operaciones de Tesorería (art. 60.2). Y si finalmente las Cortes Generales no aprueban el proyecto de ley de concesión, el Gobierno, a propuesta del Ministro de Hacienda, cancela el anticipo con cargo a los créditos del departamento u organismo cuya minoración ocasione menos trastornos al servicio público (art. 60.3).","refs":[{"ref":"Art. 60.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"dispondrá la cancelación del anticipo de Tesorería con cargo a los créditos del respectivo departamento ministerial u organismo autónomo, en su caso, cuya minoración ocasione menos trastornos para el servicio público."}]}]},{"n":"9","title":"Competencias en materia de modificaciones","blocks":[{"text":"Al Gobierno le corresponden, entre otras, las transferencias entre secciones por reorganización administrativa y los créditos extraordinarios y suplementos del art. 55.3 (art. 61). Al Ministro de Hacienda, las transferencias no atribuidas a otros ministros, determinadas generaciones, las incorporaciones de remanentes y las ampliaciones del art. 54.1 (art. 62.1). Los ministros, con informe favorable de la Intervención Delegada, autorizan transferencias dentro de un programa o entre programas de un mismo servicio que no afecten a personal, y generaciones por aportaciones, reembolsos de préstamos y reintegros (art. 63.1). Si la Intervención informa en contra y se plantea discrepancia, decide el Ministro de Hacienda (art. 62.2).","refs":[{"ref":"Art. 62.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"c) Las incorporaciones de remanentes reguladas en el artículo 58."},{"ref":"Art. 63.1.b) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"b) Generaciones de crédito en los supuestos contemplados en los párrafos a), d) y f) del apartado 2 del artículo 53 de esta ley"},{"ref":"Art. 62.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Acordar o denegar las modificaciones presupuestarias, en los supuestos de competencia de los titulares de los ministerios y organismos autónomos, cuando exista informe negativo de la Intervención Delegada y el titular de la competencia lo remita en discrepancia al Ministro de Hacienda."}]}]},{"n":"10","title":"Códigos de la clasificación económica del gasto","blocks":[{"text":"La Resolución de la Dirección General de Presupuestos de 20 de enero de 2014 fija los códigos económicos. En el capítulo 1, el concepto 120 recoge las retribuciones básicas de funcionarios (sueldo, trienios, pagas extraordinarias); el sueldo de un C1 va al subconcepto 120.02. El capítulo 2 recoge bienes fungibles, de duración inferior al ejercicio, no inventariables o reiterativos; por ejemplo, el material de oficina no inventariable (concepto 220), la limpieza contratada a una empresa (227.00) y las dietas (230, dentro del artículo 23, indemnizaciones por razón del servicio). Desde 2014, las pensiones a funcionarios se imputan al capítulo 4. La compra de ordenadores sin reponer equipos es inversión nueva (concepto 620, capítulo 6).","refs":[{"ref":"Anexo IV, concepto 120 (Res. DGP 20/01/2014)","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"Subconcepto 02. Sueldos del grupo C1 y grupo C."},{"ref":"Anexo IV, cap. 2 (Res. DGP 20/01/2014)","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"a) Ser bienes fungibles b) Tener una duración previsiblemente inferior al ejercicio presupuestario c) No ser susceptibles de inclusión en inventario d) Ser, previsiblemente, gastos reiterativos"},{"ref":"Anexo IV, concepto 227 (Res. DGP 20/01/2014)","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"Concepto 227. Trabajos realizados por otras empresas y profesionales"},{"ref":"Anexo IV, art. 23 (Res. DGP 20/01/2014)","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"Concepto 230. Dietas."},{"ref":"Preámbulo (Res. DGP 20/01/2014)","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"Los principales cambios introducidos en la clasificación económica del gasto se refieren a la imputación al capítulo 4 «Transferencias Corrientes» de los gastos correspondientes a pensiones a funcionarios o familias de carácter civil o militar que hasta 2014 se han venido imputando al capítulo 1 «Gastos de personal»."},{"ref":"Anexo IV, art. 62 (Res. DGP 20/01/2014)","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"Concepto 620. Inversión nueva asociada al funcionamiento operativo de los servicios."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Inversiones reales: operaciones de capital, no corrientes.","refs":[{"ref":"Art. 40.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En los créditos para operaciones de capital se distinguirán las inversiones reales y las transferencias de capital."}]},{"text":"Gastos reservados y atenciones protocolarias se especifican siempre a su nivel concreto.","refs":[{"ref":"Art. 43.2.a) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) Los destinados a atenciones protocolarias y representativas y los gastos reservados."}]},{"text":"No se transfiere entre secciones ni se minoran créditos suplementados o ampliados en el ejercicio.","refs":[{"ref":"Art. 52.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"c) No minorarán créditos extraordinarios o créditos que se hayan suplementado o ampliado en el ejercicio."}]},{"text":"Generación: con el ingreso ya realizado; reembolso de préstamos, solo para nuevos préstamos.","refs":[{"ref":"Art. 53.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"cuando se hayan efectuado los correspondientes ingresos que la justifican."}]},{"text":"Ampliaciones del Estado: Fondo de Contingencia o baja en otros créditos no financieros.","refs":[{"ref":"Art. 54.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"se financiarán con cargo al Fondo de Contingencia"}]},{"text":"Suplemento del propio ejercicio financiado con baja en otros créditos: proyecto de ley, con informe de la DGP y dictamen del Consejo de Estado.","refs":[{"ref":"Art. 55.2.b) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"cuando se financien con baja en otros créditos."}]},{"text":"Incorporaciones de remanentes: las autoriza el Ministro de Hacienda.","refs":[{"ref":"Art. 62.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las incorporaciones de remanentes reguladas en el artículo 58."}]},{"text":"Dietas, concepto 230; limpieza, 227.00; sueldo C1, 120.02; pensiones de funcionarios, capítulo 4.","refs":[{"ref":"Anexo IV (Res. DGP 20/01/2014)","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"00\\. Limpieza y aseo"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614', null, null, null, 'Otras normas citadas: Resolución DGP 20/01/2014 (clasificación económica) (https://www.boe.es/buscar/act.php?id=BOE-A-2014-879)'
  from public.topics t where t.slug = 'age-adm-52-modificaciones-credito'
