       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Orden de 1 de febrero de 1996 por la que se aprueban los documentos contables a utilizar por la Administración General del Estado (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-53-documentos-contables', 'V.3 Documentos contables y operatoria contable de la ejecución del gasto del Estado (Órdenes de 1 de febrero de 1996)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-53-documentos-contables' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Ámbito y soporte de los documentos contables: electrónicos, firma y sello electrónico (apdos. primero a cuarto de la Orden de 1 de febrero de 1996)"},{"n":"2","title":"Documentos del Presupuesto de Gastos: concepto y agrupaciones (apdo. quinto)"},{"n":"3","title":"Gestión de créditos: documentos MC, RC y RC-102 (apdo. sexto)"},{"n":"4","title":"Fases de ejecución del gasto y sus documentos: A, D, OK y mixtos AD y ADOK (apdo. sexto; reglas 20-24 de la Instrucción de operatoria contable)"},{"n":"5","title":"Documentos de ejercicios posteriores y de tramitación anticipada; anexos (apdo. sexto)"},{"n":"6","title":"Anulaciones y autorización de los documentos de gastos (apdos. sexto.2 y séptimo)"},{"n":"7","title":"Pagos a justificar y anticipos de caja fija (apdos. octavo a décimo)"},{"n":"8","title":"Presupuesto de Ingresos, operaciones no presupuestarias y otros documentos: CA y operaciones devengadas (apdos. decimoquinto a vigésimo cuarto)"},{"n":"9","title":"Toma de razón por las oficinas de contabilidad (regla 2 de la Instrucción de operatoria contable)"}]'::jsonb, '["Apdo. primero Orden 1/2/1996 (documentos contables): «Las normas y los documentos contables aprobados en la presente Orden serán de aplicación a la Administración General del Estado.»","Apdo. segundo.2 Orden 1/2/1996 (documentos contables): «Todos los documentos contables serán electrónicos y se ajustarán a los modelos y normas de cumplimentación previstos en esta Orden, así como al procedimiento de tramitación electrónica que establezca la Intervención General de la Administración del Estado.»","Apdo. tercero.1 Orden 1/2/1996 (documentos contables): «Los documentos contables electrónicos deberán autorizarse mediante firma electrónica por quien tenga atribuidas las facultades para ello, según las normas de procedimiento que sean aplicables en cada caso.»","Apdo. quinto.1 Orden 1/2/1996 (documentos contables): «Son documentos de contabilidad del Presupuesto de Gastos aquellos que sirven de soporte a las anotaciones contables que se realicen como consecuencia de operaciones de gestión de créditos presupuestarios y de ejecución del Presupuesto de Gastos.»","Apdo. sexto.1.a Orden 1/2/1996 (documentos contables): «Documento MC: Se utilizará en las modificaciones presupuestarias que aumenten o disminuyan los créditos.»","Regla 14.1 Orden 1/2/1996 (operatoria contable): «Para la solicitud del certificado a que se refiere el párrafo anterior, el Servicio Gestor expedirá un documento RC, de retención de créditos para gastar, que remitirá a la oficina de contabilidad.»","Regla 20.1 Orden 1/2/1996 (operatoria contable): «La ejecución de los gastos presupuestarios se realizará en las siguientes fases: […] Autorización del gasto. […] Compromiso del gasto. […] Reconocimiento de la obligación.»","Apdo. sexto.1.e Orden 1/2/1996 (documentos contables): «Documento A de ejercicio corriente: Se utilizará en las operaciones de autorización del gasto imputables al Presupuesto corriente.»","Apdo. sexto.1.f Orden 1/2/1996 (documentos contables): «Documento D de ejercicio corriente: Se utilizará en las operaciones de compromiso de gasto imputables al Presupuesto corriente.»","Apdo. sexto.1.n Orden 1/2/1996 (documentos contables): «Documento OK: Se utilizará en operaciones de reconocimiento de obligaciones.»","Regla 24.2 Orden 1/2/1996 (operatoria contable): «cuando la autorización y el compromiso de gasto se acuerdan en un acto único, se expedirá un documento mixto AD. […] Cuando en un mismo acto se acumulen la autorización del gasto, su compromiso y el reconocimiento de la obligación, se expedirá documento mixto ADOK.»","Apdo. sexto.1.k Orden 1/2/1996 (documentos contables): «Documento A de tramitación anticipada: Se utilizará en operaciones de autorización de gasto cuando se tramiten anticipadamente.»","Apdo. sexto.2 Orden 1/2/1996 (documentos contables): «se expedirá un documento idéntico al confeccionado para el registro de la operación en cuestión pero de signo contrario.»","Apdo. séptimo.1 Orden 1/2/1996 (documentos contables): «Los documentos MC de «modificación de créditos» y RC-102 de «no disponibilidad» serán autorizados por el Director General de Presupuestos.»","Apdo. décimo.1 Orden 1/2/1996 (documentos contables): «El documento de control de pagos a justificar será autorizado por el jefe de la Unidad Central a la que esté adscrita la respectiva caja pagadora.»","Apdo. vigésimo tercero.1.a Orden 1/2/1996 (documentos contables): «Documento CA de “Certificaciones anticipadas”: Se utilizará para el registro de certificaciones de obra que se extiendan y aprueben excediendo del importe de la anualidad en curso»","Regla 2.2 Orden 1/2/1996 (operatoria contable): «las oficinas de contabilidad no tomarán razón de las operaciones, procediendo a devolver a los Servicios gestores los correspondientes documentos contables electrónicos»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Ámbito y soporte de los documentos contables: electrónicos, firma y sello electrónico","blocks":[{"text":"Este tema estudia dos normas de la misma fecha: la Orden de 1 de febrero de 1996 que aprueba los documentos contables de la Administración General del Estado (aquí, «Orden de documentos») y la Orden de igual fecha que aprueba la Instrucción de operatoria contable a seguir en la ejecución del gasto del Estado («Instrucción»). Las dos se han modificado muchas veces (la última reforma que recoge el texto consolidado de la Orden de documentos es la Orden HAC/965/2024) para adaptarlas a la tramitación electrónica en el Sistema de Información Contable (SIC, hoy SIC3). Por eso algunos preceptos conservan expresiones de 1996 (papel, «remitir», remisiones al antiguo texto refundido de la LGP) que hoy deben leerse en clave electrónica. La Orden de documentos se aplica a la Administración General del Estado (apdo. primero).","refs":[{"ref":"Apdo. primero Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Las normas y los documentos contables aprobados en la presente Orden serán de aplicación a la Administración General del Estado."},{"ref":"Regla 2.4 Instrucción de operatoria contable","law":"Orden 1/2/1996 (operatoria contable)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627","quote":"todas las referencias que se realicen en las distintas reglas de esta Instrucción al envío de documentos contables y de sus justificantes a las oficinas de contabilidad, se entenderán referidas a la remisión a dichas oficinas contables de los documentos contables electrónicos acompañados de sus justificantes electrónicos."}]},{"text":"Desde 2020 todos los documentos contables son electrónicos y se ajustan a los modelos y normas de cumplimentación de la Orden y al procedimiento electrónico que fije la IGAE. Solo excepcionalmente, si lo decide la IGAE a propuesta del responsable de la oficina de contabilidad, pueden expedirse en papel (apdo. segundo.2). Se autorizan con firma electrónica de quien tenga la competencia (apdo. tercero.1); los emitidos por actuación administrativa automatizada pueden autenticarse con sello electrónico basado en certificado reconocido o cualificado (apdo. tercero.2), y el formato de firma y sello es XAdES (apdo. tercero.3).","refs":[{"ref":"Apdo. segundo.2 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Todos los documentos contables serán electrónicos y se ajustarán a los modelos y normas de cumplimentación previstos en esta Orden, así como al procedimiento de tramitación electrónica que establezca la Intervención General de la Administración del Estado. No obstante, cuando por circunstancias excepcionales así lo determine la Intervención General de la Administración del Estado a propuesta del responsable de la oficina de contabilidad, se podrán expedir documentos contables en papel."},{"ref":"Apdo. tercero.2 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Los documentos contables cuya emisión se realice mediante actuación administrativa automatizada podrán ser autenticados mediante un sistema de sello electrónico de Administración Pública, órgano, organismo público o entidad de derecho público, basado en certificado electrónico reconocido o cualificado"}]},{"text":"Para documentos que incluyen la fase O (reconocimiento de la obligación) hay dos reglas de agrupación: no se pueden mezclar facturas registradas en el Registro Contable de Facturas con otras exceptuadas de él (salvo en ADOK de reposición de anticipos de caja fija), y solo se agrupan varias facturas si la fecha de inicio del cómputo del plazo de pago es la misma para todas (apdo. tercero.4). Una vez registrado cada documento, el sistema genera un justificante electrónico de la toma de razón, con número y fecha de la operación, sellado electrónicamente (apdo. cuarto.3).","refs":[{"ref":"Apdo. tercero.4 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"solo se podrán agrupar varias facturas en un mismo documento contable que incorpore la fase O, cuando la fecha en la que se inicia el cómputo de los plazos para el abono del precio sea la misma para todas ellas."},{"ref":"Apdo. cuarto.3 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"el propio sistema generará y remitirá un justificante electrónico de la toma de razón con los datos de la operación contable, incluyendo el número y fecha de la operación, sellado electrónicamente, para los servicios gestores."}]}]},{"n":"2","title":"Documentos del Presupuesto de Gastos: concepto y agrupaciones","blocks":[{"text":"Son documentos del Presupuesto de Gastos los que sirven de soporte a las anotaciones de operaciones de gestión de créditos y de ejecución del gasto (apdo. quinto.1). Pueden afectar a cuatro agrupaciones: presupuesto corriente, presupuestos cerrados, ejercicios posteriores y tramitación anticipada (apdo. quinto.2). Cada documento lleva el nombre de la fase que registra: A (autorización), D (disposición o compromiso), O (reconocimiento de la obligación) y K (propuesta de pago).","refs":[{"ref":"Apdo. quinto.1 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Son documentos de contabilidad del Presupuesto de Gastos aquellos que sirven de soporte a las anotaciones contables que se realicen como consecuencia de operaciones de gestión de créditos presupuestarios y de ejecución del Presupuesto de Gastos."},{"ref":"Apdo. quinto.2 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Presupuesto corriente. […] Presupuestos cerrados. […] Ejercicios posteriores. […] Tramitación anticipada."}]}]},{"n":"3","title":"Gestión de créditos: documentos MC, RC y RC-102","blocks":[{"text":"El documento MC se usa en las modificaciones presupuestarias que aumentan o disminuyen créditos, y el documento de desglose, para desglosar aplicaciones presupuestarias (apdo. sexto.1.a y b). El documento RC de ejercicio corriente sirve para solicitar el certificado de existencia y retención de crédito en expedientes de gasto, de transferencias, de bajas por anulación y otras minoraciones, de retención adicional del 10 % de la adjudicación y de retención por el porcentaje cultural. Para los acuerdos de no disponibilidad hay un documento específico, el RC-102, y para el presupuesto del cajero de anticipos de caja fija, el RC-110 (apdo. sexto.1.c).","refs":[{"ref":"Apdo. sexto.1.a Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Documento MC: Se utilizará en las modificaciones presupuestarias que aumenten o disminuyan los créditos."},{"ref":"Apdo. sexto.1.c Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Se utilizará para solicitar certificado de existencia y retención de crédito en los expedientes de gasto, de transferencias, de bajas por anulación y otras minoraciones, de retención adicional del 10 % de la adjudicación"},{"ref":"Apdo. sexto.1.c Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Para el registro de los acuerdos de no disponibilidad se utilizará el documento específico “RC-102” y para el registro del presupuesto del cajero de ACF se utilizará el documento específico “RC-110”."}]},{"text":"Según la Instrucción, al iniciar un expediente de gasto el servicio gestor solicita que se certifique la existencia de crédito disponible y para ello expide un documento RC de retención de créditos para gastar; registrado, el crédito queda retenido y el sistema emite el certificado de existencia de crédito para el expediente (regla 14.1). Cuando el Gobierno acuerda la no disponibilidad, el RC lo expide la Dirección General de Presupuestos; la no disponibilidad no anula el crédito, pero con cargo a él no pueden autorizarse gastos (regla 16).","refs":[{"ref":"Regla 14.1 Instrucción de operatoria contable","law":"Orden 1/2/1996 (operatoria contable)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627","quote":"Para la solicitud del certificado a que se refiere el párrafo anterior, el Servicio Gestor expedirá un documento RC, de retención de créditos para gastar, que remitirá a la oficina de contabilidad."},{"ref":"Regla 16.2 Instrucción de operatoria contable","law":"Orden 1/2/1996 (operatoria contable)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627","quote":"La no disponibilidad de un crédito no conllevará la anulación del mismo, pero con cargo al saldo en situación de no disponible no podrán acordarse autorizaciones de gasto."}]}]},{"n":"4","title":"Fases de ejecución del gasto y sus documentos: A, D, OK y mixtos AD y ADOK","blocks":[{"text":"La Instrucción describe la ejecución del gasto en tres fases contables: autorización, compromiso y reconocimiento de la obligación; la ordenación y el pago se rigen por la orden de procedimientos de pago (regla 20). Aprobado el expediente, el gestor expide un documento A; comprometido el gasto, un documento D (reglas 21 y 22). Para el presupuesto corriente, la Orden prevé el documento A (autorización) y el D (compromiso) de ejercicio corriente (apdo. sexto.1.e y f).","refs":[{"ref":"Regla 20.1 Instrucción de operatoria contable","law":"Orden 1/2/1996 (operatoria contable)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627","quote":"La ejecución de los gastos presupuestarios se realizará en las siguientes fases: a) Autorización del gasto. b) Compromiso del gasto. c) Reconocimiento de la obligación."},{"ref":"Apdo. sexto.1.e y f Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Documento A de ejercicio corriente: Se utilizará en las operaciones de autorización del gasto imputables al Presupuesto corriente. f) Documento D de ejercicio corriente: Se utilizará en las operaciones de compromiso de gasto imputables al Presupuesto corriente."}]},{"text":"Todo reconocimiento de la obligación lleva implícita la propuesta de pago; por eso, acordado el reconocimiento, el gestor expide un documento OK (regla 23.3), que la Orden define como el documento de las operaciones de reconocimiento de obligaciones (apdo. sexto.1.n). Excepcionalmente, en la Deuda Pública se usa el documento O, que reconoce la obligación sin proponer el pago, y después un documento K de propuesta de pago (regla 23.4; apdo. sexto.1.o y p).","refs":[{"ref":"Regla 23.3 Instrucción de operatoria contable","law":"Orden 1/2/1996 (operatoria contable)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627","quote":"todo reconocimiento de la obligación llevará implícita la correspondiente propuesta de pago […] Una vez acordado el reconocimiento de la obligación, el Servicio gestor competente expedirá un documento OK"},{"ref":"Apdo. sexto.1.n y o Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Documento OK: Se utilizará en operaciones de reconocimiento de obligaciones. […] Documento O: Se utilizará exclusivamente en el ámbito de la gestión de la Deuda del Estado, cuando al reconocer la obligación no se proponga el pago."}]},{"text":"Si varias fases se acumulan en un solo acto, producen los mismos efectos que si se hubieran acordado por separado (regla 24.1). Si en un acto único se acuerdan autorización y compromiso, se expide un documento mixto AD; si se acumulan autorización, compromiso y reconocimiento de la obligación, un ADOK (regla 24.2).","refs":[{"ref":"Regla 24.2 Instrucción de operatoria contable","law":"Orden 1/2/1996 (operatoria contable)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627","quote":"cuando la autorización y el compromiso de gasto se acuerdan en un acto único, se expedirá un documento mixto AD. Cuando en un mismo acto se acumulen la autorización del gasto, su compromiso y el reconocimiento de la obligación, se expedirá documento mixto ADOK."}]}]},{"n":"5","title":"Documentos de ejercicios posteriores y de tramitación anticipada; anexos","blocks":[{"text":"Para gastos plurianuales existen documentos RC, A, D y AD de ejercicios posteriores; el RC de ejercicios posteriores sirve para pedir el certificado de cumplimiento de los límites del artículo 47 LGP (apdo. sexto.1.d a j). La regla 19 de la Instrucción aún cita el «artículo 61 del Texto Refundido de la Ley General Presupuestaria», precepto equivalente hoy al artículo 47 de la Ley 47/2003. Para la tramitación anticipada se emplean un RC específico y documentos A, D y AD de tramitación anticipada (apdo. sexto.1.d´, k, l y l´).","refs":[{"ref":"Apdo. sexto.1.d Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Documento RC de ejercicios posteriores: Se utilizará para solicitar el certificado de cumplimiento de los límites que establece el artículo 47 de la Ley 47/2003, de 26 de noviembre, General Presupuestaria"},{"ref":"Apdo. sexto.1.k Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Documento A de tramitación anticipada: Se utilizará en operaciones de autorización de gasto cuando se tramiten anticipadamente."}]},{"text":"Hay además documentos anexos que amplían a otros los principales: el «Anexo anualidades» completa los RC, A, D y AD de ejercicios posteriores y de tramitación anticipada cuando hay más de veinte anualidades futuras; el «Anexo aplicaciones», cuando el documento afecta a varias aplicaciones; el «Anexo descuentos», para OK, ADOK y K con descuentos; y el «Anexo adicional de facturas», cuando un documento con fase O incluye más de dos facturas (apdo. sexto.1.l´´, q, r y x).","refs":[{"ref":"Apdo. sexto.1.l´´ Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Se utilizará para completar los documentos RC, A, D y AD de ejercicios posteriores y de tramitación anticipada mediante la incorporación de uno o más de estos documentos a los anteriores cuando el número de anualidades posteriores previsto sea superior a veinte."},{"ref":"Apdo. sexto.1.x Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"cuando el número de facturas incluidas en el mismo sea superior a dos."}]}]},{"n":"6","title":"Anulaciones y autorización de los documentos de gastos","blocks":[{"text":"Para anular cualquiera de estas operaciones se expide un documento idéntico al que sirvió para registrarla, pero de signo contrario (apdo. sexto.2; regla 26). En cuanto a quién firma, los documentos MC de modificación de créditos y RC-102 de no disponibilidad los autoriza el Director General de Presupuestos (apdo. séptimo.1). Los demás los autoriza el responsable del órgano que gestiona los créditos, con excepciones: los RC de la oficina presupuestaria o de la Dirección General de Presupuestos los autorizan sus responsables, y los RC expedidos de oficio, el jefe de contabilidad (apdo. séptimo.2).","refs":[{"ref":"Apdo. sexto.2 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"se expedirá un documento idéntico al confeccionado para el registro de la operación en cuestión pero de signo contrario."},{"ref":"Apdo. séptimo.1 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Los documentos MC de «modificación de créditos» y RC-102 de «no disponibilidad» serán autorizados por el Director General de Presupuestos."},{"ref":"Apdo. séptimo.2 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"de documentos RC expedidos de oficio, que se autorizarán por el jefe de contabilidad"}]}]},{"n":"7","title":"Pagos a justificar y anticipos de caja fija","blocks":[{"text":"Los documentos de pagos a justificar y de anticipos de caja fija son los que soportan los registros en esos dos subsistemas (apdo. octavo). Son el documento de control de pagos a justificar (prórrogas de plazos, presentación y aprobación de la cuenta justificativa), el de adopción/distribución de anticipos de caja fija (establecimiento del sistema y reparto entre cajas pagadoras), el de distribución por conceptos (opcional, para fijar límites por conceptos) y el anexo de control de pagos a justificar para varios reintegros (apdo. noveno).","refs":[{"ref":"Apdo. noveno.a Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Documento de control de pagos a justificar: Se utilizará para el registro de las prórrogas autorizadas de los plazos de justificación, para el registro de la presentación de la cuenta justificativa y para el registro de la aprobación de la cuenta justificativa."}]},{"text":"El documento de control de pagos a justificar lo autoriza el jefe de la unidad central a la que está adscrita la caja pagadora; los de adopción/distribución y de distribución por conceptos, la autoridad que adoptó el acuerdo (apdo. décimo). La reposición de fondos de un anticipo de caja fija se contabiliza con un documento ADOK que acompaña a la cuenta justificativa (regla 36).","refs":[{"ref":"Apdo. décimo.1 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"El documento de control de pagos a justificar será autorizado por el jefe de la Unidad Central a la que esté adscrita la respectiva caja pagadora."},{"ref":"Regla 36 Instrucción de operatoria contable","law":"Orden 1/2/1996 (operatoria contable)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627","quote":"La aplicación a presupuesto de los gastos realizados con cargo al anticipo de caja fija y la propuesta de reposición de fondos al Cajero Pagador se contabilizarán mediante documento ADOK"}]}]},{"n":"8","title":"Presupuesto de Ingresos, operaciones no presupuestarias y otros documentos: CA y operaciones devengadas","blocks":[{"text":"El Presupuesto de Ingresos solo tiene dos agrupaciones, corriente y cerrados (apdo. decimoquinto.2). Sus documentos incluyen resúmenes contables, órdenes de cobro de departamentos, instrumentos de cobro, propuestas de mandamiento de pago por devolución de ingresos y no presupuestarias y la hoja de arqueo del Banco de España, que autoriza el jefe de contabilidad (apdos. decimosexto y decimoséptimo). Los anticipos de Tesorería usan el documento I, que autoriza el Director General de Presupuestos (apdos. undécimo y decimocuarto); la Orden aún se remite al «artículo 65 del texto refundido» de la LGP, hoy derogado.","refs":[{"ref":"Apdo. decimoquinto.2 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Los documentos del Presupuesto de Ingresos pueden afectar a las siguientes agrupaciones: Presupuesto corriente. Presupuestos cerrados."},{"ref":"Apdo. decimocuarto.1 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"El documento I de concesión del Anticipo de Tesorería será autorizado por el Director general de Presupuestos."}]},{"text":"Entre los «otros documentos», el CA de certificaciones anticipadas registra las certificaciones de obra que exceden de la anualidad en curso y su cesión; el de «Operaciones devengadas» registra a 31 de diciembre lo devengado y no contabilizado; y el documento soporte de asientos directos recoge operaciones sin otro documento propio (apdo. vigésimo tercero). El CA lo autoriza el gestor de los créditos, y el de operaciones devengadas, el jefe de contabilidad (apdo. vigésimo cuarto). Según la Instrucción, lo devengado y no reconocido en el ejercicio debe quedar registrado con OK o ADOK hasta el 30 de abril del ejercicio siguiente, con contrapartida en la cuenta 413 (regla 52.1).","refs":[{"ref":"Apdo. vigésimo tercero.1.a Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Documento CA de “Certificaciones anticipadas”: Se utilizará para el registro de certificaciones de obra que se extiendan y aprueben excediendo del importe de la anualidad en curso"},{"ref":"Apdo. vigésimo cuarto.2 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"El documento de operaciones devengadas y el de rectificación de operaciones devengadas serán autorizados por el jefe de contabilidad."}]}]},{"n":"9","title":"Toma de razón por las oficinas de contabilidad","blocks":[{"text":"Toda operación de gestión de gastos entra en el sistema de información contable mediante uno o más documentos contables electrónicos, que los servicios gestores envían firmados a la oficina de contabilidad del departamento (regla 2.1). La oficina no toma razón y devuelve los documentos en tres casos: si faltan documentos o no contienen todos los requisitos o datos; si no se acompaña la justificación exigida; o si la información es incoherente con los datos ya introducidos o incompatible con las validaciones del sistema (regla 2.2). Los gestores deben expedir y enviar los documentos en el plazo más breve posible desde que se dictó el acto (regla 2.3).","refs":[{"ref":"Regla 2.2 Instrucción de operatoria contable","law":"Orden 1/2/1996 (operatoria contable)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627","quote":"las oficinas de contabilidad no tomarán razón de las operaciones, procediendo a devolver a los Servicios gestores los correspondientes documentos contables electrónicos: a) Cuando no se hayan recibido todos los documentos que se precisen para el registro de la operación en cuestión, o bien cuando los documentos no contengan todos los requisitos o datos exigidos."},{"ref":"Regla 2.2.c) Instrucción de operatoria contable","law":"Orden 1/2/1996 (operatoria contable)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627","quote":"c) Cuando la información a incorporar al sistema sea incoherente con los datos anteriormente introducidos, o incompatible con las validaciones requeridas por el mismo."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Todos los documentos contables son electrónicos; el papel solo es posible excepcionalmente, si lo decide la IGAE.","refs":[{"ref":"Apdo. segundo.2 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Todos los documentos contables serán electrónicos"}]},{"text":"Agrupaciones del Presupuesto de Gastos: corriente, cerrados, ejercicios posteriores y tramitación anticipada.","refs":[{"ref":"Apdo. quinto.2 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Ejercicios posteriores. Tramitación anticipada."}]},{"text":"RC: retención de crédito; RC-102: no disponibilidad; MC: modificación de créditos.","refs":[{"ref":"Apdo. sexto.1.a Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Documento MC: Se utilizará en las modificaciones presupuestarias que aumenten o disminuyan los créditos."}]},{"text":"MC y RC-102 los autoriza el Director General de Presupuestos.","refs":[{"ref":"Apdo. séptimo.1 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"serán autorizados por el Director General de Presupuestos."}]},{"text":"AD = autorización y compromiso en un acto; ADOK = autorización, compromiso y reconocimiento de la obligación en un acto.","refs":[{"ref":"Regla 24.2 Instrucción de operatoria contable","law":"Orden 1/2/1996 (operatoria contable)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627","quote":"se expedirá documento mixto ADOK."}]},{"text":"El OK lleva implícita la propuesta de pago; el O (sin propuesta de pago) es exclusivo de la Deuda del Estado.","refs":[{"ref":"Apdo. sexto.1.o Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"Documento O: Se utilizará exclusivamente en el ámbito de la gestión de la Deuda del Estado"}]},{"text":"Anular = documento idéntico de signo contrario.","refs":[{"ref":"Apdo. sexto.2 Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"pero de signo contrario."}]},{"text":"«Anexo anualidades»: cuando hay más de veinte anualidades posteriores.","refs":[{"ref":"Apdo. sexto.1.l´´ Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"cuando el número de anualidades posteriores previsto sea superior a veinte."}]},{"text":"CA: certificaciones de obra que exceden de la anualidad en curso.","refs":[{"ref":"Apdo. vigésimo tercero.1.a Orden 1-2-1996 documentos contables","law":"Orden 1/2/1996 (documentos contables)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749","quote":"excediendo del importe de la anualidad en curso"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749', null, null, null, 'Otras normas citadas: Orden 1/2/1996 (operatoria contable) (https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627)'
  from public.topics t where t.slug = 'age-adm-53-documentos-contables'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 47/2003, de 26 de noviembre, General Presupuestaria (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-53-ejecucion-gasto', 'V.3 Ejecución del gasto, ordenación del pago y control. El Tribunal de Cuentas') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-53-ejecucion-gasto' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El procedimiento de ejecución del presupuesto de gasto: fases (art. 73 LGP)"},{"n":"2","title":"Órganos competentes en la gestión de gastos (art. 74 LGP)"},{"n":"3","title":"Compromisos de gasto para ejercicios posteriores (arts. 47, 47 bis y disposición adicional decimonovena LGP)"},{"n":"4","title":"La ordenación del pago: concepto y competencia (arts. 75 y 107 LGP)"},{"n":"5","title":"Realización del pago: modos y perceptores (arts. 75.3 y 110 LGP)"},{"n":"6","title":"Control del gasto público: control externo e interno (art. 140 LGP)"},{"n":"6.1","title":"Clases de control interno: función interventora, control financiero permanente y auditoría pública (arts. 142-166 LGP)"},{"n":"6.2","title":"El control de legalidad: fiscalización previa, reparos, discrepancias y omisión de fiscalización (arts. 148-156 LGP)"},{"n":"7","title":"El Tribunal de Cuentas y la Cuenta General del Estado (art. 136 CE; arts. 131-132 LGP)"},{"n":"8","title":"Responsabilidades por infracción de la Ley General Presupuestaria (arts. 176-180 LGP)"}]'::jsonb, '["Art. 73.1 Ley 47/2003: «a) Aprobación del gasto. b) Compromiso de gasto. c) Reconocimiento de la obligación. d) Ordenación del pago. e) Pago material.»","Art. 74.1 Ley 47/2003: «Corresponde a los Ministros y a los titulares de los demás órganos del Estado con dotaciones diferenciadas en los Presupuestos Generales del Estado aprobar y comprometer los gastos propios de sus presupuestos, salvo los casos reservados por la Ley a la competencia del Consejo de Ministros, así como reconocer las obligaciones económicas correspondientes, e interesar del Ordenador general de pagos del Estado la realización de los correspondientes pagos.»","Art. 47.1 Ley 47/2003: «Podrán adquirirse compromisos de gastos que hayan de extenderse a ejercicios posteriores a aquel en que se autoricen, siempre que su ejecución se inicie en el propio ejercicio y que no superen los límites y anualidades fijados en el número siguiente.»","Art. 75.1 Ley 47/2003: «Bajo la superior autoridad del Ministro de Economía, competen al Director General del Tesoro y Política Financiera las funciones de Ordenador General de pagos del Estado.»","Art. 75.3 Ley 47/2003: «Las órdenes de pago se expedirán a favor del acreedor que figura en la correspondiente propuesta de pago»","Art. 107 Ley 47/2003: «El Ordenador de Pagos aplicará criterios objetivos en la expedición de las órdenes de pago, tales como la fecha de recepción, el importe de la operación, la aplicación presupuestaria y la forma de pago, entre otros.»","Art. 110 Ley 47/2003: «los ingresos y los pagos de la Administración General del Estado y sus organismos autónomos podrán realizarse mediante transferencia bancaria, cheque, efectivo o cualesquiera otros medios de pago, sean o no bancarios.»","Art. 140 Ley 47/2003: «1. En su condición de supremo órgano fiscalizador de las cuentas y de la gestión económica del Estado y del sector público, corresponde al Tribunal de Cuentas el control externo del sector público estatal, en los términos establecidos en la Constitución, en su ley orgánica y en las demás leyes que regulen su competencia. 2. La Intervención General de la Administración del Estado ejercerá en los términos previstos en esta ley el control interno de la gestión económica y financiera del sector público estatal, con plena autonomía respecto de las autoridades y demás entidades cuya gestión controle.»","Art. 142.2 Ley 47/2003: «El control se realizará mediante el ejercicio de la función interventora, el control financiero permanente y la auditoría pública, a que se refieren los capítulos II, III y IV de este título.»","Art. 148 Ley 47/2003: «La función interventora tiene por objeto controlar, antes de que sean aprobados, los actos del sector público estatal que den lugar al reconocimiento de derechos o a la realización de gastos, así como los ingresos y pagos que de ellos se deriven, y la inversión o aplicación en general de sus fondos públicos, con el fin de asegurar que su gestión se ajuste a las disposiciones aplicables en cada caso.»","Art. 154.1 Ley 47/2003: «Si la Intervención, al realizar la fiscalización o intervención, se manifiesta en desacuerdo con el contenido de los actos examinados o con el procedimiento seguido para su adopción, deberá formular sus reparos por escrito, con cita de los preceptos legales en los que sustente su criterio. La formulación del reparo suspenderá la tramitación del expediente hasta que sea solventado»","Art. 157 Ley 47/2003: «El control financiero permanente se ejercerá en los órganos y entidades establecidos en el artículo siguiente y tendrá por objeto la verificación de una forma continua realizada a través de la correspondiente intervención delegada, de la situación y el funcionamiento de las entidades del sector público estatal en el aspecto económico-financiero»","Art. 162 Ley 47/2003: «La auditoría pública consistirá en la verificación, realizada con posterioridad y efectuada de forma sistemática, de la actividad económico-financiera del sector público estatal, mediante la aplicación de los procedimientos de revisión selectivos contenidos en las normas de auditoría e instrucciones que dicte la Intervención General de la Administración del Estado.»","Art. 136.1 CE: «El Tribunal de Cuentas es el supremo órgano fiscalizador de las cuentas y de la gestión económica de Estado, así como del sector público. Dependerá directamente de las Cortes Generales y ejercerá sus funciones por delegación de ellas en el examen y comprobación de la Cuenta General del Estado.»","Art. 132 Ley 47/2003: «El Tribunal de Cuentas, por delegación de las Cortes Generales, procederá al examen y comprobación de la Cuenta General del Estado dentro del plazo de seis meses a partir de la fecha en que las haya recibido. El Pleno, oído el Fiscal, dictará la declaración definitiva que le merezca para elevarla a las Cámaras con la oportuna propuesta, dando traslado al Gobierno.»","Art. 176 Ley 47/2003: «Las autoridades y demás personal al servicio de las entidades contempladas en el artículo 2 de esta ley que por dolo o culpa graves adopten resoluciones o realicen actos con infracción de las disposiciones de esta ley, estarán obligados a indemnizar a la Hacienda Pública estatal o, en su caso, a la respectiva entidad los daños y perjuicios que sean consecuencia de aquellos, con independencia de la responsabilidad penal o disciplinaria que les pueda corresponder.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El procedimiento de ejecución del presupuesto de gasto: fases","blocks":[{"text":"La Ley General Presupuestaria (LGP) ordena la gestión del presupuesto de gastos del Estado, de sus organismos autónomos, de las entidades del sector público estatal con presupuesto limitativo y de las entidades gestoras y servicios comunes de la Seguridad Social en cinco fases sucesivas: aprobación del gasto, compromiso de gasto, reconocimiento de la obligación, ordenación del pago y pago material (art. 73.1 LGP). Conviene memorizar el orden, porque cada fase presupone la anterior y en examen suele preguntarse cuál es la primera, cuál vincula ya a terceros y cuál declara la deuda.","refs":[{"ref":"Art. 73.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"se realizará a través de las siguientes fases: a) Aprobación del gasto. b) Compromiso de gasto. c) Reconocimiento de la obligación. d) Ordenación del pago. e) Pago material."}]},{"text":"La aprobación es el acto que autoriza un gasto determinado por una cuantía cierta o aproximada y reserva para ello todo o parte de un crédito; inicia el procedimiento, pero no crea relaciones con terceros ajenos a la Hacienda Pública (art. 73.2 LGP). El compromiso acuerda, tras los trámites legales, la realización de gastos ya aprobados por un importe determinado o determinable, y sí tiene relevancia jurídica frente a terceros, pues vincula a la Hacienda en la cuantía y condiciones establecidas (art. 73.3 LGP).","refs":[{"ref":"Art. 73.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La aprobación es el acto mediante el cual se autoriza la realización de un gasto determinado por una cuantía cierta o aproximada, reservando a tal fin la totalidad o parte de un crédito presupuestario. La aprobación inicia el procedimiento de ejecución del gasto, sin que implique relaciones con terceros ajenos a la Hacienda Pública estatal o a la Seguridad Social."},{"ref":"Art. 73.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El compromiso es un acto con relevancia jurídica para con terceros, vinculando a la Hacienda Pública estatal o a la Seguridad Social a la realización del gasto a que se refiera en la cuantía y condiciones establecidas."}]},{"text":"El reconocimiento de la obligación declara la existencia de un crédito exigible contra la Hacienda Pública, derivado de un gasto aprobado y comprometido, y comporta la propuesta de pago. Solo puede hacerse previa acreditación documental de que la prestación se ha realizado o de que existe el derecho del acreedor (art. 73.4 LGP). Las obligaciones se extinguen por el pago, la compensación, la prescripción u otros medios legales (art. 73.6 LGP). Por último, cuando la naturaleza de la operación lo determine, las fases precisas se acumulan en un solo acto: la ley no permite suprimir fases ni alterar su orden, solo acumularlas (art. 73.7 LGP).","refs":[{"ref":"Art. 73.4 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El reconocimiento de la obligación es el acto mediante el que se declara la existencia de un crédito exigible contra la Hacienda Pública estatal o contra la Seguridad Social, derivado de un gasto aprobado y comprometido y que comporta la propuesta de pago correspondiente."},{"ref":"Art. 73.7 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Cuando la naturaleza de la operación o gasto así lo determinen, se acumularán en un solo acto las fases de ejecución precisas."}]}]},{"n":"2","title":"Órganos competentes en la gestión de gastos","blocks":[{"text":"Corresponde a los Ministros y a los titulares de los demás órganos del Estado con dotaciones diferenciadas en los Presupuestos Generales del Estado aprobar y comprometer los gastos de sus presupuestos (salvo los reservados por ley al Consejo de Ministros), reconocer las obligaciones e interesar del Ordenador general de pagos del Estado que se realicen los pagos (art. 74.1 LGP). Los Ministros pueden fijar límites por debajo de los cuales estas competencias pasan a los Secretarios de Estado y al Subsecretario. En los organismos autónomos y entidades con presupuesto limitativo, la aprobación, el compromiso, el reconocimiento y el pago corresponden a sus presidentes o directores (art. 74.2 LGP).","refs":[{"ref":"Art. 74.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Corresponde a los Ministros y a los titulares de los demás órganos del Estado con dotaciones diferenciadas en los Presupuestos Generales del Estado aprobar y comprometer los gastos propios de sus presupuestos, salvo los casos reservados por la Ley a la competencia del Consejo de Ministros, así como reconocer las obligaciones económicas correspondientes, e interesar del Ordenador general de pagos del Estado la realización de los correspondientes pagos."},{"ref":"Art. 74.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"compete a los presidentes o directores de los organismos autónomos del Estado y a los de las entidades integrantes del sector público estatal con presupuesto limitativo la aprobación y compromiso del gasto, así como el reconocimiento y el pago de las obligaciones."}]},{"text":"Estas facultades pueden desconcentrarse por real decreto acordado en Consejo de Ministros o delegarse según el reglamento (art. 74.4 LGP). Un dato numérico frecuente: los órganos competentes para suscribir convenios o contratos-programa necesitan autorización del Consejo de Ministros cuando el gasto que derive de ellos supere doce millones de euros; esa autorización implica la aprobación del gasto, y antes de suscribir cualquier convenio debe tramitarse el expediente de gasto (art. 74.5 LGP).","refs":[{"ref":"Art. 74.5 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"necesitarán autorización del Consejo de Ministros cuando el importe del gasto que de aquellos se derive sea superior a doce millones de euros."},{"ref":"Art. 74.5 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La autorización del Consejo de Ministros implicará la aprobación del gasto que se derive del convenio o contrato-programa."}]}]},{"n":"3","title":"Compromisos de gasto para ejercicios posteriores","blocks":[{"text":"Como regla, pueden adquirirse compromisos que se extiendan a ejercicios posteriores si su ejecución empieza en el propio ejercicio y se respetan los límites legales (art. 47.1 LGP). El número de ejercicios no puede superar cuatro, y el gasto de cada ejercicio futuro no puede exceder, sobre el crédito inicial, el 70 % en el inmediato siguiente, el 60 % en el segundo y el 50 % en el tercero y el cuarto. En los contratos de obra plurianuales (salvo abono total del precio) se retiene además un 10 % del importe de adjudicación, que computa dentro de esos porcentajes. Los límites no se aplican a la carga financiera de la Deuda ni a los arrendamientos de inmuebles (art. 47.2 LGP).","refs":[{"ref":"Art. 47.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Podrán adquirirse compromisos de gastos que hayan de extenderse a ejercicios posteriores a aquel en que se autoricen, siempre que su ejecución se inicie en el propio ejercicio y que no superen los límites y anualidades fijados en el número siguiente."},{"ref":"Art. 47.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El número de ejercicios a que pueden aplicarse los gastos no será superior a cuatro. El gasto que se impute a cada uno de los ejercicios posteriores no podrá exceder de la cantidad que resulte de aplicar al crédito inicial a que corresponda la operación los siguientes porcentajes: en el ejercicio inmediato siguiente, el 70 por ciento, en el segundo ejercicio, el 60 por ciento, y en los ejercicios tercero y cuarto, el 50 por ciento."}]},{"text":"El Gobierno, en casos especialmente justificados, puede modificar los porcentajes, aumentar las anualidades o autorizar compromisos sin crédito inicial, a propuesta del Ministro de Hacienda (art. 47.3 LGP). En la tramitación anticipada de contratos, encargos a medios propios y convenios se puede llegar incluso a la adjudicación y formalización aunque la ejecución empiece en ejercicios posteriores (art. 47.6 LGP).","refs":[{"ref":"Art. 47.6 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En el caso de la tramitación anticipada de expedientes de contratación a que se refiere el artículo 117.2 de la Ley de Contratos del Sector Público, de encargos a medios propios y de convenios, podrá ultimarse incluso con la adjudicación y formalización del correspondiente contrato, la formalización del encargo o la suscripción del convenio, aun cuando su ejecución, ya sea en una o en varias anualidades, deba iniciarse en ejercicios posteriores."}]},{"text":"Si en un ejercicio posterior la ley de presupuestos no da crédito suficiente para un compromiso plurianual, el artículo 47 bis LGP fija tres pasos: el órgano competente comunica la circunstancia al tercero en cuanto la conozca; si los créditos lo permiten, se reprograman las obligaciones con reajuste de anualidades; y si no es posible, se resuelve el negocio fijando las compensaciones procedentes. La disposición adicional decimonovena LGP regula la imputación: las anualidades se imputan a los créditos del nuevo presupuesto y, si no hay crédito, la oficina de contabilidad da al servicio gestor treinta días para comunicar qué hará; si no responde, registra de oficio retenciones de crédito.","refs":[{"ref":"Art. 47 bis LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"1.º) El órgano competente para aprobar y comprometer el gasto estará obligado a comunicar tal circunstancia al tercero, tan pronto como se tenga conocimiento de ello."},{"ref":"Disp. adic. 19.ª.1 y 5 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las anualidades que correspondan al ejercicio que se inicia de compromisos de gasto de carácter plurianual contabilizados en años anteriores se imputarán a los créditos autorizados en el presupuesto de dicho ejercicio. […] dicha oficina de contabilidad procederá a registrar de oficio las retenciones de crédito por un importe igual al de dichas operaciones."}]}]},{"n":"4","title":"La ordenación del pago: concepto y competencia","blocks":[{"text":"La ordenación del pago es la cuarta fase: el acto por el que se expide la orden de pago contra el Tesoro. Bajo la superior autoridad del Ministro de Economía, las funciones de Ordenador General de pagos del Estado corresponden al Director General del Tesoro y Política Financiera; en la Seguridad Social, al Director General de la Tesorería General de la Seguridad Social (art. 75.1 y 2 LGP). Ojo: el texto consolidado conserva las denominaciones ministeriales originales de 2003 («Ministro de Economía», «Ministro de Trabajo y Asuntos Sociales»), que hoy corresponden a los departamentos que asuman esas competencias.","refs":[{"ref":"Art. 75.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Bajo la superior autoridad del Ministro de Economía, competen al Director General del Tesoro y Política Financiera las funciones de Ordenador General de pagos del Estado."},{"ref":"Art. 75.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"competen al Director General de la Tesorería General de la Seguridad Social las funciones de Ordenador general de pagos de las Entidades gestoras y Servicios comunes de la Seguridad Social."}]},{"text":"Al expedir las órdenes de pago, el Ordenador debe aplicar criterios objetivos, como la fecha de recepción, el importe, la aplicación presupuestaria y la forma de pago, entre otros (art. 107 LGP). Las providencias de embargo y actos análogos sobre derechos de cobro pagaderos por la Ordenación de Pagos del Estado se comunican necesariamente a la Dirección General del Tesoro y Política Financiera (art. 76 LGP).","refs":[{"ref":"Art. 107 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El Ordenador de Pagos aplicará criterios objetivos en la expedición de las órdenes de pago, tales como la fecha de recepción, el importe de la operación, la aplicación presupuestaria y la forma de pago, entre otros."}]}]},{"n":"5","title":"Realización del pago: modos y perceptores","blocks":[{"text":"Las órdenes de pago se expiden a favor del acreedor que figura en la propuesta de pago. Por Orden ministerial pueden regularse supuestos en que se expidan a favor de habilitaciones, cajas pagadoras o depositarías de fondos, entidades colaboradoras de subvenciones y otros agentes mediadores, que actúan como intermediarios para entregar después los fondos a los acreedores (art. 75.3 LGP). En cuanto a los medios, los ingresos y pagos de la Administración General del Estado y sus organismos autónomos pueden hacerse por transferencia bancaria, cheque, efectivo o cualquier otro medio, bancario o no, y puede limitarse el uso a ciertos medios para determinados pagos (art. 110 LGP).","refs":[{"ref":"Art. 75.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las órdenes de pago se expedirán a favor del acreedor que figura en la correspondiente propuesta de pago si bien, por Orden del Ministro de Economía, se podrán regular los supuestos en que puedan expedirse a favor de Habilitaciones, Cajas pagadoras o Depositarías de fondos"},{"ref":"Art. 110 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"los ingresos y los pagos de la Administración General del Estado y sus organismos autónomos podrán realizarse mediante transferencia bancaria, cheque, efectivo o cualesquiera otros medios de pago, sean o no bancarios."}]}]},{"n":"6","title":"Control del gasto público: control externo e interno","blocks":[{"text":"El control de la gestión económico-financiera del sector público estatal tiene dos planos. El control externo corresponde al Tribunal de Cuentas, como supremo órgano fiscalizador de las cuentas y de la gestión económica del Estado y del sector público. El control interno lo ejerce la Intervención General de la Administración del Estado (IGAE), con plena autonomía respecto de las autoridades y entidades cuya gestión controla (art. 140 LGP). El control interno lo ejerce la IGAE sobre todo el sector público estatal, por sus servicios centrales o sus Intervenciones Delegadas; en Defensa y en la Seguridad Social, a través de la Intervención General de la Defensa y de la Intervención General de la Seguridad Social, que dependen funcionalmente de la IGAE (art. 143 LGP).","refs":[{"ref":"Art. 140.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En su condición de supremo órgano fiscalizador de las cuentas y de la gestión económica del Estado y del sector público, corresponde al Tribunal de Cuentas el control externo del sector público estatal"},{"ref":"Art. 140.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La Intervención General de la Administración del Estado ejercerá en los términos previstos en esta ley el control interno de la gestión económica y financiera del sector público estatal, con plena autonomía respecto de las autoridades y demás entidades cuya gestión controle."},{"ref":"Art. 143 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En el ámbito del Ministerio de Defensa y de la Seguridad Social, el control se ejercerá, respectivamente a través de la Intervención General de la Defensa, y de la Intervención General de la Seguridad Social, dependientes funcionalmente, a estos efectos, de la Intervención General de la Administración del Estado."}]},{"text":"Los objetivos del control interno son verificar el cumplimiento de la normativa, verificar el adecuado registro y contabilización de las operaciones, evaluar la gestión conforme a los principios de buena gestión financiera y verificar el cumplimiento de los objetivos asignados a los centros gestores (art. 142.1 LGP).","refs":[{"ref":"Art. 142.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) Verificar el cumplimiento de la normativa que resulte de aplicación a la gestión objeto del control."}]}]},{"n":"6.1","title":"Clases de control interno: función interventora, control financiero permanente y auditoría pública","blocks":[{"text":"El control interno se ejerce mediante tres instrumentos: la función interventora, el control financiero permanente y la auditoría pública (art. 142.2 LGP). La función interventora controla, antes de que se aprueben, los actos que reconocen derechos o generan gastos, así como los ingresos y pagos derivados y la aplicación de los fondos públicos (art. 148 LGP). Se ejerce por la IGAE y sus interventores delegados sobre la Administración General del Estado, los organismos autónomos y las entidades gestoras y servicios comunes de la Seguridad Social; el Consejo de Ministros puede sustituirla motivadamente por control financiero permanente (art. 149 LGP).","refs":[{"ref":"Art. 142.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El control se realizará mediante el ejercicio de la función interventora, el control financiero permanente y la auditoría pública, a que se refieren los capítulos II, III y IV de este título."},{"ref":"Art. 148 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La función interventora tiene por objeto controlar, antes de que sean aprobados, los actos del sector público estatal que den lugar al reconocimiento de derechos o a la realización de gastos, así como los ingresos y pagos que de ellos se deriven"}]},{"text":"El control financiero permanente verifica de forma continua, a través de la intervención delegada, la situación y el funcionamiento económico-financiero de las entidades, el cumplimiento de la normativa y la buena gestión financiera, en especial el objetivo de estabilidad presupuestaria (art. 157 LGP). La auditoría pública es una verificación posterior y sistemática de la actividad económico-financiera mediante procedimientos de revisión selectivos (art. 162 LGP). Tiene tres modalidades: de regularidad contable, de cumplimiento y operativa; esta última es el examen sistemático y objetivo de operaciones y procedimientos para valorar con independencia su racionalidad económico-financiera y su adecuación a la buena gestión (art. 164.1 LGP).","refs":[{"ref":"Art. 157 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"tendrá por objeto la verificación de una forma continua realizada a través de la correspondiente intervención delegada, de la situación y el funcionamiento de las entidades del sector público estatal en el aspecto económico-financiero"},{"ref":"Art. 162 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La auditoría pública consistirá en la verificación, realizada con posterioridad y efectuada de forma sistemática, de la actividad económico-financiera del sector público estatal"},{"ref":"Art. 164.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"c) La auditoría operativa, que constituye el examen sistemático y objetivo de las operaciones y procedimientos de una organización, programa, actividad o función pública, con el objeto de proporcionar una valoración independiente de su racionalidad económico-financiera y su adecuación a los principios de la buena gestión"}]}]},{"n":"6.2","title":"El control de legalidad: fiscalización previa, reparos, discrepancias y omisión de fiscalización","blocks":[{"text":"La función interventora tiene una modalidad formal (examen de los documentos preceptivos del expediente) y otra material (comprobación de la real y efectiva aplicación de los fondos) (art. 150.1 LGP). Comprende cuatro momentos: la fiscalización previa de los actos que reconocen derechos, aprueban gastos, comprometen gastos o acuerdan movimientos de fondos; la intervención del reconocimiento de las obligaciones y de la comprobación de la inversión; la intervención formal de la ordenación del pago; y la intervención material del pago (art. 150.2 LGP).","refs":[{"ref":"Art. 150.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) La fiscalización previa de los actos que reconozcan derechos de contenido económico, aprueben gastos, adquieran compromisos de gasto, o acuerden movimientos de fondos y valores. b) La intervención del reconocimiento de las obligaciones y de la comprobación de la inversión. c) La intervención formal de la ordenación del pago. d) La intervención material del pago."}]},{"text":"No se someten a fiscalización previa, entre otros, los contratos menores, los gastos periódicos y de tracto sucesivo tras fiscalizar el periodo inicial, los gastos menores de 5.000 euros pagados por anticipo de caja fija, los de procesos electorales, las subvenciones nominativas, ciertos contratos de bases de datos y publicaciones y los de emergencia (art. 151 LGP). El Consejo de Ministros puede limitar la fiscalización a requisitos básicos, como la existencia de crédito adecuado y suficiente y la competencia del órgano (art. 152 LGP).","refs":[{"ref":"Art. 151.a) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"No estarán sometidos a la fiscalización previa prevista en el apartado 2.a) del artículo anterior: a) los contratos menores así como los asimilados a ellos en virtud de la legislación contractual;"},{"ref":"Art. 152.1.a) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) La existencia de crédito presupuestario y que el propuesto es el adecuado y suficiente a la naturaleza del gasto u obligación que se proponga contraer."}]},{"text":"Si la Intervención discrepa del acto o del procedimiento, formula reparo por escrito citando los preceptos en que se apoya; el reparo suspende la tramitación hasta que se subsanen las deficiencias o se resuelva la discrepancia (art. 154.1 LGP). Si el gestor no lo acepta, plantea discrepancia motivada: la resuelve la IGAE cuando el reparo es de una intervención delegada, y el Consejo de Ministros cuando el reparo es de la propia IGAE o esta lo ha confirmado (art. 155 LGP). Cuando se omite una fiscalización preceptiva, no puede reconocerse la obligación ni pagarse hasta subsanarlo; la Intervención emite un informe (que no es fiscalización) y el titular del departamento, sin posibilidad de delegar, decide si somete el asunto al Consejo de Ministros, cuyo acuerdo favorable no exime de responsabilidades (art. 156 LGP).","refs":[{"ref":"Art. 154.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La formulación del reparo suspenderá la tramitación del expediente hasta que sea solventado, bien por la subsanación de las deficiencias observadas o bien, en el caso de no aceptación del reparo, por la resolución del procedimiento previsto en el artículo siguiente."},{"ref":"Art. 155.b) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"b) Cuando el reparo haya sido formulado por la Intervención General de la Administración del Estado o este centro directivo haya confirmado el de otra Intervención General o delegada, subsistiendo la discrepancia, corresponderá al Consejo de Ministros adoptar resolución definitiva."},{"ref":"Art. 156.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Corresponderá al titular del departamento al que pertenezca el órgano responsable de la tramitación del expediente o al que esté adscrito el organismo autónomo, sin que dicha competencia pueda ser objeto de delegación, acordar, en su caso, el sometimiento del asunto al Consejo de Ministros para que adopte la resolución procedente."}]}]},{"n":"7","title":"El Tribunal de Cuentas y la Cuenta General del Estado","blocks":[{"text":"La Constitución define al Tribunal de Cuentas como supremo órgano fiscalizador de las cuentas y de la gestión económica del Estado y del sector público. Depende directamente de las Cortes Generales y ejerce sus funciones por delegación de ellas al examinar y comprobar la Cuenta General del Estado (art. 136.1 CE). Las cuentas del Estado y del sector público estatal se le rinden y son censuradas por él, y remite a las Cortes un informe anual con las infracciones o responsabilidades apreciadas (art. 136.2 CE).","refs":[{"ref":"Art. 136.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Tribunal de Cuentas es el supremo órgano fiscalizador de las cuentas y de la gestión económica de Estado, así como del sector público. Dependerá directamente de las Cortes Generales y ejercerá sus funciones por delegación de ellas en el examen y comprobación de la Cuenta General del Estado."},{"ref":"Art. 136.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Las cuentas del Estado y del sector público estatal se rendirán al Tribunal de Cuentas y serán censuradas por éste."}]},{"text":"La Cuenta General del Estado la forma la IGAE y se eleva al Gobierno para su remisión al Tribunal de Cuentas antes del 31 de octubre del año siguiente al que se refiere (art. 131.1 LGP). El Tribunal la examina y comprueba en el plazo de seis meses desde que la recibe; el Pleno, oído el Fiscal, dicta la declaración definitiva y la eleva a las Cámaras con la oportuna propuesta, dando traslado al Gobierno (art. 132 LGP).","refs":[{"ref":"Arts. 131.1 y 132 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La Cuenta General del Estado de cada año se formará por la Intervención General de la Administración del Estado y se elevará al Gobierno para su remisión al Tribunal de Cuentas antes del día 31 de octubre del año siguiente al que se refiera. […] El Tribunal de Cuentas, por delegación de las Cortes Generales, procederá al examen y comprobación de la Cuenta General del Estado dentro del plazo de seis meses a partir de la fecha en que las haya recibido. El Pleno, oído el Fiscal, dictará la declaración definitiva que le merezca para elevarla a las Cámaras con la oportuna propuesta, dando traslado al Gobierno."}]}]},{"n":"8","title":"Responsabilidades por infracción de la Ley General Presupuestaria","blocks":[{"text":"Las autoridades y el personal que, con dolo o culpa grave, adopten resoluciones o realicen actos que infrinjan la LGP deben indemnizar a la Hacienda Pública los daños y perjuicios causados, con independencia de su responsabilidad penal o disciplinaria (art. 176 LGP). Son infracciones, entre otras: incurrir en alcance o malversación, comprometer gastos u ordenar pagos sin crédito suficiente, dar lugar a pagos reintegrables y no justificar los fondos de anticipos de caja fija y pagos a justificar (art. 177.1 LGP).","refs":[{"ref":"Art. 176 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las autoridades y demás personal al servicio de las entidades contempladas en el artículo 2 de esta ley que por dolo o culpa graves adopten resoluciones o realicen actos con infracción de las disposiciones de esta ley, estarán obligados a indemnizar a la Hacienda Pública estatal"},{"ref":"Art. 177.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"c) Comprometer gastos, liquidar obligaciones y ordenar pagos sin crédito suficiente para realizarlos o con infracción de lo dispuesto en esta ley o en la de Presupuestos que sea aplicable."}]},{"text":"Con dolo se responde de todos los daños que conocidamente deriven del acto; con culpa grave, solo de los que sean consecuencia necesaria. La responsabilidad es mancomunada, salvo en caso de dolo, que es solidaria (art. 178 LGP). También responden los interventores y ordenadores de pago que no hayan salvado su actuación mediante observación escrita (art. 179 LGP). El alcance o malversación lo exige el Tribunal de Cuentas por el procedimiento de reintegro por alcance; los demás supuestos, un expediente administrativo resuelto por el Gobierno (si el responsable es autoridad) o por el Ministro de Hacienda, recurrible ante la Sala de Justicia del Tribunal de Cuentas en dos meses (art. 180 LGP).","refs":[{"ref":"Art. 178.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"La responsabilidad de quienes hayan participado en la resolución o en el acto será mancomunada, excepto en los casos de dolo, que será solidaria."},{"ref":"Art. 180.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"la responsabilidad será exigida por el Tribunal de Cuentas mediante el oportuno procedimiento de reintegro por alcance"},{"ref":"Art. 180.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Dicha resolución será recurrible ante la Sala de Justicia del Tribunal de Cuentas en el plazo de dos meses contados desde el día siguiente al de su notificación."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Cinco fases del gasto, en orden: aprobación, compromiso, reconocimiento de la obligación, ordenación del pago y pago material; pueden acumularse en un solo acto.","refs":[{"ref":"Art. 73.7 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"se acumularán en un solo acto las fases de ejecución precisas."}]},{"text":"El compromiso es la primera fase que vincula a terceros; la aprobación no.","refs":[{"ref":"Art. 73.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El compromiso es un acto con relevancia jurídica para con terceros"}]},{"text":"Plurianuales: máximo cuatro ejercicios y porcentajes del 70, 60, 50 y 50 %.","refs":[{"ref":"Art. 47.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El número de ejercicios a que pueden aplicarse los gastos no será superior a cuatro."}]},{"text":"Convenios o contratos-programa de más de doce millones de euros: autorización del Consejo de Ministros.","refs":[{"ref":"Art. 74.5 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"cuando el importe del gasto que de aquellos se derive sea superior a doce millones de euros."}]},{"text":"Ordenador General de pagos del Estado: el Director General del Tesoro y Política Financiera.","refs":[{"ref":"Art. 75.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"competen al Director General del Tesoro y Política Financiera las funciones de Ordenador General de pagos del Estado."}]},{"text":"Control interno (IGAE): función interventora, control financiero permanente y auditoría pública. Control externo: Tribunal de Cuentas.","refs":[{"ref":"Art. 142.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El control se realizará mediante el ejercicio de la función interventora, el control financiero permanente y la auditoría pública"}]},{"text":"El reparo suspende la tramitación; discrepancia con reparo de la IGAE: resuelve el Consejo de Ministros.","refs":[{"ref":"Art. 155.b) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"corresponderá al Consejo de Ministros adoptar resolución definitiva."}]},{"text":"Cuenta General: al Tribunal de Cuentas antes del 31 de octubre del año siguiente; examen en seis meses.","refs":[{"ref":"Art. 131.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"antes del día 31 de octubre del año siguiente al que se refiera."}]},{"text":"Responsabilidad mancomunada en culpa grave y solidaria en caso de dolo.","refs":[{"ref":"Art. 178.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"excepto en los casos de dolo, que será solidaria."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614', null, null, null, 'Otras normas citadas: CE (https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229)'
