insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Clasificación económica del gasto: operaciones corrientes, de capital y financieras (art. 40.1.c) LGP)"},{"n":"1.1","title":"Gastos para la compra de bienes y servicios y gastos de transferencias corrientes"},{"n":"1.2","title":"Gastos de inversión y transferencias de capital; inversiones con pago aplazado (arts. 47.2 y 48 LGP)"},{"n":"2","title":"Pagos: concepto y tipos. Pagos por obligaciones presupuestarias (arts. 73, 75 y 77 LGP)"},{"n":"3","title":"Anticipos de caja fija: concepto, límites y gestión (art. 78 LGP; RD 725/1989)"},{"n":"3.1","title":"Situación y disposición de los fondos (arts. 4 y 6 RD 725/1989)"},{"n":"3.2","title":"Reposición de fondos, rendición de cuentas y control (arts. 7-9 RD 725/1989)"},{"n":"4","title":"Pagos «a justificar» (art. 79 LGP)"},{"n":"5","title":"Justificación de libramientos y control: fiscalización e intervención (arts. 151 y 153 LGP)"},{"n":"6","title":"Responsabilidad por falta de justificación (arts. 177 y 182 LGP)"}]'::jsonb, '["Art. 40.1.c) Ley 47/2003: «En los créditos para operaciones corrientes se distinguirán los gastos de personal, los gastos corrientes en bienes y servicios, los gastos financieros y las transferencias corrientes. En los créditos para operaciones de capital se distinguirán las inversiones reales y las transferencias de capital.»","Art. 48.1 Ley 47/2003: «Podrá ser diferido el vencimiento de la obligación de pago del precio de compra de bienes inmuebles adquiridos directamente cuyo importe exceda de seis millones de euros, sin que, en ningún caso, el desembolso inicial a la firma de la escritura pueda ser inferior al 25 por ciento del precio»","Art. 77.1 Ley 47/2003: «A los efectos de esta Ley se entiende por pago indebido el que se realiza por error material, aritmético o de hecho, en favor de persona en quien no concurra derecho alguno de cobro frente a la Administración con respecto a dicho pago o en cuantía que excede de la consignada en el acto o documento que reconoció el derecho del acreedor.»","Art. 78.1 Ley 47/2003: «Se entienden por anticipos de caja fija las provisiones de fondos de carácter extrapresupuestario y permanente que se realicen a pagadurías, cajas y habilitaciones para la atención inmediata y posterior aplicación al capítulo de gastos corrientes en bienes y servicios del presupuesto del año en que se realicen, de gastos periódicos o repetitivos.»","Art. 78.3 Ley 47/2003: «En todo caso, la cuantía global de los anticipos de caja fija no podrá superar para cada ministerio u organismo autónomo el siete por ciento del total de créditos del capítulo destinado a gastos corrientes en bienes y servicios del presupuesto vigente en cada momento.»","Art. 1 RD 725/1989: «como los referentes a dietas, gastos de locomoción, material no inventariable, conservación, tracto sucesivo y otros de similares características.»","Art. 2.3 RD 725/1989: «no podrán realizarse con cargo al anticipo de caja fija pagos individualizados superiores a 5.000 euros (831.930 pesetas), excepto los destinados a gastos de teléfono, energía eléctrica, combustibles o indemnizaciones por razón del servicio.»","Art. 4.3 RD 725/1989: «Los fondos librados conforme a lo previsto en este Real Decreto tendrán, en todo caso, el carácter de fondos públicos y formarán parte integrante del Tesoro Público.»","Art. 7.1 RD 725/1989: «Los Cajeros pagadores rendirán cuentas por los gastos atendidos con anticipos de Caja fija a medida que sus necesidades de tesorería aconsejen la reposición de los fondos utilizados y, necesariamente, en el mes de diciembre de cada año.»","Art. 79.1 Ley 47/2003: «Cuando, excepcionalmente, no pueda aportarse la documentación justificativa de las obligaciones en el momento previsto en el apartado 4 del artículo 73, podrán tramitarse propuestas de pagos presupuestarios y librarse fondos con el carácter de a justificar. Asimismo, podrá procederse a la expedición de libramientos a justificar cuando los servicios y prestaciones a que se refieran hayan tenido o vayan a tener lugar en el extranjero.»","Art. 79.3 Ley 47/2003: «En todo caso, la cantidad no invertida de los libramientos en el ejercicio en que se aprobaran los mismos, será justificada mediante carta de pago demostrativa de su reintegro al tesoro público por el cajero pagador correspondiente.»","Art. 79.4 Ley 47/2003: «Los perceptores de estas órdenes de pago a justificar quedan obligados a rendir cuenta justificativa de la aplicación de las cantidades recibidas. El plazo de rendición de las cuentas será de tres meses, excepto las correspondientes a pagos de expropiaciones y pagos en el extranjero que podrán ser rendidas en el plazo de seis meses.»","Art. 79.6 Ley 47/2003: «En el curso de los dos meses siguientes a la fecha de aportación de los documentos justificativos a que se refieren los apartados anteriores de este artículo, se llevará a cabo la aprobación o reparo de la cuenta por la autoridad competente.»","Art. 151.c) Ley 47/2003: «c) los gastos menores de 5.000 euros cuyo pago se realice mediante el procedimiento especial de anticipo de caja fija, regulado en el artículo 78 de esta Ley;»","Art. 177.1.e) Ley 47/2003: «e) No justificar la inversión de los fondos a los que se refieren los artículos 78 y 79 de esta ley y la Ley General de Subvenciones.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Clasificación económica del gasto: operaciones corrientes, de capital y financieras","blocks":[{"text":"Los estados de gastos de los Presupuestos Generales del Estado se ordenan con tres clasificaciones: orgánica (quién gasta), por programas (para qué) y económica (en qué) (art. 40.1 LGP). La clasificación económica agrupa los créditos por capítulos y separa las operaciones corrientes, las de capital, las financieras y el Fondo de Contingencia (art. 40.1.c LGP). Los capítulos se desglosan en artículos, estos en conceptos y estos, a su vez, pueden dividirse en subconceptos. Además, los créditos se identifican funcionalmente según su finalidad, lo que da lugar a la clasificación funcional (art. 40.2 LGP).","refs":[{"ref":"Art. 40.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"c) La clasificación económica, que agrupará los créditos por capítulos separando las operaciones corrientes, las de capital, las financieras y el Fondo de Contingencia de ejecución presupuestaria."},{"ref":"Art. 40.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Los capítulos se desglosarán en artículos y estos, a su vez, en conceptos que podrán dividirse en subconceptos."}]},{"text":"Dentro de cada bloque, la ley precisa los tipos de gasto. Operaciones corrientes: gastos de personal, gastos corrientes en bienes y servicios, gastos financieros y transferencias corrientes. Operaciones de capital: inversiones reales y transferencias de capital. Operaciones financieras: activos financieros y pasivos financieros. El Fondo de Contingencia atiende necesidades imprevistas según el artículo 50 LGP. La numeración concreta de los capítulos (1 a 9) y la definición detallada de cada artículo y concepto no están en la LGP, sino en la orden anual de elaboración de los presupuestos y en la resolución de códigos de la Dirección General de Presupuestos, que no figuran entre las fuentes de este tema.","refs":[{"ref":"Art. 40.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En los créditos para operaciones corrientes se distinguirán los gastos de personal, los gastos corrientes en bienes y servicios, los gastos financieros y las transferencias corrientes. En los créditos para operaciones de capital se distinguirán las inversiones reales y las transferencias de capital."},{"ref":"Art. 40.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En los créditos para operaciones financieras se distinguirán las de activos financieros y las de pasivos financieros."}]}]},{"n":"1.1","title":"Gastos para la compra de bienes y servicios y gastos de transferencias corrientes","blocks":[{"text":"Los gastos corrientes en bienes y servicios son los que la Administración realiza para funcionar sin aumentar su patrimonio. La normativa de anticipos de caja fija da ejemplos típicos de gastos periódicos o repetitivos de este capítulo: dietas, gastos de locomoción, material no inventariable, conservación y gastos de tracto sucesivo (art. 1 RD 725/1989). Las transferencias corrientes, en cambio, son entregas de fondos sin contraprestación para financiar operaciones corrientes del perceptor; las de capital financian sus inversiones. La LGP solo las distingue por su nombre en el artículo 40, y sus definiciones precisas se encuentran en las normas de elaboración del presupuesto, no incluidas aquí.","refs":[{"ref":"Art. 1 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"de gastos periódicos o repetitivos, como los referentes a dietas, gastos de locomoción, material no inventariable, conservación, tracto sucesivo y otros de similares características."},{"ref":"Art. 40.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"los gastos corrientes en bienes y servicios, los gastos financieros y las transferencias corrientes."}]}]},{"n":"1.2","title":"Gastos de inversión y transferencias de capital; inversiones con pago aplazado","blocks":[{"text":"Las inversiones suelen ser plurianuales y se rigen por el artículo 47 LGP: máximo cuatro ejercicios y límites del 70, 60, 50 y 50 % del crédito inicial. En los contratos de obra plurianuales, salvo los de abono total del precio, se retiene además un 10 % del importe de adjudicación en el momento de adjudicar, que se aplica al ejercicio en que termina la obra o al siguiente y computa dentro de los porcentajes (art. 47.2 LGP).","refs":[{"ref":"Art. 47.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En los contratos de obra de carácter plurianual, con excepción de los realizados bajo la modalidad de abono total del precio, se efectuará una retención adicional de crédito del 10 por ciento del importe de adjudicación, en el momento en que ésta se realice."}]},{"text":"El pago aplazado se admite en la compra directa de inmuebles de más de seis millones de euros: el desembolso inicial al firmar la escritura no puede ser inferior al 25 % del precio, y el resto puede repartirse en los cuatro ejercicios siguientes respetando los porcentajes del artículo 47 (art. 48.1 LGP). Los contratos de obra bajo la modalidad de abono total se someten también al procedimiento del artículo 47 (art. 48.2 LGP).","refs":[{"ref":"Art. 48.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Podrá ser diferido el vencimiento de la obligación de pago del precio de compra de bienes inmuebles adquiridos directamente cuyo importe exceda de seis millones de euros, sin que, en ningún caso, el desembolso inicial a la firma de la escritura pueda ser inferior al 25 por ciento del precio, pudiendo distribuirse el resto en los cuatro ejercicios siguientes dentro de las limitaciones porcentuales contenidas en el artículo 47 de esta ley."}]}]},{"n":"2","title":"Pagos: concepto y tipos. Pagos por obligaciones presupuestarias","blocks":[{"text":"El pago es la culminación de la ejecución del gasto: tras aprobar, comprometer y reconocer la obligación, se ordena el pago y se realiza el pago material (art. 73.1 LGP). Regla general: el pago es «en firme», contra una obligación ya reconocida, lo que exige acreditar antes documentalmente la prestación o el derecho del acreedor (art. 73.4 LGP). Las órdenes de pago se expiden a favor del acreedor de la propuesta, aunque pueden expedirse a favor de habilitaciones o cajas pagadoras que entregan luego los fondos (art. 75.3 LGP). Frente a esa regla hay dos sistemas especiales: los anticipos de caja fija, que son extrapresupuestarios, y los pagos «a justificar», que son presupuestarios pero se justifican después.","refs":[{"ref":"Art. 73.4 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El reconocimiento de obligaciones con cargo a la Hacienda Pública estatal se producirá previa acreditación documental ante el órgano competente de la realización de la prestación o el derecho del acreedor"},{"ref":"Art. 75.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las órdenes de pago se expedirán a favor del acreedor que figura en la correspondiente propuesta de pago"}]},{"text":"El pago indebido es el que se realiza por error material, aritmético o de hecho a quien no tiene derecho de cobro o por cuantía superior a la reconocida (art. 77.1 LGP). Quien lo recibe debe restituirlo, y el órgano que cometió el error dispone de oficio y de inmediato su reintegro (art. 77.2 LGP), con el interés previsto en el artículo 17 LGP (art. 77.4). Otros reintegros se revisan por los procedimientos de revisión de oficio; la ley aún cita la Ley 30/1992, hoy sustituida por la Ley 39/2015 (art. 77.3).","refs":[{"ref":"Art. 77.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"A los efectos de esta Ley se entiende por pago indebido el que se realiza por error material, aritmético o de hecho, en favor de persona en quien no concurra derecho alguno de cobro frente a la Administración con respecto a dicho pago o en cuantía que excede de la consignada en el acto o documento que reconoció el derecho del acreedor."},{"ref":"Art. 77.2 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El perceptor de un pago indebido total o parcial queda obligado a su restitución."}]}]},{"n":"3","title":"Anticipos de caja fija: concepto, límites y gestión","blocks":[{"text":"Los anticipos de caja fija (ACF) son provisiones de fondos extrapresupuestarias y permanentes a pagadurías, cajas y habilitaciones para atender de inmediato gastos periódicos o repetitivos, que después se aplican al capítulo de gastos corrientes en bienes y servicios del presupuesto del año (art. 78.1 LGP; art. 1 RD 725/1989). No son pagos a justificar. Las normas de cada ministerio u organismo autónomo las dictan sus titulares, previo informe de su Intervención Delegada (art. 78.1 LGP), y los acuerdos de distribución por cajas requieren informe favorable del Interventor delegado, limitado a comprobar que se respeta el 7 % (art. 3.2 RD 725/1989).","refs":[{"ref":"Art. 1 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"Se entienden por anticipos de Caja fija las provisiones de fondos de carácter extrapresupuestario y permanente que se realicen a Pagadurías, Cajas y Habilitaciones para la atención inmediata y posterior aplicación al capítulo de gastos corrientes en bienes y servicios del presupuesto del año en que se realicen"},{"ref":"Art. 3.2 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"Los citados acuerdos habrán de ser objeto de informe favorable del Interventor delegado respectivo, circunscrito a que se respete el citado límite del 7 por 100."}]},{"text":"Límites que caen en examen: la cuantía global de los ACF no puede superar en cada ministerio u organismo autónomo el 7 % de los créditos del capítulo de gastos corrientes en bienes y servicios vigente; la AECID puede llegar al 14 % (art. 78.3 LGP). Con cargo al anticipo no se hacen pagos individualizados de más de 5.000 euros, salvo teléfono, electricidad, combustibles e indemnizaciones por razón del servicio, y no se pueden acumular gastos diversos en un justificante ni fraccionar un gasto. Establecido el sistema, no pueden tramitarse libramientos presupuestarios a perceptores directos por menos de 600 euros en esos conceptos (art. 2.3 RD 725/1989).","refs":[{"ref":"Art. 78.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En todo caso, la cuantía global de los anticipos de caja fija no podrá superar para cada ministerio u organismo autónomo el siete por ciento del total de créditos del capítulo destinado a gastos corrientes en bienes y servicios del presupuesto vigente en cada momento. Se autoriza a la Agencia Española de Cooperación Internacional para que la cuantía global de los anticipos de caja fija pueda exceder del siete por ciento previsto en este artículo, hasta un máximo del 14 por ciento"},{"ref":"Art. 2.3 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"no podrán realizarse con cargo al anticipo de caja fija pagos individualizados superiores a 5.000 euros (831.930 pesetas), excepto los destinados a gastos de teléfono, energía eléctrica, combustibles o indemnizaciones por razón del servicio. A efectos de aplicación de estos límites, no podrán acumularse en un solo justificante pagos que se deriven de diversos gastos, ni fraccionarse un único gasto en varios pagos."},{"ref":"Art. 2.3 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"no podrán tramitarse libramientos aplicados al presupuesto a favor de perceptores directos, excepto los destinados a reposición del anticipo, por importe inferior a 600 euros (99.832 pesetas)"}]}]},{"n":"3.1","title":"Situación y disposición de los fondos","blocks":[{"text":"Los fondos se ingresan por transferencia en cuentas de las cajas pagadoras en el Banco de España, agrupación «Tesoro Público. Provisión de Fondos», y si hay causa pueden situarse en entidades de crédito con autorización (art. 4.1 y 4.2 RD 725/1989; esa autorización se remite al artículo 119 del antiguo texto refundido de la LGP, hoy derogado). Son siempre fondos públicos que forman parte del Tesoro Público (art. 4.3). Los gastos siguen su tramitación y el «Páguese» del órgano de gestión debe figurar al menos en las facturas o justificantes (art. 5).","refs":[{"ref":"Art. 4.3 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"Los fondos librados conforme a lo previsto en este Real Decreto tendrán, en todo caso, el carácter de fondos públicos y formarán parte integrante del Tesoro Público."},{"ref":"Art. 5 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"El «Páguese» del Órgano de gestión correspondiente, dirigido al cajero, deberá figurar, como mínimo, en las facturas, recibos o cualquier otro justificante que refleje la reclamación o derecho del acreedor."}]},{"text":"Se dispone de los fondos mediante cheques nominativos o transferencias con firmas mancomunadas del cajero pagador y del funcionario que designe el jefe de la unidad; una misma persona no puede hacer ambas sustituciones (art. 6.1). Pueden autorizarse efectivo en caja para imprevistos y gastos menores, bajo custodia del cajero, y subcajas dependientes de una caja central (art. 6.2), y excepcionalmente, tarjeta bancaria (art. 6.3).","refs":[{"ref":"Art. 6.1 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"Las disposiciones de fondos de las cuentas a que se refiere el artículo 4.° se efectuarán mediante cheques nominativos o transferencias bancarias, autorizados con las firmas mancomunadas del Cajero pagador y del funcionario que designe el Jefe de la Unidad Administrativa a la que esté adscrita la Caja pagadora o de los sustitutos de los mismos."}]}]},{"n":"3.2","title":"Reposición de fondos, rendición de cuentas y control","blocks":[{"text":"Los cajeros rinden cuentas a medida que necesitan reponer fondos y, necesariamente, en diciembre de cada año (art. 7.1 RD 725/1989). Las aprueba el jefe de la unidad a la que está adscrita la caja, y con lo justificado se expiden documentos de ejecución del presupuesto a favor del cajero con cargo a las aplicaciones de los gastos (art. 7.2 y 7.3). La Intervención delegada examina las cuentas, incluso por muestreo, y emite informe; si señala defectos, el gestor tiene quince días para alegar o subsanar antes de remitir la cuenta al Tribunal de Cuentas (art. 7.4).","refs":[{"ref":"Art. 7.1 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"Los Cajeros pagadores rendirán cuentas por los gastos atendidos con anticipos de Caja fija a medida que sus necesidades de tesorería aconsejen la reposición de los fondos utilizados y, necesariamente, en el mes de diciembre de cada año."},{"ref":"Art. 7.4 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"Caso de que en el informe se hagan constar defectos o anomalías, el Órgano gestor, en un plazo de quince días, realizará las alegaciones que estime oportunas, y, en su caso, las subsanará, dejando constancia de ello en la cuenta, antes de su remisión al Tribunal de Cuentas."}]},{"text":"Las cajas llevan contabilidad auxiliar separada de los anticipos (art. 8.1). Como mínimo, en las primeras quincenas de enero, abril, julio y octubre, referidos al último día del trimestre anterior, se formulan estados de situación de tesorería, con copia al Interventor delegado; los interventores pueden hacer comprobaciones en cualquier momento (art. 9).","refs":[{"ref":"Art. 9.1 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"como mínimo, en las primeras quincenas de los meses de enero, abril, julio y octubre y referidos al último día del trimestre inmediato anterior se formularán estados de situación de Tesorería"}]}]},{"n":"4","title":"Pagos «a justificar»","blocks":[{"text":"Cuando, excepcionalmente, no puede aportarse la documentación justificativa al reconocer la obligación, pueden librarse fondos «a justificar»; también si los servicios se prestan en el extranjero (art. 79.1 LGP) o en localidades sin dependencia del ministerio u organismo (art. 79.2). Solo pueden imputarse obligaciones del ejercicio del libramiento; toda propuesta incluye un calendario de actuaciones, y lo no invertido en el ejercicio se justifica con la carta de pago de su reintegro al Tesoro (art. 79.3 LGP). La regulación reglamentaria de desarrollo (Real Decreto 640/1987) no figura entre las fuentes de este tema.","refs":[{"ref":"Art. 79.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Cuando, excepcionalmente, no pueda aportarse la documentación justificativa de las obligaciones en el momento previsto en el apartado 4 del artículo 73, podrán tramitarse propuestas de pagos presupuestarios y librarse fondos con el carácter de a justificar."},{"ref":"Art. 79.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En todo caso, la cantidad no invertida de los libramientos en el ejercicio en que se aprobaran los mismos, será justificada mediante carta de pago demostrativa de su reintegro al tesoro público por el cajero pagador correspondiente."}]},{"text":"Los perceptores deben rendir cuenta justificativa en tres meses, o seis en expropiaciones y pagos en el extranjero; excepcionalmente, el Ministro u órgano delegado puede ampliar estos plazos a seis y doce meses (art. 79.4 LGP). Responden de la custodia y uso de los fondos y de la rendición de la cuenta (art. 79.5), y la cuenta se aprueba o repara en los dos meses siguientes a la aportación de los justificantes (art. 79.6 LGP).","refs":[{"ref":"Art. 79.4 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El plazo de rendición de las cuentas será de tres meses, excepto las correspondientes a pagos de expropiaciones y pagos en el extranjero que podrán ser rendidas en el plazo de seis meses."},{"ref":"Art. 79.6 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En el curso de los dos meses siguientes a la fecha de aportación de los documentos justificativos a que se refieren los apartados anteriores de este artículo, se llevará a cabo la aprobación o reparo de la cuenta por la autoridad competente."}]}]},{"n":"5","title":"Justificación de libramientos y control: fiscalización e intervención","blocks":[{"text":"Los requisitos de la fiscalización previa de las órdenes de pago a justificar, de la constitución o modificación de los ACF y de sus reposiciones, y el procedimiento de intervención de sus cuentas, se fijan reglamentariamente (art. 153 LGP). No están sometidos a fiscalización previa los gastos menores de 5.000 euros pagados por ACF, ni los menores de 5.000 euros con fondos a justificar si se prestan en el extranjero (art. 151 LGP).","refs":[{"ref":"Art. 153 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Reglamentariamente se determinarán los requisitos a verificar en la fiscalización previa de las órdenes de pagos a justificar y en la constitución o modificación de los anticipos de caja fija y de sus reposiciones de fondos, así como el procedimiento a seguir en la intervención de sus cuentas justificativas."},{"ref":"Art. 151.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"c) los gastos menores de 5.000 euros cuyo pago se realice mediante el procedimiento especial de anticipo de caja fija, regulado en el artículo 78 de esta Ley;"},{"ref":"Art. 151 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Tampoco estarán sometidos a fiscalización previa los gastos menores de 5.000 euros que se realicen con cargo a fondos librados a justificar, cuando los servicios o prestaciones a que se refieran hayan tenido o vayan a tener lugar en territorio extranjero."}]}]},{"n":"6","title":"Responsabilidad por falta de justificación","blocks":[{"text":"No justificar la inversión de los fondos de ACF y pagos a justificar es una infracción de la LGP que obliga a indemnizar a la Hacienda Pública si concurre dolo o culpa grave (arts. 176 y 177.1.e LGP). En cuanto se sepa de la infracción, o venzan los plazos sin justificar los fondos, los jefes de los presuntos responsables y los ordenadores de pagos instruyen diligencias previas, adoptan medidas cautelares y avisan de inmediato al Tribunal de Cuentas o al Ministro de Hacienda (art. 182 LGP). Este supuesto se exige en expediente administrativo, no por reintegro por alcance (art. 180.2 LGP).","refs":[{"ref":"Art. 177.1.e) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"e) No justificar la inversión de los fondos a los que se refieren los artículos 78 y 79 de esta ley y la Ley General de Subvenciones."},{"ref":"Art. 182 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"hayan transcurrido los plazos señalados en los correspondientes artículos de esta ley sin haber sido justificadas las órdenes de pago o los fondos a que el mismo se refiere, los jefes de los presuntos responsables y los ordenadores de pagos, respectivamente, instruirán las diligencias previas"}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Operaciones corrientes: personal, bienes y servicios, gastos financieros y transferencias corrientes.","refs":[{"ref":"Art. 40.1.c) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"En los créditos para operaciones corrientes se distinguirán los gastos de personal"}]},{"text":"Inmuebles de más de seis millones con pago aplazado: al menos el 25 % al firmar y el resto en cuatro ejercicios.","refs":[{"ref":"Art. 48.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"pueda ser inferior al 25 por ciento del precio"}]},{"text":"ACF: extrapresupuestarios y permanentes; tope del 7 % del capítulo de bienes corrientes (14 % la AECID).","refs":[{"ref":"Art. 78.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"hasta un máximo del 14 por ciento"}]},{"text":"Pago individual por ACF: máximo 5.000 euros; libramientos directos por menos de 600 euros, prohibidos.","refs":[{"ref":"Art. 2.3 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"pagos individualizados superiores a 5.000 euros"}]},{"text":"Cuentas de ACF: siempre en diciembre; estados de tesorería en enero, abril, julio y octubre.","refs":[{"ref":"Art. 7.1 RD 725/1989","law":"RD 725/1989","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441","quote":"necesariamente, en el mes de diciembre de cada año."}]},{"text":"A justificar: cuenta en tres meses (seis en expropiaciones y extranjero); aprobación o reparo en dos meses.","refs":[{"ref":"Art. 79.4 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El plazo de rendición de las cuentas será de tres meses"}]},{"text":"No justificar fondos de ACF o a justificar es infracción del artículo 177.1.e LGP.","refs":[{"ref":"Art. 177.1.e) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"No justificar la inversión de los fondos"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614', null, null, null, 'Otras normas citadas: RD 725/1989 (https://www.boe.es/buscar/act.php?id=BOE-A-1989-14441)'
