insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Gestión económica de los contratos: presupuesto base de licitación, valor estimado y precio (arts. 100-102 LCSP)"},{"n":"2","title":"Revisión de precios (arts. 103-105 LCSP)"},{"n":"3","title":"Garantías: provisional y definitiva (arts. 106-111 LCSP)"},{"n":"4","title":"El expediente de gasto en la contratación: crédito, fiscalización y tramitación anticipada (arts. 116-117 LCSP)"},{"n":"5","title":"Pago del precio, abonos a cuenta y cesión de derechos de cobro (arts. 198-200 y 240 LCSP)"},{"n":"6","title":"Gestión económica de las subvenciones: concepto, principios y requisitos (arts. 2, 8 y 9 LGS)"},{"n":"7","title":"Órganos competentes y financiación de la actividad subvencionada (arts. 10 y 19 LGS)"},{"n":"8","title":"Justificación y gastos subvencionables (arts. 30-31 LGS)"},{"n":"9","title":"Aprobación del gasto y pago de la subvención (art. 34 LGS)"},{"n":"10","title":"Reintegro: causas, interés de demora y prescripción (arts. 37-39 y 42 LGS)"}]'::jsonb, '["Art. 100.1 Ley 9/2017: «A los efectos de esta Ley, por presupuesto base de licitación se entenderá el límite máximo de gasto que en virtud del contrato puede comprometer el órgano de contratación, incluido el Impuesto sobre el Valor Añadido, salvo disposición en contrario.»","Art. 102.1 Ley 9/2017: «Los contratos del sector público tendrán siempre un precio cierto, que se abonará al contratista en función de la prestación realmente ejecutada y de acuerdo con lo pactado. En el precio se entenderá incluido el importe a abonar en concepto de Impuesto sobre el Valor Añadido, que en todo caso se indicará como partida independiente.»","Art. 103.5 Ley 9/2017: «Salvo en los contratos de suministro de energía, cuando proceda, la revisión periódica y predeterminada de precios en los contratos del sector público tendrá lugar en los términos establecidos en este capítulo, cuando el contrato se hubiese ejecutado, al menos, en el 20 por ciento de su importe y hubiese transcurrido un año desde su formalización.»","Art. 107.1 Ley 9/2017: «deberán constituir a disposición del órgano de contratación una garantía de un 5 por 100 del precio final ofertado por aquellos, excluido el Impuesto sobre el Valor Añadido.»","Art. 116.3 Ley 9/2017: «Asimismo, deberá incorporarse el certificado de existencia de crédito o, en el caso de entidades del sector público estatal con presupuesto estimativo, documento equivalente que acredite la existencia de financiación, y la fiscalización previa de la intervención, en su caso, en los términos previstos en la Ley 47/2003, de 26 de noviembre, General Presupuestaria.»","Art. 198.4 Ley 9/2017: «La Administración tendrá la obligación de abonar el precio dentro de los treinta días siguientes a la fecha de aprobación de las certificaciones de obra o de los documentos que acrediten la conformidad con lo dispuesto en el contrato de los bienes entregados o servicios prestados»","Art. 240.1 Ley 9/2017: «A los efectos del pago, la Administración expedirá mensualmente, en los primeros diez días siguientes al mes al que correspondan, certificaciones que comprendan la obra ejecutada conforme a proyecto durante dicho período de tiempo»","Art. 2.1 Ley 38/2003: «Se entiende por subvención, a los efectos de esta ley, toda disposición dineraria realizada por cualesquiera de los sujetos contemplados en el artículo 3 de esta ley, a favor de personas públicas o privadas, y que cumpla los siguientes requisitos: a) Que la entrega se realice sin contraprestación directa de los beneficiarios.»","Art. 8.3 Ley 38/2003: «a) Publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación. b) Eficacia en el cumplimiento de los objetivos fijados por la Administración otorgante. c) Eficiencia en la asignación y utilización de los recursos públicos.»","Art. 10.2 Ley 38/2003: «la concesión de subvenciones de cuantía superior a 12 millones de euros requerirá la previa autorización del Consejo de Ministros»","Art. 19.3 Ley 38/2003: «El importe de las subvenciones en ningún caso podrá ser de tal cuantía que, aisladamente o en concurrencia con otras subvenciones, ayudas, ingresos o recursos, supere el coste de la actividad subvencionada.»","Art. 30.1 Ley 38/2003: «La justificación del cumplimiento de las condiciones impuestas y de la consecución de los objetivos previstos en el acto de concesión de la subvención se documentará de la manera que se determine reglamentariamente, pudiendo revestir la forma de cuenta justificativa del gasto realizado o acreditarse dicho gasto por módulos o mediante la presentación de estados contables, según se disponga en la normativa reguladora.»","Art. 34.1-3 Ley 38/2003: «Con carácter previo a la convocatoria de la subvención o a la concesión directa de la misma, deberá efectuarse la aprobación del gasto en los términos previstos en la Ley General Presupuestaria o en las normas presupuestarias de las restantes Administraciones públicas. 2. La resolución de concesión de la subvención conllevará el compromiso del gasto correspondiente. 3. El pago de la subvención se realizará previa justificación, por el beneficiario, de la realización de la actividad, proyecto, objetivo o adopción del comportamiento para el que se concedió en los términos establecidos en la normativa reguladora de la subvención.»","Art. 38.2 Ley 38/2003: «El interés de demora aplicable en materia de subvenciones será el interés legal del dinero incrementado en un 25 por ciento, salvo que la Ley de Presupuestos Generales del Estado establezca otro diferente.»","Art. 39.1 Ley 38/2003: «Prescribirá a los cuatro años el derecho de la Administración a reconocer o liquidar el reintegro.»","Art. 42.4 Ley 38/2003: «El plazo máximo para resolver y notificar la resolución del procedimiento de reintegro será de 12 meses desde la fecha del acuerdo de iniciación.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Gestión económica de los contratos: presupuesto base de licitación, valor estimado y precio","blocks":[{"text":"La Ley 9/2017 (LCSP) maneja tres magnitudes económicas que conviene no confundir. El presupuesto base de licitación es el límite máximo de gasto que el órgano de contratación puede comprometer con el contrato, IVA incluido salvo disposición en contrario (art. 100.1 LCSP), y debe ser adecuado a los precios de mercado y desglosarse en costes directos, indirectos y otros gastos (art. 100.2 LCSP). Es la cifra que se aprueba como gasto y la que limita las ofertas.","refs":[{"ref":"Art. 100.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"por presupuesto base de licitación se entenderá el límite máximo de gasto que en virtud del contrato puede comprometer el órgano de contratación, incluido el Impuesto sobre el Valor Añadido, salvo disposición en contrario."},{"ref":"Art. 100.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"los órganos de contratación cuidarán de que el presupuesto base de licitación sea adecuado a los precios del mercado."}]},{"text":"El valor estimado sirve para decidir el procedimiento y la publicidad. En obras, suministros y servicios es el importe total sin IVA pagadero según las estimaciones del órgano (art. 101.1.a LCSP), y en su cálculo deben incluirse las opciones eventuales y las prórrogas, así como las modificaciones al alza previstas en el pliego (art. 101.2 LCSP). Así, en un servicio de dos años prorrogable un año se toma el importe total sin IVA de los tres años. El método de cálculo no puede elegirse para eludir las normas de adjudicación (art. 101.4 LCSP).","refs":[{"ref":"Art. 101.1.a) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"En el caso de los contratos de obras, suministros y servicios, el órgano de contratación tomará el importe total, sin incluir el Impuesto sobre el Valor Añadido, pagadero según sus estimaciones."},{"ref":"Art. 101.2.a) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Cualquier forma de opción eventual y las eventuales prórrogas del contrato."},{"ref":"Art. 101.4 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La elección del método para calcular el valor estimado no podrá efectuarse con la intención de sustraer el contrato a la aplicación de las normas de adjudicación que correspondan."}]},{"text":"El precio debe ser siempre cierto, se abona según la prestación realmente ejecutada e incluye el IVA, que se indica como partida independiente (art. 102.1 LCSP). Puede fijarse por precios unitarios o a tanto alzado (art. 102.4 LCSP). En los contratos de las Administraciones Públicas está prohibido el pago aplazado del precio, salvo en el arrendamiento financiero, el arrendamiento con opción de compra o cuando esta u otra ley lo autorice expresamente (art. 102.8 LCSP).","refs":[{"ref":"Art. 102.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los contratos del sector público tendrán siempre un precio cierto, que se abonará al contratista en función de la prestación realmente ejecutada y de acuerdo con lo pactado. En el precio se entenderá incluido el importe a abonar en concepto de Impuesto sobre el Valor Añadido, que en todo caso se indicará como partida independiente."},{"ref":"Art. 102.8 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Se prohíbe el pago aplazado del precio en los contratos de las Administraciones Públicas, excepto en los supuestos en que el sistema de pago se establezca mediante la modalidad de arrendamiento financiero o de arrendamiento con opción de compra, así como en los casos en que esta u otra Ley lo autorice expresamente."}]}]},{"n":"2","title":"Revisión de precios","blocks":[{"text":"Los precios solo pueden revisarse de forma periódica y predeterminada (art. 103.1 LCSP). Previa justificación en el expediente, la revisión solo cabe en contratos de obra, de suministro de fabricación de armamento y equipamiento, de suministro de energía y en aquellos cuyo periodo de recuperación de la inversión sea igual o superior a cinco años. Nunca son revisables las amortizaciones, los costes financieros, los gastos generales o de estructura ni el beneficio industrial (art. 103.2 LCSP). El pliego fija la fórmula de revisión, invariable durante la vigencia del contrato (art. 103.4 LCSP).","refs":[{"ref":"Art. 103.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los precios de los contratos del sector público solo podrán ser objeto de revisión periódica y predeterminada en los términos establecidos en este Capítulo."},{"ref":"Art. 103.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"No se considerarán revisables en ningún caso los costes asociados a las amortizaciones, los costes financieros, los gastos generales o de estructura ni el beneficio industrial."},{"ref":"Art. 103.4 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"El pliego de cláusulas administrativas particulares deberá detallar, en tales casos, la fórmula de revisión aplicable, que será invariable durante la vigencia del contrato"}]},{"text":"Salvo en el suministro de energía, la revisión solo opera cuando se ha ejecutado al menos el 20 por ciento del importe y ha pasado un año desde la formalización; ese primer 20 por ciento y lo ejecutado el primer año quedan excluidos (art. 103.5 LCSP). Si el contratista está en mora, se aplican los índices de las fechas previstas en el contrato, salvo que los del periodo real den un coeficiente inferior (art. 104 LCSP). El importe se abona o descuenta de oficio en las certificaciones o pagos parciales (art. 105 LCSP).","refs":[{"ref":"Art. 103.5 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Salvo en los contratos de suministro de energía, cuando proceda, la revisión periódica y predeterminada de precios en los contratos del sector público tendrá lugar en los términos establecidos en este capítulo, cuando el contrato se hubiese ejecutado, al menos, en el 20 por ciento de su importe y hubiese transcurrido un año desde su formalización."},{"ref":"Art. 105 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"El importe de las revisiones que procedan se hará efectivo, de oficio, mediante el abono o descuento correspondiente en las certificaciones o pagos parciales"}]}]},{"n":"3","title":"Garantías: provisional y definitiva","blocks":[{"text":"Por regla general no se exige garantía provisional; solo excepcionalmente, por interés público motivado, para responder del mantenimiento de las ofertas hasta la perfección del contrato (art. 106.1 LCSP). Su importe no puede superar el 3 por 100 del presupuesto base de licitación, IVA excluido (art. 106.2 LCSP), y se devuelve tras la perfección del contrato (art. 106.4 LCSP).","refs":[{"ref":"Art. 106.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"En el procedimiento de contratación no procederá la exigencia de garantía provisional, salvo cuando de forma excepcional el órgano de contratación, por motivos de interés público, lo considere necesario y lo justifique motivadamente en el expediente."},{"ref":"Art. 106.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"que no podrá ser superior a un 3 por 100 del presupuesto base de licitación del contrato, excluido el Impuesto sobre el Valor Añadido"}]},{"text":"Quien presenta la mejor oferta debe constituir una garantía definitiva del 5 por 100 del precio final ofertado, IVA excluido (art. 107.1 LCSP): con una oferta de 200.000 euros sin IVA, la garantía es de 10.000 euros. El pliego puede eximirla justificadamente o añadir una complementaria de hasta otro 5 por 100 (art. 107.2 LCSP). Se presta en efectivo o valores de Deuda Pública, aval o seguro de caución (art. 108.1 LCSP), y responde, entre otros conceptos, de la formalización en plazo, las penalidades y la correcta ejecución (art. 110 LCSP). Aprobada la liquidación y vencido el plazo de garantía sin responsabilidades, la devolución debe acordarse y notificarse en dos meses (art. 111.2 LCSP).","refs":[{"ref":"Art. 107.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"deberán constituir a disposición del órgano de contratación una garantía de un 5 por 100 del precio final ofertado por aquellos, excluido el Impuesto sobre el Valor Añadido."},{"ref":"Art. 110.a)-b) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"a) De la obligación de formalizar el contrato en plazo, de conformidad con lo dispuesto en el artículo 153. b) De las penalidades impuestas al contratista conforme al artículo 192 de la presente Ley."},{"ref":"Art. 111.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"El acuerdo de devolución deberá adoptarse y notificarse al interesado en el plazo de dos meses desde la finalización del plazo de garantía."}]}]},{"n":"4","title":"El expediente de gasto en la contratación","blocks":[{"text":"La contratación está unida al procedimiento de gasto. Al expediente de contratación deben incorporarse el certificado de existencia de crédito (o documento equivalente en entidades estatales con presupuesto estimativo) y la fiscalización previa de la intervención, en su caso, según la Ley General Presupuestaria (art. 116.3 LCSP). La carencia o insuficiencia de crédito es incluso causa de nulidad de pleno derecho, salvo emergencia (art. 39.2.b LCSP).","refs":[{"ref":"Art. 116.3 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Asimismo, deberá incorporarse el certificado de existencia de crédito o, en el caso de entidades del sector público estatal con presupuesto estimativo, documento equivalente que acredite la existencia de financiación, y la fiscalización previa de la intervención, en su caso, en los términos previstos en la Ley 47/2003, de 26 de noviembre, General Presupuestaria."},{"ref":"Art. 39.2.b) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La carencia o insuficiencia de crédito"}]},{"text":"La resolución que aprueba el expediente y abre la adjudicación implica también la aprobación del gasto, salvo excepciones (art. 117.1 LCSP). Cabe la tramitación anticipada: el expediente puede llegar hasta la adjudicación y formalización aunque la ejecución empiece en el ejercicio siguiente, comprometiendo créditos con los límites de las normas presupuestarias (art. 117.2 LCSP).","refs":[{"ref":"Art. 117.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Dicha resolución implicará también la aprobación del gasto"},{"ref":"Art. 117.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Los expedientes de contratación podrán ultimarse incluso con la adjudicación y formalización del correspondiente contrato, aun cuando su ejecución, ya se realice en una o en varias anualidades, deba iniciarse en el ejercicio siguiente."}]}]},{"n":"5","title":"Pago del precio, abonos a cuenta y cesión de derechos de cobro","blocks":[{"text":"El contratista tiene derecho al precio convenido, que puede pagarse total o parcialmente, mediante abonos a cuenta o en cada vencimiento en los contratos de tracto sucesivo (art. 198.1 y 2 LCSP). La Administración debe pagar dentro de los treinta días siguientes a la aprobación de las certificaciones o documentos de conformidad; si se retrasa, debe intereses de demora y la indemnización por costes de cobro (art. 198.4 LCSP). Y debe aprobar esa conformidad dentro de los treinta días siguientes a la entrega o prestación.","refs":[{"ref":"Art. 198.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"El pago del precio podrá hacerse de manera total o parcial, mediante abonos a cuenta o, en el caso de contratos de tracto sucesivo, mediante pago en cada uno de los vencimientos que se hubiesen estipulado."},{"ref":"Art. 198.4 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"La Administración tendrá la obligación de abonar el precio dentro de los treinta días siguientes a la fecha de aprobación de las certificaciones de obra o de los documentos que acrediten la conformidad con lo dispuesto en el contrato de los bienes entregados o servicios prestados"}]},{"text":"Si la demora en el pago supera cuatro meses, el contratista puede suspender el cumplimiento avisando con un mes de antelación; si supera seis meses, puede resolver el contrato y ser resarcido de los perjuicios (art. 198.5 y 6 LCSP). Pasado el plazo de pago, puede reclamar por escrito y, si en un mes no hay respuesta, acudir al contencioso contra la inactividad (art. 199 LCSP). En obras, la Administración expide mensualmente, en los diez primeros días del mes siguiente, certificaciones de la obra ejecutada, que son pagos a cuenta (art. 240.1 LCSP). El contratista puede ceder su derecho de cobro, pero la cesión solo es eficaz frente a la Administración si se le notifica fehacientemente (art. 200 LCSP).","refs":[{"ref":"Art. 198.6 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Si la demora de la Administración fuese superior a seis meses, el contratista tendrá derecho, asimismo, a resolver el contrato y al resarcimiento de los perjuicios que como consecuencia de ello se le originen."},{"ref":"Art. 240.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"A los efectos del pago, la Administración expedirá mensualmente, en los primeros diez días siguientes al mes al que correspondan, certificaciones que comprendan la obra ejecutada conforme a proyecto durante dicho período de tiempo"},{"ref":"Art. 200.2 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"Para que la cesión del derecho de cobro sea efectiva frente a la Administración, será requisito imprescindible la notificación fehaciente a la misma del acuerdo de cesión."}]}]},{"n":"6","title":"Gestión económica de las subvenciones: concepto, principios y requisitos","blocks":[{"text":"La Ley 38/2003, General de Subvenciones (LGS), entiende por subvención la disposición dineraria a favor de personas públicas o privadas, sin contraprestación directa, sujeta al cumplimiento de un objetivo o actividad y destinada a fomentar una finalidad de utilidad pública o interés social (art. 2.1 LGS). Antes de establecerlas debe aprobarse un plan estratégico de subvenciones (art. 8.1 LGS), y su gestión se rige por publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación, eficacia y eficiencia (art. 8.3 LGS).","refs":[{"ref":"Art. 2.1.a) LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"Que la entrega se realice sin contraprestación directa de los beneficiarios."},{"ref":"Art. 8.3 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"a) Publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación. b) Eficacia en el cumplimiento de los objetivos fijados por la Administración otorgante. c) Eficiencia en la asignación y utilización de los recursos públicos."}]},{"text":"Antes de otorgar subvenciones deben aprobarse y publicarse sus bases reguladoras (art. 9.2 y 3 LGS). Además, el otorgamiento exige la competencia del órgano, la existencia de crédito adecuado y suficiente, la tramitación del procedimiento aplicable, la fiscalización previa de los actos de contenido económico y la aprobación del gasto por el órgano competente (art. 9.4 LGS).","refs":[{"ref":"Art. 9.2 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"Con carácter previo al otorgamiento de las subvenciones, deberán aprobarse las normas que establezcan las bases reguladoras de concesión en los términos establecidos en esta ley."},{"ref":"Art. 9.4 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"a) La competencia del órgano administrativo concedente. b) La existencia de crédito adecuado y suficiente para atender las obligaciones de contenido económico que se derivan de la concesión de la subvención."},{"ref":"Art. 9.4.d)-e) LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"d) La fiscalización previa de los actos administrativos de contenido económico, en los términos previstos en las leyes. e) La aprobación del gasto por el órgano competente para ello."}]}]},{"n":"7","title":"Órganos competentes y financiación de la actividad subvencionada","blocks":[{"text":"En la AGE conceden subvenciones los Ministros y Secretarios de Estado, y los presidentes o directores de los organismos dependientes, previa consignación presupuestaria (art. 10.1 LGS). Las de cuantía superior a 12 millones de euros requieren autorización previa del Consejo de Ministros; en concurrencia competitiva, debe obtenerse antes de aprobar la convocatoria, y esa autorización no implica aprobar el gasto (art. 10.2 LGS). Una convocatoria de 15 millones necesita, por tanto, esa autorización antes de aprobarse.","refs":[{"ref":"Art. 10.2 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"la concesión de subvenciones de cuantía superior a 12 millones de euros requerirá la previa autorización del Consejo de Ministros"},{"ref":"Art. 10.2 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"En el caso de subvenciones concedidas en régimen de concurrencia competitiva, la autorización a que se refiere el párrafo anterior deberá obtenerse antes de la aprobación de la convocatoria cuya cuantía supere el citado límite."}]},{"text":"Las bases pueden exigir financiación propia del beneficiario y fijan la compatibilidad con otras ayudas (art. 19.1 y 2 LGS). Pero el importe de las subvenciones nunca puede superar, solo o junto con otras ayudas, ingresos o recursos, el coste de la actividad subvencionada (art. 19.3 LGS); si lo supera, procede reintegrar el exceso con intereses (art. 37.3 LGS).","refs":[{"ref":"Art. 19.3 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"El importe de las subvenciones en ningún caso podrá ser de tal cuantía que, aisladamente o en concurrencia con otras subvenciones, ayudas, ingresos o recursos, supere el coste de la actividad subvencionada."},{"ref":"Art. 37.3 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"procederá el reintegro del exceso obtenido sobre el coste de la actividad subvencionada"}]}]},{"n":"8","title":"Justificación y gastos subvencionables","blocks":[{"text":"La justificación puede hacerse mediante cuenta justificativa del gasto, por módulos o con estados contables (art. 30.1 LGS). Si las bases no fijan el plazo, la cuenta justificativa se presenta como máximo en tres meses desde que termina el plazo para realizar la actividad (art. 30.2 LGS). Los gastos se acreditan con facturas o documentos de valor probatorio equivalente (art. 30.3 LGS), y no justificar o justificar insuficientemente da lugar a reintegro (art. 30.8 LGS).","refs":[{"ref":"Art. 30.1 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"pudiendo revestir la forma de cuenta justificativa del gasto realizado o acreditarse dicho gasto por módulos o mediante la presentación de estados contables"},{"ref":"Art. 30.2 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"su presentación se realizará, como máximo, en el plazo de tres meses desde la finalización del plazo para la realización de la actividad."}]},{"text":"Son subvencionables los gastos que responden de manera indubitada a la naturaleza de la actividad, son estrictamente necesarios y se realizan en plazo, sin superar el valor de mercado (art. 31.1 LGS). Si el gasto supera la cuantía del contrato menor, el beneficiario debe pedir al menos tres ofertas (art. 31.3 LGS); el texto consolidado aún remite a la Ley 30/2007, hoy sustituida por la Ley 9/2017. Nunca son subvencionables los intereses deudores bancarios, los recargos y sanciones ni los gastos judiciales (art. 31.7 LGS).","refs":[{"ref":"Art. 31.1 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"Se consideran gastos subvencionables, a los efectos previstos en esta ley, aquellos que de manera indubitada respondan a la naturaleza de la actividad subvencionada, resulten estrictamente necesarios y se realicen en el plazo establecido por las diferentes bases reguladoras de las subvenciones."},{"ref":"Art. 31.7 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"a) Los intereses deudores de las cuentas bancarias. b) Intereses, recargos y sanciones administrativas y penales. c) Los gastos de procedimientos judiciales."}]}]},{"n":"9","title":"Aprobación del gasto y pago de la subvención","blocks":[{"text":"El gasto se aprueba antes de la convocatoria o de la concesión directa; la resolución de concesión conlleva el compromiso del gasto, y el pago se realiza, como regla, previa justificación de la actividad (art. 34.1 a 3 LGS). Caben pagos a cuenta, según el ritmo de ejecución, y pagos anticipados antes de la justificación, pero esta posibilidad y el régimen de garantías deben preverse expresamente en la normativa reguladora (art. 34.4 LGS). No se paga mientras el beneficiario no esté al corriente de sus obligaciones tributarias y con la Seguridad Social o sea deudor por reintegro (art. 34.5 LGS).","refs":[{"ref":"Art. 34.1-3 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"Con carácter previo a la convocatoria de la subvención o a la concesión directa de la misma, deberá efectuarse la aprobación del gasto en los términos previstos en la Ley General Presupuestaria o en las normas presupuestarias de las restantes Administraciones públicas. 2\\. La resolución de concesión de la subvención conllevará el compromiso del gasto correspondiente."},{"ref":"Art. 34.4 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"También se podrán realizar pagos anticipados que supondrán entregas de fondos con carácter previo a la justificación, como financiación necesaria para poder llevar a cabo las actuaciones inherentes a la subvención. Dicha posibilidad y el régimen de garantías deberán preverse expresamente en la normativa reguladora de la subvención."},{"ref":"Art. 34.5 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"No podrá realizarse el pago de la subvención en tanto el beneficiario no se halle al corriente en el cumplimiento de sus obligaciones tributarias y frente a la Seguridad Social o sea deudor por resolución de procedencia de reintegro."}]}]},{"n":"10","title":"Reintegro: causas, interés de demora y prescripción","blocks":[{"text":"Procede reintegrar lo percibido, con interés de demora desde el pago, entre otros casos, por obtener la subvención falseando condiciones, por incumplir el objetivo o la actividad, por no justificar o justificar insuficientemente y por resistirse a la comprobación y control financiero (art. 37.1 LGS). Las cantidades a reintegrar son ingresos de derecho público (art. 38.1 LGS). El interés de demora es el interés legal del dinero incrementado en un 25 por ciento, salvo que la Ley de Presupuestos Generales del Estado fije otro (art. 38.2 LGS); por eso el tipo concreto puede variar cada año.","refs":[{"ref":"Art. 37.1.a)-c) LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"a) Obtención de la subvención falseando las condiciones requeridas para ello u ocultando aquéllas que lo hubieran impedido. b) Incumplimiento total o parcial del objetivo, de la actividad, del proyecto o la no adopción del comportamiento que fundamentan la concesión de la subvención. c) Incumplimiento de la obligación de justificación o la justificación insuficiente"},{"ref":"Art. 38.2 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"El interés de demora aplicable en materia de subvenciones será el interés legal del dinero incrementado en un 25 por ciento, salvo que la Ley de Presupuestos Generales del Estado establezca otro diferente."}]},{"text":"El derecho a reconocer o liquidar el reintegro prescribe a los cuatro años, contados desde que venció el plazo para presentar la justificación (art. 39.1 y 2 LGS), y se interrumpe por cualquier acción de la Administración con conocimiento formal del beneficiario (art. 39.3 LGS). El procedimiento se inicia de oficio, garantiza la audiencia y debe resolverse y notificarse en 12 meses desde el acuerdo de iniciación; si no, caduca. Su resolución pone fin a la vía administrativa (art. 42 LGS). El art. 42 todavía remite a la Ley 30/1992, derogada; hoy debe entenderse referida a la Ley 39/2015.","refs":[{"ref":"Art. 39.1 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"Prescribirá a los cuatro años el derecho de la Administración a reconocer o liquidar el reintegro."},{"ref":"Art. 39.2.a) LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"Desde el momento en que venció el plazo para presentar la justificación por parte del beneficiario o entidad colaboradora."},{"ref":"Art. 42.4 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"El plazo máximo para resolver y notificar la resolución del procedimiento de reintegro será de 12 meses desde la fecha del acuerdo de iniciación."},{"ref":"Art. 42.5 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"La resolución del procedimiento de reintegro pondrá fin a la vía administrativa."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Presupuesto base de licitación: límite máximo de gasto con IVA; valor estimado: sin IVA y con prórrogas.","refs":[{"ref":"Art. 101.2.a) LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"las eventuales prórrogas del contrato."}]},{"text":"Garantía provisional: máximo 3 por 100 del presupuesto base; definitiva: 5 por 100 del precio ofertado sin IVA; devolución en dos meses.","refs":[{"ref":"Art. 107.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"una garantía de un 5 por 100 del precio final ofertado"}]},{"text":"Pago en treinta días; demora de más de seis meses permite resolver.","refs":[{"ref":"Art. 198.4 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"dentro de los treinta días siguientes"}]},{"text":"Certificaciones de obra mensuales, en los primeros diez días del mes siguiente.","refs":[{"ref":"Art. 240.1 LCSP","law":"Ley 9/2017","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902","quote":"en los primeros diez días siguientes al mes al que correspondan"}]},{"text":"Subvenciones de más de 12 millones de euros: autorización previa del Consejo de Ministros.","refs":[{"ref":"Art. 10.2 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"de cuantía superior a 12 millones de euros"}]},{"text":"Cuenta justificativa sin plazo en las bases: tres meses tras el plazo de la actividad.","refs":[{"ref":"Art. 30.2 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"como máximo, en el plazo de tres meses"}]},{"text":"Interés de demora: interés legal más un 25 por ciento; prescripción del reintegro: cuatro años; procedimiento: 12 meses.","refs":[{"ref":"Art. 39.1 LGS","law":"Ley 38/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977","quote":"Prescribirá a los cuatro años"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977', null, null, null, 'Otras normas citadas: Ley 9/2017 (https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902)'
