insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Cómo se plantea el supuesto práctico: caso narrado, 20 preguntas sobre los bloques II a V"},{"n":"2","title":"Cómputo de plazos: días hábiles, meses, festivos y registro electrónico (arts. 30-31 LPAC)"},{"n":"3","title":"Subsanación, representación y desistimiento (arts. 5 y 68 LPAC)"},{"n":"4","title":"Qué recurso cabe y ante quién: alzada, reposición, contencioso (arts. 112-124 LPAC; art. 46 LJCA)"},{"n":"5","title":"Situaciones administrativas en casos prácticos (arts. 85-90 TREBEP; RD 365/1995)"},{"n":"6","title":"Qué modificación de crédito procede y cómo se financia (arts. 51-63 LGP)"},{"n":"7","title":"Clasificar un gasto: capítulo, artículo, concepto y subconcepto (Resolución DGP de 20/01/2014)"}]'::jsonb, '["Art. 30.2 Ley 39/2015: «Siempre que por Ley o en el Derecho de la Unión Europea no se exprese otro cómputo, cuando los plazos se señalen por días, se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos.»","Art. 30.5 Ley 39/2015: «Cuando el último día del plazo sea inhábil, se entenderá prorrogado al primer día hábil siguiente.»","Art. 115.2 Ley 39/2015: «El error o la ausencia de la calificación del recurso por parte del recurrente no será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter.»","Art. 114.2 Ley 39/2015: «c) Los emanados de los órganos directivos con nivel de Director general o superior, en relación con las competencias que tengan atribuidas en materia de personal.»","Art. 117.3 Ley 39/2015: «La ejecución del acto impugnado se entenderá suspendida si transcurrido un mes desde que la solicitud de suspensión haya tenido entrada en el registro electrónico de la Administración u Organismo competente para decidir sobre la misma, el órgano a quien competa resolver el recurso no ha dictado y notificado resolución expresa al respecto.»","Art. 123.2 Ley 39/2015: «No se podrá interponer recurso contencioso-administrativo hasta que sea resuelto expresamente o se haya producido la desestimación presunta del recurso de reposición interpuesto.»","Art. 46.1 Ley 29/1998: «El plazo para interponer el recurso contencioso-administrativo será de dos meses contados desde el día siguiente al de la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso.»","Art. 87.1 TREBEP: «a) Cuando sean designados miembros del Gobierno o de los órganos de gobierno de las comunidades autónomas y ciudades de Ceuta y Melilla, miembros de las Instituciones de la Unión Europea o de las organizaciones internacionales, o sean nombrados altos cargos de las citadas Administraciones Públicas o Instituciones.»","Art. 9.2 RD 365/1995: «Los Diputados, Senadores, miembros de las Asambleas Legislativas de las Comunidades Autónomas o del Parlamento Europeo que pierdan dicha condición por disolución de las correspondientes Cámaras o terminación del mandato de las mismas podrán permanecer en situación de servicios especiales hasta su nueva constitución.»","Art. 22.5 RD 365/1995: «Si una vez solicitado el reingreso al servicio activo no se concede en el plazo de seis meses, el funcionario será declarado, de oficio, en la situación de excedencia forzosa»","Art. 53.2 Ley 47/2003: «b) Ventas de bienes y prestación de servicios.»","Art. 54.1 Ley 47/2003: «Excepcionalmente tendrán la condición de ampliables los créditos destinados al pago de pensiones de Clases Pasivas del Estado»","Art. 55.2 Ley 47/2003: «b) Cuando se trate de créditos extraordinarios o suplementarios para atender obligaciones del propio ejercicio cuando se financien con baja en otros créditos.»","Anexo IV, concepto 162 Resolución DGP 20/01/2014 (clasificación económica): «Gastos de reconocimiento médico del personal y aquellos derivados de accidentes de trabajo.»","Anexo IV, concepto 226 Resolución DGP 20/01/2014 (clasificación económica): «Se incluirán en este epígrafe los gastos que ocasione la inserción de publicidad en Boletines Oficiales.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Cómo se plantea el supuesto práctico","blocks":[{"text":"La segunda parte del ejercicio consiste en un supuesto práctico (un caso narrado de oficina con preguntas de respuesta múltiple sobre los bloques II a V del programa). El detalle (supuesto a elegir entre dos, 20 preguntas) procede de las bases de la convocatoria BOE-A-2025-26262, cuyo texto no está entre las fuentes literales de estos apuntes: confírmalo en las bases. El método útil es siempre el mismo: identificar el órgano que dicta el acto, la norma aplicable y la fecha de partida, y aplicar la regla literal. Por ejemplo, todo plazo empieza a contarse desde el día siguiente a la notificación o publicación (art. 30.3 y 30.4 LPAC), y todo gasto se imputa según una estructura de capítulos, artículos, conceptos y subconceptos.","refs":[{"ref":"Art. 30.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Los plazos expresados en días se contarán a partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto de que se trate"},{"ref":"Anexo IV (Resolución DGP 20/01/2014)","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"Los capítulos se desglosarán en artículos y estos en conceptos que podrán dividirse en subconceptos."}]}]},{"n":"2","title":"Cómputo de plazos: días hábiles, meses, festivos y registro electrónico","blocks":[{"text":"Los plazos por días son hábiles salvo que una ley o el Derecho de la UE digan otra cosa: se excluyen sábados, domingos y festivos (art. 30.2 LPAC). Ejemplo: requerimiento notificado el viernes 2 de octubre de 2026, con diez días y el lunes 12 de octubre festivo nacional: se cuentan 5, 6, 7, 8, 9, 13, 14, 15, 16 y 19 de octubre, de modo que el plazo vence el lunes 19. Si el último día es inhábil, se prorroga al primer día hábil siguiente (art. 30.5 LPAC).","refs":[{"ref":"Art. 30.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Siempre que por Ley o en el Derecho de la Unión Europea no se exprese otro cómputo, cuando los plazos se señalen por días, se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos."},{"ref":"Art. 30.5 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Cuando el último día del plazo sea inhábil, se entenderá prorrogado al primer día hábil siguiente."}]},{"text":"Los plazos por meses vencen el mismo número de día del mes de vencimiento; si no existe, el último día del mes (art. 30.4 LPAC). Un día hábil donde reside el interesado pero inhábil en la sede del órgano, o a la inversa, es inhábil en todo caso (art. 30.6 LPAC). En el registro electrónico, lo presentado en día inhábil en un plazo por días hábiles se entiende presentado a la primera hora del primer día hábil siguiente (art. 31.2.b LPAC).","refs":[{"ref":"Art. 30.4 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El plazo concluirá el mismo día en que se produjo la notificación, publicación o silencio administrativo en el mes o el año de vencimiento. Si en el mes de vencimiento no hubiera día equivalente a aquel en que comienza el cómputo, se entenderá que el plazo expira el último día del mes."},{"ref":"Art. 31.2.b) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"la presentación en un día inhábil se entenderá realizada en la primera hora del primer día hábil siguiente salvo que una norma permita expresamente la recepción en día inhábil."}]}]},{"n":"3","title":"Subsanación, representación y desistimiento","blocks":[{"text":"Si la solicitud no reúne los requisitos, se requiere al interesado para que subsane en diez días, advirtiéndole de que, si no lo hace, se le tendrá por desistido de su petición, previa resolución dictada en los términos del artículo 21 (art. 68.1 LPAC). Así, si doña Rosa no aporta el plano en plazo, no se archiva sin más: se dicta resolución que la tiene por desistida. El plazo puede ampliarse hasta cinco días, salvo en procedimientos selectivos o de concurrencia competitiva (art. 68.2 LPAC).","refs":[{"ref":"Art. 68.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición, previa resolución que deberá ser dictada en los términos previstos en el artículo 21."},{"ref":"Art. 68.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Siempre que no se trate de procedimientos selectivos o de concurrencia competitiva, este plazo podrá ser ampliado prudencialmente, hasta cinco días"}]},{"text":"La representación debe acreditarse para solicitar, recurrir, desistir o renunciar; en los actos de mero trámite se presume (art. 5.3 LPAC). Si falta o es insuficiente, el acto vale si se subsana en diez días (art. 5.6 LPAC). El interesado puede desistir de su solicitud o renunciar a sus derechos; la Administración lo acepta de plano y declara concluso el procedimiento, salvo que terceros personados insten su continuación en diez días (art. 94 LPAC).","refs":[{"ref":"Art. 5.6 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"siempre que se aporte aquélla o se subsane el defecto dentro del plazo de diez días que deberá conceder al efecto el órgano administrativo"},{"ref":"Art. 94.4 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La Administración aceptará de plano el desistimiento o la renuncia, y declarará concluso el procedimiento salvo que, habiéndose personado en el mismo terceros interesados, instasen éstos su continuación en el plazo de diez días desde que fueron notificados del desistimiento o renuncia."}]}]},{"n":"4","title":"Qué recurso cabe y ante quién","blocks":[{"text":"Primera pregunta del caso: ¿el acto pone fin a la vía administrativa? En la AGE la agotan, entre otros, los actos de los Ministros y Secretarios de Estado y los de órganos con nivel de Director general o superior en materia de personal (art. 114.2 LPAC). Si la agota, cabe reposición potestativa ante el mismo órgano o directamente el contencioso (art. 123.1 LPAC): la Directora General que deniega una reducción de jornada a un funcionario dicta un acto de personal que agota la vía.","refs":[{"ref":"Art. 114.2.c) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Los emanados de los órganos directivos con nivel de Director general o superior, en relación con las competencias que tengan atribuidas en materia de personal."},{"ref":"Art. 123.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Los actos administrativos que pongan fin a la vía administrativa podrán ser recurridos potestativamente en reposición ante el mismo órgano que los hubiera dictado o ser impugnados directamente ante el orden jurisdiccional contencioso-administrativo."}]},{"text":"Si no la agota (por ejemplo, una resolución de un Subdirector General), procede la alzada ante el superior jerárquico, en un mes si el acto es expreso (arts. 121.1 y 122.1 LPAC). Si es presunto por silencio, la alzada puede interponerse en cualquier momento desde el día siguiente a aquel en que se produzcan los efectos del silencio (art. 122.1 LPAC). La reposición se interpone en un mes y se resuelve en un mes; la alzada, en tres meses (arts. 124 y 122.2 LPAC).","refs":[{"ref":"Art. 121.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"cuando no pongan fin a la vía administrativa, podrán ser recurridos en alzada ante el órgano superior jerárquico del que los dictó."},{"ref":"Art. 122.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El plazo para la interposición del recurso de alzada será de un mes, si el acto fuera expreso."},{"ref":"Art. 122.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"podrán interponer recurso de alzada en cualquier momento a partir del día siguiente a aquel en que, de acuerdo con su normativa específica, se produzcan los efectos del silencio administrativo."}]}]},{"n":"5","title":"Calificación, inadmisión, suspensión y contencioso","blocks":[{"text":"Si el ciudadano titula mal su escrito («reposición» contra un acto que no agota la vía), se tramita como alzada, porque el error en la calificación no impide la tramitación si se deduce su verdadero carácter (art. 115.2 LPAC). Si se dirige a un Ministerio un recurso contra un acto de una consejería autonómica, hay causa de inadmisión por incompetencia y el recurso debe remitirse al órgano competente (art. 116.a LPAC).","refs":[{"ref":"Art. 115.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"El error o la ausencia de la calificación del recurso por parte del recurrente no será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter."},{"ref":"Art. 116.a) LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Ser incompetente el órgano administrativo, cuando el competente perteneciera a otra Administración Pública. El recurso deberá remitirse al órgano competente"}]},{"text":"Recurrir no suspende la ejecución, pero si se pide la suspensión y pasa un mes desde su entrada en el registro electrónico del órgano competente sin resolución expresa notificada, la ejecución se entiende suspendida (art. 117.3 LPAC). Interpuesta la reposición, no cabe contencioso hasta su resolución expresa o desestimación presunta (art. 123.2 LPAC). El contencioso se interpone en dos meses desde el día siguiente a la notificación del acto expreso que agota la vía, o seis meses si es presunto (art. 46.1 LJCA).","refs":[{"ref":"Art. 117.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La ejecución del acto impugnado se entenderá suspendida si transcurrido un mes desde que la solicitud de suspensión haya tenido entrada en el registro electrónico de la Administración u Organismo competente para decidir sobre la misma, el órgano a quien competa resolver el recurso no ha dictado y notificado resolución expresa al respecto."},{"ref":"Art. 123.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"No se podrá interponer recurso contencioso-administrativo hasta que sea resuelto expresamente o se haya producido la desestimación presunta del recurso de reposición interpuesto."},{"ref":"Art. 46.1 LJCA","law":"Ley 29/1998","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718","quote":"El plazo para interponer el recurso contencioso-administrativo será de dos meses contados desde el día siguiente al de la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso. Si no lo fuera, el plazo será de seis meses"}]}]},{"n":"6","title":"Situaciones administrativas: servicio activo y servicios especiales","blocks":[{"text":"El TREBEP prevé cinco situaciones: servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones (art. 85.1 TREBEP). Pasa a servicios especiales, entre otros, quien es nombrado miembro del Gobierno o alto cargo de la AGE, de las CCAA o de instituciones europeas o internacionales (art. 87.1.a), o accede a Diputado o Senador o a parlamentario autonómico con retribuciones periódicas (art. 87.1.e). Percibe las retribuciones del cargo, conserva los trienios y el tiempo le computa para ascensos, trienios y Seguridad Social (art. 87.2).","refs":[{"ref":"Art. 85.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"a) Servicio activo. b) Servicios especiales. c) Servicio en otras Administraciones Públicas. d) Excedencia. e) Suspensión de funciones."},{"ref":"Art. 87.1.a) TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Cuando sean designados miembros del Gobierno o de los órganos de gobierno de las comunidades autónomas y ciudades de Ceuta y Melilla, miembros de las Instituciones de la Unión Europea o de las organizaciones internacionales, o sean nombrados altos cargos de las citadas Administraciones Públicas o Instituciones."},{"ref":"Art. 87.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"percibirán las retribuciones del puesto o cargo que desempeñen y no las que les correspondan como funcionarios de carrera, sin perjuicio del derecho a percibir los trienios que tengan reconocidos en cada momento."}]},{"text":"Si una Senadora en servicios especiales pierde la condición por disolución de las Cámaras, puede permanecer en servicios especiales hasta su nueva constitución (art. 9.2 RD 365/1995; art. 87.1.e TREBEP). En general, quien pierde la condición que motivó los servicios especiales debe pedir el reingreso en un mes; si no, pasa a excedencia voluntaria por interés particular (art. 9.1 RD 365/1995).","refs":[{"ref":"Art. 9.2 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"Los Diputados, Senadores, miembros de las Asambleas Legislativas de las Comunidades Autónomas o del Parlamento Europeo que pierdan dicha condición por disolución de las correspondientes Cámaras o terminación del mandato de las mismas podrán permanecer en situación de servicios especiales hasta su nueva constitución."},{"ref":"Art. 9.1 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"deberán solicitar el reingreso al servicio activo en el plazo de un mes, declarándoseles, de no hacerlo en la situación de excedencia voluntaria por interés particular"}]}]},{"n":"7","title":"Excedencias y suspensión de funciones en casos prácticos","blocks":[{"text":"El TREBEP regula la excedencia voluntaria por interés particular (cinco años previos de servicios, subordinada a las necesidades del servicio y sin retribuciones ni cómputo), por agrupación familiar, por cuidado de familiares, por violencia de género o sexual y por violencia terrorista (art. 89 TREBEP). Para cuidar a un familiar hasta el segundo grado que por edad, accidente, enfermedad o discapacidad no pueda valerse por sí mismo y no tenga actividad retribuida, la excedencia dura como máximo tres años, computa para trienios, carrera y Seguridad Social, y reserva el puesto al menos dos años (art. 89.4).","refs":[{"ref":"Art. 89.2 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"cuando hayan prestado servicios efectivos en cualquiera de las Administraciones Públicas durante un periodo mínimo de cinco años inmediatamente anteriores."},{"ref":"Art. 89.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"También tendrán derecho a un período de excedencia de duración no superior a tres años, para atender al cuidado de un familiar que se encuentre a su cargo, hasta el segundo grado inclusive de consanguinidad o afinidad que por razones de edad, accidente, enfermedad o discapacidad no pueda valerse por sí mismo y no desempeñe actividad retribuida."},{"ref":"Art. 89.4 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"El puesto de trabajo desempeñado se reservará, al menos, durante dos años."}]},{"text":"El funcionario de la AGE que pasa a servicio activo en otro cuerpo de cualquier Administración sin obtener compatibilidad es declarado en excedencia voluntaria por prestación de servicios en el sector público (art. 15.1 RD 365/1995). La suspensión firme priva del ejercicio de funciones y de los derechos y supone perder el puesto si excede de seis meses (art. 90.1 TREBEP). Quien perdió el puesto debe pedir el reingreso un mes antes de terminar la suspensión; si lo pide y no se le concede en seis meses, se le declara de oficio en excedencia forzosa con efectos de la fecha de extinción de la responsabilidad (art. 22 RD 365/1995). Ojo: el RD 365/1995 es anterior al TREBEP; aplícalo en lo que no lo contradiga.","refs":[{"ref":"Art. 15.1 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"Procederá declarar, de oficio o a instancia de parte, en la situación regulada en este artículo a los funcionarios de carrera que se encuentren en servicio activo en otro cuerpo o escala de cualquiera de las Administraciones públicas, salvo que hubieran obtenido la oportuna compatibilidad"},{"ref":"Art. 90.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"La suspensión determinará la pérdida del puesto de trabajo cuando exceda de seis meses."},{"ref":"Art. 22.5 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"Si una vez solicitado el reingreso al servicio activo no se concede en el plazo de seis meses, el funcionario será declarado, de oficio, en la situación de excedencia forzosa prevista en el artículo 13.1.b) con efectos de la fecha de extinción de la responsabilidad penal o disciplinaria."}]}]},{"n":"8","title":"Qué modificación de crédito procede: transferencias, generaciones y ampliaciones","blocks":[{"text":"Los créditos solo se modifican mediante transferencias, generaciones, ampliaciones, créditos extraordinarios y suplementos, e incorporaciones (art. 51 LGP). La transferencia traspasa dotaciones entre créditos, con restricciones: no desde operaciones financieras al resto ni desde operaciones de capital a corrientes; no entre secciones distintas; y no minorando créditos extraordinarios o ya suplementados o ampliados (art. 52.1 LGP). Por eso no cabe dar de baja crédito del capítulo 6 (inversiones reales, capital) para reforzar el capítulo 2 (gasto corriente).","refs":[{"ref":"Art. 51 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"a) Transferencias. b) Generaciones. c) Ampliaciones. d) Créditos extraordinarios y suplementos de crédito. e) Incorporaciones."},{"ref":"Art. 52.1.a) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"No podrán realizarse desde créditos para operaciones financieras al resto de los créditos, ni desde créditos para operaciones de capital a créditos para operaciones corrientes."},{"ref":"Art. 52.1.b) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"No podrán realizarse entre créditos de distintas secciones presupuestarias."}]},{"text":"La generación incrementa créditos por ingresos no previstos o superiores a los presupuestados; pueden generarla, entre otros, las ventas de bienes y prestación de servicios, las enajenaciones de inmovilizado, los reembolsos de préstamos y los reintegros de pagos indebidos (art. 53.2 LGP), y solo cuando se han realizado los ingresos (art. 53.3). Si vienen de ventas, se genera en créditos para gastos de la misma naturaleza (art. 53.4): con lo obtenido por vender publicaciones se puede reeditarlas. Son ampliables, excepcionalmente, los créditos para pensiones de Clases Pasivas y las obligaciones legales relacionadas en el estado de gastos, así como los de la Deuda del Estado (art. 54.1 LGP); en el Estado se financian con el Fondo de Contingencia o con baja en otros créditos no financieros (art. 54.3).","refs":[{"ref":"Art. 53.2.b) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Ventas de bienes y prestación de servicios."},{"ref":"Art. 53.4 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Cuando los ingresos provengan de la venta de bienes o prestaciones de servicios, las generaciones se efectuarán únicamente en aquellos créditos destinados a cubrir gastos de la misma naturaleza que los que se originaron por la adquisición o producción de los bienes enajenados o por la prestación del servicio."},{"ref":"Art. 54.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Excepcionalmente tendrán la condición de ampliables los créditos destinados al pago de pensiones de Clases Pasivas del Estado"},{"ref":"Art. 54.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las ampliaciones de crédito que afecten a operaciones del presupuesto del Estado se financiarán con cargo al Fondo de Contingencia, conforme a lo previsto en el artículo 50 de esta ley, o con baja en otros créditos del presupuesto no financiero."}]}]},{"n":"9","title":"Créditos extraordinarios y suplementos, incorporaciones, anticipos y competencias","blocks":[{"text":"Cuando un gasto no puede demorarse al ejercicio siguiente y no hay crédito, o es insuficiente y no ampliable, y no cabe otra figura, se tramita un crédito extraordinario o un suplemento; en operaciones no financieras se financia con baja en el Fondo de Contingencia u otros créditos no financieros (art. 55.1 LGP). Requieren proyecto de ley a las Cortes, entre otros, los destinados a obligaciones de ejercicios anteriores sin crédito anulado y los del propio ejercicio financiados con baja en otros créditos (art. 55.2); los financiados con el Fondo de Contingencia para obligaciones del ejercicio los autoriza el Consejo de Ministros (art. 55.3).","refs":[{"ref":"Art. 55.1.a) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Si la necesidad surgiera en operaciones no financieras del presupuesto, el crédito extraordinario o suplementario se financiará mediante baja en los créditos del Fondo de Contingencia o en otros no financieros que se consideren adecuados."},{"ref":"Art. 55.2.b) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Cuando se trate de créditos extraordinarios o suplementarios para atender obligaciones del propio ejercicio cuando se financien con baja en otros créditos."},{"ref":"Art. 55.3 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"El Consejo de Ministros autorizará los créditos extraordinarios y suplementos de crédito para atender obligaciones del ejercicio corriente o de ejercicios anteriores si se hubiera anulado crédito en el ejercicio de procedencia, cuando se financien con cargo al Fondo de Contingencia."}]},{"text":"Las incorporaciones permiten llevar remanentes del ejercicio anterior en casos tasados (art. 58 LGP). Los anticipos de Tesorería, excepcionales, los concede el Gobierno para gastos inaplazables con un límite del uno por ciento de los créditos autorizados, una vez dictaminado favorablemente el expediente por el Consejo de Estado o promulgada la ley que exige el crédito (art. 60.1 LGP). Los Ministros autorizan, con informe favorable de la Intervención Delegada, transferencias dentro de un mismo programa o entre programas de un mismo servicio (art. 63.1.a); el Ministro de Hacienda, entre otras, las ampliaciones del artículo 54.1 (art. 62.1.d). Los nombres de ministerios de la LGP pueden no coincidir con la estructura actual.","refs":[{"ref":"Art. 60.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"podrá conceder anticipos de Tesorería para atender gastos inaplazables, con el límite máximo en cada ejercicio del uno por ciento de los créditos autorizados al Estado por la Ley de Presupuestos Generales del Estado"},{"ref":"Art. 63.1.a) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Transferencias entre créditos de un mismo programa o entre programas de un mismo servicio"},{"ref":"Art. 62.1.d) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Las ampliaciones de crédito previstas en el artículo 54.1"}]}]},{"n":"10","title":"Clasificar un gasto: capítulo, artículo, concepto y subconcepto","blocks":[{"text":"Los capítulos 1 a 4 recogen operaciones corrientes (personal, bienes corrientes y servicios, gastos financieros y transferencias corrientes); el 5, el Fondo de Contingencia; el 6 y el 7, operaciones de capital (inversiones reales y transferencias de capital); y el 8 y el 9, operaciones financieras (Anexo IV de la Resolución DGP de 20/01/2014). Los reconocimientos médicos del personal se imputan al capítulo 1, concepto 162 «Gastos sociales del personal», subconcepto 09 «Otros». La inserción de publicidad en Boletines Oficiales va al capítulo 2, concepto 226 «Gastos diversos», subconcepto 02 «Publicidad y propaganda». El concepto 226 recoge los gastos corrientes que no caben en otros conceptos del capítulo 2. Nota: la Resolución remite aún a la derogada Ley de Contratos de 2011 en el concepto 162.","refs":[{"ref":"Anexo IV (Resolución DGP 20/01/2014)","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"el presupuesto de gastos clasifica en sus capítulos 1 al 4 los gastos por operaciones corrientes, separando los gastos de funcionamiento de los servicios (personal y gastos corrientes en bienes y servicios), los gastos financieros y las transferencias corrientes."},{"ref":"Anexo IV (Resolución DGP 20/01/2014)","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"Las operaciones de capital comprenden los capítulos 6 y 7 que recogen las inversiones reales y las transferencias de capital."},{"ref":"Anexo IV, concepto 162.09","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"Subconcepto 09. Otros Gastos de reconocimiento médico del personal y aquellos derivados de accidentes de trabajo."},{"ref":"Anexo IV, concepto 226.02","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"Subconcepto 02. Publicidad y propaganda. […] Se incluirán en este epígrafe los gastos que ocasione la inserción de publicidad en Boletines Oficiales."},{"ref":"Anexo IV, concepto 226","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"Se incluyen todos aquellos gastos de naturaleza corriente que no tienen cabida en otros conceptos del capítulo 2."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Diez días hábiles: sáltate sábados, domingos y festivos, y empieza al día siguiente de notificar (art. 30 LPAC).","refs":[{"ref":"Art. 30.2 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"excluyéndose del cómputo los sábados, los domingos y los declarados festivos."}]},{"text":"Subsanación no atendida: desistimiento previa resolución (art. 68.1 LPAC).","refs":[{"ref":"Art. 68.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se le tendrá por desistido de su petición"}]},{"text":"Director general en materia de personal: agota la vía; reposición potestativa o contencioso (arts. 114.2.c y 123.1 LPAC).","refs":[{"ref":"Art. 123.1 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"podrán ser recurridos potestativamente en reposición ante el mismo órgano que los hubiera dictado"}]},{"text":"Suspensión pedida y no resuelta en un mes: se entiende suspendida (art. 117.3 LPAC).","refs":[{"ref":"Art. 117.3 LPAC","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"La ejecución del acto impugnado se entenderá suspendida"}]},{"text":"Alto cargo: servicios especiales (art. 87.1.a TREBEP).","refs":[{"ref":"Art. 87.1 TREBEP","law":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719","quote":"Los funcionarios de carrera serán declarados en situación de servicios especiales"}]},{"text":"Reingreso tras suspensión no concedido en seis meses: excedencia forzosa (art. 22.5 RD 365/1995).","refs":[{"ref":"Art. 22.5 RD 365/1995","law":"RD 365/1995","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730","quote":"el funcionario será declarado, de oficio, en la situación de excedencia forzosa"}]},{"text":"Clases Pasivas: ampliación; ventas de bienes: generación; capital a corriente: transferencia prohibida (arts. 52-54 LGP).","refs":[{"ref":"Art. 52.1.a) LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"ni desde créditos para operaciones de capital a créditos para operaciones corrientes."}]},{"text":"Reconocimiento médico: 162.09; anuncio en el BOE: 226.02 (Resolución DGP 20/01/2014).","refs":[{"ref":"Anexo IV, concepto 162.09","law":"Resolución DGP 20/01/2014 (clasificación económica)","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-879","quote":"Gastos de reconocimiento médico del personal y aquellos derivados de accidentes de trabajo."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', null, null, null, 'Otras normas citadas: Ley 29/1998 (https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718), TREBEP (https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719), RD 365/1995 (https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730), Ley 47/2003 (https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614), Resolución DGP 20/01/2014 (clasificación económica) (https://www.boe.es/buscar/act.php?id=BOE-A-2014-879)'
  from public.topics t where t.slug = 'age-adm-60-supuesto-practico'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);

do $$
declare
  v_owner uuid;
  v_slug text;
  v_n int := 0;
begin
  select id into v_owner from public.profiles
   where role = 'owner' and status = 'active' order by created_at limit 1;
  if v_owner is null then
    raise notice 'No hay persona titular: no se publica nada.';
    return;
  end if;
  perform set_config('request.jwt.claims',
    json_build_object('sub', v_owner, 'role', 'authenticated')::text, true);

  for v_slug in select t.slug from public.topics t
                  join public.topic_notes n on n.topic_id = t.id
                 where t.slug like 'age-adm-%' and n.status <> 'published'
                 order by t.slug loop
    perform public.review_topic_notes(v_slug, 'approved');
    v_n := v_n + public.review_topic_notes(v_slug, 'published');
  end loop;

  perform public.log_admin_action('content.publish_notes', 'exam_bodies',
    'administrativo-estado',
    jsonb_build_object('notes', v_n,
                       'motivo', 'Petición expresa de joel en el hilo del proyecto (10/11/2026: apuntes completos por tema)'));
  perform set_config('request.jwt.claims', '', true);
  raise notice 'Administrativo del Estado: % fichas con apuntes publicadas', v_n;
end $$;

commit;
